import { db } from '../firebase';
import { collection, addDoc, getDocs, query, orderBy, where, Timestamp } from 'firebase/firestore';
import { Product, Order, Customer } from '../types';

// Helper to generate a random code between 4 and 6 digits
export const generateProductCode = (): string => {
  const min = 1000;
  const max = 999999;
  const num = Math.floor(Math.random() * (max - min + 1)) + min;
  return num.toString();
};

// --- Products ---

export const addProduct = async (product: Omit<Product, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "products"), product);
    return { ...product, id: docRef.id };
  } catch (e) {
    console.error("Error adding product: ", e);
    throw e;
  }
};

export const getProducts = async (): Promise<Product[]> => {
  try {
    const q = query(collection(db, "products"), orderBy("name"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product));
  } catch (e) {
    console.error("Error fetching products: ", e);
    return [];
  }
};

// --- Orders ---

export const createOrder = async (order: Omit<Order, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "orders"), {
      ...order,
      createdAt: Timestamp.now().toMillis() // Using number timestamp for easier frontend handling
    });
    return { ...order, id: docRef.id };
  } catch (e) {
    console.error("Error creating order: ", e);
    throw e;
  }
};

// --- Customers ---

export const getCustomers = async (): Promise<Customer[]> => {
    try {
      const q = query(collection(db, "customers"), orderBy("name"));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Customer));
    } catch (e) {
      console.error("Error fetching customers", e);
      return [];
    }
}

export const addCustomer = async (customer: Customer) => {
    try {
        const docRef = await addDoc(collection(db, "customers"), customer);
        return { ...customer, id: docRef.id };
    } catch(e) {
        console.error("Error adding customer", e);
        throw e;
    }
}

import React, { useState } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers } from 'lucide-react';
import { Button, Input, Select, Card } from '../components/UI';
import { Product } from '../types';
import { generateProductCode, addProduct } from '../services/dataService';

const Inventory: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<Partial<Product>>({
    code: generateProductCode(),
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'Disfraces',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
  });

  const [variationInput, setVariationInput] = useState('');

  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  const handleVariationAdd = () => {
    if (variationInput.trim()) {
      setFormData(prev => ({
        ...prev,
        variations: [...(prev.variations || []), variationInput.trim()]
      }));
      setVariationInput('');
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.code) return;

    setLoading(true);
    try {
      await addProduct(formData as Product);
      alert('Producto guardado exitosamente');
      // Reset form
      setFormData({
        code: generateProductCode(),
        name: '',
        description: '',
        salePrice: 0,
        rentalPrice: 0,
        category: 'Disfraces',
        stock: 1,
        variations: [],
        isRentalAvailable: true,
        isSaleAvailable: false,
      });
    } catch (error) {
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="p-4 md:p-8 max-w-4xl mx-auto pb-24">
      <header className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3">
          <Box className="w-8 h-8 text-indigo-600" />
          Inventario
        </h1>
        <p className="text-slate-500 mt-2">Alta de disfraces y artículos</p>
      </header>

      <form onSubmit={handleSubmit}>
        <Card className="space-y-6">
          {/* Code Section */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="flex items-end gap-2">
              <Input 
                label="Código (Aleatorio)" 
                value={formData.code} 
                readOnly 
                className="bg-slate-50 font-mono text-lg tracking-widest text-center"
              />
              <Button type="button" variant="secondary" onClick={generateCode} className="mb-[1px]">
                <RefreshCw className="w-5 h-5" />
              </Button>
            </div>

            <Input 
              label="Nombre del Artículo" 
              value={formData.name} 
              onChange={(e) => setFormData({...formData, name: e.target.value})}
              placeholder="Ej. Traje de Spiderman"
              required
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input 
              label="Descripción" 
              value={formData.description} 
              onChange={(e) => setFormData({...formData, description: e.target.value})}
              placeholder="Detalles del estado, material, etc."
            />
             <Select 
              label="Categoría"
              value={formData.category}
              onChange={(e) => setFormData({...formData, category: e.target.value})}
            >
              <option value="Disfraces">Disfraces</option>
              <option value="Accesorios">Accesorios</option>
              <option value="Decoración">Decoración</option>
              <option value="Venta General">Venta General</option>
            </Select>
          </div>

          {/* Pricing */}
          <div className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
            <h3 className="text-sm font-bold text-indigo-900 uppercase tracking-wide mb-4 flex items-center gap-2">
              <DollarSign className="w-4 h-4" /> Precios y Disponibilidad
            </h3>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-3">
                <label className="flex items-center gap-2 p-3 bg-white rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300 transition-all">
                  <input 
                    type="checkbox" 
                    checked={formData.isRentalAvailable}
                    onChange={(e) => setFormData({...formData, isRentalAvailable: e.target.checked})}
                    className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500"
                  />
                  <span className="font-medium text-slate-700">Disponible Renta</span>
                </label>
                {formData.isRentalAvailable && (
                  <Input 
                    type="number" 
                    label="Costo Renta" 
                    placeholder="0.00"
                    value={formData.rentalPrice || ''}
                    onChange={(e) => setFormData({...formData, rentalPrice: parseFloat(e.target.value)})}
                  />
                )}
              </div>

              <div className="space-y-3">
                <label className="flex items-center gap-2 p-3 bg-white rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300 transition-all">
                  <input 
                    type="checkbox" 
                    checked={formData.isSaleAvailable}
                    onChange={(e) => setFormData({...formData, isSaleAvailable: e.target.checked})}
                    className="w-5 h-5 text-emerald-600 rounded focus:ring-emerald-500"
                  />
                  <span className="font-medium text-slate-700">Disponible Venta</span>
                </label>
                {formData.isSaleAvailable && (
                  <Input 
                    type="number" 
                    label="Costo Venta" 
                    placeholder="0.00"
                    value={formData.salePrice || ''}
                    onChange={(e) => setFormData({...formData, salePrice: parseFloat(e.target.value)})}
                  />
                )}
              </div>
            </div>
          </div>

          {/* Variations & Inventory */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input 
              type="number" 
              label="Stock Inicial" 
              value={formData.stock}
              onChange={(e) => setFormData({...formData, stock: parseInt(e.target.value)})}
              min="1"
            />

            <div className="flex flex-col gap-1.5">
              <label className="text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1">Variaciones (Tallas/Colores)</label>
              <div className="flex gap-2">
                <Input 
                  placeholder="Ej. Talla M" 
                  value={variationInput}
                  onChange={(e) => setVariationInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && (e.preventDefault(), handleVariationAdd())}
                />
                <Button type="button" variant="secondary" onClick={handleVariationAdd}>
                  <Plus className="w-5 h-5" />
                </Button>
              </div>
              <div className="flex flex-wrap gap-2 mt-2">
                {formData.variations?.map((v, i) => (
                  <span key={i} className="bg-white border border-slate-200 px-3 py-1 rounded-lg text-sm flex items-center gap-2">
                    {v}
                    <button 
                      type="button"
                      onClick={() => setFormData(prev => ({...prev, variations: prev.variations?.filter((_, idx) => idx !== i)}))}
                      className="text-slate-400 hover:text-rose-500"
                    >
                      &times;
                    </button>
                  </span>
                ))}
              </div>
            </div>
          </div>

          <div className="pt-4 flex justify-end">
             <Button type="submit" disabled={loading} className="w-full md:w-auto">
               {loading ? 'Guardando...' : 'Guardar Artículo'}
             </Button>
          </div>
        </Card>
      </form>
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useMemo } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard } from 'lucide-react';
import { Button, Input, Card, Badge } from '../components/UI';
import { Product, CartItem, Customer, Order } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer } from '../services/dataService';

const POS: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const p = await getProducts();
      const c = await getCustomers();
      setProducts(p);
      setCustomers(c);
    };
    fetchData();
  }, []);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent') => {
    const existing = cart.find(item => item.id === product.id && item.transactionType === type);

    if (existing) {
      setCart(cart.map(item => 
        (item.id === product.id && item.transactionType === type) 
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1 
      }]);
    }
  };

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Calculations
  const total = cart.reduce((sum, item) => {
    const price = item.transactionType === 'rent' ? item.rentalPrice : item.salePrice;
    return sum + (price * item.quantity);
  }, 0);

  // Customer Handling
  const handleQuickCustomerAdd = async () => {
    if(!newCustomerName) return;
    const newCus: Customer = {
        name: newCustomerName,
        phone: newCustomerPhone
    }
    const saved = await addCustomer(newCus);
    setCustomers([...customers, saved]);
    setSelectedCustomer(saved);
    setShowCustomerModal(false);
    setNewCustomerName('');
    setNewCustomerPhone('');
  }

  // Checkout
  const handleCheckout = async () => {
    if (cart.length === 0) return;
    if (hasRentals && (!selectedCustomer || !rentalDate || !returnDate)) {
      alert("Para rentas, se requiere Cliente y Fechas.");
      return;
    }

    const order: Omit<Order, 'id'> = {
      items: cart,
      total,
      status: 'pending',
      createdAt: Date.now(),
      customer: selectedCustomer || undefined,
      rentalStartDate: rentalDate ? new Date(rentalDate).getTime() : undefined,
      rentalEndDate: returnDate ? new Date(returnDate).getTime() : undefined,
    };

    await createOrder(order);
    alert("Venta registrada!");
    setCart([]);
    setSelectedCustomer(null);
    setRentalDate('');
    setReturnDate('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Buscar por nombre o código..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      {product.variations.map(v => <span key={v} className="text-[10px] bg-slate-50 px-1.5 rounded text-slate-500 border border-slate-100">{v}</span>)}
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => addToCart(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100"
                  >
                    <span>Rentar</span>
                    <span>${product.rentalPrice}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => addToCart(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100"
                  >
                    <span>Vender</span>
                    <span>${product.salePrice}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout (Sidebar on Desktop, Drawer/Bottom Sheet logic on mobile could be added, but handled via flex order/scroll for now) */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
