import { db } from '../firebase';
import { collection, addDoc, getDocs, query, orderBy, where, Timestamp, deleteDoc, doc } from 'firebase/firestore';
import { Product, Order, Customer } from '../types';

// Helper to generate a random code between 4 and 6 digits
export const generateProductCode = (): string => {
  const min = 1000;
  const max = 999999;
  const num = Math.floor(Math.random() * (max - min + 1)) + min;
  return num.toString();
};

// --- Products ---

export const addProduct = async (product: Omit<Product, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "products"), product);
    return { ...product, id: docRef.id };
  } catch (e) {
    console.error("Error adding product: ", e);
    throw e;
  }
};

export const getProducts = async (): Promise<Product[]> => {
  try {
    const q = query(collection(db, "products"), orderBy("name"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product));
  } catch (e) {
    console.error("Error fetching products: ", e);
    return [];
  }
};

export const deleteProduct = async (id: string) => {
    try {
        await deleteDoc(doc(db, "products", id));
    } catch (e) {
        console.error("Error deleting product", e);
        throw e;
    }
}

// --- Orders ---

export const createOrder = async (order: Omit<Order, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "orders"), {
      ...order,
      createdAt: Timestamp.now().toMillis() // Using number timestamp for easier frontend handling
    });
    return { ...order, id: docRef.id };
  } catch (e) {
    console.error("Error creating order: ", e);
    throw e;
  }
};

// --- Customers ---

export const getCustomers = async (): Promise<Customer[]> => {
    try {
      const q = query(collection(db, "customers"), orderBy("name"));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Customer));
    } catch (e) {
      console.error("Error fetching customers", e);
      return [];
    }
}

export const addCustomer = async (customer: Customer) => {
    try {
        const docRef = await addDoc(collection(db, "customers"), customer);
        return { ...customer, id: docRef.id };
    } catch(e) {
        console.error("Error adding customer", e);
        throw e;
    }
}

export const deleteCustomer = async (id: string) => {
    try {
        await deleteDoc(doc(db, "customers", id));
    } catch (e) {
        console.error("Error deleting customer", e);
        throw e;
    }
}

import React, { useState, useEffect } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers, Search, Trash2, ArrowLeft, Filter } from 'lucide-react';
import { Button, Input, Select, Card, Badge } from '../components/UI';
import { Product } from '../types';
import { generateProductCode, addProduct, getProducts, deleteProduct } from '../services/dataService';

const Inventory: React.FC = () => {
  const [view, setView] = useState<'list' | 'form'>('list');
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    code: generateProductCode(),
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'Disfraces',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
  });
  const [variationInput, setVariationInput] = useState('');

  // Load Data
  const loadProducts = async () => {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setLoading(false);
  };

  useEffect(() => {
    if (view === 'list') {
        loadProducts();
    }
  }, [view]);

  // Actions
  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  const handleVariationAdd = () => {
    if (variationInput.trim()) {
      setFormData(prev => ({
        ...prev,
        variations: [...(prev.variations || []), variationInput.trim()]
      }));
      setVariationInput('');
    }
  };

  const handleDelete = async (id: string) => {
      if(confirm('¿Estás seguro de eliminar este artículo?')) {
          await deleteProduct(id);
          loadProducts();
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.code) return;

    setLoading(true);
    try {
      await addProduct(formData as Product);
      alert('Producto guardado exitosamente');
      // Reset form
      setFormData({
        code: generateProductCode(),
        name: '',
        description: '',
        salePrice: 0,
        rentalPrice: 0,
        category: 'Disfraces',
        stock: 1,
        variations: [],
        isRentalAvailable: true,
        isSaleAvailable: false,
      });
      setView('list');
    } catch (error) {
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.code.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto pb-24 h-full flex flex-col">
      <header className="mb-6 flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3">
            <Box className="w-8 h-8 text-indigo-600" />
            Inventario
            </h1>
            <p className="text-slate-500 mt-1 text-sm">{view === 'list' ? 'Gestión de existencias' : 'Nuevo registro'}</p>
        </div>
        {view === 'list' ? (
            <Button onClick={() => setView('form')} className="shadow-xl shadow-indigo-200">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">Nuevo Artículo</span>
            </Button>
        ) : (
            <Button variant="secondary" onClick={() => setView('list')}>
                <ArrowLeft className="w-5 h-5" /> <span className="hidden sm:inline">Volver</span>
            </Button>
        )}
      </header>

      {view === 'list' ? (
          <div className="flex-1 overflow-hidden flex flex-col">
              {/* Filter Bar */}
              <div className="mb-6 flex gap-4">
                  <div className="relative flex-1">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                      <input 
                          type="text" 
                          placeholder="Buscar por código, nombre..." 
                          value={searchQuery}
                          onChange={(e) => setSearchQuery(e.target.value)}
                          className="w-full pl-12 pr-4 py-3 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
                      />
                  </div>
                  {/* Future: Filter Select */}
              </div>

              {/* Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-20">
                  {filteredProducts.map(product => (
                      <Card key={product.id} className="group hover:border-indigo-200 transition-all duration-300">
                          <div className="flex justify-between items-start mb-3">
                              <span className="font-mono text-xs bg-slate-100 px-2 py-1 rounded text-slate-500 font-bold">{product.code}</span>
                              <div className="flex gap-1">
                                  {product.isRentalAvailable && <Badge color="indigo">Renta</Badge>}
                                  {product.isSaleAvailable && <Badge color="green">Venta</Badge>}
                              </div>
                          </div>

                          <h3 className="font-bold text-lg text-slate-800 mb-1">{product.name}</h3>
                          <p className="text-sm text-slate-500 mb-4 line-clamp-2 min-h-[2.5rem]">{product.description || 'Sin descripción'}</p>

                          <div className="flex flex-wrap gap-2 mb-4">
                              {product.variations?.map((v,i) => (
                                  <span key={i} className="text-[10px] px-2 py-0.5 rounded-full border border-slate-200 text-slate-500">{v}</span>
                              ))}
                          </div>

                          <div className="flex items-end justify-between border-t border-slate-100 pt-3 mt-auto">
                              <div>
                                  <div className="text-xs text-slate-400 font-semibold uppercase">Stock</div>
                                  <div className="text-lg font-bold text-slate-800">{product.stock}</div>
                              </div>
                              <div className="text-right">
                                  {product.isRentalAvailable && <div className="text-sm text-indigo-600 font-semibold">R: ${product.rentalPrice}</div>}
                                  {product.isSaleAvailable && <div className="text-sm text-emerald-600 font-semibold">V: ${product.salePrice}</div>}
                              </div>
                          </div>

                          <button 
                            onClick={() => product.id && handleDelete(product.id)}
                            className="absolute top-4 right-4 opacity-0 group-hover:opacity-100 text-rose-400 hover:text-rose-600 transition-opacity bg-white/80 p-1 rounded-full"
                          >
                              <Trash2 className="w-4 h-4"/>
                          </button>
                      </Card>
                  ))}
                  {filteredProducts.length === 0 && (
                      <div className="col-span-full py-12 text-center text-slate-400">
                          No se encontraron artículos
                      </div>
                  )}
              </div>
          </div>
      ) : (
        /* Form View */
        <form onSubmit={handleSubmit} className="max-w-4xl mx-auto w-full animate-in slide-in-from-bottom-4 duration-500">
            <Card className="space-y-6">
            {/* Code Section */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex items-end gap-2">
                <Input 
                    label="Código (Aleatorio)" 
                    value={formData.code} 
                    readOnly 
                    className="bg-slate-50 font-mono text-lg tracking-widest text-center"
                />
                <Button type="button" variant="secondary" onClick={generateCode} className="mb-[1px]">
                    <RefreshCw className="w-5 h-5" />
                </Button>
                </div>

                <Input 
                label="Nombre del Artículo" 
                value={formData.name} 
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                placeholder="Ej. Traje de Spiderman"
                required
                />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Input 
                label="Descripción" 
                value={formData.description} 
                onChange={(e) => setFormData({...formData, description: e.target.value})}
                placeholder="Detalles del estado, material, etc."
                />
                <Select 
                label="Categoría"
                value={formData.category}
                onChange={(e) => setFormData({...formData, category: e.target.value})}
                >
                <option value="Disfraces">Disfraces</option>
                <option value="Accesorios">Accesorios</option>
                <option value="Decoración">Decoración</option>
                <option value="Venta General">Venta General</option>
                </Select>
            </div>

            {/* Pricing */}
            <div className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                <h3 className="text-sm font-bold text-indigo-900 uppercase tracking-wide mb-4 flex items-center gap-2">
                <DollarSign className="w-4 h-4" /> Precios y Disponibilidad
                </h3>
                <div className="grid grid-cols-2 gap-4">
                <div className="space-y-3">
                    <label className="flex items-center gap-2 p-3 bg-white rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300 transition-all">
                    <input 
                        type="checkbox" 
                        checked={formData.isRentalAvailable}
                        onChange={(e) => setFormData({...formData, isRentalAvailable: e.target.checked})}
                        className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500"
                    />
                    <span className="font-medium text-slate-700">Disponible Renta</span>
                    </label>
                    {formData.isRentalAvailable && (
                    <Input 
                        type="number" 
                        label="Costo Renta" 
                        placeholder="0.00"
                        value={formData.rentalPrice || ''}
                        onChange={(e) => setFormData({...formData, rentalPrice: parseFloat(e.target.value)})}
