export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: string[]; // e.g., ["S", "M", "L"] or ["Red", "Blue"]
