// --- Custom Touch Date Picker ---

interface DatePickerProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (date: string) => void;
  title: string;
}

export const DatePickerModal: React.FC<DatePickerProps> = ({ isOpen, onClose, onSelect, title }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  if (!isOpen) return null;

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const monthNames = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];

  const changeMonth = (delta: number) => {
    setCurrentDate(new Date(year, month + delta, 1));
  };

  const handleDayClick = (day: number) => {
    // Format YYYY-MM-DD
    const strMonth = (month + 1).toString().padStart(2, '0');
    const strDay = day.toString().padStart(2, '0');
    onSelect(`${year}-${strMonth}-${strDay}`);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden">
        {/* Header */}
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-start">
          <div>
            <h3 className="text-indigo-200 text-sm font-bold uppercase tracking-wider mb-1">{title}</h3>
            <div className="text-3xl font-bold">
              {monthNames[month]} {year}
            </div>
          </div>
          <button onClick={onClose} className="bg-white/20 p-2 rounded-full hover:bg-white/30 active:scale-95 transition-all">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Calendar Controls */}
        <div className="flex items-center justify-between p-4 border-b border-slate-100">
           <button onClick={() => changeMonth(-1)} className="p-3 hover:bg-slate-100 rounded-xl active:bg-slate-200 text-slate-600">
             <ChevronLeft className="w-6 h-6" />
           </button>
           <span className="font-bold text-slate-700">{monthNames[month]}</span>
           <button onClick={() => changeMonth(1)} className="p-3 hover:bg-slate-100 rounded-xl active:bg-slate-200 text-slate-600">
             <ChevronRight className="w-6 h-6" />
           </button>
        </div>

        {/* Grid */}
        <div className="p-4">
          <div className="grid grid-cols-7 mb-2 text-center">
             {['D','L','M','M','J','V','S'].map(d => (
               <div key={d} className="text-xs font-bold text-slate-400 py-1">{d}</div>
             ))}
          </div>
          <div className="grid grid-cols-7 gap-2">
            {[...Array(firstDayOfMonth)].map((_, i) => <div key={`empty-${i}`} />)}
            {[...Array(daysInMonth)].map((_, i) => {
              const day = i + 1;
              const isToday = new Date().getDate() === day && new Date().getMonth() === month && new Date().getFullYear() === year;
              return (
                <button
                  key={day}
                  onClick={() => handleDayClick(day)}
                  className={`h-10 w-10 rounded-xl flex items-center justify-center text-sm font-semibold transition-all active:scale-90 ${
                    isToday 
                      ? 'bg-indigo-100 text-indigo-700 border border-indigo-200' 
                      : 'hover:bg-slate-100 text-slate-700 bg-slate-50'
                  }`}
                >
                  {day}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight } from 'lucide-react';
import { Button, Input, Card, Badge, DatePickerModal } from '../components/UI';
import { Product, CartItem, Customer, Order } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer } from '../services/dataService';

const POS: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);

  // Form Data
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; // Sales only don't strictly require customer
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const p = await getProducts();
      const c = await getCustomers();
      setProducts(p);
      setCustomers(c);
    };
    fetchData();
  }, []);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent') => {
    const existing = cart.find(item => item.id === product.id && item.transactionType === type);

    if (existing) {
      setCart(cart.map(item => 
        (item.id === product.id && item.transactionType === type) 
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1 
      }]);
    }
  };

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Calculations
  const total = cart.reduce((sum, item) => {
    const price = item.transactionType === 'rent' ? item.rentalPrice : item.salePrice;
    return sum + (price * item.quantity);
  }, 0);

  // Customer Handling
  const handleQuickCustomerAdd = async () => {
    if(!newCustomerName) return;
    const newCus: Customer = {
        name: newCustomerName,
        phone: newCustomerPhone
    }
    const saved = await addCustomer(newCus);
    setCustomers([...customers, saved]);
    setSelectedCustomer(saved);
    setShowCustomerModal(false);
    setNewCustomerName('');
    setNewCustomerPhone('');
  }

  // Checkout
  const handleCheckout = async () => {
    if (!isCheckoutEnabled) return;

    const order: Omit<Order, 'id'> = {
      items: cart,
      total,
      status: 'pending',
      createdAt: Date.now(),
      customer: selectedCustomer || undefined,
      rentalStartDate: rentalDate ? new Date(rentalDate).getTime() : undefined,
      rentalEndDate: returnDate ? new Date(returnDate).getTime() : undefined,
    };

    await createOrder(order);
    alert("Venta registrada!");
    setCart([]);
    setSelectedCustomer(null);
    setRentalDate('');
    setReturnDate('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Buscar por nombre o código..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      {product.variations.map(v => <span key={v} className="text-[10px] bg-slate-50 px-1.5 rounded text-slate-500 border border-slate-100">{v}</span>)}
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => addToCart(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform"
                  >
                    <span>Rentar</span>
                    <span>${product.rentalPrice}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => addToCart(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform"
                  >
                    <span>Vender</span>
                    <span>${product.salePrice}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            Ticket Actual
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors">
            Limpiar
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p>El carrito está vacío</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.cartId} className="flex gap-4 p-3 bg-slate-50 rounded-2xl group">
                <div className="flex-1">
                  <div className="flex justify-between">
                     <h4 className="font-semibold text-slate-800">{item.name}</h4>
                     <span className="font-mono font-bold text-slate-700">
                        ${(item.transactionType === 'rent' ? item.rentalPrice : item.salePrice) * item.quantity}
                     </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                    </Badge>
                    <span className="text-xs text-slate-400">Cod: {item.code}</span>
                  </div>
                </div>

                <div className="flex flex-col items-center gap-2">
                    <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                        <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                        <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.cartId, 1)} className="p-2 hover:bg-slate-100 rounded-r-lg text-slate-500 active:bg-slate-200"><Plus className="w-4 h-4"/></button>
                    </div>
                    <button onClick={() => removeFromCart(item.cartId)} className="text-rose-400 hover:text-rose-600 p-2">
                        <Trash2 className="w-5 h-5" />
                    </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Rental & Customer Info */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-4">

          {/* Customer Selection Button (Large) */}
          {hasRentals && (
             <button 
                onClick={() => setShowCustomerModal(true)}
                className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all active:scale-95 shadow-sm ${
                    selectedCustomer 
                    ? 'bg-indigo-600 border-indigo-600 text-white' 
                    : 'bg-white border-dashed border-slate-300 text-slate-500 hover:border-indigo-400 hover:text-indigo-600'
                }`}
             >
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${selectedCustomer ? 'bg-white/20' : 'bg-slate-100'}`}>
                        <User className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                        <div className="text-xs font-bold uppercase tracking-wider opacity-80">
                            {selectedCustomer ? 'Cliente Asignado' : 'Asignar Cliente (Requerido)'}
