                    </div>
                    {!rentalDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
                <div onClick={() => setShowEndDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">Fecha Devolución</span>
                    <div className="flex items-center gap-2">
                         <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!returnDate && 'text-slate-400'}`}>{returnDate || 'Seleccionar'}</span>
                    </div>
                    {!returnDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
