// --- Custom Touch Date Picker ---

interface DatePickerProps {
  isOpen: boolean;
  onClose: () => void;
  onSelect: (date: string) => void;
  title: string;
}

export const DatePickerModal: React.FC<DatePickerProps> = ({ isOpen, onClose, onSelect, title }) => {
  const [currentDate, setCurrentDate] = useState(new Date());

  if (!isOpen) return null;

  const year = currentDate.getFullYear();
  const month = currentDate.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayOfMonth = new Date(year, month, 1).getDay();

  const monthNames = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];

  const changeMonth = (delta: number) => {
    setCurrentDate(new Date(year, month + delta, 1));
  };

  const handleDayClick = (day: number) => {
    // Format YYYY-MM-DD
    const strMonth = (month + 1).toString().padStart(2, '0');
    const strDay = day.toString().padStart(2, '0');
    onSelect(`${year}-${strMonth}-${strDay}`);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in">
      <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden">
        {/* Header */}
        <div className="bg-indigo-600 p-6 text-white flex justify-between items-start">
          <div>
            <h3 className="text-indigo-200 text-sm font-bold uppercase tracking-wider mb-1">{title}</h3>
            <div className="text-3xl font-bold">
              {monthNames[month]} {year}
            </div>
          </div>
          <button onClick={onClose} className="bg-white/20 p-2 rounded-full hover:bg-white/30 active:scale-95 transition-all">
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Calendar Controls */}
        <div className="flex items-center justify-between p-4 border-b border-slate-100">
           <button onClick={() => changeMonth(-1)} className="p-3 hover:bg-slate-100 rounded-xl active:bg-slate-200 text-slate-600">
             <ChevronLeft className="w-6 h-6" />
           </button>
           <span className="font-bold text-slate-700">{monthNames[month]}</span>
           <button onClick={() => changeMonth(1)} className="p-3 hover:bg-slate-100 rounded-xl active:bg-slate-200 text-slate-600">
             <ChevronRight className="w-6 h-6" />
           </button>
        </div>

        {/* Grid */}
        <div className="p-4">
          <div className="grid grid-cols-7 mb-2 text-center">
             {['D','L','M','M','J','V','S'].map(d => (
               <div key={d} className="text-xs font-bold text-slate-400 py-1">{d}</div>
             ))}
          </div>
          <div className="grid grid-cols-7 gap-2">
            {[...Array(firstDayOfMonth)].map((_, i) => <div key={`empty-${i}`} />)}
            {[...Array(daysInMonth)].map((_, i) => {
              const day = i + 1;
              const isToday = new Date().getDate() === day && new Date().getMonth() === month && new Date().getFullYear() === year;
              return (
                <button
                  key={day}
                  onClick={() => handleDayClick(day)}
                  className={`h-10 w-10 rounded-xl flex items-center justify-center text-sm font-semibold transition-all active:scale-90 ${
                    isToday 
                      ? 'bg-indigo-100 text-indigo-700 border border-indigo-200' 
                      : 'hover:bg-slate-100 text-slate-700 bg-slate-50'
                  }`}
                >
                  {day}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers, Search, Trash2, ArrowLeft, Filter } from 'lucide-react';
import { Button, Input, Select, Card, Badge } from '../components/UI';
import { Product, Variation } from '../types';
import { generateProductCode, addProduct, getProducts, deleteProduct } from '../services/dataService';

const Inventory: React.FC = () => {
  const [view, setView] = useState<'list' | 'form'>('list');
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    code: generateProductCode(),
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'Disfraces',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
  });

  // New Variation Input State
  const [newVarName, setNewVarName] = useState('');
  const [newVarRent, setNewVarRent] = useState('');
  const [newVarSale, setNewVarSale] = useState('');

  // Load Data
  const loadProducts = async () => {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setLoading(false);
  };

  useEffect(() => {
    if (view === 'list') {
        loadProducts();
    }
  }, [view]);

  // Actions
  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  const handleVariationAdd = () => {
    if (!newVarName.trim()) return;

    const newVariation: Variation = {
      name: newVarName.trim(),
    };

    if (newVarRent) newVariation.rentalPrice = parseFloat(newVarRent);
    if (newVarSale) newVariation.salePrice = parseFloat(newVarSale);

    setFormData(prev => ({
      ...prev,
      variations: [...(prev.variations || []), newVariation]
    }));

    setNewVarName('');
    setNewVarRent('');
    setNewVarSale('');
  };

  const removeVariation = (index: number) => {
    setFormData(prev => ({
      ...prev,
      variations: prev.variations?.filter((_, i) => i !== index)
    }));
  };

  const handleDelete = async (id: string) => {
      if(confirm('¿Estás seguro de eliminar este artículo?')) {
          await deleteProduct(id);
          loadProducts();
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.code) return;

    setLoading(true);
    try {
      await addProduct(formData as Product);
      alert('Producto guardado exitosamente');
      // Reset form
      setFormData({
        code: generateProductCode(),
        name: '',
        description: '',
        salePrice: 0,
        rentalPrice: 0,
        category: 'Disfraces',
        stock: 1,
        variations: [],
        isRentalAvailable: true,
        isSaleAvailable: false,
      });
      setView('list');
    } catch (error) {
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.code.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto pb-24 h-full flex flex-col">
      <header className="mb-6 flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3">
            <Box className="w-8 h-8 text-indigo-600" />
            Inventario
            </h1>
            <p className="text-slate-500 mt-1 text-sm">{view === 'list' ? 'Gestión de existencias' : 'Nuevo registro'}</p>
        </div>
        {view === 'list' ? (
            <Button onClick={() => setView('form')} className="shadow-xl shadow-indigo-200">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">Nuevo Artículo</span>
            </Button>
        ) : (
            <Button variant="secondary" onClick={() => setView('list')}>
                <ArrowLeft className="w-5 h-5" /> <span className="hidden sm:inline">Volver</span>
            </Button>
        )}
      </header>

      {view === 'list' ? (
          <div className="flex-1 overflow-hidden flex flex-col">
              {/* Filter Bar */}
              <div className="mb-6 flex gap-4">
                  <div className="relative flex-1">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                      <input 
                          type="text" 
                          placeholder="Buscar por código, nombre..." 
                          value={searchQuery}
                          onChange={(e) => setSearchQuery(e.target.value)}
                          className="w-full pl-12 pr-4 py-3 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
                      />
                  </div>
              </div>

              {/* Grid */}
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto pb-20">
                  {filteredProducts.map(product => (
                      <Card key={product.id} className="group hover:border-indigo-200 transition-all duration-300 relative">
                          <div className="flex justify-between items-start mb-3">
                              <span className="font-mono text-xs bg-slate-100 px-2 py-1 rounded text-slate-500 font-bold">{product.code}</span>
                              <div className="flex gap-1">
                                  {product.isRentalAvailable && <Badge color="indigo">Renta</Badge>}
                                  {product.isSaleAvailable && <Badge color="green">Venta</Badge>}
                              </div>
                          </div>

                          <h3 className="font-bold text-lg text-slate-800 mb-1">{product.name}</h3>
                          <p className="text-sm text-slate-500 mb-4 line-clamp-2 min-h-[2.5rem]">{product.description || 'Sin descripción'}</p>

                          <div className="flex flex-wrap gap-2 mb-4">
                              {product.variations?.map((v,i) => {
                                const label = typeof v === 'string' ? v : v.name; // Backward compatibility
                                return (
                                  <span key={i} className="text-[10px] px-2 py-0.5 rounded-full border border-slate-200 text-slate-500">{label}</span>
                                );
                              })}
                          </div>

                          <div className="flex items-end justify-between border-t border-slate-100 pt-3 mt-auto">
                              <div>
                                  <div className="text-xs text-slate-400 font-semibold uppercase">Stock</div>
                                  <div className="text-lg font-bold text-slate-800">{product.stock}</div>
                              </div>
                              <div className="text-right">
                                  {product.isRentalAvailable && <div className="text-sm text-indigo-600 font-semibold">R: ${product.rentalPrice}</div>}
                                  {product.isSaleAvailable && <div className="text-sm text-emerald-600 font-semibold">V: ${product.salePrice}</div>}
                              </div>
                          </div>

                          {/* Large touch-friendly delete button */}
                          <button 
                            onClick={(e) => { e.stopPropagation(); product.id && handleDelete(product.id); }}
                            className="absolute top-2 right-2 p-3 bg-white/90 shadow-sm rounded-full text-rose-300 hover:text-rose-600 hover:bg-white active:scale-95 transition-all opacity-0 group-hover:opacity-100"
                          >
                              <Trash2 className="w-5 h-5"/>
                          </button>
                      </Card>
                  ))}
                  {filteredProducts.length === 0 && (
                      <div className="col-span-full py-12 text-center text-slate-400">
                          No se encontraron artículos
                      </div>
                  )}
              </div>
          </div>
      ) : (
        /* Form View */
        <form onSubmit={handleSubmit} className="max-w-4xl mx-auto w-full animate-in slide-in-from-bottom-4 duration-500">
            <Card className="space-y-6">
            {/* Code Section */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="flex items-end gap-2">
                <Input 
                    label="Código (Aleatorio)" 
                    value={formData.code} 
                    readOnly 
                    className="bg-slate-50 font-mono text-lg tracking-widest text-center"
                />
                <Button type="button" variant="secondary" onClick={generateCode} className="mb-[1px]">
                    <RefreshCw className="w-5 h-5" />
                </Button>
                </div>

                <Input 
                label="Nombre del Artículo" 
                value={formData.name} 
                onChange={(e) => setFormData({...formData, name: e.target.value})}
                placeholder="Ej. Traje de Spiderman"
                required
                />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <Input 
                label="Descripción" 
                value={formData.description} 
                onChange={(e) => setFormData({...formData, description: e.target.value})}
                placeholder="Detalles del estado, material, etc."
                />
                <Select 
                label="Categoría"
                value={formData.category}
                onChange={(e) => setFormData({...formData, category: e.target.value})}
                >
                <option value="Disfraces">Disfraces</option>
                <option value="Accesorios">Accesorios</option>
                <option value="Decoración">Decoración</option>
                <option value="Venta General">Venta General</option>
                </Select>
            </div>

            {/* Pricing */}
            <div className="p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                <h3 className="text-sm font-bold text-indigo-900 uppercase tracking-wide mb-4 flex items-center gap-2">
                <DollarSign className="w-4 h-4" /> Precios Base
                </h3>
                <div className="grid grid-cols-2 gap-4">
                <div className="space-y-3">
                    <label className="flex items-center gap-2 p-3 bg-white rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300 transition-all">
                    <input 
                        type="checkbox" 
                        checked={formData.isRentalAvailable}
                        onChange={(e) => setFormData({...formData, isRentalAvailable: e.target.checked})}
                        className="w-5 h-5 text-indigo-600 rounded focus:ring-indigo-500"
                    />
                    <span className="font-medium text-slate-700">Disponible Renta</span>
                    </label>
                    {formData.isRentalAvailable && (
                    <Input 
                        type="number" 
                        label="Costo Renta Base" 
                        placeholder="0.00"
                        value={formData.rentalPrice || ''}
                        onChange={(e) => setFormData({...formData, rentalPrice: parseFloat(e.target.value)})}
                    />
                    )}
                </div>

                <div className="space-y-3">
                    <label className="flex items-center gap-2 p-3 bg-white rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300 transition-all">
                    <input 
                        type="checkbox" 
                        checked={formData.isSaleAvailable}
                        onChange={(e) => setFormData({...formData, isSaleAvailable: e.target.checked})}
                        className="w-5 h-5 text-emerald-600 rounded focus:ring-emerald-500"
                    />
                    <span className="font-medium text-slate-700">Disponible Venta</span>
                    </label>
                    {formData.isSaleAvailable && (
                    <Input 
                        type="number" 
                        label="Costo Venta Base" 
                        placeholder="0.00"
                        value={formData.salePrice || ''}
                        onChange={(e) => setFormData({...formData, salePrice: parseFloat(e.target.value)})}
                    />
                    )}
                </div>
                </div>
            </div>

            {/* Variations */}
            <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100">
                <div className="flex items-center gap-2 mb-4">
                  <Layers className="w-5 h-5 text-slate-500" />
                  <h3 className="text-sm font-bold text-slate-700 uppercase tracking-wide">Variaciones (Tallas/Colores)</h3>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-4 gap-3 items-end mb-4">
                  <div className="md:col-span-2">
                     <Input 
                       label="Nombre (Ej. Talla XL)" 
                       value={newVarName}
                       onChange={e => setNewVarName(e.target.value)}
                     />
                  </div>
                  {formData.isRentalAvailable && (
                    <div>
                      <Input 
                        label="Precio Renta (Opcional)" 
                        type="number" 
                        placeholder={`Base: $${formData.rentalPrice || 0}`}
                        value={newVarRent}
                        onChange={e => setNewVarRent(e.target.value)}
