import React, { useState, useEffect, useMemo } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight } from 'lucide-react';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer } from '../services/dataService';

const POS: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Form Data
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; // Sales only don't strictly require customer
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const p = await getProducts();
      const c = await getCustomers();
      setProducts(p);
      setCustomers(c);
    };
    fetchData();
  }, []);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation) => {

    // Determine price
    let price = type === 'rent' ? product.rentalPrice : product.salePrice;
    if (variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    // Unique Cart Key (Product + Variation)
    const variationId = variation ? variation.name : 'base';
    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name)
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        selectedVariation: variation,
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Calculations
  const total = cart.reduce((sum, item) => {
    return sum + (item.appliedPrice * item.quantity);
  }, 0);

  // Customer Handling
  const handleQuickCustomerAdd = async () => {
    if(!newCustomerName) return;
    const newCus: Customer = {
        name: newCustomerName,
        phone: newCustomerPhone
    }
    const saved = await addCustomer(newCus);
    setCustomers([...customers, saved]);
    setSelectedCustomer(saved);
    setShowCustomerModal(false);
    setNewCustomerName('');
    setNewCustomerPhone('');
  }

  // Checkout
  const handleCheckout = async () => {
    if (!isCheckoutEnabled) return;

    const order: Omit<Order, 'id'> = {
      items: cart,
      total,
      status: 'pending',
      createdAt: Date.now(),
      customer: selectedCustomer || undefined,
      rentalStartDate: rentalDate ? new Date(rentalDate).getTime() : undefined,
      rentalEndDate: returnDate ? new Date(returnDate).getTime() : undefined,
    };

    await createOrder(order);
    alert("Venta registrada!");
    setCart([]);
    setSelectedCustomer(null);
    setRentalDate('');
    setReturnDate('');
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="Buscar por nombre o código..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                        {product.variations.length} variaciones
                      </span>
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform"
                  >
                    <span>Rentar</span>
                    <span>${product.rentalPrice}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform"
                  >
                    <span>Vender</span>
                    <span>${product.salePrice}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            Ticket Actual
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors">
            Limpiar
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p>El carrito está vacío</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.cartId} className="flex gap-4 p-3 bg-slate-50 rounded-2xl group">
                <div className="flex-1">
                  <div className="flex justify-between">
                     <div>
                       <h4 className="font-semibold text-slate-800 leading-tight">{item.name}</h4>
                       {item.selectedVariation && (
                         <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                            {item.selectedVariation.name}
                         </div>
                       )}
                     </div>
                     <span className="font-mono font-bold text-slate-700">
                        ${item.appliedPrice * item.quantity}
                     </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
