            <div className="space-y-4">
                <Input placeholder="Nombre Completo" value={newCustomerName} onChange={e => setNewCustomerName(e.target.value)} />
                <Input placeholder="Teléfono" value={newCustomerPhone} onChange={e => setNewCustomerPhone(e.target.value)} />
                <div className="flex gap-3 mt-4">
                    <Button variant="secondary" onClick={() => setShowCustomerModal(false)} className="flex-1 py-4">Cancelar</Button>
                    <Button onClick={handleQuickCustomerAdd} className="flex-1 py-4">Guardar y Asignar</Button>
                </div>
            </div>
          </div>
      </Modal>

      {/* Variation Selection Modal */}
      <Modal 
        isOpen={!!variationModalData} 
        onClose={() => setVariationModalData(null)} 
        title={`Seleccionar Variación`}
      >
        <div className="space-y-4">
           <p className="text-sm text-slate-500">
             Elige la variante para <strong>{variationModalData?.product.name}</strong> ({variationModalData?.type === 'rent' ? 'Renta' : 'Venta'})
           </p>
           <div className="grid grid-cols-1 gap-3">
             {variationModalData?.product.variations?.map((v, i) => {
               const vName = typeof v === 'string' ? v : v.name;
               let vPrice = variationModalData?.type === 'rent' 
                  ? variationModalData.product.rentalPrice 
                  : variationModalData.product.salePrice;

               // Override if pricing exists
               if (typeof v !== 'string') {
                  if (variationModalData?.type === 'rent' && v.rentalPrice) vPrice = v.rentalPrice;
                  if (variationModalData?.type === 'sale' && v.salePrice) vPrice = v.salePrice;
               }

               return (
                 <button 
                   key={i}
                   onClick={() => handleVariationSelect(typeof v === 'string' ? {name: v} : v)}
                   className="flex justify-between items-center p-4 rounded-xl border border-slate-200 hover:border-indigo-500 hover:bg-indigo-50 transition-all active:scale-95"
                 >
                    <span className="font-bold text-slate-800">{vName}</span>
                    <span className="font-mono font-medium text-indigo-600">${vPrice}</span>
                 </button>
               );
             })}
           </div>
           <div className="pt-2">
             <Button variant="ghost" onClick={() => setVariationModalData(null)} className="w-full">Cancelar</Button>
           </div>
        </div>
      </Modal>
    </div>
  );
};

