      setView('list');
    } catch (error) {
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  // --- CSV Import Logic ---

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const parseLoyverseCSV = (text: string) => {
    const lines = text.split('\n');
    if (lines.length < 2) return [];

    // Simple CSV parser that handles quotes is complex, 
    // assuming standard Loyverse export which usually uses commas.
    // If Loyverse uses semicolons in your region, adjust split(',') to split(';').
    const headers = lines[0].split(',').map(h => h.trim().replace(/^"|"$/g, '').toLowerCase());

    // Map headers to indices
    const idxName = headers.findIndex(h => h === 'name' || h === 'item name');
    const idxCat = headers.findIndex(h => h === 'category');
    const idxSku = headers.findIndex(h => h === 'sku' || h === 'reference');
    const idxPrice = headers.findIndex(h => h === 'price');
    const idxStock = headers.findIndex(h => h === 'in stock' || h === 'stock');
    const idxVarName = headers.findIndex(h => h === 'option1 name' || h === 'option1 value');
    const idxVarVal = headers.findIndex(h => h === 'option1 value');

    const groupedProducts: Record<string, Partial<Product>> = {};

    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        // Handle basic comma separation (Warning: breaks if Name has comma inside quotes)
        // For a robust solution, a library like PapaParse is recommended, but kept simple here.
        const row = line.split(',').map(c => c.trim().replace(/^"|"$/g, ''));

        const name = row[idxName];
        if (!name) continue;

        if (!groupedProducts[name]) {
            groupedProducts[name] = {
                name: name,
                category: idxCat > -1 ? (row[idxCat] || 'Venta General') : 'Venta General',
                description: '',
                code: (idxSku > -1 && row[idxSku]) ? row[idxSku] : generateProductCode(),
                salePrice: idxPrice > -1 ? parseFloat(row[idxPrice]) || 0 : 0,
                rentalPrice: 0, // Default to 0 for imported items
                stock: idxStock > -1 ? parseFloat(row[idxStock]) || 0 : 0,
                isSaleAvailable: true,
                isRentalAvailable: false, // Default false for safety
                variations: []
            };
        }

        // If it's a variation
        if (idxVarVal > -1 && row[idxVarVal]) {
            const variantPrice = idxPrice > -1 ? parseFloat(row[idxPrice]) || 0 : 0;
            const variantName = row[idxVarVal];

            // Add to variations array
            groupedProducts[name].variations?.push({
                name: variantName,
                salePrice: variantPrice
            });
        }
    }

    return Object.values(groupedProducts);
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

