                  )}
                  {formData.isSaleAvailable && (
                    <div>
                      <Input 
                        label="Precio Venta (Opcional)" 
                        type="number" 
                        placeholder={`Base: $${formData.salePrice || 0}`}
                        value={newVarSale}
                        onChange={e => setNewVarSale(e.target.value)}
                        className="text-sm"
                      />
                    </div>
                  )}
                  <div className="md:col-span-4 flex justify-end">
                    <Button type="button" variant="secondary" onClick={handleVariationAdd} disabled={!newVarName}>
                      <Plus className="w-4 h-4" /> Agregar Variación
                    </Button>
                  </div>
                </div>

                <div className="flex flex-wrap gap-2">
                    {formData.variations?.map((v, i) => (
                    <span key={i} className="bg-white border border-slate-200 pl-3 pr-2 py-2 rounded-xl text-sm flex items-center gap-3 shadow-sm">
                        <div className="flex flex-col">
                           <span className="font-bold text-slate-700">{v.name}</span>
                           <span className="text-[10px] text-slate-500 flex gap-2">
                              {v.rentalPrice && <span className="text-indigo-600">R: ${v.rentalPrice}</span>}
                              {v.salePrice && <span className="text-emerald-600">V: ${v.salePrice}</span>}
                              {!v.rentalPrice && !v.salePrice && <span>Precio Base</span>}
                           </span>
                        </div>
                        <button 
                          type="button"
                          onClick={() => removeVariation(i)}
                          className="text-slate-400 hover:text-rose-500 p-1"
                        >
                        &times;
                        </button>
                    </span>
                    ))}
                    {(!formData.variations || formData.variations.length === 0) && (
                      <span className="text-sm text-slate-400 italic">Sin variaciones registradas.</span>
                    )}
                </div>
            </div>

            <div className="grid grid-cols-1">
                <Input 
                type="number" 
                label="Stock Inicial General" 
                value={formData.stock}
                onChange={(e) => setFormData({...formData, stock: parseInt(e.target.value)})}
                min="1"
                />
            </div>

            <div className="pt-4 flex justify-end">
                <Button type="submit" disabled={loading} className="w-full md:w-auto">
                {loading ? 'Guardando...' : 'Guardar Artículo'}
                </Button>
            </div>
            </Card>
        </form>
      )}
    </div>
  );
};

export default Inventory;

import React, { useState, useEffect, useRef } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers, Search, Trash2, ArrowLeft, Upload, FileUp } from 'lucide-react';
import { Button, Input, Select, Card, Badge } from '../components/UI';
import { Product, Variation } from '../types';
import { generateProductCode, addProduct, getProducts, deleteProduct, importProductsBatch } from '../services/dataService';

const Inventory: React.FC = () => {
  const [view, setView] = useState<'list' | 'form'>('list');
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');

  // File Import Ref
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Product>>({
    code: generateProductCode(),
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'Disfraces',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
  });

  // New Variation Input State
  const [newVarName, setNewVarName] = useState('');
  const [newVarRent, setNewVarRent] = useState('');
  const [newVarSale, setNewVarSale] = useState('');

  // Load Data
  const loadProducts = async () => {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setLoading(false);
  };

  useEffect(() => {
    if (view === 'list') {
        loadProducts();
    }
  }, [view]);

  // Actions
  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  const handleVariationAdd = () => {
    if (!newVarName.trim()) return;

    const newVariation: Variation = {
      name: newVarName.trim(),
    };

    if (newVarRent) newVariation.rentalPrice = parseFloat(newVarRent);
    if (newVarSale) newVariation.salePrice = parseFloat(newVarSale);

    setFormData(prev => ({
      ...prev,
      variations: [...(prev.variations || []), newVariation]
    }));

    setNewVarName('');
    setNewVarRent('');
    setNewVarSale('');
  };

  const removeVariation = (index: number) => {
    setFormData(prev => ({
      ...prev,
      variations: prev.variations?.filter((_, i) => i !== index)
    }));
  };

  const handleDelete = async (id: string) => {
      if(confirm('¿Estás seguro de eliminar este artículo?')) {
          await deleteProduct(id);
          loadProducts();
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.code) return;

    setLoading(true);
    try {
      await addProduct(formData as Product);
      alert('Producto guardado exitosamente');
      // Reset form
      setFormData({
        code: generateProductCode(),
        name: '',
        description: '',
        salePrice: 0,
        rentalPrice: 0,
        category: 'Disfraces',
        stock: 1,
        variations: [],
        isRentalAvailable: true,
        isSaleAvailable: false,
      });
      setView('list');
    } catch (error) {
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  // --- CSV Import Logic ---

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const parseLoyverseCSV = (text: string) => {
    // Robust CSV Line Splitter that handles quoted values containing commas or newlines
    const splitCSVLine = (str: string) => {
        const matches = [];
        let inQuote = false;
        let buffer = '';
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            if (c === '"') {
                inQuote = !inQuote;
            } else if (c === ',' && !inQuote) {
                matches.push(buffer);
                buffer = '';
            } else {
                buffer += c;
            }
        }
        matches.push(buffer);
        return matches.map(m => m.trim().replace(/^"|"$/g, '').replace(/""/g, '"'));
    };

    const lines = text.split(/\r\n|\n/);
    if (lines.length < 2) return [];

    // 1. Map Headers
    const headers = splitCSVLine(lines[0]).map(h => h.toLowerCase());

    const idxHandle = headers.findIndex(h => h === 'handle');
    const idxName = headers.findIndex(h => h === 'nombre');
    const idxCat = headers.findIndex(h => h === 'categoria');
    const idxRef = headers.findIndex(h => h === 'ref'); // Uses REF as code
    const idxDesc = headers.findIndex(h => h.includes('descripción'));

    // Fuzzy match for Price and Stock columns (ignoring store name brackets)
    const idxPrice = headers.findIndex(h => h.includes('precio'));
    const idxStock = headers.findIndex(h => h.includes('en inventario') || h.includes('stock'));

    // Variation Columns
    const idxOpt1Val = headers.findIndex(h => h === 'opción 1 valor' || h === 'option1 value');

    if (idxHandle === -1 || idxName === -1) {
        console.error("Columnas faltantes: Handle o Nombre son requeridas.");
        return [];
    }

    // 2. Group Rows by Handle
    const grouped: Record<string, any[]> = {};

    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const row = splitCSVLine(line);
        // Safety check if row has enough columns (at least up to handle)
        if (row.length <= idxHandle) continue;

        const handle = row[idxHandle];
        if (!handle) continue;

        if (!grouped[handle]) {
            grouped[handle] = [];
        }
        grouped[handle].push(row);
    }

    // 3. Convert Groups to Products
    const products: Partial<Product>[] = [];

    Object.keys(grouped).forEach(handle => {
        const rows = grouped[handle];
        const mainRow = rows[0]; // Usually first row has the general info

        // Sometimes Name is only in the first row, subsequent rows might be variants
        const nameRow = rows.find(r => r[idxName]) || mainRow;

        const productName = nameRow[idxName] || 'Sin Nombre';
        const category = (idxCat > -1 ? nameRow[idxCat] : 'Venta General') || 'Venta General';
        const description = idxDesc > -1 ? nameRow[idxDesc] : '';
        const code = (idxRef > -1 && mainRow[idxRef]) ? mainRow[idxRef] : handle;

        const variations: Variation[] = [];
        let totalStock = 0;
        let basePrice = 0;

        rows.forEach(row => {
            // Parse numeric values
            const stockVal = idxStock > -1 ? parseFloat(row[idxStock]) : 0;
            const priceValString = idxPrice > -1 ? row[idxPrice] : '0';
            const priceVal = isNaN(parseFloat(priceValString)) ? 0 : parseFloat(priceValString);

            if (!isNaN(stockVal)) totalStock += stockVal;

            // Check for variation
            const optVal = idxOpt1Val > -1 ? row[idxOpt1Val] : '';

            if (optVal) {
                variations.push({
                    name: optVal,
                    salePrice: priceVal,
                    rentalPrice: 0 // Default, needs manual update or different logic
                });
            } else {
                // If it's a row without variation option, it's the base price
                if (priceVal > 0) basePrice = priceVal;
            }
        });

        // Fallback: If basePrice is 0 but we have variations, use the first variation's price
        if (basePrice === 0 && variations.length > 0) {
            basePrice = variations[0].salePrice || 0;
        }

        products.push({
            name: productName,
            code: code,
            category: category,
            description: description,
            stock: totalStock,
            salePrice: basePrice,
            rentalPrice: 0, // Defaults to 0 for safety
            isSaleAvailable: true,
            isRentalAvailable: false,
            variations: variations
        });
    });

    return products;
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'text/csv' && !file.name.endsWith('.csv')) {
        alert('Por favor sube un archivo CSV válido.');
        return;
    }

    setLoading(true);
    const reader = new FileReader();

    reader.onload = async (e) => {
        try {
            const text = e.target?.result as string;
            const parsedProducts = parseLoyverseCSV(text);

            if (parsedProducts.length === 0) {
                alert('No se encontraron productos válidos. Verifique que el archivo tenga columnas "Handle" y "Nombre".');
                setLoading(false);
                return;
            }

            const count = await importProductsBatch(parsedProducts as Omit<Product, 'id'>[]);
            alert(`¡Importación exitosa! Se procesaron ${parsedProducts.length} items y se guardaron ${count} productos en la base de datos.`);
            loadProducts();

        } catch (error) {
            console.error(error);
            alert('Hubo un error al procesar el archivo. Revise la consola para más detalles.');
        } finally {
            setLoading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    reader.readAsText(file);
  };

  const filteredProducts = products.filter(p => 
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.code.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto pb-24 h-full flex flex-col">
