import React, { useState, useEffect } from 'react';
import { Users, Search, Phone, Mail, Plus, Trash2, Pencil } from 'lucide-react';
import { Button, Input, Card } from '../components/UI';
import { Customer } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer } from '../services/dataService';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // New Customer Form State
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newEmail, setNewEmail] = useState('');

  const loadCustomers = async () => {
    setLoading(true);
    const data = await getCustomers();
    setCustomers(data);
    setLoading(false);
  };

  useEffect(() => {
    loadCustomers();
  }, []);

  const handleNewCustomerClick = () => {
      // Clear form and open
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewEmail('');
      setShowForm(true); // Ensure open if closed, or just resets if open
      if(showForm && !editingId) setShowForm(false); // Toggle behavior if strictly just adding
      else setShowForm(true);
  };

  const handleEditClick = (customer: Customer) => {
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewEmail(customer.email || '');
      setShowForm(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            email: newEmail
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewEmail('');
        setShowForm(false);
        setEditingId(null);
        loadCustomers();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  const handleDelete = async (id: string) => {
      if(confirm('¿Eliminar cliente permanentemente?')) {
          await deleteCustomer(id);
          loadCustomers();
          if (editingId === id) {
              setShowForm(false);
              setEditingId(null);
          }
      }
  };

  const filtered = customers.filter(c => 
      c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.phone.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-6xl mx-auto pb-24 min-h-full flex flex-col">
      <header className="mb-8 flex justify-between items-end">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3">
            <Users className="w-8 h-8 text-indigo-600" />
            Clientes
           </h1>
           <p className="text-slate-500 mt-2">Directorio y alta de clientes</p>
        </div>

        <div className="flex gap-4 items-center">
            <div className="text-right hidden sm:block">
                <div className="text-2xl font-bold text-slate-800">{customers.length}</div>
                <div className="text-xs text-slate-400 uppercase font-bold">Total</div>
            </div>
            <Button onClick={handleNewCustomerClick} variant={showForm && !editingId ? 'secondary' : 'primary'}>
                {showForm && !editingId ? 'Cancelar' : 'Nuevo Cliente'}
            </Button>
        </div>
      </header>

      <div className="flex-1 flex flex-col md:flex-row gap-6 overflow-hidden">
        {/* Left: List */}
        <div className="flex-1 flex flex-col overflow-hidden">
             <div className="relative mb-4">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder="Buscar cliente..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                    className="w-full pl-12 pr-4 py-3 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all"
                />
            </div>

            <div className="flex-1 overflow-y-auto space-y-3 pb-20">
                {filtered.map(customer => (
                    <Card key={customer.id} className={`flex items-center justify-between group hover:border-indigo-200 transition-colors ${editingId === customer.id ? 'border-indigo-500 ring-2 ring-indigo-100' : ''}`}>
                        <div className="flex items-center gap-4 cursor-pointer flex-1" onClick={() => handleEditClick(customer)}>
                            <div className="w-10 h-10 rounded-full bg-indigo-50 text-indigo-600 flex items-center justify-center font-bold text-lg">
                                {customer.name.charAt(0).toUpperCase()}
                            </div>
                            <div>
                                <h3 className="font-bold text-slate-800">{customer.name}</h3>
                                <div className="flex flex-col sm:flex-row gap-1 sm:gap-4 text-sm text-slate-500">
                                    {customer.phone && (
                                        <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {customer.phone}</span>
                                    )}
                                    {customer.email && (
                                        <span className="flex items-center gap-1"><Mail className="w-3 h-3" /> {customer.email}</span>
                                    )}
                                </div>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                            <button 
                                onClick={() => handleEditClick(customer)}
                                className="p-4 bg-slate-50 rounded-xl text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 transition-all active:scale-95"
                                title="Editar"
                            >
                                <Pencil className="w-5 h-5" />
                            </button>
                            <button 
                                onClick={(e) => { e.stopPropagation(); customer.id && handleDelete(customer.id); }}
                                className="p-4 bg-slate-50 rounded-xl text-slate-400 hover:text-rose-500 hover:bg-rose-50 transition-all active:scale-95"
                                title="Eliminar"
                            >
                                <Trash2 className="w-5 h-5" />
                            </button>
                        </div>
                    </Card>
                ))}
                {filtered.length === 0 && (
                    <div className="text-center py-10 text-slate-400">
                        No se encontraron clientes
                    </div>
                )}
            </div>
        </div>

        {/* Right: Form (Desktop) or Modal logic */}
        {showForm && (
            <div className="w-full md:w-96 animate-in slide-in-from-right duration-300">
                <Card className={`bg-white border-l-4 ${editingId ? 'border-l-amber-500' : 'border-l-indigo-500'}`}>
                    <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
                        {editingId ? <Pencil className="w-5 h-5 text-amber-500" /> : <Plus className="w-5 h-5 text-indigo-600" />}
                        {editingId ? 'Editar Cliente' : 'Registrar Cliente'}
                    </h3>
                    <form onSubmit={handleSubmit} className="space-y-4">
                        <Input 
                            label="Nombre Completo" 
                            placeholder="Ej. Juan Pérez" 
                            value={newName}
