                    : 'bg-white border-dashed border-slate-300 text-slate-500 hover:border-indigo-400 hover:text-indigo-600'
                }`}
             >
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${selectedCustomer ? 'bg-white/20' : 'bg-slate-100'}`}>
                        <User className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                        <div className="text-xs font-bold uppercase tracking-wider opacity-80">
                            {selectedCustomer ? 'Cliente Asignado' : 'Asignar Cliente (Requerido)'}
                        </div>
                        <div className="font-bold text-lg leading-tight">
                            {selectedCustomer ? selectedCustomer.name : 'Seleccionar...'}
                        </div>
                    </div>
                </div>
                {selectedCustomer ? (
                     <div onClick={(e) => { e.stopPropagation(); setSelectedCustomer(null); }} className="p-2 bg-white/20 rounded-full hover:bg-white/30">
                        <Trash2 className="w-5 h-5" />
                     </div>
                ) : (
                    <ChevronRight className="w-6 h-6" />
                )}
             </button>
          )}

          {hasRentals && (
            <div className="grid grid-cols-2 gap-3">
                <div onClick={() => setShowStartDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">Fecha Entrega</span>
                    <div className="flex items-center gap-2">
                        <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!rentalDate && 'text-slate-400'}`}>{rentalDate || 'Seleccionar'}</span>
                    </div>
                    {!rentalDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
                <div onClick={() => setShowEndDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">Fecha Devolución</span>
                    <div className="flex items-center gap-2">
                         <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!returnDate && 'text-slate-400'}`}>{returnDate || 'Seleccionar'}</span>
                    </div>
                    {!returnDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
            </div>
          )}

          {/* Totals */}
          <div className="pt-2">
            <div className="flex justify-between items-center mb-4">
                <span className="text-slate-500">Total a pagar</span>
                <span className="text-3xl font-bold text-slate-800">${total.toFixed(2)}</span>
            </div>

            <Button 
                onClick={handleCheckout} 
                className={`w-full py-4 text-lg shadow-xl ${isCheckoutEnabled ? 'shadow-indigo-200' : 'bg-slate-300 text-slate-500 shadow-none cursor-not-allowed'}`}
                disabled={!isCheckoutEnabled}
            >
                {isCheckoutEnabled ? 'Cobrar Ticket' : (hasRentals ? 'Completa datos de renta' : 'Carrito Vacío')}
            </Button>
          </div>
        </div>
      </div>

      {/* Date Pickers */}
      <DatePickerModal 
        isOpen={showStartDatePicker} 
        onClose={() => setShowStartDatePicker(false)} 
        onSelect={setRentalDate} 
        title="Fecha de Entrega"
      />
       <DatePickerModal 
        isOpen={showEndDatePicker} 
        onClose={() => setShowEndDatePicker(false)} 
        onSelect={setReturnDate} 
        title="Fecha de Devolución"
      />

      {/* Customer Modal */}
      <Modal isOpen={showCustomerModal} onClose={() => setShowCustomerModal(false)} title="Seleccionar Cliente">
          {/* Quick select existing */}
          <div className="mb-6 max-h-60 overflow-y-auto space-y-2">
              {customers.map(c => (
                  <button key={c.id} onClick={() => { setSelectedCustomer(c); setShowCustomerModal(false); }} className="w-full text-left px-4 py-4 bg-slate-50 border border-slate-100 hover:bg-indigo-50 hover:border-indigo-200 active:scale-95 transition-all rounded-xl flex justify-between items-center">
                      <span className="font-bold text-slate-700">{c.name}</span>
                      <span className="text-slate-400 text-sm">{c.phone}</span>
                  </button>
              ))}
          </div>

          <div className="border-t border-slate-100 pt-6">
            <h4 className="text-xs font-bold text-slate-500 uppercase mb-4">Registrar Nuevo Cliente</h4>
            <div className="space-y-4">
                <Input placeholder="Nombre Completo" value={newCustomerName} onChange={e => setNewCustomerName(e.target.value)} />
                <Input placeholder="Teléfono" value={newCustomerPhone} onChange={e => setNewCustomerPhone(e.target.value)} />
                <div className="flex gap-3 mt-4">
                    <Button variant="secondary" onClick={() => setShowCustomerModal(false)} className="flex-1 py-4">Cancelar</Button>
                    <Button onClick={handleQuickCustomerAdd} className="flex-1 py-4">Guardar y Asignar</Button>
                </div>
            </div>
          </div>
      </Modal>

      {/* Variation Selection Modal */}
      <Modal 
        isOpen={!!variationModalData} 
        onClose={() => setVariationModalData(null)} 
        title={`Seleccionar Variación`}
      >
        <div className="space-y-4">
           <p className="text-sm text-slate-500">
             Elige la variante para <strong>{variationModalData?.product.name}</strong> ({variationModalData?.type === 'rent' ? 'Renta' : 'Venta'})
           </p>
           <div className="grid grid-cols-1 gap-3">
             {variationModalData?.product.variations?.map((v, i) => {
               const vName = typeof v === 'string' ? v : v.name;
               let vPrice = variationModalData?.type === 'rent' 
                  ? variationModalData.product.rentalPrice 
                  : variationModalData.product.salePrice;

               // Override if pricing exists
               if (typeof v !== 'string') {
                  if (variationModalData?.type === 'rent' && v.rentalPrice) vPrice = v.rentalPrice;
