      {customPriceModal && (
         <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
             <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col">
                 <div className="p-6 pb-2 text-center">
                    <h3 className="text-lg font-bold text-slate-500 uppercase tracking-wide">INGRESAR PRECIO</h3>
                    <p className="text-slate-400 text-sm mb-4">{customPriceModal.product.name} {customPriceModal.variation ? `(${typeof customPriceModal.variation === 'string' ? customPriceModal.variation : customPriceModal.variation.name})` : ''}</p>
                    <div className="text-5xl font-bold text-indigo-600 mb-2 font-mono h-14">
                        ${customPriceValue || '0'}
                    </div>
                 </div>

                 <div className="p-4 grid grid-cols-3 gap-3">
                    {[1,2,3,4,5,6,7,8,9].map(n => (
                        <button key={n} onClick={() => handleNumpadPress(n.toString())} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">
                            {n}
                        </button>
                    ))}
                    <button onClick={() => handleNumpadPress('.')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">.</button>
                    <button onClick={() => handleNumpadPress('0')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">0</button>
                    <button onClick={handleNumpadBackspace} className="h-16 rounded-xl bg-rose-50 text-rose-500 flex items-center justify-center active:bg-rose-100 transition-colors">
                        <Delete className="w-8 h-8" />
                    </button>
                 </div>

                 <div className="p-4 pt-0 grid grid-cols-2 gap-3">
                     <Button variant="secondary" onClick={() => setCustomPriceModal(null)} className="h-14 text-lg uppercase">CANCELAR</Button>
                     <Button onClick={handleCustomPriceSubmit} className="h-14 text-lg uppercase">ACEPTAR</Button>
                 </div>
             </div>
         </div>
      )}
    </div>
  );
};

