import React, { useState, useEffect, useMemo } from 'react';
import { BarChart3, Calendar, TrendingUp, DollarSign, ArrowUpRight, Activity } from 'lucide-react';
import { Card } from '../components/UI';
import { Order } from '../types';
import { getOrders } from '../services/dataService';

const Reports: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      const data = await getOrders();
      setOrders(data);
      setLoading(false);
    };
    loadData();
  }, []);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
    const now = new Date();

    // --- Helper for Date Ranges ---
    const formatDate = (date: Date) => date.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' }).toUpperCase();

    // 1. TODAY
    const todayStr = now.toLocaleDateString();
    const rangeToday = formatDate(now);

    // 2. THIS WEEK (Monday to Sunday)
    // JS getDay(): 0=Sun, 1=Mon... 
    // We want Monday to be the start. 
    // If today is Sunday (0), we go back 6 days. If Monday (1), go back 0 days.
    const currentDay = now.getDay(); 
    const daysToMonday = currentDay === 0 ? 6 : currentDay - 1;

    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - daysToMonday);
    startOfWeek.setHours(0,0,0,0);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23,59,59,999);

    const rangeWeek = `${formatDate(startOfWeek)} - ${formatDate(endOfWeek)}`;

    // 3. THIS MONTH
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    const rangeMonth = `${formatDate(startOfMonth)} - ${formatDate(endOfMonth)}`;

    // 4. THIS YEAR
    const startOfYear = new Date(now.getFullYear(), 0, 1);
    const endOfYear = new Date(now.getFullYear(), 11, 31);
    const rangeYear = `${now.getFullYear()}`;

    let todayTotal = 0;
    let weekTotal = 0;
    let monthTotal = 0;
    let yearTotal = 0;

    // Daily Aggregation for Table
    const dailyMap: Record<string, { date: string, total: number, rentTotal: number, saleTotal: number, count: number }> = {};
    let maxDailyTotal = 0;

    orders.forEach(order => {
      const orderDate = new Date(order.createdAt);

      // Totals by Period
      if (orderDate.toLocaleDateString() === todayStr) todayTotal += order.total;
      if (orderDate >= startOfWeek) weekTotal += order.total;
      if (orderDate >= startOfMonth) monthTotal += order.total;
      if (orderDate >= startOfYear) yearTotal += order.total;

      // Group by Day (Format YYYY-MM-DD for sorting logic, but display varies)
      // We use a comparable string key like YYYY/MM/DD
      const sortKey = `${orderDate.getFullYear()}/${(orderDate.getMonth()+1).toString().padStart(2,'0')}/${orderDate.getDate().toString().padStart(2,'0')}`;

      if (!dailyMap[sortKey]) {
        dailyMap[sortKey] = {
            date: orderDate.toLocaleDateString('es-MX', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }).toUpperCase(),
            total: 0,
            rentTotal: 0,
            saleTotal: 0,
            count: 0
        };
      }

      dailyMap[sortKey].total += order.total;
      dailyMap[sortKey].count += 1;

      // Split rent/sale logic roughly based on items
      // Note: An order can be mixed. We approximate by checking items in order.
      // A more precise way is to loop items.
      let orderRentSum = 0;
      let orderSaleSum = 0;
      order.items.forEach(item => {
          const itemTotal = item.appliedPrice * item.quantity;
          if (item.transactionType === 'rent') orderRentSum += itemTotal;
          else orderSaleSum += itemTotal;
      });

      dailyMap[sortKey].rentTotal += orderRentSum;
      dailyMap[sortKey].saleTotal += orderSaleSum;

      if (dailyMap[sortKey].total > maxDailyTotal) maxDailyTotal = dailyMap[sortKey].total;
    });

    // Convert map to array and sort descending
    const dailyList = Object.keys(dailyMap).sort().reverse().map(key => dailyMap[key]);

    return {
      today: todayTotal,
      week: weekTotal,
      month: monthTotal,
      year: yearTotal,
      ranges: {
          today: rangeToday,
          week: rangeWeek,
          month: rangeMonth,
          year: rangeYear
      },
      dailyList,
      maxDailyTotal
    };
  }, [orders]);

  const StatCard = ({ title, value, icon: Icon, color, subtitle }: any) => (
    <div className={`p-6 rounded-3xl border border-white/50 shadow-sm relative overflow-hidden group ${color}`}>
        <div className="relative z-10">
            <div className="flex justify-between items-start mb-4">
                <div className="p-3 bg-white/20 rounded-2xl backdrop-blur-sm">
                    <Icon className="w-6 h-6 text-white" />
                </div>
                <div className="flex flex-col items-end">
                    <div className="flex items-center gap-1 text-white/80 text-xs font-bold bg-white/10 px-2 py-1 rounded-lg mb-1">
                        <TrendingUp className="w-3 h-3" />
                        <span>ACTIVO</span>
                    </div>
                    <span className="text-[10px] text-white/70 font-mono bg-black/10 px-1.5 rounded">{subtitle}</span>
                </div>
            </div>
            <p className="text-white/70 text-sm font-bold uppercase tracking-wider">{title}</p>
            <h3 className="text-3xl font-bold text-white mt-1">${value.toLocaleString()}</h3>
        </div>
        {/* Decorative Blob */}
        <div className="absolute -bottom-10 -right-10 w-32 h-32 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform duration-500"></div>
    </div>
  );

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto pb-24">
      <header className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
          <BarChart3 className="w-8 h-8 text-indigo-600" />
          INFORMES FINANCIEROS
        </h1>
        <p className="text-slate-500 mt-2 uppercase">RESUMEN DE INGRESOS Y MÉTRICAS</p>
      </header>

      {/* KPI GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6 mb-8">
        <StatCard 
            title="VENTA DE HOY" 
            value={stats.today} 
            icon={Activity} 
            color="bg-indigo-500"
            subtitle={stats.ranges.today} 
        />
        <StatCard 
            title="ESTA SEMANA" 
            value={stats.week} 
            icon={Calendar} 
            color="bg-violet-500" 
            subtitle={stats.ranges.week}
        />
        <StatCard 
            title="ESTE MES" 
            value={stats.month} 
            icon={BarChart3} 
            color="bg-fuchsia-500" 
            subtitle={stats.ranges.month}
        />
        <StatCard 
            title="ESTE AÑO" 
            value={stats.year} 
            icon={DollarSign} 
            color="bg-emerald-500" 
            subtitle={stats.ranges.year}
        />
      </div>

      {/* DETAILED TABLE */}
      <Card className="overflow-hidden p-0">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/50">
              <h3 className="text-lg font-bold text-slate-800 uppercase flex items-center gap-2">
                  <TrendingUp className="w-5 h-5 text-indigo-600" />
                  DESGLOSE DE INGRESOS POR DÍA
              </h3>
              <span className="text-xs font-mono bg-slate-100 px-2 py-1 rounded text-slate-500 uppercase">
                  ÚLTIMOS {stats.dailyList.length} DÍAS
              </span>
          </div>

          <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                  <thead>
                      <tr className="bg-slate-50/80 text-slate-500 text-xs uppercase font-bold tracking-wider">
                          <th className="px-6 py-4">FECHA</th>
                          <th className="px-6 py-4 text-center">TICKETS</th>
                          <th className="px-6 py-4 text-right text-emerald-600">VENTAS</th>
                          <th className="px-6 py-4 text-right text-indigo-600">RENTAS</th>
                          <th className="px-6 py-4 text-right">TOTAL GENERAL</th>
                          <th className="px-6 py-4 w-32 hidden md:table-cell">GRÁFICO</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                      {loading ? (
                          <tr><td colSpan={6} className="p-8 text-center text-slate-400 uppercase">CARGANDO DATOS...</td></tr>
                      ) : stats.dailyList.length === 0 ? (
                          <tr><td colSpan={6} className="p-8 text-center text-slate-400 uppercase">NO HAY REGISTROS AÚN</td></tr>
                      ) : (
                        stats.dailyList.map((day, idx) => (
                            <tr key={idx} className="hover:bg-indigo-50/30 transition-colors group">
                                <td className="px-6 py-4">
                                    <div className="font-bold text-slate-800 uppercase text-sm">{day.date}</div>
                                </td>
                                <td className="px-6 py-4 text-center">
                                    <span className="bg-slate-100 text-slate-600 px-2 py-1 rounded-lg text-xs font-bold">
                                        {day.count}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-right font-mono text-emerald-600 text-sm">
                                    ${day.saleTotal.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                </td>
                                <td className="px-6 py-4 text-right font-mono text-indigo-600 text-sm">
                                    ${day.rentTotal.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="font-bold text-slate-900 font-mono">
                                        ${day.total.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                    </div>
                                </td>
                                <td className="px-6 py-4 hidden md:table-cell align-middle">
                                    <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden">
                                        <div 
                                            className="h-full bg-gradient-to-r from-indigo-500 to-purple-500 rounded-full"
                                            style={{ width: `${(day.total / stats.maxDailyTotal) * 100}%` }}
                                        ></div>
                                    </div>
                                </td>
                            </tr>
                        ))
                      )}
                  </tbody>
              </table>
          </div>
      </Card>
    </div>
  );
};

export default Reports;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil } from 'lucide-react';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer } from '../services/dataService';

const POS: React.FC = () => {
  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State (For items with 0 price)
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); // For editing logic
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; // Sales only don't strictly require customer
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const p = await getProducts();
      const c = await getCustomers();
      setProducts(p);
      setCustomers(c);
    };
    fetchData();
  }, []);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Filter Customers for Modal
  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()) || 
    c.phone.includes(customerSearchTerm)
  );

  // --- Handlers ---

  // Date Logic: Auto set return date to next day
  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);

      // Parse the date string YYYY-MM-DD safely
      const [year, month, day] = dateStr.split('-').map(Number);
      const startDate = new Date(year, month - 1, day);

      // Add 1 day
      startDate.setDate(startDate.getDate() + 1);

      const nextYear = startDate.getFullYear();
      const nextMonth = (startDate.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = startDate.getDate().toString().padStart(2, '0');

      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // Customer Logic
  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          // If perfect match and only one, select it
          const exactMatch = filteredCustomers.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());

          if (exactMatch) {
              setSelectedCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filteredCustomers.length > 0 && customerSearchTerm === '') {
             // Do nothing if empty search
          } else {
              // Switch to create mode
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        // Update local list
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    setSelectedCustomer(resultCustomer);
    setShowCustomerModal(false);

    // Reset forms
    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }


  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {

    // Determine price
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    // If no override, check if variation has specific price
    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    // CHECK FOR 0 PRICE -> If 0, trigger modal instead of adding
    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); // Reset input
        return;
    }

    // Unique Cart Key (Product + Variation)
    const variationId = variation ? variation.name : 'base';
    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price // Treat different prices as different items just in case
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  // Numpad handlers for Custom Price
  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));


  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Calculations
  const total = cart.reduce((sum, item) => {
    return sum + (item.appliedPrice * item.quantity);
  }, 0);

  // Checkout
  const handleCheckout = async () => {
    if (!isCheckoutEnabled) return;

    // Use conditional spread to avoid sending 'undefined' fields to Firestore
    const order: Omit<Order, 'id'> = {
      items: cart,
      total,
      status: 'pending',
      createdAt: Date.now(),
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      await createOrder(order);
      alert("VENTA REGISTRADA!");
      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="BUSCAR POR NOMBRE O CÓDIGO..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                        {product.variations.length} VARIACIONES
                      </span>
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>RENTAR</span>
                    <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : 'VARIABLE'}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>VENDER</span>
                    <span>{product.salePrice > 0 ? `$${product.salePrice}` : 'VARIABLE'}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2 uppercase">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            TICKET ACTUAL
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors uppercase">
            LIMPIAR
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p className="uppercase">EL CARRITO ESTÁ VACÍO</p>
            </div>
          ) : (
            cart.map((item) => (
              <div key={item.cartId} className="flex gap-4 p-3 bg-slate-50 rounded-2xl group">
                <div className="flex-1">
                  <div className="flex justify-between">
                     <div>
                       <h4 className="font-semibold text-slate-800 leading-tight">{item.name}</h4>
                       {item.selectedVariation && (
                         <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                            {item.selectedVariation.name}
                         </div>
                       )}
                     </div>
                     <span className="font-mono font-bold text-slate-700">
                        ${(item.appliedPrice * item.quantity).toFixed(2)}
                     </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                    </Badge>
                    <span className="text-xs text-slate-400">COD: {item.code}</span>
                    {item.appliedPrice === 0 || (item.transactionType === 'rent' && item.rentalPrice === 0) || (item.transactionType === 'sale' && item.salePrice === 0) ? (
                        <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-1 rounded uppercase">PRECIO MANUAL</span>
                    ) : null}
                  </div>
                </div>

                <div className="flex flex-col items-center gap-2">
                    <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                        <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                        <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                        <button onClick={() => updateQuantity(item.cartId, 1)} className="p-2 hover:bg-slate-100 rounded-r-lg text-slate-500 active:bg-slate-200"><Plus className="w-4 h-4"/></button>
                    </div>
                    <button onClick={() => removeFromCart(item.cartId)} className="text-rose-400 hover:text-rose-600 p-2">
                        <Trash2 className="w-5 h-5" />
                    </button>
                </div>
              </div>
            ))
          )}
        </div>

        {/* Rental & Customer Info */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-4">

          {/* Customer Selection Button (Large) */}
          {hasRentals && (
             <button 
                onClick={openCustomerModal}
                className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all active:scale-95 shadow-sm ${
                    selectedCustomer 
                    ? 'bg-indigo-600 border-indigo-600 text-white' 
                    : 'bg-white border-dashed border-slate-300 text-slate-500 hover:border-indigo-400 hover:text-indigo-600'
                }`}
             >
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${selectedCustomer ? 'bg-white/20' : 'bg-slate-100'}`}>
                        <User className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                        <div className="text-xs font-bold uppercase tracking-wider opacity-80">
                            {selectedCustomer ? 'CLIENTE ASIGNADO' : 'ASIGNAR CLIENTE (REQUERIDO)'}
                        </div>
                        <div className="font-bold text-lg leading-tight">
                            {selectedCustomer ? selectedCustomer.name : 'SELECCIONAR...'}
                        </div>
                    </div>
                </div>
                {selectedCustomer ? (
                     <div onClick={(e) => { e.stopPropagation(); setSelectedCustomer(null); }} className="p-2 bg-white/20 rounded-full hover:bg-white/30">
                        <Trash2 className="w-5 h-5" />
                     </div>
                ) : (
                    <ChevronRight className="w-6 h-6" />
                )}
             </button>
          )}

          {hasRentals && (
            <div className="grid grid-cols-2 gap-3">
                <div onClick={() => setShowStartDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA ENTREGA</span>
                    <div className="flex items-center gap-2">
                        <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!rentalDate && 'text-slate-400'}`}>{rentalDate || 'SELECCIONAR'}</span>
                    </div>
                    {!rentalDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
                <div onClick={() => setShowEndDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA DEVOLUCIÓN</span>
                    <div className="flex items-center gap-2">
                         <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!returnDate && 'text-slate-400'}`}>{returnDate || 'SELECCIONAR'}</span>
                    </div>
                    {!returnDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
            </div>
          )}

          {/* Totals */}
          <div className="pt-2">
            <div className="flex justify-between items-center mb-4">
                <span className="text-slate-500 uppercase">TOTAL A PAGAR</span>
                <span className="text-3xl font-bold text-slate-800">${total.toFixed(2)}</span>
            </div>

            <Button 
                onClick={handleCheckout} 
                className={`w-full py-4 text-lg shadow-xl uppercase ${isCheckoutEnabled ? 'shadow-indigo-200' : 'bg-slate-300 text-slate-500 shadow-none cursor-not-allowed'}`}
                disabled={!isCheckoutEnabled}
            >
                {isCheckoutEnabled ? 'COBRAR TICKET' : (hasRentals ? 'COMPLETA DATOS DE RENTA' : 'CARRITO VACÍO')}
            </Button>
          </div>
        </div>
      </div>

      {/* Date Pickers */}
      <DatePickerModal 
        isOpen={showStartDatePicker} 
        onClose={() => setShowStartDatePicker(false)} 
        onSelect={handleRentalStartDateSelect} 
        title="FECHA DE ENTREGA"
      />
       <DatePickerModal 
        isOpen={showEndDatePicker} 
        onClose={() => setShowEndDatePicker(false)} 
        onSelect={setReturnDate} 
        title="FECHA DE DEVOLUCIÓN"
      />

      {/* Improved Customer Modal */}
      <Modal 
        isOpen={showCustomerModal} 
        onClose={() => setShowCustomerModal(false)} 
        title={customerViewMode === 'search' ? "BUSCAR CLIENTE" : (editingCustomerId ? "EDITAR CLIENTE" : "REGISTRAR CLIENTE")}
      >
          {customerViewMode === 'search' ? (
              <>
                  <div className="mb-4">
                      <div className="relative">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                          <input 
                              type="text"
                              autoFocus
                              placeholder="ESCRIBE NOMBRE O TELÉFONO..."
                              value={customerSearchTerm}
                              onChange={(e) => setCustomerSearchTerm(e.target.value.toUpperCase())}
                              onKeyDown={handleCustomerSearchKeyDown}
                              className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 border border-slate-200 text-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500/20 uppercase"
