                      </div>
                      <div className="mt-2 flex justify-between items-center text-xs text-slate-400 px-1">
                          <span>{filteredCustomers.length} COINCIDENCIAS</span>
                          <span>PRESIONA <strong>ENTER</strong> PARA CREAR SI NO EXISTE</span>
                      </div>
                  </div>

                  <div className="max-h-60 overflow-y-auto space-y-2 mb-4">
                      {filteredCustomers.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => { setSelectedCustomer(c); setShowCustomerModal(false); }} 
                            className="w-full text-left px-4 py-3 bg-white border border-slate-100 hover:bg-indigo-50 hover:border-indigo-200 active:scale-95 transition-all rounded-xl flex justify-between items-center cursor-pointer group"
                          >
                              <div className="flex-1">
                                  <div className="font-bold text-slate-800 text-lg">{c.name}</div>
                                  <div className="flex flex-col sm:flex-row gap-1 sm:gap-4 mt-1">
                                    <div className="text-xs text-slate-500 flex items-center gap-1 font-medium">
                                        <Phone className="w-3 h-3 text-indigo-400" /> {c.phone}
                                    </div>
                                    {c.address && (
                                        <div className="text-xs text-slate-400 flex items-center gap-1 uppercase">
                                            <MapPin className="w-3 h-3 text-slate-400" /> {c.address}
                                        </div>
                                    )}
                                  </div>
                              </div>
                              <div className="flex items-center gap-2">
                                  {/* Edit Button */}
                                  <button 
                                    onClick={(e) => handleEditCustomerFromSearch(e, c)}
                                    className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-100 rounded-lg transition-colors"
                                  >
                                      <Pencil className="w-4 h-4" />
                                  </button>
                                  <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-indigo-400" />
                              </div>
                          </div>
                      ))}
                      {filteredCustomers.length === 0 && customerSearchTerm && (
                          <div className="text-center py-6 text-slate-400">
                              <p>NO SE ENCONTRÓ "{customerSearchTerm}"</p>
                          </div>
                      )}
                  </div>

                  <div className="border-t border-slate-100 pt-4">
                      <Button onClick={switchToCreateCustomer} variant="secondary" className="w-full uppercase py-4">
                          <UserPlus className="w-5 h-5" /> REGISTRAR "{customerSearchTerm || 'NUEVO'}" MANUALMENTE
                      </Button>
                  </div>
              </>
          ) : (
              <form onSubmit={handleQuickCustomerAdd} className="animate-in slide-in-from-right duration-300">
                  <div className="space-y-4">
                      <Input 
                          label="NOMBRE COMPLETO" 
                          value={newCustomerName} 
                          onChange={e => setNewCustomerName(e.target.value.toUpperCase())} 
                          placeholder="NOMBRE DEL CLIENTE"
                      />
                      <div className="grid grid-cols-1 gap-4">
                          <Input 
                              label="TELÉFONO CELULAR" 
                              value={newCustomerPhone} 
                              onChange={e => {
                                  // Ensure only digits and max length 10
                                  const val = e.target.value.replace(/\D/g, '');
                                  if (val.length <= 10) setNewCustomerPhone(val);
                              }} 
                              placeholder="10 DÍGITOS"
                              type="tel"
                              maxLength={10}
                              autoFocus
                          />
                          <Input 
                              label="DIRECCIÓN" 
                              value={newCustomerAddress} 
                              onChange={e => setNewCustomerAddress(e.target.value.toUpperCase())} 
                              placeholder="CALLE, NÚMERO, COLONIA"
                          />
                      </div>
                      <div className="flex gap-3 mt-6">
                          <Button 
                             type="button" 
                             variant="secondary" 
                             onClick={() => setCustomerViewMode('search')} 
                             className="flex-1 py-4 uppercase"
                          >
                              <ArrowLeft className="w-5 h-5" /> VOLVER
                          </Button>
                          <Button type="submit" className="flex-[2] py-4 uppercase">
                              {editingCustomerId ? 'GUARDAR CAMBIOS' : 'GUARDAR Y ASIGNAR'}
                          </Button>
                      </div>
                  </div>
              </form>
          )}
      </Modal>

      {/* Variation Selection Modal */}
      <Modal 
        isOpen={!!variationModalData} 
        onClose={() => setVariationModalData(null)} 
        title={`SELECCIONAR VARIACIÓN`}
      >
        <div className="space-y-4">
           <p className="text-sm text-slate-500 uppercase">
             ELIGE LA VARIANTE PARA <strong>{variationModalData?.product.name}</strong> ({variationModalData?.type === 'rent' ? 'RENTA' : 'VENTA'})
           </p>
           <div className="grid grid-cols-1 gap-3">
             {variationModalData?.product.variations?.map((v, i) => {
               const vName = typeof v === 'string' ? v : v.name;
               let vPrice = variationModalData?.type === 'rent' 
                  ? variationModalData.product.rentalPrice 
                  : variationModalData.product.salePrice;

               // Override if pricing exists
               if (typeof v !== 'string') {
                  if (variationModalData?.type === 'rent' && v.rentalPrice) vPrice = v.rentalPrice;
                  if (variationModalData?.type === 'sale' && v.salePrice) vPrice = v.salePrice;
               }

               return (
                 <button 
                   key={i}
                   onClick={() => handleVariationSelect(typeof v === 'string' ? {name: v} : v)}
                   className="flex justify-between items-center p-4 rounded-xl border border-slate-200 hover:border-indigo-500 hover:bg-indigo-50 transition-all active:scale-95"
                 >
                    <span className="font-bold text-slate-800">{vName}</span>
                    <span className="font-mono font-medium text-indigo-600">{vPrice > 0 ? `$${vPrice}` : 'PRECIO LIBRE'}</span>
                 </button>
               );
             })}
           </div>
           <div className="pt-2">
             <Button variant="ghost" onClick={() => setVariationModalData(null)} className="w-full uppercase">CANCELAR</Button>
           </div>
        </div>
      </Modal>

      {/* Custom Price Modal */}
      {customPriceModal && (
         <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
             <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col">
                 <div className="p-6 pb-2 text-center">
                    <h3 className="text-lg font-bold text-slate-500 uppercase tracking-wide">INGRESAR PRECIO</h3>
                    <p className="text-slate-400 text-sm mb-4">{customPriceModal.product.name} {customPriceModal.variation ? `(${typeof customPriceModal.variation === 'string' ? customPriceModal.variation : customPriceModal.variation.name})` : ''}</p>
                    <div className="text-5xl font-bold text-indigo-600 mb-2 font-mono h-14">
                        ${customPriceValue || '0'}
                    </div>
                 </div>

                 <div className="p-4 grid grid-cols-3 gap-3">
                    {[1,2,3,4,5,6,7,8,9].map(n => (
                        <button key={n} onClick={() => handleNumpadPress(n.toString())} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">
                            {n}
                        </button>
                    ))}
                    <button onClick={() => handleNumpadPress('.')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">.</button>
                    <button onClick={() => handleNumpadPress('0')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">0</button>
                    <button onClick={handleNumpadBackspace} className="h-16 rounded-xl bg-rose-50 text-rose-500 flex items-center justify-center active:bg-rose-100 transition-colors">
                        <Delete className="w-8 h-8" />
                    </button>
                 </div>

                 <div className="p-4 pt-0 grid grid-cols-2 gap-3">
                     <Button variant="secondary" onClick={() => setCustomPriceModal(null)} className="h-14 text-lg uppercase">CANCELAR</Button>
                     <Button onClick={handleCustomPriceSubmit} className="h-14 text-lg uppercase">ACEPTAR</Button>
                 </div>
             </div>
         </div>
      )}
    </div>
  );
};

