import React, { useState, useEffect } from 'react';
import { Users, Search, Phone, MapPin, Plus, Trash2, Pencil, UserPlus, Map as MapIcon } from 'lucide-react';
import { Button, Input, Card, Modal } from '../components/UI';
import { Customer } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer } from '../services/dataService';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form Data
  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newAddress, setNewAddress] = useState('');

  const loadCustomers = async () => {
    setLoading(true);
    const data = await getCustomers();
    setCustomers(data);
    setLoading(false);
  };

  useEffect(() => {
    loadCustomers();
  }, []);

  const handleNewCustomerClick = () => {
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewAddress('');
      setIsModalOpen(true);
  };

  const handleEditClick = (customer: Customer) => {
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewAddress(customer.address || '');
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            address: newAddress
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewAddress('');
        setIsModalOpen(false);
        setEditingId(null);
        loadCustomers();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  // Delete triggered from the list (Small button)
  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
      e.stopPropagation(); // Stop click from opening the edit modal
      e.nativeEvent.stopImmediatePropagation(); // Double assurance for touch events

      if(window.confirm('¿Eliminar cliente permanentemente?')) {
         await performDelete(id);
      }
  };

  // Delete triggered from inside the Modal (Big button)
  const handleDeleteFromModal = async (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent form submission
      e.stopPropagation(); // Stop event bubbling

      if (!editingId) return;
      if(window.confirm('¿Estás seguro de eliminar a este cliente? Esta acción no se deshace.')) {
          await performDelete(editingId);
          setIsModalOpen(false);
          setEditingId(null);
      }
  };

  const performDelete = async (id: string) => {
      try {
          await deleteCustomer(id);
          // Optimistic update
          setCustomers(prev => prev.filter(c => c.id !== id));
      } catch (error) {
          console.error(error);
          alert("No se pudo eliminar el cliente.");
          loadCustomers(); // Reload to sync state if error
      }
  }

  const handleOpenMap = (e: React.MouseEvent, address?: string) => {
      e.stopPropagation();
      if (!address) {
          alert("Este cliente no tiene dirección registrada.");
          return;
      }
      // Opens Google Maps Search in a new tab
      const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
      window.open(url, '_blank');
  };

  const filtered = customers.filter(c => 
      c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.phone.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-5xl mx-auto pb-24 min-h-full flex flex-col">
      <header className="mb-8 flex justify-between items-end">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <Users className="w-8 h-8 text-indigo-600" />
            CLIENTES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">DIRECTORIO Y ALTA DE CLIENTES</p>
        </div>

        <div className="flex gap-4 items-center">
            <div className="text-right hidden sm:block">
                <div className="text-2xl font-bold text-slate-800">{customers.length}</div>
                <div className="text-xs text-slate-400 uppercase font-bold">TOTAL</div>
            </div>
            <Button onClick={handleNewCustomerClick} className="shadow-xl shadow-indigo-200 uppercase">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO CLIENTE</span>
                <span className="sm:hidden">NUEVO</span>
            </Button>
        </div>
      </header>

      {/* Main List Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
             <div className="relative mb-6">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder="BUSCAR CLIENTE POR NOMBRE O TELÉFONO..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                />
            </div>

            <div className="flex-1 overflow-y-auto space-y-3 pb-20">
                {filtered.map(customer => (
                    <Card key={customer.id} className="flex items-center justify-between group hover:border-indigo-200 transition-colors cursor-pointer active:scale-[0.99]">
                        <div className="flex items-center gap-4 flex-1" onClick={() => handleEditClick(customer)}>
                            <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex flex-shrink-0 items-center justify-center font-bold text-xl uppercase">
                                {customer.name.charAt(0)}
                            </div>
                            <div>
                                <h3 className="font-bold text-lg text-slate-800 uppercase">{customer.name}</h3>
                                <div className="flex flex-col sm:flex-row sm:gap-4 text-sm text-slate-500 mt-1">
                                    {customer.phone && (
                                        <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {customer.phone}</span>
                                    )}
                                    {customer.address && (
                                        <span className="flex items-center gap-1 uppercase"><MapPin className="w-3 h-3" /> {customer.address}</span>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2 pl-3 border-l border-slate-100 ml-2">
                             {/* Google Maps Button */}
                             <button 
                                onClick={(e) => handleOpenMap(e, customer.address)}
                                className={`p-3 rounded-xl transition-all active:bg-indigo-200 ${customer.address ? 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100' : 'bg-slate-50 text-slate-300 cursor-not-allowed'}`}
                                title="Ver en Google Maps"
                                disabled={!customer.address}
                            >
                                <MapIcon className="w-5 h-5" />
                            </button>

                             {/* Delete Button */}
                            <button 
                                onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                className="p-3 bg-rose-50 rounded-xl text-rose-400 hover:text-rose-600 hover:bg-rose-100 transition-all active:bg-rose-200"
                                title="Eliminar Cliente"
                            >
                                <Trash2 className="w-5 h-5" />
                            </button>
                        </div>
                    </Card>
                ))}
                {filtered.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                        <Users className="w-16 h-16 mb-4 opacity-20" />
                        <p className="uppercase">NO SE ENCONTRARON CLIENTES</p>
                    </div>
                )}
            </div>
      </div>

      {/* MODAL FORM */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={editingId ? 'EDITAR CLIENTE' : 'REGISTRAR NUEVO CLIENTE'}
      >
        <form onSubmit={handleSubmit} className="space-y-6 pt-2">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 mb-6 flex items-center gap-3">
                 <div className={`w-12 h-12 rounded-full flex items-center justify-center ${editingId ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                    {editingId ? <Pencil className="w-6 h-6" /> : <UserPlus className="w-6 h-6" />}
                 </div>
                 <div>
                     <p className="text-sm text-slate-500 font-medium uppercase">ESTÁS {editingId ? 'EDITANDO A' : 'CREANDO EL PERFIL PARA'}</p>
                     <p className="text-lg font-bold text-slate-800 uppercase">{editingId ? newName : 'UN NUEVO CLIENTE'}</p>
                 </div>
            </div>

            <div className="space-y-4">
                <Input 
                    label="NOMBRE COMPLETO" 
                    placeholder="EJ. JUAN PÉREZ" 
                    value={newName}
                    onChange={(e) => setNewName(e.target.value.toUpperCase())}
                    autoFocus
                />
                <Input 
                    label="TELÉFONO" 
                    placeholder="EJ. 55 1234 5678" 
                    value={newPhone}
                    onChange={(e) => {
                        // Ensure only digits and max length 10
                        const val = e.target.value.replace(/\D/g, '');
                        if (val.length <= 10) setNewPhone(val);
                    }}
                    type="tel"
                    maxLength={10}
                />
                 <Input 
                    label="DIRECCIÓN" 
                    placeholder="CALLE, NÚMERO, COLONIA..." 
                    value={newAddress}
                    onChange={(e) => setNewAddress(e.target.value.toUpperCase())}
                />
            </div>

            <div className="pt-6 flex flex-col-reverse sm:flex-row gap-3">
                {editingId && (
                     <Button 
                        type="button" 
                        variant="danger" 
                        onClick={handleDeleteFromModal}
                        className="flex-1 uppercase"
                     >
                        <Trash2 className="w-5 h-5" /> ELIMINAR
                     </Button>
                )}
                {!editingId && (
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="flex-1 uppercase">
                        CANCELAR
                    </Button>
                )}
                <Button type="submit" className="flex-[2] py-4 text-lg uppercase">
                    {editingId ? 'GUARDAR CAMBIOS' : 'REGISTRAR CLIENTE'}
                </Button>
            </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

