import React, { useState, useEffect } from 'react';
import { Users, Search, Phone, MapPin, Plus, Trash2, Pencil, UserPlus, Map as MapIcon, Wallet } from 'lucide-react';
import { Button, Input, Card, Modal } from '../components/UI';
import { Customer } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer } from '../services/dataService';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Form Data
  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newAddress, setNewAddress] = useState('');

  const loadCustomers = async () => {
    setLoading(true);
    const data = await getCustomers();
    setCustomers(data);
    setLoading(false);
  };

  useEffect(() => {
    loadCustomers();
  }, []);

  const handleNewCustomerClick = () => {
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewAddress('');
      setIsModalOpen(true);
  };

  const handleEditClick = (customer: Customer) => {
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewAddress(customer.address || '');
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            address: newAddress
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewAddress('');
        setIsModalOpen(false);
        setEditingId(null);
        loadCustomers();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  // Delete triggered from the list (Small button)
  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
      e.stopPropagation(); // Stop click from opening the edit modal
      e.nativeEvent.stopImmediatePropagation(); // Double assurance for touch events

      if(window.confirm('¿Eliminar cliente permanentemente?')) {
         await performDelete(id);
      }
  };

  // Delete triggered from inside the Modal (Big button)
  const handleDeleteFromModal = async (e: React.MouseEvent) => {
      e.preventDefault(); // Prevent form submission
      e.stopPropagation(); // Stop event bubbling

      if (!editingId) return;
      if(window.confirm('¿Estás seguro de eliminar a este cliente? Esta acción no se deshace.')) {
          await performDelete(editingId);
          setIsModalOpen(false);
          setEditingId(null);
      }
  };

  const performDelete = async (id: string) => {
      try {
          await deleteCustomer(id);
          // Optimistic update
          setCustomers(prev => prev.filter(c => c.id !== id));
      } catch (error) {
          console.error(error);
          alert("No se pudo eliminar el cliente.");
          loadCustomers(); // Reload to sync state if error
      }
  }

  const handleOpenMap = (e: React.MouseEvent, address?: string) => {
      e.stopPropagation();
      if (!address) {
          alert("Este cliente no tiene dirección registrada.");
          return;
      }
      // Opens Google Maps Search in a new tab
      const url = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}`;
      window.open(url, '_blank');
  };

  const filtered = customers.filter(c => 
      c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.phone.includes(searchQuery)
  );

  return (
    <div className="p-4 md:p-8 max-w-5xl mx-auto h-full flex flex-col">
      <header className="mb-8 flex justify-between items-end flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <Users className="w-8 h-8 text-indigo-600" />
            CLIENTES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">DIRECTORIO Y ALTA DE CLIENTES</p>
        </div>

        <div className="flex gap-4 items-center">
            <div className="text-right hidden sm:block">
                <div className="text-2xl font-bold text-slate-800">{customers.length}</div>
                <div className="text-xs text-slate-400 uppercase font-bold">TOTAL</div>
            </div>
            <Button onClick={handleNewCustomerClick} className="shadow-xl shadow-indigo-200 uppercase">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO CLIENTE</span>
                <span className="sm:hidden">NUEVO</span>
            </Button>
        </div>
      </header>

      {/* Main List Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
             <div className="relative mb-6 flex-shrink-0">
                <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                <input 
                    type="text" 
                    placeholder="BUSCAR CLIENTE POR NOMBRE O TELÉFONO..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                />
            </div>

            <div className="flex-1 overflow-y-auto space-y-3 pb-32">
                {filtered.map(customer => (
                    <Card key={customer.id} className="flex items-center justify-between group hover:border-indigo-200 transition-colors cursor-pointer active:scale-[0.99]">
                        <div className="flex items-center gap-4 flex-1" onClick={() => handleEditClick(customer)}>
                            <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex flex-shrink-0 items-center justify-center font-bold text-xl uppercase">
                                {customer.name.charAt(0)}
                            </div>
                            <div>
                                <h3 className="font-bold text-lg text-slate-800 uppercase flex items-center gap-2">
                                    {customer.name}
                                    {customer.balance && customer.balance < 0 && (
                                        <span className="text-[10px] bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full border border-rose-200 animate-pulse">
                                            DEUDA: ${Math.abs(customer.balance).toFixed(2)}
                                        </span>
                                    )}
                                </h3>
                                <div className="flex flex-col sm:flex-row sm:gap-4 text-sm text-slate-500 mt-1">
                                    {customer.phone && (
                                        <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {customer.phone}</span>
                                    )}
                                    {customer.address && (
                                        <span className="flex items-center gap-1 uppercase"><MapPin className="w-3 h-3" /> {customer.address}</span>
                                    )}
                                </div>
                            </div>
                        </div>

                        <div className="flex items-center gap-2 pl-3 border-l border-slate-100 ml-2">
                             {/* Google Maps Button */}
                             <button 
                                onClick={(e) => handleOpenMap(e, customer.address)}
                                className={`p-3 rounded-xl transition-all active:bg-indigo-200 ${customer.address ? 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100' : 'bg-slate-50 text-slate-300 cursor-not-allowed'}`}
                                title="Ver en Google Maps"
                                disabled={!customer.address}
                            >
                                <MapIcon className="w-5 h-5" />
                            </button>

                             {/* Delete Button */}
                            <button 
                                onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                className="p-3 bg-rose-50 rounded-xl text-rose-400 hover:text-rose-600 hover:bg-rose-100 transition-all active:bg-rose-200"
                                title="Eliminar Cliente"
                            >
                                <Trash2 className="w-5 h-5" />
                            </button>
                        </div>
                    </Card>
                ))}
                {filtered.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                        <Users className="w-16 h-16 mb-4 opacity-20" />
                        <p className="uppercase">NO SE ENCONTRARON CLIENTES</p>
                    </div>
                )}
            </div>
      </div>

      {/* MODAL FORM */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={editingId ? 'EDITAR CLIENTE' : 'REGISTRAR NUEVO CLIENTE'}
      >
        <form onSubmit={handleSubmit} className="space-y-6 pt-2">
            <div className="bg-slate-50 p-4 rounded-2xl border border-slate-100 mb-6 flex items-center gap-3">
                 <div className={`w-12 h-12 rounded-full flex items-center justify-center ${editingId ? 'bg-amber-100 text-amber-600' : 'bg-indigo-100 text-indigo-600'}`}>
                    {editingId ? <Pencil className="w-6 h-6" /> : <UserPlus className="w-6 h-6" />}
                 </div>
                 <div>
                     <p className="text-sm text-slate-500 font-medium uppercase">ESTÁS {editingId ? 'EDITANDO A' : 'CREANDO EL PERFIL PARA'}</p>
                     <p className="text-lg font-bold text-slate-800 uppercase">{editingId ? newName : 'UN NUEVO CLIENTE'}</p>
                 </div>
            </div>

            <div className="space-y-4">
                <Input 
                    label="NOMBRE COMPLETO" 
                    placeholder="EJ. JUAN PÉREZ" 
                    value={newName}
                    onChange={(e) => setNewName(e.target.value.toUpperCase())}
                    autoFocus
                />
                <Input 
                    label="TELÉFONO" 
                    placeholder="EJ. 55 1234 5678" 
                    value={newPhone}
                    onChange={(e) => {
                        // Ensure only digits and max length 10
                        const val = e.target.value.replace(/\D/g, '');
                        if (val.length <= 10) setNewPhone(val);
                    }}
                    type="tel"
                    maxLength={10}
                />
                 <Input 
                    label="DIRECCIÓN" 
                    placeholder="CALLE, NÚMERO, COLONIA..." 
                    value={newAddress}
                    onChange={(e) => setNewAddress(e.target.value.toUpperCase())}
                />
            </div>

            <div className="pt-6 flex flex-col-reverse sm:flex-row gap-3">
                {editingId && (
                     <Button 
                        type="button" 
                        variant="danger" 
                        onClick={handleDeleteFromModal}
                        className="flex-1 uppercase"
                     >
                        <Trash2 className="w-5 h-5" /> ELIMINAR
                     </Button>
                )}
                {!editingId && (
                    <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="flex-1 uppercase">
                        CANCELAR
                    </Button>
                )}
                <Button type="submit" className="flex-[2] py-4 text-lg uppercase">
                    {editingId ? 'GUARDAR CAMBIOS' : 'REGISTRAR CLIENTE'}
                </Button>
            </div>
        </form>
      </Modal>
    </div>
  );
};

export default Customers;

import React, { useState, useEffect } from 'react';
import { RotateCcw, Search, Clock, AlertTriangle, CheckCircle, Calendar, User, ShoppingBag, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Order } from '../types';
import { getOrders, updateOrder, updateCustomer } from '../services/dataService';
import { Button, Input, Modal, Card, Badge } from '../components/UI';

const Returns: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'active' | 'history'>('active');

  // Modal State
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [lateFeeAmount, setLateFeeAmount] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const data = await getOrders();
    // Filter only orders that contain rentals
    const rentals = data.filter(o => o.items.some(i => i.transactionType === 'rent'));
    setOrders(rentals);
    setLoading(false);
  };

  const getRentalStatus = (order: Order) => {
    if (order.status === 'returned' || order.status === 'returned_late') {
        return { status: 'returned', label: 'DEVUELTO', color: 'green' as const, late: order.status === 'returned_late' };
    }

    const now = Date.now();
    const end = order.rentalEndDate || 0;

    if (now > end) {
        return { status: 'late', label: 'CON ATRASO', color: 'rose' as const, late: true };
    }

    return { status: 'active', label: 'EN TIEMPO', color: 'indigo' as const, late: false };
  };

  const handleCardClick = (order: Order) => {
      if (viewMode === 'history') return; // History is read-only here
      setSelectedOrder(order);
      const status = getRentalStatus(order);

      if (status.late) {
          setLateFeeAmount('');
          setShowReturnModal(true);
      } else {
          if(confirm(`¿Confirmar devolución del Ticket #${order.id?.slice(-4)}?`)) {
              processReturn(order, 0, false);
          }
      }
  };

  const processReturn = async (order: Order, fee: number, payLater: boolean) => {
    if (!order.id) return;

    try {
        const newStatus = fee > 0 ? 'returned_late' : 'returned';
        const updateData = {
            status: newStatus,
            returnedAt: Date.now(),
            ...(fee > 0 && { lateFee: fee })
        };

        await updateOrder(order.id, updateData as any);

        if (payLater && fee > 0 && order.customer && order.customer.id) {
            const currentBalance = order.customer.balance || 0;
            await updateCustomer(order.customer.id, {
                balance: currentBalance - fee 
            });
            alert(`Devolución registrada. Deuda de $${fee} cargada a ${order.customer.name}`);
        } else if (!payLater && fee > 0) {
            navigate('/', { 
                state: { 
                    action: 'pay_late_fee', 
                    customer: order.customer,
                    amount: fee,
                    refTicket: order.id
                } 
            });
            return;
        }

        // Refresh Data
        await loadData();
        setShowReturnModal(false);
        setSelectedOrder(null);

    } catch (error) {
        console.error(error);
        alert("Error al procesar devolución.");
    }
  };

  const handlePayNow = () => {
    const fee = parseFloat(lateFeeAmount);
    if (isNaN(fee) || fee <= 0) { alert("Monto inválido"); return; }
    if (selectedOrder) processReturn(selectedOrder, fee, false);
  };

  const handlePayLater = () => {
    const fee = parseFloat(lateFeeAmount);
    if (isNaN(fee) || fee <= 0) { alert("Monto inválido"); return; }
    if (selectedOrder) processReturn(selectedOrder, fee, true);
  };

  // Filter Logic
  const filteredOrders = orders.filter(o => {
      const matchesSearch = 
        o.id?.toLowerCase().includes(searchQuery.toLowerCase()) || 
        o.customer?.name.toLowerCase().includes(searchQuery.toLowerCase());

      const isReturned = o.status === 'returned' || o.status === 'returned_late';

      if (viewMode === 'active') return matchesSearch && !isReturned;
      return matchesSearch && isReturned;
  });

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto h-full flex flex-col">
       <header className="mb-6 flex flex-col md:flex-row justify-between items-end md:items-center gap-4 flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <RotateCcw className="w-8 h-8 text-indigo-600" />
            DEVOLUCIONES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">CONTROL DE RENTAS Y ENTREGAS</p>
        </div>

        {/* Toggle View */}
        <div className="bg-white p-1 rounded-2xl border border-slate-200 flex shadow-sm">
            <button 
                onClick={() => setViewMode('active')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'active' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Pendientes
            </button>
            <button 
                onClick={() => setViewMode('history')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Historial
            </button>
        </div>
      </header>

      {/* Search */}
      <div className="relative mb-6 flex-shrink-0">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input 
              type="text" 
              placeholder="BUSCAR POR TICKET O NOMBRE DE CLIENTE..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
          />
      </div>

      {/* Grid */}
      <div className="flex-1 overflow-y-auto pb-24">
         <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
             {loading ? (
                 <div className="col-span-full text-center py-10 text-slate-400">CARGANDO RENTAS...</div>
             ) : filteredOrders.length === 0 ? (
                 <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-400 opacity-50">
                     <ShoppingBag className="w-16 h-16 mb-4" />
                     <p className="uppercase font-bold">NO HAY RENTAS {viewMode === 'active' ? 'PENDIENTES' : 'EN EL HISTORIAL'}</p>
                 </div>
             ) : (
                 filteredOrders.map(order => {
                     const status = getRentalStatus(order);
                     return (
                         <div 
                            key={order.id} 
                            onClick={() => handleCardClick(order)}
                            className={`
                                relative bg-white rounded-3xl p-6 border transition-all duration-300 group
                                ${viewMode === 'active' ? 'cursor-pointer hover:shadow-xl hover:-translate-y-1' : 'opacity-80'}
                                ${status.late ? 'border-rose-200 bg-rose-50/30' : 'border-slate-100'}
                            `}
                         >
                             {/* Header Date & Status */}
                             <div className="flex justify-between items-start mb-4">
                                 <div className="flex items-center gap-2 text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-lg">
                                     <Clock className="w-3 h-3" />
                                     {new Date(order.createdAt).toLocaleDateString()}
                                 </div>
                                 <Badge color={status.color}>{status.label}</Badge>
                             </div>

                             {/* Customer Info */}
                             <div className="mb-4">
                                 <h3 className="text-xl font-bold text-slate-800 uppercase line-clamp-1">{order.customer?.name || 'CLIENTE GENERAL'}</h3>
                                 <div className="flex items-center gap-4 mt-2 text-xs text-slate-500 uppercase">
                                     <span className="flex items-center gap-1"><User className="w-3 h-3"/> TICKET #{order.id?.slice(-4)}</span>
                                 </div>
                             </div>

                             {/* Date Emphasis */}
                             <div className={`rounded-xl p-3 mb-4 flex justify-between items-center ${status.late ? 'bg-rose-100 text-rose-800' : 'bg-indigo-50 text-indigo-800'}`}>
                                 <div className="text-xs font-bold uppercase opacity-70">DEVOLUCIÓN PACTADA</div>
                                 <div className="text-lg font-bold font-mono">
                                     {new Date(order.rentalEndDate || 0).toLocaleDateString()}
                                 </div>
                             </div>

                             {/* Items Preview */}
                             <div className="space-y-2 mb-4">
                                 {order.items.filter(i => i.transactionType === 'rent').slice(0, 3).map((item, idx) => (
                                     <div key={idx} className="flex justify-between text-sm text-slate-600">
                                         <span className="uppercase font-medium truncate flex-1 pr-2">• {item.name}</span>
                                     </div>
                                 ))}
                                 {order.items.filter(i => i.transactionType === 'rent').length > 3 && (
                                     <div className="text-xs text-slate-400 italic text-center pt-1">
                                         + {order.items.filter(i => i.transactionType === 'rent').length - 3} artículos más
                                     </div>
                                 )}
                             </div>

                             {/* Action Hint */}
                             {viewMode === 'active' && (
                                 <div className={`mt-4 pt-4 border-t ${status.late ? 'border-rose-100' : 'border-slate-100'} flex justify-between items-center text-sm font-bold uppercase transition-colors ${status.late ? 'text-rose-600 group-hover:text-rose-700' : 'text-indigo-600 group-hover:text-indigo-700'}`}>
                                     <span>{status.late ? 'REGISTRAR ATRASO' : 'REGISTRAR DEVOLUCIÓN'}</span>
                                     <ArrowRight className="w-4 h-4" />
                                 </div>
                             )}
                         </div>
                     );
                 })
             )}
         </div>
      </div>

      {/* Late Fee Modal */}
      <Modal isOpen={showReturnModal} onClose={() => setShowReturnModal(false)} title="DEVOLUCIÓN CON ATRASO">
         <div className="space-y-6">
             <div className="bg-rose-50 border border-rose-200 p-4 rounded-xl flex items-start gap-3">
                 <AlertTriangle className="w-6 h-6 text-rose-600 flex-shrink-0" />
                 <div>
                     <h4 className="font-bold text-rose-800 uppercase">Artículos Atrasados</h4>
                     <p className="text-sm text-rose-600">
                         Cliente: <strong>{selectedOrder?.customer?.name}</strong><br/>
                         Vencimiento: {new Date(selectedOrder?.rentalEndDate || 0).toLocaleDateString()}
                     </p>
                 </div>
             </div>

             <Input 
                label="MONTO DE RECARGO / MULTA" 
                placeholder="$0.00" 
                type="number" 
                autoFocus
                value={lateFeeAmount}
                onChange={(e) => setLateFeeAmount(e.target.value)}
                className="text-lg font-bold"
             />

             <div className="grid grid-cols-1 gap-3 pt-2">
                 <Button onClick={handlePayNow} className="w-full uppercase py-4 shadow-xl">
                    <ShoppingBag className="w-5 h-5" /> COBRAR AHORA (IR A CAJA)
                 </Button>
                 <Button onClick={handlePayLater} variant="secondary" className="w-full uppercase py-4">
                    <User className="w-5 h-5" /> CARGAR A CUENTA DEL CLIENTE
                 </Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

