import React, { useState, useEffect, useMemo } from 'react';
import { Search, ArrowLeft, Printer, Clock, Receipt, User, Calendar, CreditCard, ShoppingBag, ChevronRight, AlertTriangle, CheckCircle, RotateCcw } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Order, CartItem } from '../types';
import { getOrders } from '../services/dataService';
import { Button, Modal, Input, Badge } from '../components/UI';

const Tickets: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);

  // Get current user from storage to display in receipt
  const currentUser = useMemo(() => {
     try {
         const u = localStorage.getItem('cyc_pos_user');
         return u ? JSON.parse(u) : { name: 'CAJERO' };
     } catch(e) { return { name: 'CAJERO' }; }
  }, []);

  useEffect(() => {
    const fetchOrders = async () => {
      setLoading(true);
      const data = await getOrders();
      setOrders(data);
      setLoading(false);
    };
    fetchOrders();
  }, []);

  // Determine Rental Status for an Order
  const getRentalStatus = (order: Order) => {
      if (!order.items.some(i => i.transactionType === 'rent')) return null; // Not a rental

      // If manually marked as returned
      if (order.status === 'returned' || order.status === 'returned_late') {
          return { status: 'returned', label: 'DEVUELTO', color: 'green' as const, late: order.status === 'returned_late' };
      }

      const now = Date.now();
      const end = order.rentalEndDate || 0;

      // Add a small buffer (e.g., end of the day) if needed, but here we assume strict timestamp
      if (now > end) {
          return { status: 'late', label: 'CON ATRASO', color: 'rose' as const, late: true };
      }

      return { status: 'active', label: 'RENTADO', color: 'indigo' as const, late: false };
  };

  // Group orders by Date
  const groupedOrders = useMemo(() => {
    const groups: Record<string, Order[]> = {};

    // Filter first
    const filtered = orders.filter(o => 
       o.id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
       o.customer?.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
       o.total.toString().includes(searchQuery)
    );

    filtered.forEach(order => {
      const dateKey = new Date(order.createdAt).toLocaleDateString('es-MX', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
      // Capitalize first letter
      const formattedDate = dateKey.charAt(0).toUpperCase() + dateKey.slice(1);

      if (!groups[formattedDate]) {
        groups[formattedDate] = [];
      }
      groups[formattedDate].push(order);
    });

    return groups;
  }, [orders, searchQuery]);

  const handlePrint = () => {
    window.print();
  };

  // Receipt Component (The Paper Ticket)
  const ReceiptView = ({ order }: { order: Order }) => {
    const date = new Date(order.createdAt);
    const hasRentals = order.items.some(i => i.transactionType === 'rent');
    const rentalStatus = getRentalStatus(order);

    return (
      <div className="bg-white w-full max-w-md mx-auto shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300 print:shadow-none print:w-full relative">
         {/* Status Badge Over Receipt */}
         {rentalStatus && (
             <div className="absolute top-4 right-4 z-10 print:hidden">
                 <Badge color={rentalStatus.color}>
                    {rentalStatus.late && rentalStatus.status === 'returned' ? 'DEVUELTO CON RECARGO' : rentalStatus.label}
                 </Badge>
             </div>
         )}

         {/* Receipt Top Edge Effect */}
         <div className="h-2 bg-slate-800 w-full"></div>

         <div className="p-8 font-mono text-sm text-slate-700 leading-relaxed">
            {/* Header */}
            <div className="text-center mb-6">
                <h2 className="text-2xl font-bold text-slate-900 mb-1 uppercase tracking-wider">CyC POS 26</h2>
                <p className="text-slate-500 text-xs">DISFRACES Y ACCESORIOS</p>
                <div className="flex justify-center items-center gap-2 mt-2 text-xs text-slate-400">
                    <span>{date.toLocaleDateString()}</span>
                    <span>•</span>
                    <span>{date.toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                </div>
            </div>

            {/* Order Meta */}
            <div className="border-b-2 border-dashed border-slate-200 pb-4 mb-4">
                <div className="flex justify-between">
                    <span className="text-slate-500">TICKET #</span>
                    <span className="font-bold">{order.id?.slice(0, 8).toUpperCase()}</span>
                </div>
                {order.customer && (
                    <div className="flex justify-between mt-1">
                        <span className="text-slate-500">CLIENTE:</span>
                        <span className="font-bold uppercase">{order.customer.name}</span>
                    </div>
                )}
                <div className="flex justify-between mt-1">
                    <span className="text-slate-500">CAJERO:</span>
                    <span className="uppercase">{currentUser.name}</span> 
                </div>
            </div>

            {/* Items */}
            <div className="space-y-3 mb-6">
                {order.items.map((item, idx) => (
                    <div key={idx} className="flex justify-between items-start">
                        <div className="flex-1 pr-2">
                             <div className="uppercase font-bold text-slate-800">{item.name}</div>
                             <div className="text-xs text-slate-500">
                                {item.quantity} x ${item.appliedPrice.toFixed(2)}
                                {item.transactionType === 'rent' && <span className="font-bold text-indigo-600"> (RENTA)</span>}
                             </div>
                             {item.selectedVariation && (
                                <div className="text-xs text-slate-400 italic">Var: {item.selectedVariation.name}</div>
                             )}
                        </div>
                        <div className="font-bold text-slate-800">
                            ${(item.quantity * item.appliedPrice).toFixed(2)}
                        </div>
                    </div>
                ))}
            </div>

            {/* Totals */}
            <div className="border-t-2 border-dashed border-slate-200 pt-4 mb-6">
                 <div className="flex justify-between text-lg font-bold text-slate-900">
                    <span>TOTAL</span>
                    <span>${order.total.toFixed(2)}</span>
                 </div>
                 <div className="flex justify-between text-xs text-slate-400 mt-1 uppercase">
                    <span>Método de Pago</span>
                    <span>EFECTIVO / TARJETA</span>
                 </div>

                 {/* Late Fee Display in Receipt */}
                 {order.lateFee && order.lateFee > 0 && (
                     <div className="flex justify-between text-rose-600 font-bold mt-2 pt-2 border-t border-slate-100">
                        <span>RECARGO POR ATRASO</span>
                        <span>${order.lateFee.toFixed(2)}</span>
                     </div>
                 )}
            </div>

            {/* Rental Details - High Emphasis */}
            {(order.rentalStartDate || order.rentalEndDate) && hasRentals && (
                <div className="mt-8 mb-6">
                    <div className={`border-4 border-double p-4 rounded-xl text-center bg-white ${rentalStatus?.status === 'late' ? 'border-rose-200 bg-rose-50' : 'border-slate-800'}`}>
                        <div className="flex flex-col gap-1 mb-3 pb-3 border-b border-dashed border-slate-300">
                            <span className="text-xs text-slate-500 uppercase tracking-wide">Fecha de Entrega</span>
                            <span className="font-bold text-lg text-slate-800">
                                {new Date(order.rentalStartDate!).toLocaleDateString()}
                            </span>
                        </div>

                        <div className="flex flex-col gap-1 relative">
                             {/* Attention icon decoration */}
                             <div className="text-center mb-1">
                                <span className={`inline-block text-white text-[10px] font-black px-2 py-0.5 rounded uppercase tracking-widest ${rentalStatus?.status === 'late' ? 'bg-rose-600 animate-pulse' : 'bg-slate-800'}`}>
                                    Fecha de Devolución
                                </span>
                             </div>
                             <span className={`font-black text-4xl px-2 py-2 rounded-lg transform -rotate-1 shadow-sm font-mono border-2 ${rentalStatus?.status === 'late' ? 'text-rose-600 bg-white border-rose-600' : 'text-slate-900 bg-amber-200 border-slate-900'}`}>
                                {new Date(order.rentalEndDate!).toLocaleDateString()}
                             </span>
                             {rentalStatus?.status !== 'returned' && (
                                <p className="text-[10px] text-slate-500 mt-2 uppercase italic">
                                    {rentalStatus?.status === 'late' ? '¡DISFRAZ CON ATRASO! SE APLICARÁN CARGOS.' : '* Evite recargos devolviendo a tiempo *'}
                                </p>
                             )}
                        </div>
                    </div>
                </div>
            )}

            {/* Footer */}
            <div className="text-center space-y-2 mt-6">
                <p className="text-xs uppercase font-bold">¡GRACIAS POR SU PREFERENCIA!</p>

                {/* Fake Barcode */}
                <div className="h-12 w-3/4 mx-auto mt-4 bg-slate-800 mask-barcode opacity-80 flex items-center justify-center text-white text-[8px] tracking-[0.5em]">
                    || | ||| | || ||| || ||
                </div>
                <p className="text-[10px] text-slate-400 mt-1">{order.id}</p>
            </div>
         </div>
      </div>
    );
  };

  return (
    <div className="flex h-full flex-col lg:flex-row bg-white overflow-hidden">

      {/* LEFT PANEL: Ticket List */}
      <div className={`w-full lg:w-[400px] xl:w-[450px] flex flex-col border-r border-slate-200 bg-white h-full transition-all duration-300 ${selectedOrder ? 'hidden lg:flex' : 'flex'}`}>

        {/* Header */}
        <div className="p-4 bg-indigo-600 text-white flex justify-between items-center flex-shrink-0">
             <div className="flex items-center gap-3">
                 <Receipt className="w-6 h-6" />
                 <h1 className="text-xl font-bold uppercase">Recibos</h1>
             </div>
             <div className="text-xs font-mono bg-indigo-500 px-2 py-1 rounded">
                 {orders.length} TOTAL
             </div>
        </div>

        {/* Search */}
        <div className="p-4 border-b border-slate-100 bg-slate-50">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="BUSCAR TICKET O CLIENTE..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    className="w-full pl-10 pr-4 py-3 rounded-xl border border-slate-200 text-sm focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
                />
            </div>
        </div>

        {/* List */}
        <div className="flex-1 overflow-y-auto">
            {loading ? (
                <div className="p-10 text-center text-slate-400 text-sm uppercase">Cargando tickets...</div>
            ) : Object.keys(groupedOrders).length === 0 ? (
                <div className="p-10 text-center text-slate-400 text-sm uppercase">No hay tickets registrados</div>
            ) : (
                Object.entries(groupedOrders).map(([date, dateOrders]) => (
                    <div key={date}>
                        <div className="px-4 py-2 bg-slate-50 text-xs font-bold text-indigo-600 uppercase tracking-wider sticky top-0 border-b border-slate-100 z-10 backdrop-blur-sm bg-slate-50/90">
                            {date}
                        </div>
                        {(dateOrders as Order[]).map(order => {
                            const rStatus = getRentalStatus(order);
                            return (
                                <div 
                                    key={order.id}
                                    onClick={() => setSelectedOrder(order)}
                                    className={`px-4 py-4 border-b border-slate-50 cursor-pointer hover:bg-indigo-50 transition-colors flex justify-between items-center group relative ${selectedOrder?.id === order.id ? 'bg-indigo-50 border-l-4 border-l-indigo-600' : 'border-l-4 border-l-transparent'}`}
                                >
                                    <div className="flex items-center gap-4">
                                        <div className={`p-3 rounded-full ${order.status.includes('returned') ? 'bg-emerald-100 text-emerald-600' : (rStatus?.status === 'late' ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-500')}`}>
                                            {order.items.length > 2 ? <ShoppingBag className="w-5 h-5"/> : <Receipt className="w-5 h-5" />}
                                        </div>
                                        <div>
                                            <div className="font-bold text-slate-800 text-lg">
                                                ${order.total.toFixed(2)}
                                            </div>
                                            <div className="text-xs text-slate-400 flex items-center gap-1 mt-0.5">
                                                <Clock className="w-3 h-3" />
                                                {new Date(order.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                                <span className="mx-1">•</span>
                                                <span>#{order.id?.slice(-4).toUpperCase()}</span>
                                                {rStatus && (
                                                    <span className={`ml-2 font-bold px-1.5 py-0.5 rounded text-[10px] ${rStatus.late ? 'bg-rose-100 text-rose-600' : 'bg-indigo-50 text-indigo-600'}`}>
                                                        {rStatus.status === 'returned' ? 'DEVUELTO' : (rStatus.late ? 'ATRASADO' : 'RENTADO')}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="text-right">
                                        <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-indigo-400" />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ))
            )}
        </div>
      </div>

      {/* RIGHT PANEL: Details / Receipt */}
      <div className={`flex-1 bg-slate-100 relative flex flex-col h-full ${!selectedOrder ? 'hidden lg:flex' : 'flex'}`}>
          {selectedOrder ? (
            <>
                {/* Mobile Header for Right Panel */}
                <div className="lg:hidden bg-white p-4 flex items-center gap-3 border-b border-slate-200">
                    <Button variant="ghost" onClick={() => setSelectedOrder(null)} className="p-2">
                        <ArrowLeft className="w-6 h-6" />
                    </Button>
                    <span className="font-bold text-slate-800">DETALLE DEL TICKET</span>
                </div>

                {/* Toolbar */}
                <div className="p-4 flex justify-end gap-3 absolute top-0 right-0 z-20 w-full pointer-events-none">
                    <div className="pointer-events-auto flex gap-2">
                        <Button onClick={handlePrint} className="shadow-xl bg-slate-800 hover:bg-slate-900 text-white rounded-full w-12 h-12 flex items-center justify-center p-0">
                            <Printer className="w-5 h-5" />
                        </Button>
                    </div>
                </div>

                {/* Receipt Container */}
                <div className="flex-1 overflow-y-auto p-4 md:p-10 flex items-start justify-center">
                    <ReceiptView order={selectedOrder} />
                </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 p-8">
                <div className="w-24 h-24 bg-slate-200 rounded-full flex items-center justify-center mb-6 animate-pulse">
                    <Receipt className="w-10 h-10 text-slate-400" />
