                    <div>
                        <div className="text-xs font-bold uppercase tracking-wider opacity-60 flex items-center gap-1">
                            <Wallet className="w-4 h-4" /> SALDO ACTUAL
                        </div>
                        <div className={`text-3xl font-bold font-mono ${selectedCustomer.balance && selectedCustomer.balance < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
                            ${(selectedCustomer.balance || 0).toFixed(2)}
