import React, { useState, useEffect } from 'react';
import { RotateCcw, Search, Clock, AlertTriangle, CheckCircle, Calendar, User, ShoppingBag, ArrowRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Order } from '../types';
import { getOrders, updateOrder, updateCustomer, getSystemSettings } from '../services/dataService';
import { Button, Input, Modal, Card, Badge } from '../components/UI';

const Returns: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'active' | 'history'>('active');

  // Modal State
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [lateFeeAmount, setLateFeeAmount] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const data = await getOrders();
    // Filter only orders that contain rentals
    const rentals = data.filter(o => o.items.some(i => i.transactionType === 'rent'));
    setOrders(rentals);
    setLoading(false);
  };

  const getRentalStatus = (order: Order) => {
    if (order.status === 'returned' || order.status === 'returned_late') {
        return { status: 'returned', label: 'DEVUELTO', color: 'green' as const, late: order.status === 'returned_late' };
    }

    const now = Date.now();
    const end = order.rentalEndDate || 0;

    if (now > end) {
        return { status: 'late', label: 'CON ATRASO', color: 'rose' as const, late: true };
    }

    return { status: 'active', label: 'EN TIEMPO', color: 'indigo' as const, late: false };
  };

  const handleCardClick = async (order: Order) => {
      if (viewMode === 'history') return; // History is read-only here
      setSelectedOrder(order);
      const status = getRentalStatus(order);

      if (status.late) {
          // Fetch Default Fee
          const settings = await getSystemSettings();
          setLateFeeAmount(settings.defaultLateFee.toString());
          setShowReturnModal(true);
      } else {
          if(confirm(`¿Confirmar devolución del Ticket #${order.id?.slice(-4)}?`)) {
              processReturn(order, 0, false);
          }
      }
  };

  const processReturn = async (order: Order, fee: number, payLater: boolean) => {
    if (!order.id) return;

    try {
        const newStatus = fee > 0 ? 'returned_late' : 'returned';
        const updateData = {
            status: newStatus,
            returnedAt: Date.now(),
            ...(fee > 0 && { lateFee: fee })
        };

        await updateOrder(order.id, updateData as any);

        if (payLater && fee > 0 && order.customer && order.customer.id) {
            const currentBalance = order.customer.balance || 0;
            await updateCustomer(order.customer.id, {
                balance: currentBalance - fee 
            });
            alert(`Devolución registrada. Deuda de $${fee} cargada a ${order.customer.name}`);
        } else if (!payLater && fee > 0) {
            navigate('/', { 
                state: { 
                    action: 'pay_late_fee', 
                    customer: order.customer,
                    amount: fee,
                    refTicket: order.id
                } 
            });
            return;
        }

        // Refresh Data
        await loadData();
        setShowReturnModal(false);
        setSelectedOrder(null);

    } catch (error) {
        console.error(error);
        alert("Error al procesar devolución.");
    }
  };

  const handlePayNow = () => {
    const fee = parseFloat(lateFeeAmount);
    if (isNaN(fee) || fee <= 0) { alert("Monto inválido"); return; }
    if (selectedOrder) processReturn(selectedOrder, fee, false);
  };

  const handlePayLater = () => {
    const fee = parseFloat(lateFeeAmount);
    if (isNaN(fee) || fee <= 0) { alert("Monto inválido"); return; }
    if (selectedOrder) processReturn(selectedOrder, fee, true);
  };

  // Filter Logic
  const filteredOrders = orders.filter(o => {
      const matchesSearch = 
        o.id?.toLowerCase().includes(searchQuery.toLowerCase()) || 
        o.customer?.name.toLowerCase().includes(searchQuery.toLowerCase());

      const isReturned = o.status === 'returned' || o.status === 'returned_late';

      if (viewMode === 'active') return matchesSearch && !isReturned;
      return matchesSearch && isReturned;
  });

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto h-full flex flex-col">
       <header className="mb-6 flex flex-col md:flex-row justify-between items-end md:items-center gap-4 flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <RotateCcw className="w-8 h-8 text-indigo-600" />
            DEVOLUCIONES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">CONTROL DE RENTAS Y ENTREGAS</p>
        </div>

        {/* Toggle View */}
        <div className="bg-white p-1 rounded-2xl border border-slate-200 flex shadow-sm">
            <button 
                onClick={() => setViewMode('active')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'active' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Pendientes
            </button>
            <button 
                onClick={() => setViewMode('history')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Historial
            </button>
        </div>
      </header>

      {/* Search */}
      <div className="relative mb-6 flex-shrink-0">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input 
              type="text" 
              placeholder="BUSCAR POR TICKET O NOMBRE DE CLIENTE..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
          />
      </div>

      {/* Grid */}
      <div className="flex-1 overflow-y-auto pb-24">
         <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
             {loading ? (
                 <div className="col-span-full text-center py-10 text-slate-400">CARGANDO RENTAS...</div>
             ) : filteredOrders.length === 0 ? (
                 <div className="col-span-full flex flex-col items-center justify-center py-20 text-slate-400 opacity-50">
                     <ShoppingBag className="w-16 h-16 mb-4" />
                     <p className="uppercase font-bold">NO HAY RENTAS {viewMode === 'active' ? 'PENDIENTES' : 'EN EL HISTORIAL'}</p>
                 </div>
             ) : (
                 filteredOrders.map(order => {
                     const status = getRentalStatus(order);
                     return (
                         <div 
                            key={order.id} 
                            onClick={() => handleCardClick(order)}
                            className={`
                                relative bg-white rounded-3xl p-6 border transition-all duration-300 group
                                ${viewMode === 'active' ? 'cursor-pointer hover:shadow-xl hover:-translate-y-1' : 'opacity-80'}
                                ${status.late ? 'border-rose-200 bg-rose-50/30' : 'border-slate-100'}
                            `}
                         >
                             {/* Header Date & Status */}
                             <div className="flex justify-between items-start mb-4">
                                 <div className="flex items-center gap-2 text-xs font-bold text-slate-400 bg-slate-50 px-2 py-1 rounded-lg">
                                     <Clock className="w-3 h-3" />
                                     {new Date(order.createdAt).toLocaleDateString()}
                                 </div>
                                 <Badge color={status.color}>{status.label}</Badge>
                             </div>

                             {/* Customer Info */}
                             <div className="mb-4">
                                 <h3 className="text-xl font-bold text-slate-800 uppercase line-clamp-1">{order.customer?.name || 'CLIENTE GENERAL'}</h3>
                                 <div className="flex items-center gap-4 mt-2 text-xs text-slate-500 uppercase">
                                     <span className="flex items-center gap-1"><User className="w-3 h-3"/> TICKET #{order.id?.slice(-4)}</span>
                                 </div>
                             </div>

                             {/* Date Emphasis */}
                             <div className={`rounded-xl p-3 mb-4 flex justify-between items-center ${status.late ? 'bg-rose-100 text-rose-800' : 'bg-indigo-50 text-indigo-800'}`}>
                                 <div className="text-xs font-bold uppercase opacity-70">DEVOLUCIÓN PACTADA</div>
                                 <div className="text-lg font-bold font-mono">
                                     {new Date(order.rentalEndDate || 0).toLocaleDateString()}
                                 </div>
                             </div>

                             {/* Items Preview */}
                             <div className="space-y-2 mb-4">
                                 {order.items.filter(i => i.transactionType === 'rent').slice(0, 3).map((item, idx) => (
                                     <div key={idx} className="flex justify-between text-sm text-slate-600">
                                         <span className="uppercase font-medium truncate flex-1 pr-2">• {item.name}</span>
                                     </div>
                                 ))}
                                 {order.items.filter(i => i.transactionType === 'rent').length > 3 && (
                                     <div className="text-xs text-slate-400 italic text-center pt-1">
                                         + {order.items.filter(i => i.transactionType === 'rent').length - 3} artículos más
                                     </div>
                                 )}
                             </div>

                             {/* Action Hint */}
                             {viewMode === 'active' && (
                                 <div className={`mt-4 pt-4 border-t ${status.late ? 'border-rose-100' : 'border-slate-100'} flex justify-between items-center text-sm font-bold uppercase transition-colors ${status.late ? 'text-rose-600 group-hover:text-rose-700' : 'text-indigo-600 group-hover:text-indigo-700'}`}>
                                     <span>{status.late ? 'REGISTRAR ATRASO' : 'REGISTRAR DEVOLUCIÓN'}</span>
                                     <ArrowRight className="w-4 h-4" />
                                 </div>
                             )}
                         </div>
                     );
                 })
             )}
         </div>
      </div>

      {/* Late Fee Modal */}
      <Modal isOpen={showReturnModal} onClose={() => setShowReturnModal(false)} title="DEVOLUCIÓN CON ATRASO">
         <div className="space-y-6">
             <div className="bg-rose-50 border border-rose-200 p-4 rounded-xl flex items-start gap-3">
                 <AlertTriangle className="w-6 h-6 text-rose-600 flex-shrink-0" />
                 <div>
                     <h4 className="font-bold text-rose-800 uppercase">Artículos Atrasados</h4>
                     <p className="text-sm text-rose-600">
                         Cliente: <strong>{selectedOrder?.customer?.name}</strong><br/>
                         Vencimiento: {new Date(selectedOrder?.rentalEndDate || 0).toLocaleDateString()}
                     </p>
                 </div>
             </div>

             <Input 
                label="MONTO DE RECARGO / MULTA" 
                placeholder="$0.00" 
                type="number" 
                autoFocus
                value={lateFeeAmount}
                onChange={(e) => setLateFeeAmount(e.target.value)}
                className="text-lg font-bold"
             />

             <div className="grid grid-cols-1 gap-3 pt-2">
                 <Button onClick={handlePayNow} className="w-full uppercase py-4 shadow-xl">
                    <ShoppingBag className="w-5 h-5" /> COBRAR AHORA (IR A CAJA)
                 </Button>
                 <Button onClick={handlePayLater} variant="secondary" className="w-full uppercase py-4">
                    <User className="w-5 h-5" /> CARGAR A CUENTA DEL CLIENTE
                 </Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

export default Returns;

export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff';
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
}

export type TransactionType = 'sale' | 'rent';

export interface CartItem extends Product {
  cartId: string; // Unique ID for the item in cart
  transactionType: TransactionType;
  quantity: number;
  selectedVariation?: Variation;
  appliedPrice: number; // The actual price used for this item (base or variation)
}

export interface Order {
  id?: string;
  items: CartItem[];
  customer?: Customer; // Required if there are rentals
  total: number;
  status: 'pending' | 'completed' | 'returned' | 'late' | 'returned_late';
  createdAt: number; // Timestamp
  rentalStartDate?: number;
  rentalEndDate?: number;
  returnedAt?: number; // When it was actually returned
  lateFee?: number; // Fee charged if returned late
}

import { db } from '../firebase';
import { collection, addDoc, getDocs, query, orderBy, where, Timestamp, deleteDoc, doc, writeBatch, updateDoc, setDoc, getDoc } from 'firebase/firestore';
import { Product, Order, Customer, User, SystemSettings } from '../types';

// Helper to generate a random code between 4 and 6 digits
export const generateProductCode = (): string => {
  const min = 1000;
  const max = 999999;
  const num = Math.floor(Math.random() * (max - min + 1)) + min;
  return num.toString();
};

// Helper to recursively strip undefined values from objects
const stripUndefined = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(stripUndefined);
  } else if (obj !== null && typeof obj === 'object') {
    return Object.entries(obj).reduce((acc, [key, value]) => {
      if (value !== undefined) {
        acc[key] = stripUndefined(value);
      }
      return acc;
    }, {} as any);
  }
  return obj;
};

// --- Products ---

export const addProduct = async (product: Omit<Product, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "products"), product);
    return { ...product, id: docRef.id };
  } catch (e) {
    console.error("Error adding product: ", e);
    throw e;
  }
};

export const updateProduct = async (id: string, product: Partial<Product>) => {
  try {
    const docRef = doc(db, "products", id);
    await updateDoc(docRef, product);
  } catch (e) {
    console.error("Error updating product: ", e);
    throw e;
  }
};

export const getProducts = async (): Promise<Product[]> => {
  try {
    const q = query(collection(db, "products"), orderBy("name"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product));
  } catch (e) {
    console.error("Error fetching products: ", e);
    return [];
  }
};

export const deleteProduct = async (id: string) => {
    try {
        await deleteDoc(doc(db, "products", id));
    } catch (e) {
        console.error("Error deleting product", e);
        throw e;
    }
}

export const importProductsBatch = async (products: Omit<Product, 'id'>[]) => {
  try {
    const batch = writeBatch(db);
    const collectionRef = collection(db, "products");
    const chunk = products.slice(0, 500);

    chunk.forEach(prod => {
      const docRef = doc(collectionRef);
      batch.set(docRef, prod);
    });

    await batch.commit();
    return chunk.length;
  } catch (e) {
    console.error("Error batch importing: ", e);
    throw e;
  }
}

// --- Orders ---

export const createOrder = async (order: Omit<Order, 'id'>) => {
  try {
    const cleanOrder = stripUndefined(order);
    const docRef = await addDoc(collection(db, "orders"), {
      ...cleanOrder,
      createdAt: Timestamp.now().toMillis() 
    });
    return { ...order, id: docRef.id };
  } catch (e) {
    console.error("Error creating order: ", e);
    throw e;
  }
};

export const updateOrder = async (id: string, data: Partial<Order>) => {
    try {
      const docRef = doc(db, "orders", id);
      await updateDoc(docRef, data);
    } catch (e) {
      console.error("Error updating order: ", e);
      throw e;
    }
};

export const getOrders = async (): Promise<Order[]> => {
  try {
    const q = query(collection(db, "orders"), orderBy("createdAt", "desc"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Order));
  } catch (e) {
    console.error("Error fetching orders: ", e);
    return [];
  }
};

// --- Customers ---

export const getCustomers = async (): Promise<Customer[]> => {
    try {
      const q = query(collection(db, "customers"), orderBy("name"));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Customer));
    } catch (e) {
      console.error("Error fetching customers", e);
      return [];
    }
}

export const addCustomer = async (customer: Customer) => {
    try {
        const docRef = await addDoc(collection(db, "customers"), { ...customer, balance: 0 });
        return { ...customer, balance: 0, id: docRef.id };
    } catch(e) {
        console.error("Error adding customer", e);
        throw e;
    }
}

export const updateCustomer = async (id: string, customer: Partial<Customer>) => {
  try {
    const docRef = doc(db, "customers", id);
    await updateDoc(docRef, customer);
  } catch (e) {
    console.error("Error updating customer: ", e);
    throw e;
  }
};

export const deleteCustomer = async (id: string) => {
    try {
        await deleteDoc(doc(db, "customers", id));
    } catch (e) {
        console.error("Error deleting customer", e);
        throw e;
    }
}

// --- Users (Auth) ---

export const getUsers = async (): Promise<User[]> => {
  try {
    const q = query(collection(db, "users"), orderBy("name"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as User));
  } catch (e) {
    console.error("Error fetching users", e);
    return [];
  }
}

export const addUser = async (user: User) => {
  try {
      const docRef = await addDoc(collection(db, "users"), user);
      return { ...user, id: docRef.id };
  } catch(e) {
      console.error("Error adding user", e);
      throw e;
  }
}

export const deleteUser = async (id: string) => {
  try {
      await deleteDoc(doc(db, "users", id));
  } catch (e) {
      console.error("Error deleting user", e);
      throw e;
  }
}

// --- Settings ---

export const getSystemSettings = async (): Promise<SystemSettings> => {
  try {
    const docRef = doc(db, "settings", "global");
    const docSnap = await getDoc(docRef);
    if (docSnap.exists()) {
      const data = docSnap.data();
      return {
          defaultLateFee: data.defaultLateFee || 50,
          pricePerExtraDay: data.pricePerExtraDay || 0
      } as SystemSettings;
    } else {
      // Return default
      return { defaultLateFee: 50, pricePerExtraDay: 50 };
    }
  } catch (e) {
    console.error("Error getting settings", e);
    return { defaultLateFee: 50, pricePerExtraDay: 50 };
  }
}

export const updateSystemSettings = async (settings: SystemSettings) => {
  try {
    await setDoc(doc(db, "settings", "global"), settings);
  } catch (e) {
    console.error("Error saving settings", e);
    throw e;
  }
}

