import React, { useState, useEffect } from 'react';
import { RotateCcw, Search, Clock, AlertTriangle, CheckCircle, Calendar, User, ShoppingBag, ArrowRight, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Order } from '../types';
import { getOrders, updateOrder, updateCustomer, getSystemSettings } from '../services/dataService';
import { Button, Input, Modal, Card, Badge } from '../components/UI';

const Returns: React.FC = () => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState<'active' | 'history'>('active');

  // Modal State
  const [selectedOrder, setSelectedOrder] = useState<Order | null>(null);
  const [showReturnModal, setShowReturnModal] = useState(false);
  const [lateFeeAmount, setLateFeeAmount] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    setLoading(true);
    const data = await getOrders();
    // Filter only orders that contain rentals
    const rentals = data.filter(o => o.items.some(i => i.transactionType === 'rent'));
    setOrders(rentals);
    setLoading(false);
  };

  const getRentalStatus = (order: Order) => {
    if (order.status === 'returned' || order.status === 'returned_late') {
        return { status: 'returned', label: 'DEVUELTO', color: 'green' as const, late: order.status === 'returned_late' };
    }

    const now = Date.now();
    const end = order.rentalEndDate || 0;

    if (now > end) {
        return { status: 'late', label: 'CON ATRASO', color: 'rose' as const, late: true };
    }

    return { status: 'active', label: 'EN TIEMPO', color: 'indigo' as const, late: false };
  };

  // Immediate Action: Mark as returned (Clean)
  const handleQuickReturn = async (order: Order) => {
    if(!confirm(`¿Confirmar recepción de artículos del Ticket #${order.id?.slice(-4)}?`)) return;

    try {
        await updateOrder(order.id!, {
            status: 'returned',
            returnedAt: Date.now()
        });
        // Optimistic Update
        setOrders(prev => prev.map(o => o.id === order.id ? { ...o, status: 'returned', returnedAt: Date.now() } : o));
        alert("Devolución registrada correctamente.");
        loadData(); // Ensure Sync
    } catch (e) {
        alert("Error al registrar devolución.");
    }
  };

  // Open Modal for Late Fee
  const handleLateReturnClick = async (order: Order) => {
      setSelectedOrder(order);
      // Fetch Default Fee
      const settings = await getSystemSettings();
      setLateFeeAmount(settings.defaultLateFee.toString());
      setShowReturnModal(true);
  };

  const processLateReturn = async (payLater: boolean) => {
    if (!selectedOrder?.id) return;
    const fee = parseFloat(lateFeeAmount);
    if (isNaN(fee) || fee <= 0) { alert("Monto inválido"); return; }

    try {
        const updateData = {
            status: 'returned_late',
            returnedAt: Date.now(),
            lateFee: fee
        };

        await updateOrder(selectedOrder.id, updateData as any);

        if (payLater && selectedOrder.customer && selectedOrder.customer.id) {
            const currentBalance = selectedOrder.customer.balance || 0;
            await updateCustomer(selectedOrder.customer.id, {
                balance: currentBalance - fee 
            });
            alert(`Devolución registrada. Deuda de $${fee} cargada a ${selectedOrder.customer.name}`);
        } else {
            // Pay Now: Redirect to POS with pre-filled cart logic (Handled in POS via location state)
            navigate('/', { 
                state: { 
                    action: 'pay_late_fee', 
                    customer: selectedOrder.customer,
                    amount: fee,
                    refTicket: selectedOrder.id
                } 
            });
            return;
        }

        // Refresh Data
        await loadData();
        setShowReturnModal(false);
        setSelectedOrder(null);

    } catch (error) {
        console.error(error);
        alert("Error al procesar devolución.");
    }
  };

  // Filter Logic
  const filteredOrders = orders.filter(o => {
      const matchesSearch = 
        o.id?.toLowerCase().includes(searchQuery.toLowerCase()) || 
        o.customer?.name.toLowerCase().includes(searchQuery.toLowerCase());

      const isReturned = o.status === 'returned' || o.status === 'returned_late';

      if (viewMode === 'active') return matchesSearch && !isReturned;
      return matchesSearch && isReturned;
  });

  return (
    <div className="p-4 md:p-8 max-w-[1600px] mx-auto h-full flex flex-col">
       <header className="mb-6 flex flex-col md:flex-row justify-between items-end md:items-center gap-4 flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <RotateCcw className="w-8 h-8 text-indigo-600" />
            DEVOLUCIONES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">CONTROL DE RENTAS Y ENTREGAS</p>
        </div>

        {/* Toggle View */}
        <div className="bg-white p-1 rounded-2xl border border-slate-200 flex shadow-sm">
            <button 
                onClick={() => setViewMode('active')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'active' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Pendientes
            </button>
            <button 
                onClick={() => setViewMode('history')}
                className={`px-6 py-2 rounded-xl text-sm font-bold uppercase transition-all ${viewMode === 'history' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
            >
                Historial
            </button>
        </div>
      </header>

      {/* Search */}
      <div className="relative mb-6 flex-shrink-0">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input 
              type="text" 
              placeholder="BUSCAR POR TICKET O NOMBRE DE CLIENTE..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
          />
      </div>

      {/* Dense Table View */}
      <div className="flex-1 overflow-hidden rounded-3xl border border-slate-200 bg-white shadow-sm flex flex-col">
          <div className="overflow-x-auto flex-1">
             <table className="w-full text-left border-collapse">
                 <thead className="bg-slate-50 text-slate-500 text-xs uppercase font-bold sticky top-0 z-10">
                     <tr>
                         <th className="px-6 py-4">Ticket</th>
                         <th className="px-6 py-4">Cliente</th>
                         <th className="px-6 py-4">Artículos en Renta</th>
                         <th className="px-6 py-4">Fecha Entrega</th>
                         <th className="px-6 py-4">Fecha Devolución</th>
                         <th className="px-6 py-4 text-center">Estado</th>
                         {viewMode === 'active' && <th className="px-6 py-4 text-right">Acción</th>}
                     </tr>
                 </thead>
                 <tbody className="divide-y divide-slate-100 text-sm">
                     {loading ? (
                         <tr><td colSpan={7} className="p-10 text-center text-slate-400">CARGANDO...</td></tr>
                     ) : filteredOrders.length === 0 ? (
                         <tr><td colSpan={7} className="p-20 text-center text-slate-400 uppercase font-bold opacity-50">NO HAY REGISTROS EN ESTA VISTA</td></tr>
                     ) : (
                         filteredOrders.map(order => {
                             const status = getRentalStatus(order);
                             const rentalItems = order.items.filter(i => i.transactionType === 'rent');

                             return (
                                 <tr key={order.id} className="hover:bg-slate-50/80 transition-colors group">
                                     <td className="px-6 py-4 font-mono text-slate-500">
                                         #{order.id?.slice(-4).toUpperCase()}
                                     </td>
                                     <td className="px-6 py-4 font-bold text-slate-800 uppercase">
                                         {order.customer?.name}
                                     </td>
                                     <td className="px-6 py-4">
                                         <div className="flex flex-col gap-1">
                                             {rentalItems.slice(0, 2).map((item, i) => (
                                                 <span key={i} className="text-slate-600 uppercase text-xs">• {item.name}</span>
                                             ))}
                                             {rentalItems.length > 2 && (
                                                 <span className="text-[10px] text-slate-400 italic">+ {rentalItems.length - 2} más</span>
                                             )}
                                         </div>
                                     </td>
                                     <td className="px-6 py-4 text-slate-500">
                                         {new Date(order.rentalStartDate || 0).toLocaleDateString()}
                                     </td>
                                     <td className="px-6 py-4">
                                         <div className={`font-mono font-bold ${status.late && viewMode === 'active' ? 'text-rose-600' : 'text-slate-800'}`}>
                                            {new Date(order.rentalEndDate || 0).toLocaleDateString()}
                                         </div>
                                     </td>
                                     <td className="px-6 py-4 text-center">
                                         <Badge color={status.color}>{status.label}</Badge>
                                     </td>
                                     {viewMode === 'active' && (
                                         <td className="px-6 py-4 text-right">
                                             <div className="flex justify-end gap-2">
                                                 {status.late ? (
                                                     <button 
                                                        onClick={() => handleLateReturnClick(order)}
                                                        className="bg-rose-100 text-rose-700 px-4 py-2 rounded-lg font-bold text-xs uppercase hover:bg-rose-200 transition-colors shadow-sm flex items-center gap-2"
                                                     >
                                                         <AlertTriangle className="w-4 h-4" /> REGISTRAR ATRASO
                                                     </button>
                                                 ) : (
                                                     <button 
                                                        onClick={() => handleQuickReturn(order)}
                                                        className="bg-indigo-600 text-white px-4 py-2 rounded-lg font-bold text-xs uppercase hover:bg-indigo-700 transition-colors shadow-md shadow-indigo-200 flex items-center gap-2"
                                                     >
                                                         <CheckCircle className="w-4 h-4" /> RECIBIR
                                                     </button>
                                                 )}
                                             </div>
                                         </td>
                                     )}
                                 </tr>
                             );
                         })
                     )}
                 </tbody>
             </table>
          </div>
      </div>

      {/* Late Fee Modal */}
      <Modal isOpen={showReturnModal} onClose={() => setShowReturnModal(false)} title="DEVOLUCIÓN CON ATRASO">
         <div className="space-y-6">
             <div className="bg-rose-50 border border-rose-200 p-4 rounded-xl flex items-start gap-3">
                 <AlertTriangle className="w-6 h-6 text-rose-600 flex-shrink-0" />
                 <div>
                     <h4 className="font-bold text-rose-800 uppercase">Artículos Atrasados</h4>
                     <p className="text-sm text-rose-600">
                         Cliente: <strong>{selectedOrder?.customer?.name}</strong><br/>
                         Vencimiento: {new Date(selectedOrder?.rentalEndDate || 0).toLocaleDateString()}
                     </p>
                 </div>
             </div>

             <Input 
                label="MONTO DE RECARGO / MULTA" 
                placeholder="$0.00" 
                type="number" 
                autoFocus
                value={lateFeeAmount}
                onChange={(e) => setLateFeeAmount(e.target.value)}
                className="text-lg font-bold"
             />

             <div className="grid grid-cols-1 gap-3 pt-2">
                 <Button onClick={() => processLateReturn(false)} className="w-full uppercase py-4 shadow-xl">
                    <ShoppingBag className="w-5 h-5" /> COBRAR AHORA (IR A CAJA)
                 </Button>
                 <Button onClick={() => processLateReturn(true)} variant="secondary" className="w-full uppercase py-4">
                    <User className="w-5 h-5" /> CARGAR A CUENTA DEL CLIENTE
                 </Button>
             </div>
         </div>
      </Modal>
    </div>
  );
};

export default Returns;

import React, { useState, useEffect } from 'react';
import { Users, Search, Phone, MapPin, Plus, Trash2, Pencil, UserPlus, Map as MapIcon, History, Wallet, AlertCircle, CheckCircle, Clock, Receipt, ArrowUpRight, ArrowDownLeft, Filter } from 'lucide-react';
import { Button, Input, Card, Modal, Badge } from '../components/UI';
import { Customer, Order } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer, getOrders } from '../services/dataService';

const Customers: React.FC = () => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState<'all' | 'attention'>('all');

  // Create/Edit Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newAddress, setNewAddress] = useState('');

  // History Modal State
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [customerOrders, setCustomerOrders] = useState<Order[]>([]);
  const [historyTab, setHistoryTab] = useState<'active' | 'all'>('active');

  const loadData = async () => {
    setLoading(true);
    const [cData, oData] = await Promise.all([getCustomers(), getOrders()]);
    setCustomers(cData);
    setOrders(oData);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  // --- Helpers ---
  const hasActiveRental = (customerId: string) => {
      return orders.some(o => 
        o.customer?.id === customerId && 
        o.items.some(i => i.transactionType === 'rent') &&
        !o.status.includes('returned')
      );
  };

  // --- CRUD Handlers ---

  const handleNewCustomerClick = () => {
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewAddress('');
      setIsModalOpen(true);
  };

  const handleEditClick = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewAddress(customer.address || '');
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            address: newAddress
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewAddress('');
        setIsModalOpen(false);
        setEditingId(null);
        loadData();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
      e.stopPropagation(); 
      if(window.confirm('¿Eliminar cliente permanentemente?')) {
         await performDelete(id);
      }
  };

  const performDelete = async (id: string) => {
      try {
          await deleteCustomer(id);
          setCustomers(prev => prev.filter(c => c.id !== id));
      } catch (error) {
          alert("No se pudo eliminar el cliente.");
          loadData();
      }
  }

  // --- History & Balance Handlers ---

  const handleViewHistory = async (customer: Customer) => {
      setSelectedCustomer(customer);
      setIsHistoryOpen(true);
      const userOrders = orders.filter(o => o.customer?.id === customer.id);
      setCustomerOrders(userOrders);
      setHistoryTab('active');
  };

  const handleSettleDebt = async () => {
      if (!selectedCustomer || !selectedCustomer.id) return;
      if (!selectedCustomer.balance || selectedCustomer.balance >= 0) return;

      if (confirm(`¿Confirmar que ${selectedCustomer.name} ha liquidado su deuda de $${Math.abs(selectedCustomer.balance).toFixed(2)}?`)) {
          await updateCustomer(selectedCustomer.id, { balance: 0 });
          // Update local state
          const updated = { ...selectedCustomer, balance: 0 };
          setSelectedCustomer(updated);
          setCustomers(prev => prev.map(c => c.id === updated.id ? updated : c));
          alert("Deuda liquidada.");
      }
  };

  const filtered = customers.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(searchQuery.toLowerCase()) || c.phone.includes(searchQuery);

      if (filterMode === 'attention') {
          const isDebtor = (c.balance || 0) < 0;
          const isActive = c.id ? hasActiveRental(c.id) : false;
          return matchesSearch && (isDebtor || isActive);
      }

      return matchesSearch;
  });

  // Filter orders for the active tab inside modal
  const displayedOrders = customerOrders.filter(order => {
      if (historyTab === 'all') return true;
      // Active = Contains rentals that are NOT returned
      const hasRentals = order.items.some(i => i.transactionType === 'rent');
      const isClosed = order.status === 'returned' || order.status === 'returned_late';
      return hasRentals && !isClosed;
  });

  return (
    <div className="p-4 md:p-8 max-w-5xl mx-auto h-full flex flex-col">
      <header className="mb-8 flex justify-between items-end flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <Users className="w-8 h-8 text-indigo-600" />
            CLIENTES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">DIRECTORIO Y ALTA DE CLIENTES</p>
        </div>

        <div className="flex gap-4 items-center">
            <div className="text-right hidden sm:block">
                <div className="text-2xl font-bold text-slate-800">{customers.length}</div>
                <div className="text-xs text-slate-400 uppercase font-bold">TOTAL</div>
            </div>
            <Button onClick={handleNewCustomerClick} className="shadow-xl shadow-indigo-200 uppercase">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO CLIENTE</span>
                <span className="sm:hidden">NUEVO</span>
            </Button>
        </div>
      </header>

      {/* Main List Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
             <div className="flex gap-4 mb-6 flex-shrink-0">
                 <div className="relative flex-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR CLIENTE POR NOMBRE O TELÉFONO..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                    />
                </div>

                {/* Attention Filter Toggle */}
                <button 
                    onClick={() => setFilterMode(prev => prev === 'all' ? 'attention' : 'all')}
                    className={`px-4 rounded-2xl border flex items-center gap-2 font-bold uppercase transition-all ${filterMode === 'attention' ? 'bg-amber-100 border-amber-300 text-amber-800 shadow-sm' : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'}`}
                >
                    <AlertCircle className={`w-5 h-5 ${filterMode === 'attention' ? 'fill-current' : ''}`} />
                    <span className="hidden sm:inline">⚠️ ATENCIÓN REQUERIDA</span>
                    <span className="sm:hidden">FILTRAR</span>
                </button>
             </div>

            <div className="flex-1 overflow-y-auto space-y-3 pb-32">
                {filtered.map(customer => {
                    const isActiveRenter = customer.id && hasActiveRental(customer.id);
                    return (
                        <Card key={customer.id} className="flex items-center justify-between group hover:border-indigo-200 transition-colors cursor-pointer active:scale-[0.99]">
                            <div className="flex items-center gap-4 flex-1" onClick={() => handleViewHistory(customer)}>
                                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex flex-shrink-0 items-center justify-center font-bold text-xl uppercase relative">
                                    {customer.name.charAt(0)}
                                    {customer.balance && customer.balance < 0 ? (
                                        <div className="absolute -top-1 -right-1 w-4 h-4 bg-rose-500 rounded-full border-2 border-white"></div>
                                    ) : null}
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg text-slate-800 uppercase flex items-center gap-2">
                                        {customer.name}
                                        {customer.balance && customer.balance < 0 && (
                                            <span className="text-[10px] bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full border border-rose-200 animate-pulse font-bold flex items-center gap-1">
                                                <AlertCircle className="w-3 h-3" />
                                                DEUDA: ${Math.abs(customer.balance).toFixed(2)}
                                            </span>
                                        )}
                                        {isActiveRenter && (
                                            <span className="text-[10px] bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-full border border-indigo-200 font-bold flex items-center gap-1">
                                                <Clock className="w-3 h-3" /> RENTA ACTIVA
                                            </span>
                                        )}
                                        {customer.balance && customer.balance > 0 && (
                                            <span className="text-[10px] bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full border border-emerald-200 font-bold">
                                                FAVOR: ${customer.balance.toFixed(2)}
                                            </span>
                                        )}
                                    </h3>
                                    <div className="flex flex-col sm:flex-row sm:gap-4 text-sm text-slate-500 mt-1">
                                        {customer.phone && (
                                            <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {customer.phone}</span>
                                        )}
                                        {customer.address && (
                                            <span className="flex items-center gap-1 uppercase"><MapPin className="w-3 h-3" /> {customer.address}</span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 pl-3 border-l border-slate-100 ml-2">
                                {/* History Button */}
                                <button 
                                    onClick={() => handleViewHistory(customer)}
                                    className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-all"
                                    title="Ver Historial"
                                >
                                    <History className="w-5 h-5" />
                                </button>

                                {/* Edit Button */}
                                <button 
                                    onClick={(e) => handleEditClick(e, customer)}
                                    className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 hover:text-indigo-600 transition-all"
                                    title="Editar"
                                >
                                    <Pencil className="w-5 h-5" />
                                </button>

                                {/* Delete Button */}
                                <button 
                                    onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                    className="p-3 bg-rose-50 rounded-xl text-rose-400 hover:text-rose-600 hover:bg-rose-100 transition-all active:bg-rose-200"
                                    title="Eliminar Cliente"
                                >
                                    <Trash2 className="w-5 h-5" />
                                </button>
                            </div>
                        </Card>
                    );
                })}
                {filtered.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                        <Users className="w-16 h-16 mb-4 opacity-20" />
                        <p className="uppercase">NO SE ENCONTRARON CLIENTES</p>
                    </div>
                )}
            </div>
      </div>

      {/* CREATE/EDIT MODAL */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={editingId ? 'EDITAR CLIENTE' : 'REGISTRAR NUEVO CLIENTE'}
      >
        <form onSubmit={handleSubmit} className="space-y-6 pt-2">
            <div className="space-y-4">
                <Input 
                    label="NOMBRE COMPLETO" 
                    placeholder="EJ. JUAN PÉREZ" 
                    value={newName}
                    onChange={(e) => setNewName(e.target.value.toUpperCase())}
                    autoFocus
                />
                <Input 
                    label="TELÉFONO" 
                    placeholder="EJ. 55 1234 5678" 
                    value={newPhone}
                    onChange={(e) => {
                        const val = e.target.value.replace(/\D/g, '');
                        if (val.length <= 10) setNewPhone(val);
                    }}
                    type="tel"
                    maxLength={10}
                />
                 <Input 
                    label="DIRECCIÓN" 
                    placeholder="CALLE, NÚMERO, COLONIA..." 
                    value={newAddress}
                    onChange={(e) => setNewAddress(e.target.value.toUpperCase())}
                />
            </div>

            <div className="pt-6 flex gap-3">
                <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="flex-1 uppercase">
                    CANCELAR
                </Button>
                <Button type="submit" className="flex-[2] uppercase">
                    {editingId ? 'GUARDAR CAMBIOS' : 'REGISTRAR CLIENTE'}
                </Button>
            </div>
        </form>
      </Modal>

      {/* HISTORY MODAL */}
      {selectedCustomer && (
        <Modal 
            isOpen={isHistoryOpen} 
            onClose={() => setIsHistoryOpen(false)} 
            title={`HISTORIAL: ${selectedCustomer.name}`}
        >
            <div className="space-y-6">

                {/* Balance Card */}
                <div className={`p-4 rounded-2xl border flex justify-between items-center ${selectedCustomer.balance && selectedCustomer.balance < 0 ? 'bg-rose-50 border-rose-100' : 'bg-slate-50 border-slate-100'}`}>
                    <div>
                        <div className="text-xs font-bold uppercase tracking-wider opacity-60 flex items-center gap-1">
                            <Wallet className="w-4 h-4" /> SALDO ACTUAL
                        </div>
                        <div className={`text-3xl font-bold font-mono ${selectedCustomer.balance && selectedCustomer.balance < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
                            ${(selectedCustomer.balance || 0).toFixed(2)}
                        </div>
                    </div>
                    {selectedCustomer.balance && selectedCustomer.balance < 0 && (
                        <Button variant="danger" onClick={handleSettleDebt} className="uppercase text-xs px-4">
                            LIQUIDAR DEUDA
                        </Button>
                    )}
                </div>

                {/* Tabs */}
                <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                        onClick={() => setHistoryTab('active')}
                        className={`flex-1 py-2 text-xs font-bold uppercase rounded-lg transition-all ${historyTab === 'active' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                    >
                        RENTAS ACTIVAS
                    </button>
                    <button 
                        onClick={() => setHistoryTab('all')}
                        className={`flex-1 py-2 text-xs font-bold uppercase rounded-lg transition-all ${historyTab === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                    >
                        TODO EL HISTORIAL
                    </button>
                </div>

                {/* List */}
                <div className="max-h-[50vh] overflow-y-auto space-y-3">
                    {displayedOrders.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 text-sm uppercase">
                            NO HAY MOVIMIENTOS {historyTab === 'active' ? 'ACTIVOS' : 'REGISTRADOS'}
                        </div>
                    ) : (
                        displayedOrders.map(order => {
                            // Check if late
                            const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate && !order.status.includes('returned');

                            return (
                                <div key={order.id} className={`p-4 rounded-xl border relative ${isLate ? 'bg-rose-50/50 border-rose-200' : 'bg-white border-slate-100'}`}>
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="flex items-center gap-2">
                                            <Badge color={order.items.some(i => i.transactionType === 'rent') ? 'indigo' : 'green'}>
                                                {order.items.some(i => i.transactionType === 'rent') ? 'RENTA' : 'VENTA'}
                                            </Badge>
                                            <span className="text-xs font-mono text-slate-400">#{order.id?.slice(-4)}</span>
                                        </div>
                                        <div className="font-bold text-slate-800">${order.total.toFixed(2)}</div>
                                    </div>

                                    <div className="text-xs text-slate-500 mb-2">
                                        {new Date(order.createdAt).toLocaleDateString()}
                                    </div>

                                    {/* Active Rental Warnings */}
                                    {order.rentalEndDate && !order.status.includes('returned') && (
                                        <div className={`text-xs font-bold uppercase flex items-center gap-1 mt-2 p-2 rounded-lg ${isLate ? 'text-rose-600 bg-rose-100' : 'text-indigo-600 bg-indigo-50'}`}>
                                            <Clock className="w-3 h-3" />
                                            {isLate ? 'ATRASADO - ' : 'ENTREGAR EL: '}
                                            {new Date(order.rentalEndDate).toLocaleDateString()}
                                        </div>
                                    )}

                                    {/* Items Preview */}
                                    <div className="mt-2 space-y-1">
                                        {order.items.map((item, i) => (
                                            <div key={i} className="text-xs text-slate-600 flex justify-between">
                                                <span className="uppercase">{item.quantity} x {item.name}</span>
                                                {item.transactionType === 'rent' && <span className="font-bold text-indigo-400">R</span>}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>

            </div>
        </Modal>
      )}

    </div>
  );
};

export default Customers;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation, SystemSettings } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getSystemSettings } from '../services/dataService';

const POS: React.FC = () => {
  const location = useLocation();

  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [settings, setSettings] = useState<SystemSettings>({ defaultLateFee: 50, pricePerExtraDay: 0 });
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State (For items with 0 price)
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); 
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Helper: Format Date for Display (YYYY-MM-DD -> DD-MMM-YY)
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return 'SELECCIONAR';
      const [year, month, day] = dateStr.split('-');
      const months = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'];
      return `${day}-${months[parseInt(month) - 1]}-${year.slice(2)}`;
  };

  // Helper: Date Logic (Skip Sundays)
  const getNextBusinessDay = (date: Date): Date => {
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      // If Sunday (0), move to Monday
      if (next.getDay() === 0) {
          next.setDate(next.getDate() + 1);
      }
      return next;
  };

  const countExtraDays = (startStr: string, endStr: string): number => {
      if (!startStr || !endStr) return 0;

      const [sY, sM, sD] = startStr.split('-').map(Number);
      const start = new Date(sY, sM - 1, sD);

      const [eY, eM, eD] = endStr.split('-').map(Number);
      const end = new Date(eY, eM - 1, eD);

      const standardReturn = getNextBusinessDay(start);

      // If returning on or before standard day, no extra fee
      if (end <= standardReturn) return 0;

      // Count days from standardReturn + 1 until end, skipping Sundays
      let extraCount = 0;
      let current = new Date(standardReturn);
      current.setDate(current.getDate() + 1); // Start counting from the day after standard return

      while (current <= end) {
          if (current.getDay() !== 0) { // If not Sunday
              extraCount++;
          }
          current.setDate(current.getDate() + 1);
      }

      return extraCount;
  };

  const extraDaysCount = useMemo(() => countExtraDays(rentalDate, returnDate), [rentalDate, returnDate]);
  const extraDaysTotal = extraDaysCount * settings.pricePerExtraDay;


  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; 
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load & Redirection Handling
  useEffect(() => {
    const fetchData = async () => {
      const [p, c, s] = await Promise.all([getProducts(), getCustomers(), getSystemSettings()]);
      setProducts(p);
      setCustomers(c);
      setSettings(s);

      // Handle Redirect from Tickets for Late Fee
      if (location.state && location.state.action === 'pay_late_fee') {
         const { customer, amount, refTicket } = location.state;
         if (customer) setSelectedCustomer(customer);
         const lateFeeItem: CartItem = {
             code: 'FEE',
             name: `RECARGO POR ATRASO (Ticket #${refTicket?.slice(-4)})`,
             description: 'Cargo por devolución tardía',
             salePrice: amount,
             rentalPrice: 0,
             category: 'SERVICIOS',
             stock: 999,
             variations: [],
             isRentalAvailable: false,
             isSaleAvailable: true,
             cartId: 'late-fee-' + Date.now(),
             transactionType: 'sale',
             quantity: 1,
             appliedPrice: amount
         };
         setCart([lateFeeItem]);
         window.history.replaceState({}, document.title);
      }
    };
    fetchData();
  }, [location]);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Filter Customers for Modal
  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()) || 
    c.phone.includes(customerSearchTerm)
  );

  // --- Handlers ---

  // Date Logic: Auto set return date
  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);

      // Parse YYYY-MM-DD
      const [year, month, day] = dateStr.split('-').map(Number);
      const startDate = new Date(year, month - 1, day);

      // Logic: Delivery + 1 Business Day (Skip Sunday)
      const nextBusinessDay = getNextBusinessDay(startDate);

      const nextYear = nextBusinessDay.getFullYear();
      const nextMonth = (nextBusinessDay.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = nextBusinessDay.getDate().toString().padStart(2, '0');

      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // Customer Logic
  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          const exactMatch = filteredCustomers.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());
          if (exactMatch) {
              setSelectedCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filteredCustomers.length > 0 && customerSearchTerm === '') {
             // Do nothing
          } else {
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    setSelectedCustomer(resultCustomer);
    setShowCustomerModal(false);

    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }


  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); 
        return;
    }

    const variationId = variation ? variation.name : 'base';
    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Calculations
  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  const finalTotal = cartTotal + extraDaysTotal;

  // Checkout
  const handleCheckout = async () => {
    if (!isCheckoutEnabled) return;

    // Prepare final items - Inject Extra Day Fee as item
    const finalItems = [...cart];

    if (extraDaysTotal > 0) {
        finalItems.push({
            code: 'EXT-DAY',
            name: `DÍAS EXTRA DE RENTA (${extraDaysCount})`,
            description: 'Cargo por extensión de periodo',
            salePrice: settings.pricePerExtraDay,
            rentalPrice: settings.pricePerExtraDay,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'extra-day-' + Date.now(),
            transactionType: 'sale',
            quantity: extraDaysCount,
            appliedPrice: settings.pricePerExtraDay
        });
    }

    const order: Omit<Order, 'id'> = {
      items: finalItems,
      total: finalTotal,
      status: 'pending',
      createdAt: Date.now(),
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      await createOrder(order);
      alert("VENTA REGISTRADA!");
      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="BUSCAR POR NOMBRE O CÓDIGO..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                        {product.variations.length} VARIACIONES
                      </span>
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>RENTAR</span>
                    <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : 'VARIABLE'}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>VENDER</span>
                    <span>{product.salePrice > 0 ? `$${product.salePrice}` : 'VARIABLE'}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
