import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock, Wallet, ArrowUpRight, DollarSign } from 'lucide-react';
