               return (
                 <button 
                   key={i}
                   onClick={() => handleVariationSelect(typeof v === 'string' ? {name: v} : v)}
                   className="flex justify-between items-center p-4 rounded-xl border border-slate-200 hover:border-indigo-500 hover:bg-indigo-50 transition-all active:scale-95"
                 >
                    <span className="font-bold text-slate-800">{vName}</span>
                    <span className="font-mono font-medium text-indigo-600">{vPrice > 0 ? `$${vPrice}` : 'PRECIO LIBRE'}</span>
                 </button>
               );
             })}
           </div>
           <div className="pt-2">
             <Button variant="ghost" onClick={() => setVariationModalData(null)} className="w-full uppercase">CANCELAR</Button>
           </div>
        </div>
      </Modal>

      {/* Custom Price Modal */}
      {customPriceModal && (
         <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
             <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col">
                 <div className="p-6 pb-2 text-center">
                    <h3 className="text-lg font-bold text-slate-500 uppercase tracking-wide">INGRESAR PRECIO</h3>
                    <p className="text-slate-400 text-sm mb-4">{customPriceModal.product.name} {customPriceModal.variation ? `(${typeof customPriceModal.variation === 'string' ? customPriceModal.variation : customPriceModal.variation.name})` : ''}</p>
                    <div className="text-5xl font-bold text-indigo-600 mb-2 font-mono h-14">
                        ${customPriceValue || '0'}
                    </div>
                 </div>

                 <div className="p-4 grid grid-cols-3 gap-3">
                    {[1,2,3,4,5,6,7,8,9].map(n => (
                        <button key={n} onClick={() => handleNumpadPress(n.toString())} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">
                            {n}
                        </button>
                    ))}
                    <button onClick={() => handleNumpadPress('.')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">.</button>
                    <button onClick={() => handleNumpadPress('0')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">0</button>
                    <button onClick={handleNumpadBackspace} className="h-16 rounded-xl bg-rose-50 text-rose-500 flex items-center justify-center active:bg-rose-100 transition-colors">
                        <Delete className="w-8 h-8" />
                    </button>
                 </div>

                 <div className="p-4 pt-0 grid grid-cols-2 gap-3">
                     <Button variant="secondary" onClick={() => setCustomPriceModal(null)} className="h-14 text-lg uppercase">CANCELAR</Button>
                     <Button onClick={handleCustomPriceSubmit} className="h-14 text-lg uppercase">ACEPTAR</Button>
                 </div>
             </div>
         </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock, Wallet, ArrowUpRight, DollarSign } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation, SystemSettings } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getSystemSettings } from '../services/dataService';

const POS: React.FC = () => {
  const location = useLocation();

  // State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [settings, setSettings] = useState<SystemSettings>({ defaultLateFee: 50, pricePerExtraDay: 0, cardFeePercentage: 0 });
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);

  // Payment Logic State
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountTendered, setAmountTendered] = useState('');

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State (For items with 0 price)
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); 
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // Helper: Format Date for Display (YYYY-MM-DD -> DD-MMM-YY)
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return 'SELECCIONAR';
      const [year, month, day] = dateStr.split('-');
      const months = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'];
      return `${day}-${months[parseInt(month) - 1]}-${year.slice(2)}`;
  };

  // Helper: Date Logic (Skip Sundays)
  const getNextBusinessDay = (date: Date): Date => {
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      // If Sunday (0), move to Monday
      if (next.getDay() === 0) {
          next.setDate(next.getDate() + 1);
      }
      return next;
  };

  const countExtraDays = (startStr: string, endStr: string): number => {
      if (!startStr || !endStr) return 0;

      const [sY, sM, sD] = startStr.split('-').map(Number);
      const start = new Date(sY, sM - 1, sD);

      const [eY, eM, eD] = endStr.split('-').map(Number);
      const end = new Date(eY, eM - 1, eD);

      const standardReturn = getNextBusinessDay(start);

      // If returning on or before standard day, no extra fee
      if (end <= standardReturn) return 0;

      // Count days from standardReturn + 1 until end, skipping Sundays
      let extraCount = 0;
      let current = new Date(standardReturn);
      current.setDate(current.getDate() + 1); // Start counting from the day after standard return

      while (current <= end) {
          if (current.getDay() !== 0) { // If not Sunday
              extraCount++;
          }
          current.setDate(current.getDate() + 1);
      }

      return extraCount;
  };

  const extraDaysCount = useMemo(() => countExtraDays(rentalDate, returnDate), [rentalDate, returnDate]);
  const extraDaysTotal = extraDaysCount * settings.pricePerExtraDay;


  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; 
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load & Redirection Handling
  useEffect(() => {
    const fetchData = async () => {
      const [p, c, s] = await Promise.all([getProducts(), getCustomers(), getSystemSettings()]);
      setProducts(p);
      setCustomers(c);
      setSettings(s);

      // Handle Redirect from Tickets for Late Fee
      if (location.state && location.state.action === 'pay_late_fee') {
         const { customer, amount, refTicket } = location.state;
         if (customer) setSelectedCustomer(customer);
         const lateFeeItem: CartItem = {
             code: 'FEE',
             name: `RECARGO POR ATRASO (Ticket #${refTicket?.slice(-4)})`,
             description: 'Cargo por devolución tardía',
             salePrice: amount,
             rentalPrice: 0,
             category: 'SERVICIOS',
             stock: 999,
             variations: [],
             isRentalAvailable: false,
             isSaleAvailable: true,
             cartId: 'late-fee-' + Date.now(),
             transactionType: 'sale',
             quantity: 1,
             appliedPrice: amount
         };
         setCart([lateFeeItem]);
         window.history.replaceState({}, document.title);
      }
    };
    fetchData();
  }, [location]);

  // Filter Products
  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchQuery.toLowerCase()) || 
    p.code.includes(searchQuery)
  );

  // Filter Customers for Modal
  const filteredCustomers = customers.filter(c => 
    c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()) || 
    c.phone.includes(customerSearchTerm)
  );

  // --- Handlers ---

  // Date Logic: Auto set return date
  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);

      // Parse YYYY-MM-DD
      const [year, month, day] = dateStr.split('-').map(Number);
      const startDate = new Date(year, month - 1, day);

      // Logic: Delivery + 1 Business Day (Skip Sunday)
      const nextBusinessDay = getNextBusinessDay(startDate);

      const nextYear = nextBusinessDay.getFullYear();
      const nextMonth = (nextBusinessDay.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = nextBusinessDay.getDate().toString().padStart(2, '0');

      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // Customer Logic
  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          const exactMatch = filteredCustomers.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());
          if (exactMatch) {
              setSelectedCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filteredCustomers.length > 0 && customerSearchTerm === '') {
             // Do nothing
          } else {
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    setSelectedCustomer(resultCustomer);
    setShowCustomerModal(false);

    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }


  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); 
        return;
    }

    const variationId = variation ? variation.name : 'base';
    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // --- Payment Calculations ---
  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  const totalWithExtraDays = cartTotal + extraDaysTotal;

  // Dynamic Total based on Payment Method (Card Fee)
  const cardFeeAmount = settings.cardFeePercentage ? (totalWithExtraDays * (settings.cardFeePercentage / 100)) : 0;
  const finalPayableTotal = paymentMethod === 'card' ? totalWithExtraDays + cardFeeAmount : totalWithExtraDays;

  // Change Calculation
  const tendered = parseFloat(amountTendered) || 0;
  const changeDue = paymentMethod === 'cash' ? Math.max(0, tendered - finalPayableTotal) : 0;

  // Smart Bills Logic (Mexican Pesos)
  const suggestedBills = useMemo(() => {
      if (paymentMethod !== 'cash') return [];
      const total = finalPayableTotal;
      const commonBills = [20, 50, 100, 200, 500, 1000];

      const suggestions = commonBills.filter(bill => bill >= total);
      // Always include exact amount if not in bills (unlikely for exact, but good for UX)
      // Return top 3 closest bills
      return suggestions.slice(0, 3);
  }, [finalPayableTotal, paymentMethod]);


  // Initiate Checkout Flow
  const openPaymentModal = () => {
      if (!isCheckoutEnabled) return;
      setPaymentMethod('cash');
      setAmountTendered('');
      setShowPaymentModal(true);
  };

  // Finalize Order
  const confirmCheckout = async () => {
    // If Cash, validate amount
    if (paymentMethod === 'cash' && tendered < finalPayableTotal) {
        alert("El monto recibido es menor al total.");
        return;
    }

    // Prepare final items
    const finalItems = [...cart];

    // Inject Extra Day Fee
    if (extraDaysTotal > 0) {
        finalItems.push({
            code: 'EXT-DAY',
            name: `DÍAS EXTRA DE RENTA (${extraDaysCount})`,
            description: 'Cargo por extensión de periodo',
            salePrice: settings.pricePerExtraDay,
            rentalPrice: settings.pricePerExtraDay,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'extra-day-' + Date.now(),
            transactionType: 'sale',
            quantity: extraDaysCount,
            appliedPrice: settings.pricePerExtraDay
        });
    }

    // Inject Card Fee
    if (paymentMethod === 'card' && cardFeeAmount > 0) {
         finalItems.push({
            code: 'CARD-FEE',
            name: `COMISIÓN POR TARJETA (${settings.cardFeePercentage}%)`,
            description: 'Cargo por servicio',
            salePrice: cardFeeAmount,
            rentalPrice: 0,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'card-fee-' + Date.now(),
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: cardFeeAmount
        });
    }

    const order: Omit<Order, 'id'> = {
      items: finalItems,
      total: finalPayableTotal,
      status: 'pending',
      createdAt: Date.now(),
      paymentMethod: paymentMethod,
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      await createOrder(order);

      // UX Success
      if (paymentMethod === 'cash' && changeDue > 0) {
          alert(`VENTA REGISTRADA.\n\nENTREGAR CAMBIO: $${changeDue.toFixed(2)}`);
      } else {
          alert("VENTA REGISTRADA EXITOSAMENTE.");
      }

      // Reset
      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
      setShowPaymentModal(false);
    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Product Grid */}
      <div className="flex-1 flex flex-col h-full overflow-hidden">
        <div className="p-4 md:p-6 pb-0">
          <div className="relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
            <input 
              type="text" 
              placeholder="BUSCAR POR NOMBRE O CÓDIGO..." 
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-white shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
            />
          </div>
        </div>

        <div className="p-4 md:p-6 overflow-y-auto grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-32 lg:pb-6">
          {filteredProducts.map(product => (
            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
              <div>
                <div className="flex justify-between items-start mb-2">
                   <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                   <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                </div>
                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                {product.variations && product.variations.length > 0 && (
                   <div className="flex gap-1 mt-2 flex-wrap">
                      <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                        {product.variations.length} VARIACIONES
                      </span>
                   </div>
                )}
              </div>

              <div className="mt-4 space-y-2">
                {product.isRentalAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'rent')}
                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>RENTAR</span>
                    <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : 'VARIABLE'}</span>
                  </button>
                )}
                {product.isSaleAvailable && (
                  <button 
                    onClick={() => handleProductClick(product, 'sale')}
                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                  >
                    <span>VENDER</span>
                    <span>{product.salePrice > 0 ? `$${product.salePrice}` : 'VARIABLE'}</span>
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2 uppercase">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            TICKET ACTUAL
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors uppercase">
            LIMPIAR
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 && extraDaysCount === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p className="uppercase">EL CARRITO ESTÁ VACÍO</p>
            </div>
          ) : (
             <>
                {cart.map((item) => (
                <div key={item.cartId} className="flex gap-4 p-3 bg-slate-50 rounded-2xl group">
                    <div className="flex-1">
                    <div className="flex justify-between">
                        <div>
                        <h4 className="font-semibold text-slate-800 leading-tight">{item.name}</h4>
                        {item.selectedVariation && (
                            <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                                {item.selectedVariation.name}
                            </div>
                        )}
                        </div>
                        <span className="font-mono font-bold text-slate-700">
                            ${(item.appliedPrice * item.quantity).toFixed(2)}
                        </span>
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                        <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                            {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                        </Badge>
                        <span className="text-xs text-slate-400">COD: {item.code}</span>
                        {item.appliedPrice === 0 || (item.transactionType === 'rent' && item.rentalPrice === 0) || (item.transactionType === 'sale' && item.salePrice === 0) ? (
                            <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-1 rounded uppercase">PRECIO MANUAL</span>
                        ) : null}
                    </div>
                    </div>

                    <div className="flex flex-col items-center gap-2">
                        <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                            <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                            <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
