import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock, Wallet, ArrowUpRight, DollarSign, LayoutGrid, ListFilter, Percent, Box, Star } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation, SystemSettings } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getSystemSettings } from '../services/dataService';

const POS: React.FC = () => {
  const location = useLocation();

  // View State
  const [viewMode, setViewMode] = useState<'dashboard' | 'catalog'>('dashboard');
  const [activeCategory, setActiveCategory] = useState<string>('TODOS');

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [settings, setSettings] = useState<SystemSettings>({ defaultLateFee: 50, pricePerExtraDay: 0, cardFeePercentage: 0 });
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);

  // Payment Logic State
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountTendered, setAmountTendered] = useState('');

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); 
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // --- Derived Data ---
  const categories = useMemo(() => {
      const cats = products.map(p => p.category).filter(Boolean);
      return ['TODOS', ...Array.from(new Set(cats)).sort()];
  }, [products]);

  const filteredCustomers = useMemo(() => {
      const term = customerSearchTerm.toLowerCase();
      return customers.filter(c => 
          c.name.toLowerCase().includes(term) || 
          c.phone.includes(term)
      );
  }, [customers, customerSearchTerm]);

  // Helper: Format Date
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return 'SELECCIONAR';
      const [year, month, day] = dateStr.split('-');
      const months = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'];
      return `${day}-${months[parseInt(month) - 1]}-${year.slice(2)}`;
  };

  const getNextBusinessDay = (date: Date): Date => {
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      if (next.getDay() === 0) {
          next.setDate(next.getDate() + 1);
      }
      return next;
  };

  const countExtraDays = (startStr: string, endStr: string): number => {
      if (!startStr || !endStr) return 0;
      const [sY, sM, sD] = startStr.split('-').map(Number);
      const start = new Date(sY, sM - 1, sD);
      const [eY, eM, eD] = endStr.split('-').map(Number);
      const end = new Date(eY, eM - 1, eD);
      const standardReturn = getNextBusinessDay(start);
      if (end <= standardReturn) return 0;
      let extraCount = 0;
      let current = new Date(standardReturn);
      current.setDate(current.getDate() + 1); 
      while (current <= end) {
          if (current.getDay() !== 0) extraCount++;
          current.setDate(current.getDate() + 1);
      }
      return extraCount;
  };

  const extraDaysCount = useMemo(() => countExtraDays(rentalDate, returnDate), [rentalDate, returnDate]);
  const extraDaysTotal = extraDaysCount * settings.pricePerExtraDay;

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; 
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const [p, c, s] = await Promise.all([getProducts(), getCustomers(), getSystemSettings()]);
      setProducts(p);
      setCustomers(c);
      setSettings(s);

      if (location.state && location.state.action === 'pay_late_fee') {
         const { customer, amount, refTicket } = location.state;
         if (customer) handleSetCustomer(customer); // Use new handler

         const lateFeeItem: CartItem = {
             code: 'FEE',
             name: `RECARGO POR ATRASO (Ticket #${refTicket})`,
             description: 'Cargo por devolución tardía',
             salePrice: amount,
             rentalPrice: 0,
             category: 'SERVICIOS',
             stock: 999,
             variations: [],
             isRentalAvailable: false,
             isSaleAvailable: true,
             cartId: 'late-fee-' + Date.now(),
             transactionType: 'sale',
             quantity: 1,
             appliedPrice: amount
         };
         // We use callback to ensure we don't overwrite the Debt item if it was added by handleSetCustomer
         setCart(prev => [...prev, lateFeeItem]);
         window.history.replaceState({}, document.title);
      }
    };
    fetchData();
  }, [location]);

  // Filter Products Logic
  const filteredProducts = useMemo(() => {
      return products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.code.includes(searchQuery);
        const matchesCategory = activeCategory === 'TODOS' || p.category === activeCategory;
        return matchesSearch && matchesCategory;
      });
  }, [products, searchQuery, activeCategory]);

  // --- Handlers ---

  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);
      const [year, month, day] = dateStr.split('-');
      const startDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
      const nextBusinessDay = getNextBusinessDay(startDate);
      const nextYear = nextBusinessDay.getFullYear();
      const nextMonth = (nextBusinessDay.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = nextBusinessDay.getDate().toString().padStart(2, '0');
      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // --- CUSTOMER HANDLING WITH DEBT LOGIC ---
  const handleSetCustomer = (customer: Customer | null) => {
    // 1. Remove any existing 'DEUDA' item first (from previous customer)
    setCart(prevCart => prevCart.filter(item => item.code !== 'DEUDA'));

    if (customer && customer.balance && customer.balance < 0) {
        // 2. Add debt item if customer has debt
        const debtAmount = Math.abs(customer.balance);
        const debtItem: CartItem = {
            code: 'DEUDA',
            name: 'LIQUIDACIÓN DE ADEUDO',
            description: 'Saldo pendiente anterior',
            salePrice: debtAmount,
            rentalPrice: 0,
            category: 'FINANCIERO',
            stock: 1,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'debt-' + customer.id,
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: debtAmount
        };
        setCart(prevCart => [...prevCart, debtItem]);
    }

    setSelectedCustomer(customer);
  };

  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          const filtered = customers.filter(c => c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()));
          const exactMatch = filtered.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());
          if (exactMatch) {
              handleSetCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filtered.length > 0 && customerSearchTerm === '') {
             // Do nothing
          } else {
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    handleSetCustomer(resultCustomer);
    setShowCustomerModal(false);

    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); 
        return;
    }

    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Manual Item / Discount Addition
  const handleAddManualItem = () => {
      const dummyProduct: Product = {
          code: 'MANUAL',
          name: 'CONCEPTO MANUAL / DESCUENTO',
          description: 'Ajuste manual',
          salePrice: 0,
          rentalPrice: 0,
          category: 'SERVICIOS',
          stock: 999,
          variations: [],
          isRentalAvailable: false,
          isSaleAvailable: true,
      };
      // Use sale type for manual adjustments
      setCustomPriceModal({ product: dummyProduct, type: 'sale' });
      setCustomPriceValue('');
  };

  const handleQuickCategoryClick = (category: string) => {
      if (category === 'TODOS') {
          setActiveCategory('TODOS');
      } else {
          setActiveCategory(category);
      }
      setViewMode('catalog');
  };

  // --- Payment Calculations ---
  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  const totalWithExtraDays = cartTotal + extraDaysTotal;
  const cardFeeAmount = settings.cardFeePercentage ? (totalWithExtraDays * (settings.cardFeePercentage / 100)) : 0;
  const finalPayableTotal = paymentMethod === 'card' ? totalWithExtraDays + cardFeeAmount : totalWithExtraDays;
  const tendered = parseFloat(amountTendered) || 0;
  const changeDue = paymentMethod === 'cash' ? Math.max(0, tendered - finalPayableTotal) : 0;

  const suggestedBills = useMemo(() => {
      if (paymentMethod !== 'cash') return [];
      const total = finalPayableTotal;
      const commonBills = [20, 50, 100, 200, 500, 1000];
      const suggestions = commonBills.filter(bill => bill >= total);
      return suggestions.slice(0, 3);
  }, [finalPayableTotal, paymentMethod]);

  const openPaymentModal = () => {
      if (!isCheckoutEnabled) return;
      setPaymentMethod('cash');
      setAmountTendered('');
      setShowPaymentModal(true);
  };

  const confirmCheckout = async () => {
    if (paymentMethod === 'cash' && tendered < finalPayableTotal) {
        alert("El monto recibido es menor al total.");
        return;
    }

    const finalItems = [...cart];

    // Check if we are paying off a debt
    const debtItem = cart.find(i => i.code === 'DEUDA');

    if (extraDaysTotal > 0) {
        finalItems.push({
            code: 'EXT-DAY',
            name: `DÍAS EXTRA DE RENTA (${extraDaysCount})`,
            description: 'Cargo por extensión de periodo',
            salePrice: settings.pricePerExtraDay,
            rentalPrice: settings.pricePerExtraDay,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'extra-day-' + Date.now(),
            transactionType: 'sale',
            quantity: extraDaysCount,
            appliedPrice: settings.pricePerExtraDay
        });
    }

    if (paymentMethod === 'card' && cardFeeAmount > 0) {
         finalItems.push({
            code: 'CARD-FEE',
            name: `CARGO POR SERVICIO (${settings.cardFeePercentage}%)`,
            description: 'Cargo por servicio',
            salePrice: cardFeeAmount,
            rentalPrice: 0,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'card-fee-' + Date.now(),
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: cardFeeAmount
        });
    }

    const order: Omit<Order, 'id'> = {
      items: finalItems,
      total: finalPayableTotal,
      status: 'pending',
      createdAt: Date.now(),
      paymentMethod: paymentMethod,
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      const createdOrder = await createOrder(order);

      // If there was a debt item and the customer was selected, update their balance to 0 (Assuming full payment)
      if (debtItem && selectedCustomer && selectedCustomer.id) {
          // Update the balance in Firestore
          await updateCustomer(selectedCustomer.id, { balance: 0 });
          // Update local customer list state
          setCustomers(prev => prev.map(c => c.id === selectedCustomer.id ? { ...c, balance: 0 } : c));
      }

      if (paymentMethod === 'cash' && changeDue > 0) {
          alert(`TICKET #${createdOrder.id} REGISTRADO.\n\nENTREGAR CAMBIO: $${changeDue.toFixed(2)}`);
      } else {
          alert(`TICKET #${createdOrder.id} REGISTRADO EXITOSAMENTE.`);
      }

      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
      setShowPaymentModal(false);
      setViewMode('dashboard'); // Return to dashboard after sale
    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Dashboard or Catalog */}
      <div className="flex-1 flex flex-col h-full overflow-hidden relative">

        {/* Top Navigation Bar */}
        <div className="p-4 md:p-6 pb-0 flex items-center gap-3">
            <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex items-center">
                <button 
                    onClick={() => setViewMode('dashboard')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'dashboard' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <LayoutGrid className="w-5 h-5" /> INICIO
                </button>
                <button 
                    onClick={() => setViewMode('catalog')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'catalog' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <ListFilter className="w-5 h-5" /> CATÁLOGO
                </button>
            </div>
            {viewMode === 'catalog' && (
                <div className="flex-1 relative animate-in fade-in slide-in-from-right-4">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR..." 
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    />
                </div>
            )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 pb-32 lg:pb-6">

            {/* VIEW: DASHBOARD (Quick Access) */}
            {viewMode === 'dashboard' && (
                <div className="animate-in fade-in zoom-in-95 duration-300">
                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 ml-1">ACCESOS RÁPIDOS</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {/* Special Actions */}
                        <div onClick={handleAddManualItem} className="bg-gradient-to-br from-amber-400 to-orange-500 rounded-3xl p-6 shadow-lg shadow-orange-500/20 text-white cursor-pointer active:scale-95 transition-transform flex flex-col justify-between h-40 group">
                            <Percent className="w-10 h-10 bg-white/20 p-2 rounded-full" />
                            <span className="font-bold text-lg uppercase leading-none">AGREGAR<br/>DESCUENTO / OTRO</span>
                        </div>

                        <div onClick={() => handleQuickCategoryClick('TODOS')} className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm hover:border-indigo-300 hover:shadow-md cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40">
                            <Box className="w-10 h-10 text-indigo-600 bg-indigo-50 p-2 rounded-full" />
                            <span className="font-bold text-lg text-slate-800 uppercase leading-none">VER TODO<br/>EL CATÁLOGO</span>
                        </div>

                        {/* Categories as Quick Tiles */}
                        {categories.filter(c => c !== 'TODOS').map((cat, idx) => (
                            <div 
                                key={cat} 
                                onClick={() => handleQuickCategoryClick(cat)}
                                className={`rounded-3xl p-6 shadow-sm cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40 border hover:shadow-md relative overflow-hidden group
                                    ${idx % 3 === 0 ? 'bg-emerald-50 border-emerald-100 hover:border-emerald-300 text-emerald-800' : ''}
                                    ${idx % 3 === 1 ? 'bg-purple-50 border-purple-100 hover:border-purple-300 text-purple-800' : ''}
                                    ${idx % 3 === 2 ? 'bg-blue-50 border-blue-100 hover:border-blue-300 text-blue-800' : ''}
                                `}
                            >
                                <div className="absolute -right-4 -bottom-4 opacity-10 transform rotate-12 scale-150">
                                    <Tag className="w-24 h-24" />
                                </div>
                                <Tag className="w-10 h-10 bg-white/50 p-2 rounded-full" />
                                <span className="font-bold text-lg uppercase leading-tight relative z-10">{cat}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* VIEW: CATALOG */}
            {viewMode === 'catalog' && (
                <div className="flex flex-col h-full">
                    {/* Category Pills */}
                    <div className="flex gap-2 overflow-x-auto pb-4 hide-scrollbar flex-shrink-0">
                        {categories.map(cat => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`px-5 py-2 rounded-full text-sm font-bold uppercase whitespace-nowrap transition-all flex-shrink-0 ${
                                    activeCategory === cat 
                                    ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' 
                                    : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                                }`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>

                    {/* Product Grid */}
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20">
                        {filteredProducts.map(product => (
                            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
                            <div>
                                <div className="flex justify-between items-start mb-2">
                                <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                                <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                                </div>
                                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                                {product.variations && product.variations.length > 0 && (
                                <div className="flex gap-1 mt-2 flex-wrap">
                                    <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                                        {product.variations.length} VAR
                                    </span>
                                </div>
                                )}
                            </div>

                            <div className="mt-4 space-y-2">
                                {product.isRentalAvailable && (
                                <button 
                                    onClick={() => handleProductClick(product, 'rent')}
                                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                                >
                                    <span>RENTAR</span>
                                    <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : '$?'}</span>
                                </button>
                                )}
                                {product.isSaleAvailable && (
                                <button 
                                    onClick={() => handleProductClick(product, 'sale')}
                                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                                >
                                    <span>VENDER</span>
                                    <span>{product.salePrice > 0 ? `$${product.salePrice}` : '$?'}</span>
                                </button>
                                )}
                            </div>
                            </div>
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="col-span-full py-20 text-center text-slate-400">
                                <Search className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                <p>NO SE ENCONTRARON RESULTADOS EN "{activeCategory}"</p>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[450px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2 uppercase">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            TICKET ACTUAL
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors uppercase">
            LIMPIAR
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 && extraDaysCount === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p className="uppercase">EL CARRITO ESTÁ VACÍO</p>
            </div>
          ) : (
             <>
                {cart.map((item) => (
                <div key={item.cartId} className={`flex gap-4 p-3 rounded-2xl group ${item.code === 'DEUDA' ? 'bg-rose-50 border border-rose-100' : 'bg-slate-50'}`}>
                    <div className="flex-1">
                    <div className="flex justify-between">
                        <div>
                        <h4 className={`font-semibold leading-tight ${item.code === 'DEUDA' ? 'text-rose-800' : 'text-slate-800'}`}>{item.name}</h4>
                        {item.selectedVariation && (
                            <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                                {item.selectedVariation.name}
                            </div>
                        )}
                        </div>
                        <span className={`font-mono font-bold ${item.code === 'DEUDA' ? 'text-rose-700' : 'text-slate-700'}`}>
                            ${(item.appliedPrice * item.quantity).toFixed(2)}
                        </span>
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                        <Badge color={item.code === 'DEUDA' ? 'rose' : (item.transactionType === 'rent' ? 'indigo' : 'green')}>
                            {item.code === 'DEUDA' ? 'ADEUDO' : (item.transactionType === 'rent' ? 'RENTA' : 'VENTA')}
                        </Badge>
                        <span className="text-xs text-slate-400">COD: {item.code}</span>
                        {item.appliedPrice === 0 || (item.transactionType === 'rent' && item.rentalPrice === 0) || (item.transactionType === 'sale' && item.salePrice === 0) ? (
                            <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-1 rounded uppercase">PRECIO MANUAL</span>
                        ) : null}
                    </div>
                    </div>

                    <div className="flex flex-col items-center gap-2">
                        {item.code !== 'DEUDA' && (
                            <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                                <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                                <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                                <button onClick={() => updateQuantity(item.cartId, 1)} className="p-2 hover:bg-slate-100 rounded-r-lg text-slate-500 active:bg-slate-200"><Plus className="w-4 h-4"/></button>
                            </div>
                        )}
                        <button onClick={() => removeFromCart(item.cartId)} className="text-rose-400 hover:text-rose-600 p-2">
                            <Trash2 className="w-5 h-5" />
                        </button>
                    </div>
                </div>
                ))}

                {/* Phantom Item for Extra Days */}
                {extraDaysCount > 0 && (
                    <div className="flex gap-4 p-3 bg-indigo-50 rounded-2xl border border-indigo-100">
                         <div className="flex-1">
                            <div className="flex justify-between">
                                <div>
                                    <h4 className="font-semibold text-indigo-800 leading-tight">CARGO: DÍAS EXTRA</h4>
                                    <div className="text-xs text-indigo-600 font-bold mt-0.5">
                                        {extraDaysCount} Día(s) x ${settings.pricePerExtraDay}
                                    </div>
                                </div>
                                <span className="font-mono font-bold text-indigo-800">
                                    ${extraDaysTotal.toFixed(2)}
                                </span>
                            </div>
                            <div className="flex items-center gap-2 mt-1">
                                <span className="text-[10px] bg-indigo-200 text-indigo-800 font-bold px-1.5 py-0.5 rounded uppercase">SERVICIO</span>
                                <div className="text-xs text-indigo-400 flex items-center gap-1">
                                    <CalendarClock className="w-3 h-3" /> Automático
                                </div>
                            </div>
                         </div>
                    </div>
                )}
             </>
          )}
        </div>

        {/* Rental & Customer Info */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-4">

          {/* Customer Selection */}
          {hasRentals && (
             <button 
                onClick={openCustomerModal}
                className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all active:scale-95 shadow-sm ${
                    selectedCustomer 
                    ? 'bg-indigo-600 border-indigo-600 text-white' 
                    : 'bg-white border-dashed border-slate-300 text-slate-500 hover:border-indigo-400 hover:text-indigo-600'
                }`}
             >
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${selectedCustomer ? 'bg-white/20' : 'bg-slate-100'}`}>
                        <User className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                        <div className="text-xs font-bold uppercase tracking-wider opacity-80">
                            {selectedCustomer ? 'CLIENTE ASIGNADO' : 'ASIGNAR CLIENTE (REQUERIDO)'}
                        </div>
                        <div className="font-bold text-lg leading-tight">
                            {selectedCustomer ? selectedCustomer.name : 'SELECCIONAR...'}
                        </div>
                    </div>
                </div>
                {selectedCustomer ? (
                     <div onClick={(e) => { e.stopPropagation(); handleSetCustomer(null); }} className="p-2 bg-white/20 rounded-full hover:bg-white/30">
                        <Trash2 className="w-5 h-5" />
                     </div>
                ) : (
                    <ChevronRight className="w-6 h-6" />
                )}
             </button>
          )}

          {hasRentals && (
            <div className="grid grid-cols-2 gap-3">
                <div onClick={() => setShowStartDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA ENTREGA</span>
                    <div className="flex items-center gap-2">
                        <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!rentalDate && 'text-slate-400'}`}>{formatDateDisplay(rentalDate)}</span>
                    </div>
                    {!rentalDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
                <div onClick={() => setShowEndDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA DEVOLUCIÓN</span>
                    <div className="flex items-center gap-2">
                         <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!returnDate && 'text-slate-400'}`}>{formatDateDisplay(returnDate)}</span>
                    </div>
                    {!returnDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
            </div>
          )}

          {/* Totals */}
          <div className="pt-2">
            <div className="flex justify-between items-center mb-4">
                <span className="text-slate-500 uppercase">TOTAL A PAGAR</span>
                <span className="text-3xl font-bold text-slate-800">${totalWithExtraDays.toFixed(2)}</span>
            </div>

            <Button 
                onClick={openPaymentModal} 
                className={`w-full py-4 text-lg shadow-xl uppercase ${isCheckoutEnabled ? 'shadow-indigo-200' : 'bg-slate-300 text-slate-500 shadow-none cursor-not-allowed'}`}
                disabled={!isCheckoutEnabled}
            >
                {isCheckoutEnabled ? 'COBRAR TICKET' : (hasRentals ? 'COMPLETA DATOS DE RENTA' : 'CARRITO VACÍO')}
            </Button>
          </div>
        </div>
      </div>

      {/* PAYMENT MODAL */}
      <Modal 
        isOpen={showPaymentModal} 
        onClose={() => setShowPaymentModal(false)} 
        title="FINALIZAR COBRO"
      >
        <div className="space-y-6">

            {/* Payment Method Tabs */}
            <div className="flex bg-slate-100 p-1 rounded-2xl">
                <button onClick={() => setPaymentMethod('cash')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'cash' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    EFECTIVO
                </button>
                <button onClick={() => setPaymentMethod('card')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'card' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    TARJETA
                </button>
                <button onClick={() => setPaymentMethod('transfer')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'transfer' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    TRANSFER
                </button>
            </div>

            {/* Total Display */}
            <div className="text-center p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">TOTAL A COBRAR</div>
                <div className="text-5xl font-black text-slate-800 font-mono tracking-tight">
                    ${finalPayableTotal.toFixed(2)}
                </div>
                {paymentMethod === 'card' && cardFeeAmount > 0 && (
                    <div className="mt-2 inline-flex items-center gap-1 bg-amber-100 text-amber-800 px-3 py-1 rounded-full text-xs font-bold">
                        <AlertCircle className="w-3 h-3" />
                        INCLUYE ${cardFeeAmount.toFixed(2)} DE SERVICIO ({settings.cardFeePercentage}%)
                    </div>
                )}
            </div>

            {/* Cash Specific Controls */}
            {paymentMethod === 'cash' && (
                <div className="space-y-4 animate-in fade-in zoom-in-95 duration-200">
                    <Input 
                        label="DINERO RECIBIDO" 
                        placeholder="$0.00" 
                        type="number"
                        className="text-2xl font-bold text-center"
                        value={amountTendered}
                        onChange={(e) => setAmountTendered(e.target.value)}
                        autoFocus
                    />

                    {/* Smart Suggestion Buttons */}
                    <div className="grid grid-cols-4 gap-2">
                        {/* Always show Exact */}
                         <button 
                            onClick={() => setAmountTendered(finalPayableTotal.toString())}
                            className="bg-slate-100 hover:bg-indigo-50 hover:text-indigo-600 text-slate-600 font-bold py-3 rounded-xl text-sm border border-slate-200 transition-colors"
                        >
                            EXACTO
                        </button>
                        {suggestedBills.map(bill => (
                             <button 
                                key={bill}
                                onClick={() => setAmountTendered(bill.toString())}
                                className="bg-white hover:bg-emerald-50 hover:border-emerald-200 hover:text-emerald-700 text-slate-700 font-bold py-3 rounded-xl text-lg border border-slate-200 shadow-sm transition-all"
                            >
                                ${bill}
                            </button>
                        ))}
                    </div>

                    {/* Change Display */}
                    {tendered >= finalPayableTotal && (
                         <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-2xl flex justify-between items-center">
                             <div className="text-emerald-800 font-bold uppercase text-sm">CAMBIO A ENTREGAR</div>
                             <div className="text-2xl font-black text-emerald-600 font-mono">${changeDue.toFixed(2)}</div>
                         </div>
                    )}
                </div>
            )}

            {/* Transfer/Card Info */}
            {(paymentMethod === 'card' || paymentMethod === 'transfer') && (
                <div className="p-8 text-center text-slate-400 animate-in fade-in zoom-in-95 duration-200">
                     {paymentMethod === 'card' ? <CreditCard className="w-16 h-16 mx-auto mb-4 opacity-50" /> : <ArrowUpRight className="w-16 h-16 mx-auto mb-4 opacity-50" />}
                     <p className="uppercase font-medium">
                         PROCESE EL PAGO EN TERMINAL O APP BANCARIA POR <strong className="text-slate-800">${finalPayableTotal.toFixed(2)}</strong>
                     </p>
                </div>
            )}

            {/* Actions */}
            <div className="grid grid-cols-2 gap-4 pt-4">
                <Button variant="secondary" onClick={() => setShowPaymentModal(false)} className="uppercase h-14">CANCELAR</Button>
                <Button 
                    onClick={confirmCheckout} 
                    className="uppercase h-14 shadow-xl"
                    disabled={paymentMethod === 'cash' && tendered < finalPayableTotal}
                >
                    CONFIRMAR PAGO
                </Button>
            </div>
        </div>
      </Modal>

      {/* Date Pickers */}
      <DatePickerModal 
        isOpen={showStartDatePicker} 
        onClose={() => setShowStartDatePicker(false)} 
        onSelect={handleRentalStartDateSelect} 
        title="FECHA DE ENTREGA"
      />
       <DatePickerModal 
        isOpen={showEndDatePicker} 
        onClose={() => setShowEndDatePicker(false)} 
        onSelect={setReturnDate} 
        title="FECHA DE DEVOLUCIÓN"
      />

      {/* Improved Customer Modal */}
      <Modal 
        isOpen={showCustomerModal} 
        onClose={() => setShowCustomerModal(false)} 
        title={customerViewMode === 'search' ? "BUSCAR CLIENTE" : (editingCustomerId ? "EDITAR CLIENTE" : "REGISTRAR CLIENTE")}
      >
          {customerViewMode === 'search' ? (
              <>
                  <div className="mb-4">
                      <div className="relative">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                          <input 
                              type="text"
                              autoFocus
                              placeholder="ESCRIBE NOMBRE O TELÉFONO..."
                              value={customerSearchTerm}
                              onChange={(e) => setCustomerSearchTerm(e.target.value.toUpperCase())}
                              onKeyDown={handleCustomerSearchKeyDown}
                              className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 border border-slate-200 text-lg font-bold outline-none focus:ring-2 focus:ring-indigo-500/20 uppercase"
                          />
                      </div>
                      <div className="mt-2 flex justify-between items-center text-xs text-slate-400 px-1">
                          <span>{filteredCustomers.length} COINCIDENCIAS</span>
                          <span>PRESIONA <strong>ENTER</strong> PARA CREAR SI NO EXISTE</span>
                      </div>
                  </div>

                  <div className="max-h-60 overflow-y-auto space-y-2 mb-4">
                      {filteredCustomers.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => { handleSetCustomer(c); setShowCustomerModal(false); }} 
                            className="w-full text-left px-4 py-3 bg-white border border-slate-100 hover:bg-indigo-50 hover:border-indigo-200 active:scale-95 transition-all rounded-xl flex justify-between items-center cursor-pointer group"
                          >
                              <div className="flex-1">
                                  <div className="flex items-center gap-2">
                                    <div className="font-bold text-slate-800 text-lg">{c.name}</div>
                                    {/* SHOW DEBT WARNING */}
                                    {c.balance && c.balance < 0 && (
                                        <div className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold border border-rose-200 flex items-center gap-1 animate-pulse">
                                            <AlertCircle className="w-3 h-3" />
                                            DEUDA: ${Math.abs(c.balance).toFixed(2)}
                                        </div>
                                    )}
                                  </div>
                                  <div className="flex flex-col sm:flex-row gap-1 sm:gap-4 mt-1">
                                    <div className="text-xs text-slate-500 flex items-center gap-1 font-medium">
                                        <Phone className="w-3 h-3 text-indigo-400" /> {c.phone}
                                    </div>
                                    {c.address && (
                                        <div className="text-xs text-slate-400 flex items-center gap-1 uppercase">
                                            <MapPin className="w-3 h-3 text-slate-400" /> {c.address}
                                        </div>
                                    )}
                                  </div>
                              </div>
                              <div className="flex items-center gap-2">
                                  {/* Edit Button */}
                                  <button 
                                    onClick={(e) => handleEditCustomerFromSearch(e, c)}
                                    className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-100 rounded-lg transition-colors"
                                  >
                                      <Pencil className="w-4 h-4" />
                                  </button>
                                  <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-indigo-400" />
                              </div>
                          </div>
                      ))}
                      {filteredCustomers.length === 0 && customerSearchTerm && (
                          <div className="text-center py-6 text-slate-400">
                              <p>NO SE ENCONTRÓ "{customerSearchTerm}"</p>
                          </div>
                      )}
                  </div>

                  <div className="border-t border-slate-100 pt-4">
                      <Button onClick={switchToCreateCustomer} variant="secondary" className="w-full uppercase py-4">
                          <UserPlus className="w-5 h-5" /> REGISTRAR "{customerSearchTerm || 'NUEVO'}" MANUALMENTE
                      </Button>
                  </div>
              </>
          ) : (
              <form onSubmit={handleQuickCustomerAdd} className="animate-in slide-in-from-right duration-300">
                  <div className="space-y-4">
                      <Input 
                          label="NOMBRE COMPLETO" 
                          value={newCustomerName} 
                          onChange={e => setNewCustomerName(e.target.value.toUpperCase())} 
                          placeholder="NOMBRE DEL CLIENTE"
                      />
                      <div className="grid grid-cols-1 gap-4">
                          <Input 
                              label="TELÉFONO CELULAR" 
                              value={newCustomerPhone} 
                              onChange={e => {
                                  // Ensure only digits and max length 10
                                  const val = e.target.value.replace(/\D/g, '');
                                  if (val.length <= 10) setNewCustomerPhone(val);
                              }} 
                              placeholder="10 DÍGITOS"
                              type="tel"
                              maxLength={10}
                              autoFocus
                          />
                          <Input 
                              label="DIRECCIÓN" 
                              value={newCustomerAddress} 
                              onChange={e => setNewCustomerAddress(e.target.value.toUpperCase())} 
                              placeholder="CALLE, NÚMERO, COLONIA"
                          />
                      </div>
                      <div className="flex gap-3 mt-6">
                          <Button 
                             type="button" 
                             variant="secondary" 
                             onClick={() => setCustomerViewMode('search')} 
                             className="flex-1 py-4 uppercase"
                          >
                              <ArrowLeft className="w-5 h-5" /> VOLVER
                          </Button>
                          <Button type="submit" className="flex-[2] py-4 uppercase">
                              {editingCustomerId ? 'GUARDAR CAMBIOS' : 'GUARDAR Y ASIGNAR'}
                          </Button>
                      </div>
                  </div>
              </form>
          )}
      </Modal>

      {/* Variation Selection Modal */}
      <Modal 
        isOpen={!!variationModalData} 
        onClose={() => setVariationModalData(null)} 
        title={`SELECCIONAR VARIACIÓN`}
      >
        <div className="space-y-4">
           <p className="text-sm text-slate-500 uppercase">
             ELIGE LA VARIANTE PARA <strong>{variationModalData?.product.name}</strong> ({variationModalData?.type === 'rent' ? 'RENTA' : 'VENTA'})
           </p>
           <div className="grid grid-cols-1 gap-3">
             {variationModalData?.product.variations?.map((v, i) => {
               const vName = typeof v === 'string' ? v : v.name;
               let vPrice = variationModalData?.type === 'rent' 
                  ? variationModalData.product.rentalPrice 
                  : variationModalData.product.salePrice;

               // Override if pricing exists
               if (typeof v !== 'string') {
                  if (variationModalData?.type === 'rent' && v.rentalPrice) vPrice = v.rentalPrice;
                  if (variationModalData?.type === 'sale' && v.salePrice) vPrice = v.salePrice;
               }

               return (
                 <button 
                   key={i}
                   onClick={() => handleVariationSelect(typeof v === 'string' ? {name: v} : v)}
                   className="flex justify-between items-center p-4 rounded-xl border border-slate-200 hover:border-indigo-500 hover:bg-indigo-50 transition-all active:scale-95"
                 >
                    <span className="font-bold text-slate-800">{vName}</span>
                    <span className="font-mono font-medium text-indigo-600">{vPrice > 0 ? `$${vPrice}` : 'PRECIO LIBRE'}</span>
                 </button>
               );
             })}
           </div>
           <div className="pt-2">
             <Button variant="ghost" onClick={() => setVariationModalData(null)} className="w-full uppercase">CANCELAR</Button>
           </div>
        </div>
      </Modal>

      {/* Custom Price Modal */}
      {customPriceModal && (
         <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
             <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col">
                 <div className="p-6 pb-2 text-center">
                    <h3 className="text-lg font-bold text-slate-500 uppercase tracking-wide">INGRESAR PRECIO</h3>
                    <p className="text-slate-400 text-sm mb-4">{customPriceModal.product.name} {customPriceModal.variation ? `(${typeof customPriceModal.variation === 'string' ? customPriceModal.variation : customPriceModal.variation.name})` : ''}</p>
                    <div className="text-5xl font-bold text-indigo-600 mb-2 font-mono h-14">
                        ${customPriceValue || '0'}
                    </div>
                 </div>

                 <div className="p-4 grid grid-cols-3 gap-3">
                    {[1,2,3,4,5,6,7,8,9].map(n => (
                        <button key={n} onClick={() => handleNumpadPress(n.toString())} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">
                            {n}
                        </button>
                    ))}
                    <button onClick={() => handleNumpadPress('.')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">.</button>
                    <button onClick={() => handleNumpadPress('0')} className="h-16 rounded-xl bg-slate-50 text-2xl font-bold text-slate-700 active:bg-indigo-100 active:text-indigo-600 transition-colors">0</button>
                    <button onClick={handleNumpadBackspace} className="h-16 rounded-xl bg-rose-50 text-rose-500 flex items-center justify-center active:bg-rose-100 transition-colors">
                        <Delete className="w-8 h-8" />
                    </button>
                 </div>

                 <div className="p-4 pt-0 grid grid-cols-2 gap-3">
                     <Button variant="secondary" onClick={() => setCustomPriceModal(null)} className="h-14 text-lg uppercase">CANCELAR</Button>
                     <Button onClick={handleCustomPriceSubmit} className="h-14 text-lg uppercase">ACEPTAR</Button>
                 </div>
             </div>
         </div>
      )}
    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock, Wallet, ArrowUpRight, DollarSign, LayoutGrid, ListFilter, Percent, Box, Star } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { Button, Input, Card, Badge, DatePickerModal, Modal } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation, SystemSettings } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getSystemSettings } from '../services/dataService';

const POS: React.FC = () => {
  const location = useLocation();

  // View State
  const [viewMode, setViewMode] = useState<'dashboard' | 'catalog'>('dashboard');
  const [activeCategory, setActiveCategory] = useState<string>('TODOS');

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [settings, setSettings] = useState<SystemSettings>({ defaultLateFee: 50, pricePerExtraDay: 0, cardFeePercentage: 0 });
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);

  // Payment Logic State
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountTendered, setAmountTendered] = useState('');

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); 
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // --- Derived Data ---
  const categories = useMemo(() => {
      const cats = products.map(p => p.category).filter(Boolean);
      return ['TODOS', ...Array.from(new Set(cats)).sort()];
  }, [products]);

  const filteredCustomers = useMemo(() => {
      const term = customerSearchTerm.toLowerCase();
      return customers.filter(c => 
          c.name.toLowerCase().includes(term) || 
          c.phone.includes(term)
      );
  }, [customers, customerSearchTerm]);

  // Helper: Format Date
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return 'SELECCIONAR';
      const [year, month, day] = dateStr.split('-');
      const months = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'];
      return `${day}-${months[parseInt(month) - 1]}-${year.slice(2)}`;
  };

  const getNextBusinessDay = (date: Date): Date => {
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      if (next.getDay() === 0) {
          next.setDate(next.getDate() + 1);
      }
      return next;
  };

  const countExtraDays = (startStr: string, endStr: string): number => {
      if (!startStr || !endStr) return 0;
      const [sY, sM, sD] = startStr.split('-').map(Number);
      const start = new Date(sY, sM - 1, sD);
      const [eY, eM, eD] = endStr.split('-').map(Number);
      const end = new Date(eY, eM - 1, eD);
      const standardReturn = getNextBusinessDay(start);
      if (end <= standardReturn) return 0;
      let extraCount = 0;
      let current = new Date(standardReturn);
      current.setDate(current.getDate() + 1); 
      while (current <= end) {
          if (current.getDay() !== 0) extraCount++;
          current.setDate(current.getDate() + 1);
      }
      return extraCount;
  };

  const extraDaysCount = useMemo(() => countExtraDays(rentalDate, returnDate), [rentalDate, returnDate]);
  const extraDaysTotal = extraDaysCount * settings.pricePerExtraDay;

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; 
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const [p, c, s] = await Promise.all([getProducts(), getCustomers(), getSystemSettings()]);
      setProducts(p);
      setCustomers(c);
      setSettings(s);

      if (location.state && location.state.action === 'pay_late_fee') {
         const { customer, amount, refTicket } = location.state;
         if (customer) handleSetCustomer(customer); // Use new handler

         const lateFeeItem: CartItem = {
             code: 'FEE',
             name: `RECARGO POR ATRASO (Ticket #${refTicket})`,
             description: 'Cargo por devolución tardía',
             salePrice: amount,
             rentalPrice: 0,
             category: 'SERVICIOS',
             stock: 999,
             variations: [],
             isRentalAvailable: false,
             isSaleAvailable: true,
             cartId: 'late-fee-' + Date.now(),
             transactionType: 'sale',
             quantity: 1,
             appliedPrice: amount
         };
         // We use callback to ensure we don't overwrite the Debt item if it was added by handleSetCustomer
         setCart(prev => [...prev, lateFeeItem]);
         window.history.replaceState({}, document.title);
      }
    };
    fetchData();
  }, [location]);

  // Filter Products Logic
  const filteredProducts = useMemo(() => {
      return products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.code.includes(searchQuery);
        const matchesCategory = activeCategory === 'TODOS' || p.category === activeCategory;
        return matchesSearch && matchesCategory;
      });
  }, [products, searchQuery, activeCategory]);

  // --- Handlers ---

  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);
      const [year, month, day] = dateStr.split('-');
      const startDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
      const nextBusinessDay = getNextBusinessDay(startDate);
      const nextYear = nextBusinessDay.getFullYear();
      const nextMonth = (nextBusinessDay.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = nextBusinessDay.getDate().toString().padStart(2, '0');
      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // --- CUSTOMER HANDLING WITH DEBT LOGIC ---
  const handleSetCustomer = (customer: Customer | null) => {
    // 1. Remove any existing 'DEUDA' item first (from previous customer)
    setCart(prevCart => prevCart.filter(item => item.code !== 'DEUDA'));

    if (customer && customer.balance && customer.balance < 0) {
        // 2. Add debt item if customer has debt
        const debtAmount = Math.abs(customer.balance);
        const debtItem: CartItem = {
            code: 'DEUDA',
            name: 'LIQUIDACIÓN DE ADEUDO',
            description: 'Saldo pendiente anterior',
            salePrice: debtAmount,
            rentalPrice: 0,
            category: 'FINANCIERO',
            stock: 1,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'debt-' + customer.id,
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: debtAmount
        };
        setCart(prevCart => [...prevCart, debtItem]);
    }

    setSelectedCustomer(customer);
  };

  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          const filtered = customers.filter(c => c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()));
          const exactMatch = filtered.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());
          if (exactMatch) {
              handleSetCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filtered.length > 0 && customerSearchTerm === '') {
             // Do nothing
          } else {
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    handleSetCustomer(resultCustomer);
    setShowCustomerModal(false);

    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); 
        return;
    }

    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Manual Item / Discount Addition
  const handleAddManualItem = () => {
      const dummyProduct: Product = {
          code: 'MANUAL',
          name: 'CONCEPTO MANUAL / DESCUENTO',
          description: 'Ajuste manual',
          salePrice: 0,
          rentalPrice: 0,
          category: 'SERVICIOS',
          stock: 999,
          variations: [],
          isRentalAvailable: false,
          isSaleAvailable: true,
      };
      // Use sale type for manual adjustments
      setCustomPriceModal({ product: dummyProduct, type: 'sale' });
      setCustomPriceValue('');
  };

  const handleQuickCategoryClick = (category: string) => {
      if (category === 'TODOS') {
          setActiveCategory('TODOS');
      } else {
          setActiveCategory(category);
      }
      setViewMode('catalog');
  };

  // --- Payment Calculations ---
  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  const totalWithExtraDays = cartTotal + extraDaysTotal;
  const cardFeeAmount = settings.cardFeePercentage ? (totalWithExtraDays * (settings.cardFeePercentage / 100)) : 0;
  const finalPayableTotal = paymentMethod === 'card' ? totalWithExtraDays + cardFeeAmount : totalWithExtraDays;
  const tendered = parseFloat(amountTendered) || 0;
  const changeDue = paymentMethod === 'cash' ? Math.max(0, tendered - finalPayableTotal) : 0;

  const suggestedBills = useMemo(() => {
      if (paymentMethod !== 'cash') return [];
      const total = finalPayableTotal;
      const commonBills = [20, 50, 100, 200, 500, 1000];
      const suggestions = commonBills.filter(bill => bill >= total);
      return suggestions.slice(0, 3);
  }, [finalPayableTotal, paymentMethod]);

  const openPaymentModal = () => {
      if (!isCheckoutEnabled) return;
      setPaymentMethod('cash');
      setAmountTendered('');
      setShowPaymentModal(true);
  };

  const confirmCheckout = async () => {
    if (paymentMethod === 'cash' && tendered < finalPayableTotal) {
        alert("El monto recibido es menor al total.");
        return;
    }

    const finalItems = [...cart];

    // Check if we are paying off a debt
    const debtItem = cart.find(i => i.code === 'DEUDA');

    if (extraDaysTotal > 0) {
        finalItems.push({
            code: 'EXT-DAY',
            name: `DÍAS EXTRA DE RENTA (${extraDaysCount})`,
            description: 'Cargo por extensión de periodo',
            salePrice: settings.pricePerExtraDay,
            rentalPrice: settings.pricePerExtraDay,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'extra-day-' + Date.now(),
            transactionType: 'sale',
            quantity: extraDaysCount,
            appliedPrice: settings.pricePerExtraDay
        });
    }

    if (paymentMethod === 'card' && cardFeeAmount > 0) {
         finalItems.push({
            code: 'CARD-FEE',
            name: `CARGO POR SERVICIO (${settings.cardFeePercentage}%)`,
            description: 'Cargo por servicio',
            salePrice: cardFeeAmount,
            rentalPrice: 0,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'card-fee-' + Date.now(),
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: cardFeeAmount
        });
    }

    const order: Omit<Order, 'id'> = {
      items: finalItems,
      total: finalPayableTotal,
      status: 'pending',
      createdAt: Date.now(),
      paymentMethod: paymentMethod,
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      const createdOrder = await createOrder(order);

      // If there was a debt item and the customer was selected, update their balance to 0 (Assuming full payment)
      if (debtItem && selectedCustomer && selectedCustomer.id) {
          // Update the balance in Firestore
          await updateCustomer(selectedCustomer.id, { balance: 0 });
          // Update local customer list state
          setCustomers(prev => prev.map(c => c.id === selectedCustomer.id ? { ...c, balance: 0 } : c));
      }

      if (paymentMethod === 'cash' && changeDue > 0) {
          alert(`TICKET #${createdOrder.id} REGISTRADO.\n\nENTREGAR CAMBIO: $${changeDue.toFixed(2)}`);
      } else {
          alert(`TICKET #${createdOrder.id} REGISTRADO EXITOSAMENTE.`);
      }

      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
      setShowPaymentModal(false);
      setViewMode('dashboard'); // Return to dashboard after sale
    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* LEFT: Dashboard or Catalog */}
      <div className="flex-1 flex flex-col h-full overflow-hidden relative">

        {/* Top Navigation Bar */}
        <div className="p-4 md:p-6 pb-0 flex items-center gap-3">
            <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex items-center">
                <button 
                    onClick={() => setViewMode('dashboard')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'dashboard' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <LayoutGrid className="w-5 h-5" /> INICIO
                </button>
                <button 
                    onClick={() => setViewMode('catalog')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'catalog' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <ListFilter className="w-5 h-5" /> CATÁLOGO
                </button>
            </div>
            {viewMode === 'catalog' && (
                <div className="flex-1 relative animate-in fade-in slide-in-from-right-4">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR..." 
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    />
                </div>
            )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 pb-32 lg:pb-6">

            {/* VIEW: DASHBOARD (Quick Access) */}
            {viewMode === 'dashboard' && (
                <div className="animate-in fade-in zoom-in-95 duration-300">
                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 ml-1">ACCESOS RÁPIDOS</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {/* Special Actions */}
                        <div onClick={handleAddManualItem} className="bg-gradient-to-br from-amber-400 to-orange-500 rounded-3xl p-6 shadow-lg shadow-orange-500/20 text-white cursor-pointer active:scale-95 transition-transform flex flex-col justify-between h-40 group">
                            <Percent className="w-10 h-10 bg-white/20 p-2 rounded-full" />
                            <span className="font-bold text-lg uppercase leading-none">AGREGAR<br/>DESCUENTO / OTRO</span>
                        </div>

                        <div onClick={() => handleQuickCategoryClick('TODOS')} className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm hover:border-indigo-300 hover:shadow-md cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40">
                            <Box className="w-10 h-10 text-indigo-600 bg-indigo-50 p-2 rounded-full" />
                            <span className="font-bold text-lg text-slate-800 uppercase leading-none">VER TODO<br/>EL CATÁLOGO</span>
                        </div>

                        {/* Categories as Quick Tiles */}
                        {categories.filter(c => c !== 'TODOS').map((cat, idx) => (
                            <div 
                                key={cat} 
                                onClick={() => handleQuickCategoryClick(cat)}
                                className={`rounded-3xl p-6 shadow-sm cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40 border hover:shadow-md relative overflow-hidden group
                                    ${idx % 3 === 0 ? 'bg-emerald-50 border-emerald-100 hover:border-emerald-300 text-emerald-800' : ''}
                                    ${idx % 3 === 1 ? 'bg-purple-50 border-purple-100 hover:border-purple-300 text-purple-800' : ''}
                                    ${idx % 3 === 2 ? 'bg-blue-50 border-blue-100 hover:border-blue-300 text-blue-800' : ''}
                                `}
                            >
                                <div className="absolute -right-4 -bottom-4 opacity-10 transform rotate-12 scale-150">
                                    <Tag className="w-24 h-24" />
                                </div>
                                <Tag className="w-10 h-10 bg-white/50 p-2 rounded-full" />
                                <span className="font-bold text-lg uppercase leading-tight relative z-10">{cat}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* VIEW: CATALOG */}
            {viewMode === 'catalog' && (
                <div className="flex flex-col h-full">
                    {/* Category Pills */}
                    <div className="flex gap-2 overflow-x-auto pb-4 hide-scrollbar flex-shrink-0">
                        {categories.map(cat => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`px-5 py-2 rounded-full text-sm font-bold uppercase whitespace-nowrap transition-all flex-shrink-0 ${
                                    activeCategory === cat 
                                    ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' 
                                    : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                                }`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>

                    {/* Product Grid */}
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20">
                        {filteredProducts.map(product => (
                            <div key={product.id} className="bg-white rounded-3xl p-4 shadow-sm border border-slate-100 flex flex-col justify-between group active:scale-95 transition-transform">
                            <div>
                                <div className="flex justify-between items-start mb-2">
                                <span className="text-xs font-mono text-slate-400 bg-slate-100 px-2 py-1 rounded-md">{product.code}</span>
                                <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                                </div>
                                <h3 className="font-bold text-slate-800 leading-tight mb-1">{product.name}</h3>
                                <p className="text-xs text-slate-500 line-clamp-2">{product.description}</p>
                                {product.variations && product.variations.length > 0 && (
                                <div className="flex gap-1 mt-2 flex-wrap">
                                    <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                                        {product.variations.length} VAR
                                    </span>
                                </div>
                                )}
                            </div>

                            <div className="mt-4 space-y-2">
                                {product.isRentalAvailable && (
                                <button 
                                    onClick={() => handleProductClick(product, 'rent')}
                                    className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                                >
                                    <span>RENTAR</span>
                                    <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : '$?'}</span>
                                </button>
                                )}
                                {product.isSaleAvailable && (
                                <button 
                                    onClick={() => handleProductClick(product, 'sale')}
                                    className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-sm font-semibold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                                >
                                    <span>VENDER</span>
                                    <span>{product.salePrice > 0 ? `$${product.salePrice}` : '$?'}</span>
                                </button>
                                )}
                            </div>
                            </div>
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="col-span-full py-20 text-center text-slate-400">
                                <Search className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                <p>NO SE ENCONTRARON RESULTADOS EN "{activeCategory}"</p>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[360px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2 uppercase">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            TICKET ACTUAL
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors uppercase">
            LIMPIAR
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 && extraDaysCount === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p className="uppercase">EL CARRITO ESTÁ VACÍO</p>
            </div>
          ) : (
             <>
                {cart.map((item) => (
                <div key={item.cartId} className={`flex gap-4 p-3 rounded-2xl group ${item.code === 'DEUDA' ? 'bg-rose-50 border border-rose-100' : 'bg-slate-50'}`}>
                    <div className="flex-1">
                    <div className="flex justify-between">
                        <div>
                        <h4 className={`font-semibold leading-tight ${item.code === 'DEUDA' ? 'text-rose-800' : 'text-slate-800'}`}>{item.name}</h4>
                        {item.selectedVariation && (
                            <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                                {item.selectedVariation.name}
                            </div>
                        )}
                        </div>
                        <span className={`font-mono font-bold ${item.code === 'DEUDA' ? 'text-rose-700' : 'text-slate-700'}`}>
                            ${(item.appliedPrice * item.quantity).toFixed(2)}
                        </span>
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                        <Badge color={item.code === 'DEUDA' ? 'rose' : (item.transactionType === 'rent' ? 'indigo' : 'green')}>
                            {item.code === 'DEUDA' ? 'ADEUDO' : (item.transactionType === 'rent' ? 'RENTA' : 'VENTA')}
                        </Badge>
                        <span className="text-xs text-slate-400">COD: {item.code}</span>
                        {item.appliedPrice === 0 || (item.transactionType === 'rent' && item.rentalPrice === 0) || (item.transactionType === 'sale' && item.salePrice === 0) ? (
                            <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-1 rounded uppercase">PRECIO MANUAL</span>
                        ) : null}
                    </div>
                    </div>

                    <div className="flex flex-col items-center gap-2">
                        {item.code !== 'DEUDA' && (
                            <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                                <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                                <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                                <button onClick={() => updateQuantity(item.cartId, 1)} className="p-2 hover:bg-slate-100 rounded-r-lg text-slate-500 active:bg-slate-200"><Plus className="w-4 h-4"/></button>
                            </div>
                        )}
                        <button onClick={() => removeFromCart(item.cartId)} className="text-rose-400 hover:text-rose-600 p-2">
                            <Trash2 className="w-5 h-5" />
                        </button>
                    </div>
                </div>
                ))}

                {/* Phantom Item for Extra Days */}
                {extraDaysCount > 0 && (
                    <div className="flex gap-4 p-3 bg-indigo-50 rounded-2xl border border-indigo-100">
                         <div className="flex-1">
                            <div className="flex justify-between">
                                <div>
                                    <h4 className="font-semibold text-indigo-800 leading-tight">CARGO: DÍAS EXTRA</h4>
                                    <div className="text-xs text-indigo-600 font-bold mt-0.5">
                                        {extraDaysCount} Día(s) x ${settings.pricePerExtraDay}
                                    </div>
                                </div>
                                <span className="font-mono font-bold text-indigo-800">
                                    ${extraDaysTotal.toFixed(2)}
                                </span>
                            </div>
                            <div className="flex items-center gap-2 mt-1">
                                <span className="text-[10px] bg-indigo-200 text-indigo-800 font-bold px-1.5 py-0.5 rounded uppercase">SERVICIO</span>
                                <div className="text-xs text-indigo-400 flex items-center gap-1">
                                    <CalendarClock className="w-3 h-3" /> Automático
                                </div>
                            </div>
                         </div>
                    </div>
                )}
             </>
          )}
        </div>

        {/* Rental & Customer Info */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-4">

          {/* Customer Selection */}
          {hasRentals && (
             <button 
                onClick={openCustomerModal}
                className={`w-full p-4 rounded-2xl border flex items-center justify-between transition-all active:scale-95 shadow-sm ${
                    selectedCustomer 
                    ? 'bg-indigo-600 border-indigo-600 text-white' 
                    : 'bg-white border-dashed border-slate-300 text-slate-500 hover:border-indigo-400 hover:text-indigo-600'
                }`}
             >
                <div className="flex items-center gap-3">
                    <div className={`p-2 rounded-full ${selectedCustomer ? 'bg-white/20' : 'bg-slate-100'}`}>
                        <User className="w-6 h-6" />
                    </div>
                    <div className="text-left">
                        <div className="text-xs font-bold uppercase tracking-wider opacity-80">
                            {selectedCustomer ? 'CLIENTE ASIGNADO' : 'ASIGNAR CLIENTE (REQUERIDO)'}
                        </div>
                        <div className="font-bold text-lg leading-tight">
                            {selectedCustomer ? selectedCustomer.name : 'SELECCIONAR...'}
                        </div>
                    </div>
                </div>
                {selectedCustomer ? (
                     <div onClick={(e) => { e.stopPropagation(); handleSetCustomer(null); }} className="p-2 bg-white/20 rounded-full hover:bg-white/30">
                        <Trash2 className="w-5 h-5" />
                     </div>
                ) : (
                    <ChevronRight className="w-6 h-6" />
                )}
             </button>
          )}

          {hasRentals && (
            <div className="grid grid-cols-2 gap-3">
                <div onClick={() => setShowStartDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA ENTREGA</span>
                    <div className="flex items-center gap-2">
                        <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!rentalDate && 'text-slate-400'}`}>{formatDateDisplay(rentalDate)}</span>
                    </div>
                    {!rentalDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
                <div onClick={() => setShowEndDatePicker(true)} className="bg-white border border-slate-200 p-3 rounded-2xl active:scale-95 transition-transform cursor-pointer relative overflow-hidden">
                    <span className="text-[10px] text-slate-500 uppercase font-bold block mb-1">FECHA DEVOLUCIÓN</span>
                    <div className="flex items-center gap-2">
                         <Calendar className="w-5 h-5 text-indigo-600" />
                        <span className={`font-medium ${!returnDate && 'text-slate-400'}`}>{formatDateDisplay(returnDate)}</span>
                    </div>
                    {!returnDate && <div className="absolute top-0 right-0 w-2 h-2 bg-rose-500 rounded-full m-2"></div>}
                </div>
            </div>
          )}

          {/* Totals */}
          <div className="pt-2">
            <div className="flex justify-between items-center mb-4">
                <span className="text-slate-500 uppercase">TOTAL A PAGAR</span>
                <span className="text-3xl font-bold text-slate-800">${totalWithExtraDays.toFixed(2)}</span>
            </div>

            <Button 
                onClick={openPaymentModal} 
                className={`w-full py-4 text-lg shadow-xl uppercase ${isCheckoutEnabled ? 'shadow-indigo-200' : 'bg-slate-300 text-slate-500 shadow-none cursor-not-allowed'}`}
                disabled={!isCheckoutEnabled}
            >
                {isCheckoutEnabled ? 'COBRAR TICKET' : (hasRentals ? 'COMPLETA DATOS DE RENTA' : 'CARRITO VACÍO')}
            </Button>
          </div>
        </div>
      </div>

      {/* PAYMENT MODAL */}
      <Modal 
        isOpen={showPaymentModal} 
        onClose={() => setShowPaymentModal(false)} 
        title="FINALIZAR COBRO"
      >
        <div className="space-y-6">

            {/* Payment Method Tabs */}
            <div className="flex bg-slate-100 p-1 rounded-2xl">
                <button onClick={() => setPaymentMethod('cash')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'cash' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    EFECTIVO
                </button>
                <button onClick={() => setPaymentMethod('card')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'card' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    TARJETA
                </button>
                <button onClick={() => setPaymentMethod('transfer')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'transfer' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                    TRANSFER
                </button>
            </div>

            {/* Total Display */}
            <div className="text-center p-6 bg-slate-50 rounded-3xl border border-slate-100">
                <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">TOTAL A COBRAR</div>
                <div className="text-5xl font-black text-slate-800 font-mono tracking-tight">
                    ${finalPayableTotal.toFixed(2)}
                </div>
                {paymentMethod === 'card' && cardFeeAmount > 0 && (
                    <div className="mt-2 inline-flex items-center gap-1 bg-amber-100 text-amber-800 px-3 py-1 rounded-full text-xs font-bold">
                        <AlertCircle className="w-3 h-3" />
                        INCLUYE ${cardFeeAmount.toFixed(2)} DE SERVICIO ({settings.cardFeePercentage}%)
                    </div>
                )}
            </div>

            {/* Cash Specific Controls */}
            {paymentMethod === 'cash' && (
                <div className="space-y-4 animate-in fade-in zoom-in-95 duration-200">
                    <Input 
                        label="DINERO RECIBIDO" 
                        placeholder="$0.00" 
                        type="number"
                        className="text-2xl font-bold text-center"
                        value={amountTendered}
                        onChange={(e) => setAmountTendered(e.target.value)}
                        autoFocus
                    />

                    {/* Smart Suggestion Buttons */}
                    <div className="grid grid-cols-4 gap-2">
                        {/* Always show Exact */}
                         <button 
                            onClick={() => setAmountTendered(finalPayableTotal.toString())}
                            className="bg-slate-100 hover:bg-indigo-50 hover:text-indigo-600 text-slate-600 font-bold py-3 rounded-xl text-sm border border-slate-200 transition-colors"
                        >
                            EXACTO
                        </button>
                        {suggestedBills.map(bill => (
                             <button 
                                key={bill}
                                onClick={() => setAmountTendered(bill.toString())}
                                className="bg-white hover:bg-emerald-50 hover:border-emerald-200 hover:text-emerald-700 text-slate-700 font-bold py-3 rounded-xl text-lg border border-slate-200 shadow-sm transition-all"
                            >
                                ${bill}
                            </button>
                        ))}
                    </div>

                    {/* Change Display */}
                    {tendered >= finalPayableTotal && (
                         <div className="p-4 bg-emerald-50 border border-emerald-100 rounded-2xl flex justify-between items-center">
                             <div className="text-emerald-800 font-bold uppercase text-sm">CAMBIO A ENTREGAR</div>
                             <div className="text-2xl font-black text-emerald-600 font-mono">${changeDue.toFixed(2)}</div>
                         </div>
                    )}
                </div>
            )}

            {/* Transfer/Card Info */}
            {(paymentMethod === 'card' || paymentMethod === 'transfer') && (
                <div className="p-8 text-center text-slate-400 animate-in fade-in zoom-in-95 duration-200">
                     {paymentMethod === 'card' ? <CreditCard className="w-16 h-16 mx-auto mb-4 opacity-50" /> : <ArrowUpRight className="w-16 h-16 mx-auto mb-4 opacity-50" />}
                     <p className="uppercase font-medium">
                         PROCESE EL PAGO EN TERMINAL O APP BANCARIA POR <strong className="text-slate-800">${finalPayableTotal.toFixed(2)}</strong>
                     </p>
                </div>
