                          >
                              <div className="flex-1">
                                  <div className="flex items-center gap-2">
                                    <div className="font-bold text-slate-800 text-lg">{c.name}</div>
                                    {/* SHOW DEBT WARNING */}
                                    {c.balance && c.balance < 0 && (
                                        <div className="bg-rose-100 text-rose-600 px-2 py-0.5 rounded text-[10px] font-bold border border-rose-200 flex items-center gap-1 animate-pulse">
                                            <AlertCircle className="w-3 h-3" />
