                                  <div className="flex flex-col sm:flex-row gap-1 sm:gap-4 mt-1">
                                    <div className="text-xs text-slate-500 flex items-center gap-1 font-medium">
                                        <Phone className="w-3 h-3 text-indigo-400" /> {c.phone}
