import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Link, useLocation } from 'react-router-dom';
import { LayoutGrid, ShoppingCart, History, Users, Settings as SettingsIcon, BarChart3, Receipt, RotateCcw, BoxSelect, Search, Clock, AlertTriangle, CheckCircle, X } from 'lucide-react';
import POS from './pages/POS';
import Inventory from './pages/Inventory';
import Customers from './pages/Customers';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import Tickets from './pages/Tickets';
import Returns from './pages/Returns';
import Login from './pages/Login';
import { User, Order, SystemSettings } from './types';
import { getOrders, updateOrder, updateCustomer, getSystemSettings } from './services/dataService';
import { Modal, Input, Button, Badge } from './components/UI';

// Icon Map for Nav
const NavItem = ({ to, icon: Icon, label }: { to: string, icon: any, label: string }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link to={to} className={`flex flex-col items-center justify-center gap-1 p-2 rounded-2xl transition-all duration-300 ${isActive ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-slate-600'}`}>
      <Icon className={`w-6 h-6 ${isActive ? 'fill-current' : ''}`} />
      <span className="text-[10px] font-medium uppercase">{label}</span>
    </Link>
  );
};

// Layout Component to handle Route-aware logic (FAB positioning)
const MainLayout: React.FC<{ 
  user: User, 
  setUser: (u: User | null) => void, 
  onOpenQuickReturn: () => void 
}> = ({ user, setUser, onOpenQuickReturn }) => {
  const location = useLocation();
  const isPos = location.pathname === '/';

  // Dynamic FAB Position
  // POS Desktop: Top-right of left panel (avoiding cart) -> top-6 right-[470px]
  // POS Mobile: Top-right (avoiding header buttons) -> top-24 right-4
  // Other Pages: Standard bottom-right -> bottom-24 lg:bottom-10 right-6 lg:right-10
  const fabPositionClass = isPos 
    ? "top-24 right-4 lg:top-6 lg:right-[390px]" 
    : "bottom-24 lg:bottom-10 right-6 lg:right-10";

  return (
    <div className="min-h-screen bg-[#f3f4f6] text-slate-900 font-sans pb-24 lg:pb-0 lg:pl-24 relative">
        {/* Desktop Sidebar / Mobile Bottom Bar */}
        <nav className="fixed bottom-0 left-0 w-full lg:w-24 lg:h-full bg-white border-t lg:border-t-0 lg:border-r border-slate-200 z-40 flex lg:flex-col items-center justify-around lg:justify-center gap-1 lg:gap-6 p-2 lg:p-6 shadow-2xl lg:shadow-none overflow-y-auto hide-scrollbar">
          <div className="hidden lg:flex items-center justify-center w-12 h-12 bg-indigo-600 rounded-xl mb-auto shadow-lg shadow-indigo-300 flex-shrink-0">
             <span className="text-white font-bold text-xl">CyC</span>
          </div>

          <div className="flex lg:flex-col justify-around w-full gap-1 lg:gap-4">
            <NavItem to="/" icon={ShoppingCart} label="Venta" />
            <NavItem to="/returns" icon={RotateCcw} label="Devoluciones" />
            <NavItem to="/tickets" icon={Receipt} label="Recibos" />
            <NavItem to="/inventory" icon={LayoutGrid} label="Stock" />
            <NavItem to="/customers" icon={Users} label="Clientes" />
            <NavItem to="/reports" icon={BarChart3} label="Informes" />
            <NavItem to="/settings" icon={SettingsIcon} label="Ajustes" />
          </div>

          <div 
            className="hidden lg:flex mt-auto w-10 h-10 rounded-full bg-slate-100 items-center justify-center font-bold text-indigo-600 cursor-pointer hover:bg-rose-100 hover:text-rose-600 transition-colors flex-shrink-0" 
            title={`Cerrar sesión de ${user.name}`} 
            onClick={() => setUser(null)}
          >
            {user.name.charAt(0)}
          </div>
        </nav>

        {/* Main Content Area */}
        <main className="h-screen overflow-hidden">
          <Routes>
            <Route path="/" element={<POS />} />
            <Route path="/returns" element={<Returns />} />
            <Route path="/tickets" element={<Tickets />} />
            <Route path="/inventory" element={<Inventory />} />
            <Route path="/customers" element={<Customers />} />
            <Route path="/reports" element={<Reports />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </main>

        {/* --- FLOATING ACTION BUTTON (QUICK RETURN) --- */}
        <button 
            onClick={onOpenQuickReturn}
            className={`fixed ${fabPositionClass} z-50 bg-slate-900 text-white p-4 rounded-full shadow-2xl shadow-slate-900/40 hover:scale-110 active:scale-95 transition-all duration-300 border-4 border-[#f3f4f6] group`}
            title="Devolución Rápida"
        >
            <RotateCcw className="w-6 h-6 group-hover:-rotate-90 transition-transform" />
            {!isPos && (
              <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 bg-slate-800 text-white text-xs font-bold px-3 py-1 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                  DEVOLUCIÓN RÁPIDA
              </span>
            )}
        </button>
    </div>
  );
};

const App: React.FC = () => {
  // Initialize state from localStorage if available
  const [user, setUser] = useState<User | null>(() => {
    try {
      const savedUser = localStorage.getItem('cyc_pos_user');
      return savedUser ? JSON.parse(savedUser) : null;
    } catch (error) {
      console.error("Error parsing user session", error);
      return null;
    }
  });

  // --- Quick Return Logic ---
  const [isQuickReturnOpen, setIsQuickReturnOpen] = useState(false);
  const [activeRentals, setActiveRentals] = useState<Order[]>([]);
  const [quickSearch, setQuickSearch] = useState('');
  const [loadingRentals, setLoadingRentals] = useState(false);
  const [selectedReturnOrder, setSelectedReturnOrder] = useState<Order | null>(null);
  const [lateFee, setLateFee] = useState('');
  const [step, setStep] = useState<'list' | 'confirm'>('list');

  // Sync state changes to localStorage
  useEffect(() => {
    if (user) {
      localStorage.setItem('cyc_pos_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('cyc_pos_user');
    }
  }, [user]);

  // Load active rentals when modal opens
  useEffect(() => {
    if (isQuickReturnOpen) {
        loadActiveRentals();
    }
  }, [isQuickReturnOpen]);

  const loadActiveRentals = async () => {
      setLoadingRentals(true);
      const allOrders = await getOrders();
      // Filter: Has rental items AND status is NOT returned
      const active = allOrders.filter(o => 
          o.items.some(i => i.transactionType === 'rent') && 
          !o.status.includes('returned')
      );
      setActiveRentals(active);
      setLoadingRentals(false);
  };

  const filteredRentals = useMemo(() => {
      const q = quickSearch.toUpperCase();
      return activeRentals.filter(o => 
          o.id?.includes(q) || 
          o.customer?.name.includes(q)
      );
  }, [activeRentals, quickSearch]);

  const handleCardClick = async (order: Order) => {
      setSelectedReturnOrder(order);
      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;

      if (isLate) {
          const settings = await getSystemSettings();
          setLateFee(settings.defaultLateFee.toString());
      } else {
          setLateFee('0');
      }
      setStep('confirm');
  };

  const processQuickReturn = async (chargeToBalance: boolean) => {
      if (!selectedReturnOrder || !selectedReturnOrder.id) return;

      const fee = parseFloat(lateFee) || 0;
      const isLate = fee > 0; // Simplified logic: if fee > 0, assume late handling or just extra charge

      try {
          const updateData: any = {
              status: isLate ? 'returned_late' : 'returned',
              returnedAt: Date.now(),
          };
          if (isLate) updateData.lateFee = fee;

          await updateOrder(selectedReturnOrder.id, updateData);

          // Handle Debt
          if (isLate && chargeToBalance && selectedReturnOrder.customer?.id) {
               const currentBalance = selectedReturnOrder.customer.balance || 0;
               await updateCustomer(selectedReturnOrder.customer.id, {
                   balance: currentBalance - fee
               });
               alert(`Devolución registrada. Deuda de $${fee} cargada al cliente.`);
          } else {
               alert("Devolución registrada correctamente.");
          }

          // Reset and Reload
          setStep('list');
          setSelectedReturnOrder(null);
          loadActiveRentals();
          setQuickSearch('');

      } catch (e) {
          console.error(e);
          alert("Error al procesar la devolución.");
      }
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  return (
    <HashRouter>
      <MainLayout user={user} setUser={setUser} onOpenQuickReturn={() => setIsQuickReturnOpen(true)} />

      {/* --- QUICK RETURN MODAL --- */}
      <Modal 
          isOpen={isQuickReturnOpen} 
          onClose={() => { setIsQuickReturnOpen(false); setStep('list'); setQuickSearch(''); }} 
          title="DEVOLUCIÓN RÁPIDA"
      >
          <div className="h-[60vh] flex flex-col">
              {step === 'list' ? (
                  <>
                      <div className="mb-4 relative flex-shrink-0">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                          <input 
                              type="number" 
                              placeholder="ESCANEAR O TECLEAR ID TICKET..." 
                              value={quickSearch}
                              onChange={(e) => setQuickSearch(e.target.value)}
                              className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 border-2 border-indigo-100 focus:border-indigo-500 text-2xl font-bold text-center tracking-widest outline-none transition-colors"
                              autoFocus
                          />
                      </div>

                      <div className="flex-1 overflow-y-auto p-1">
                          {loadingRentals ? (
                              <div className="text-center py-10 text-slate-400">CARGANDO RENTAS...</div>
                          ) : filteredRentals.length === 0 ? (
                              <div className="text-center py-10 text-slate-400">
                                  <div className="inline-block p-4 bg-slate-100 rounded-full mb-2"><BoxSelect className="w-8 h-8 opacity-50"/></div>
                                  <p>NO SE ENCONTRARON RENTAS ACTIVAS</p>
                              </div>
                          ) : (
                              <div className="grid grid-cols-2 gap-3">
                                  {filteredRentals.map(order => {
                                      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;
                                      return (
                                          <div 
                                              key={order.id} 
                                              onClick={() => handleCardClick(order)}
                                              className={`p-3 rounded-2xl border-2 cursor-pointer transition-all active:scale-95 relative overflow-hidden flex flex-col justify-between min-h-[140px] ${
                                                  isLate 
                                                  ? 'bg-rose-50 border-rose-200 hover:border-rose-400' 
                                                  : 'bg-white border-slate-200 hover:border-indigo-400'
                                              }`}
                                          >
                                              <div className="flex justify-between items-start">
                                                  <span className={`font-mono font-black text-lg ${isLate ? 'text-rose-700' : 'text-slate-600'}`}>
                                                      #{order.id}
                                                  </span>
                                                  {isLate && <AlertTriangle className="w-5 h-5 text-rose-500 animate-pulse" />}
                                              </div>

                                              <div className="my-2">
                                                  <div className="text-[10px] uppercase text-slate-400 font-bold tracking-wider">CLIENTE</div>
                                                  <div className="font-bold text-slate-800 leading-tight uppercase line-clamp-2">
                                                      {order.customer?.name}
                                                  </div>
                                              </div>

                                              <div className="flex items-end justify-between">
                                                  <div className="text-xs text-slate-500">
                                                      {order.items.filter(i => i.transactionType === 'rent').length} Artículo(s)
                                                  </div>
                                                  <div className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${isLate ? 'bg-rose-200 text-rose-800' : 'bg-indigo-100 text-indigo-700'}`}>
                                                      {isLate ? 'ATRASADO' : 'A TIEMPO'}
                                                  </div>
                                              </div>
                                          </div>
                                      );
                                  })}
                              </div>
                          )}
                      </div>
                  </>
              ) : (
                  <div className="flex flex-col h-full animate-in slide-in-from-right duration-300">
                      {/* CONFIRMATION SCREEN */}
                      <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-4">
                          <div className="flex justify-between items-center mb-2">
                              <h3 className="font-bold text-slate-700 uppercase">CONFIRMAR DEVOLUCIÓN</h3>
                              <div className="font-mono text-slate-400">#{selectedReturnOrder?.id}</div>
                          </div>
                          <div className="text-2xl font-bold text-slate-900 uppercase mb-1">{selectedReturnOrder?.customer?.name}</div>
                          <div className="text-xs text-slate-500 uppercase flex flex-col gap-1">
                              {selectedReturnOrder?.items.filter(i => i.transactionType === 'rent').map((item, idx) => (
                                  <span key={idx}>• {item.name}</span>
                              ))}
                          </div>
                      </div>

                      {parseFloat(lateFee) > 0 && (
                          <div className="mb-4">
                              <div className="bg-rose-100 text-rose-800 p-3 rounded-t-xl flex items-center gap-2 font-bold text-sm">
                                  <AlertTriangle className="w-4 h-4" /> SE DETECTÓ ATRASO
                              </div>
                              <div className="bg-white border-x border-b border-rose-100 p-4 rounded-b-xl">
                                  <Input 
                                      label="MONTO A COBRAR (MULTA)" 
                                      type="number" 
