export const importProductsBatch = async (products: Omit<Product, 'id'>[]) => {
  try {
    const batch = writeBatch(db);
    const collectionRef = collection(db, "products");
    const chunk = products.slice(0, 500);

    chunk.forEach(prod => {
      const docRef = doc(collectionRef);
      batch.set(docRef, prod);
    });

    await batch.commit();
    return chunk.length;
  } catch (e) {
    console.error("Error batch importing: ", e);
    throw e;
  }
}

// --- Orders ---

export const createOrder = async (order: Omit<Order, 'id'>) => {
  try {
    const cleanOrder = stripUndefined(order);

    // Generate Custom ID: YY + 4 Random Digits
    const date = new Date();
    const year = date.getFullYear().toString().slice(-2);
    let isUnique = false;
    let customId = '';

    // Retry loop to ensure ID uniqueness
    let attempts = 0;
    while (!isUnique && attempts < 10) {
        // Generate random 4 digits (0000 - 9999)
        const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
        customId = `${year}${randomPart}`;

        const docRef = doc(db, "orders", customId);
        const docSnap = await getDoc(docRef);
        if (!docSnap.exists()) {
            isUnique = true;
        }
        attempts++;
    }

    if (!isUnique) throw new Error("Could not generate unique Ticket ID");

    // Use setDoc with the specific customId
    await setDoc(doc(db, "orders", customId), {
      ...cleanOrder,
      createdAt: Timestamp.now().toMillis() 
    });

    return { ...order, id: customId };
  } catch (e) {
    console.error("Error creating order: ", e);
    throw e;
  }
};

