import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Search, ShoppingBag, User, Calendar, Trash2, Plus, Minus, Tag, CreditCard, ChevronRight, Delete, UserPlus, MapPin, Phone, ArrowLeft, Pencil, AlertCircle, Clock, CalendarClock, Wallet, ArrowUpRight, DollarSign, LayoutGrid, ListFilter, Percent, Box, Star, Printer, CheckCircle } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { Button, Input, Card, Badge, DatePickerModal, Modal, ReceiptTemplate } from '../components/UI';
import { Product, CartItem, Customer, Order, Variation, SystemSettings } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getSystemSettings } from '../services/dataService';

const POS: React.FC = () => {
  const location = useLocation();

  // View State
  const [viewMode, setViewMode] = useState<'dashboard' | 'catalog'>('dashboard');
  const [activeCategory, setActiveCategory] = useState<string>('TODOS');

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [settings, setSettings] = useState<SystemSettings>({ defaultLateFee: 50, pricePerExtraDay: 0, cardFeePercentage: 0 });
  const [searchQuery, setSearchQuery] = useState('');
  const [cart, setCart] = useState<CartItem[]>([]);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Modals
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [showStartDatePicker, setShowStartDatePicker] = useState(false);
  const [showEndDatePicker, setShowEndDatePicker] = useState(false);
  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [showSuccessModal, setShowSuccessModal] = useState(false);

  // Payment Logic State
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountTendered, setAmountTendered] = useState('');
  const [lastOrder, setLastOrder] = useState<Order | null>(null);
  const [lastChangeDue, setLastChangeDue] = useState(0);

  // Variation Modal State
  const [variationModalData, setVariationModalData] = useState<{product: Product, type: 'sale' | 'rent'} | null>(null);

  // Custom Price Modal State
  const [customPriceModal, setCustomPriceModal] = useState<{product: Product, type: 'sale' | 'rent', variation?: Variation} | null>(null);
  const [customPriceValue, setCustomPriceValue] = useState('');

  // Customer Modal Logic
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'create'>('search');
  const [customerSearchTerm, setCustomerSearchTerm] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null); 
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');

  // Rental Logic
  const hasRentals = useMemo(() => cart.some(item => item.transactionType === 'rent'), [cart]);
  const [rentalDate, setRentalDate] = useState('');
  const [returnDate, setReturnDate] = useState('');

  // --- Derived Data ---
  const categories = useMemo(() => {
      const cats = products.map(p => p.category).filter(Boolean);
      return ['TODOS', ...Array.from(new Set(cats)).sort()];
  }, [products]);

  const filteredCustomers = useMemo(() => {
      const term = customerSearchTerm.toLowerCase();
      return customers.filter(c => 
          c.name.toLowerCase().includes(term) || 
          c.phone.includes(term)
      );
  }, [customers, customerSearchTerm]);

  // Helper: Format Date
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return 'SELECCIONAR';
      const [year, month, day] = dateStr.split('-');
      const months = ['ENE', 'FEB', 'MAR', 'ABR', 'MAY', 'JUN', 'JUL', 'AGO', 'SEP', 'OCT', 'NOV', 'DIC'];
      return `${day}-${months[parseInt(month) - 1]}-${year.slice(2)}`;
  };

  const getNextBusinessDay = (date: Date): Date => {
      const next = new Date(date);
      next.setDate(next.getDate() + 1);
      if (next.getDay() === 0) {
          next.setDate(next.getDate() + 1);
      }
      return next;
  };

  const countExtraDays = (startStr: string, endStr: string): number => {
      if (!startStr || !endStr) return 0;
      const [sY, sM, sD] = startStr.split('-').map(Number);
      const start = new Date(sY, sM - 1, sD);
      const [eY, eM, eD] = endStr.split('-').map(Number);
      const end = new Date(eY, eM - 1, eD);
      const standardReturn = getNextBusinessDay(start);
      if (end <= standardReturn) return 0;
      let extraCount = 0;
      let current = new Date(standardReturn);
      current.setDate(current.getDate() + 1); 
      while (current <= end) {
          if (current.getDay() !== 0) extraCount++;
          current.setDate(current.getDate() + 1);
      }
      return extraCount;
  };

  const extraDaysCount = useMemo(() => countExtraDays(rentalDate, returnDate), [rentalDate, returnDate]);
  const extraDaysTotal = extraDaysCount * settings.pricePerExtraDay;

  // Checkout Status Logic
  const isCheckoutEnabled = useMemo(() => {
    if (cart.length === 0) return false;
    if (hasRentals) {
      return selectedCustomer !== null && rentalDate !== '' && returnDate !== '';
    }
    return true; 
  }, [cart, hasRentals, selectedCustomer, rentalDate, returnDate]);

  // Initial Load
  useEffect(() => {
    const fetchData = async () => {
      const [p, c, s] = await Promise.all([getProducts(), getCustomers(), getSystemSettings()]);
      setProducts(p);
      setCustomers(c);
      setSettings(s);

      if (location.state && location.state.action === 'pay_late_fee') {
         const { customer, amount, refTicket } = location.state;
         if (customer) handleSetCustomer(customer); // Use new handler

         const lateFeeItem: CartItem = {
             code: 'FEE',
             name: `RECARGO POR ATRASO (Ticket #${refTicket})`,
             description: 'Cargo por devolución tardía',
             salePrice: amount,
             rentalPrice: 0,
             category: 'SERVICIOS',
             stock: 999,
             variations: [],
             isRentalAvailable: false,
             isSaleAvailable: true,
             cartId: 'late-fee-' + Date.now(),
             transactionType: 'sale',
             quantity: 1,
             appliedPrice: amount
         };
         // We use callback to ensure we don't overwrite the Debt item if it was added by handleSetCustomer
         setCart(prev => [...prev, lateFeeItem]);
         window.history.replaceState({}, document.title);
      }
    };
    fetchData();
  }, [location]);

  // Filter Products Logic
  const filteredProducts = useMemo(() => {
      return products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.code.includes(searchQuery);
        const matchesCategory = activeCategory === 'TODOS' || p.category === activeCategory;
        return matchesSearch && matchesCategory;
      });
  }, [products, searchQuery, activeCategory]);

  // --- Handlers ---

  const handleRentalStartDateSelect = (dateStr: string) => {
      setRentalDate(dateStr);
      const [year, month, day] = dateStr.split('-');
      const startDate = new Date(parseInt(year), parseInt(month) - 1, parseInt(day));
      const nextBusinessDay = getNextBusinessDay(startDate);
      const nextYear = nextBusinessDay.getFullYear();
      const nextMonth = (nextBusinessDay.getMonth() + 1).toString().padStart(2, '0');
      const nextDay = nextBusinessDay.getDate().toString().padStart(2, '0');
      setReturnDate(`${nextYear}-${nextMonth}-${nextDay}`);
  };

  // --- CUSTOMER HANDLING WITH DEBT LOGIC ---
  const handleSetCustomer = (customer: Customer | null) => {
    // 1. Remove any existing 'DEUDA' item first (from previous customer)
    setCart(prevCart => prevCart.filter(item => item.code !== 'DEUDA'));

    if (customer && customer.balance && customer.balance < 0) {
        // 2. Add debt item if customer has debt
        const debtAmount = Math.abs(customer.balance);
        const debtItem: CartItem = {
            code: 'DEUDA',
            name: 'LIQUIDACIÓN DE ADEUDO',
            description: 'Saldo pendiente anterior',
            salePrice: debtAmount,
            rentalPrice: 0,
            category: 'FINANCIERO',
            stock: 1,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'debt-' + customer.id,
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: debtAmount
        };
        setCart(prevCart => [...prevCart, debtItem]);
    }

    setSelectedCustomer(customer);
  };

  const openCustomerModal = () => {
      setCustomerViewMode('search');
      setCustomerSearchTerm('');
      setEditingCustomerId(null);
      setShowCustomerModal(true);
  };

  const handleCustomerSearchKeyDown = (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
          const filtered = customers.filter(c => c.name.toLowerCase().includes(customerSearchTerm.toLowerCase()));
          const exactMatch = filtered.find(c => c.name.toLowerCase() === customerSearchTerm.toLowerCase());
          if (exactMatch) {
              handleSetCustomer(exactMatch);
              setShowCustomerModal(false);
          } else if (filtered.length > 0 && customerSearchTerm === '') {
             // Do nothing
          } else {
              switchToCreateCustomer();
          }
      }
  };

  const switchToCreateCustomer = () => {
      setNewCustomerName(customerSearchTerm.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
      setCustomerViewMode('create');
  };

  const handleEditCustomerFromSearch = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingCustomerId(customer.id || null);
      setNewCustomerName(customer.name);
      setNewCustomerPhone(customer.phone);
      setNewCustomerAddress(customer.address || '');
      setCustomerViewMode('create');
  };

  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if(!newCustomerName) return;

    const customerData = {
        name: newCustomerName,
        phone: newCustomerPhone,
        address: newCustomerAddress
    };

    let resultCustomer: Customer;

    if (editingCustomerId) {
        await updateCustomer(editingCustomerId, customerData);
        resultCustomer = { ...customerData, id: editingCustomerId };
        setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
    } else {
        const saved = await addCustomer(customerData);
        resultCustomer = saved;
        setCustomers([...customers, saved]);
    }

    handleSetCustomer(resultCustomer);
    setShowCustomerModal(false);

    setNewCustomerName('');
    setNewCustomerPhone('');
    setNewCustomerAddress('');
    setEditingCustomerId(null);
    setCustomerViewMode('search');
  }

  // Cart Actions
  const addToCart = (product: Product, type: 'sale' | 'rent', variation?: Variation, overriddenPrice?: number) => {
    let price = overriddenPrice !== undefined ? overriddenPrice : (type === 'rent' ? product.rentalPrice : product.salePrice);

    if (overriddenPrice === undefined && variation) {
      if (type === 'rent' && variation.rentalPrice) price = variation.rentalPrice;
      if (type === 'sale' && variation.salePrice) price = variation.salePrice;
    }

    if (price === 0) {
        setCustomPriceModal({ product, type, variation });
        setCustomPriceValue(''); 
        return;
    }

    const existing = cart.find(item => 
      item.id === product.id && 
      item.transactionType === type && 
      (item.selectedVariation?.name === variation?.name) &&
      item.appliedPrice === price
    );

    if (existing) {
      setCart(cart.map(item => 
        (item.cartId === existing.cartId)
          ? { ...item, quantity: item.quantity + 1 } 
          : item
      ));
    } else {
      setCart([...cart, { 
        ...product, 
        cartId: Math.random().toString(36),
        transactionType: type, 
        quantity: 1,
        ...(variation && { selectedVariation: variation }),
        appliedPrice: price
      }]);
    }
  };

  const handleProductClick = (product: Product, type: 'sale' | 'rent') => {
    if (product.variations && product.variations.length > 0) {
      setVariationModalData({ product, type });
    } else {
      addToCart(product, type);
    }
  };

  const handleVariationSelect = (variation: Variation) => {
    if (variationModalData) {
      addToCart(variationModalData.product, variationModalData.type, variation);
      setVariationModalData(null);
    }
  };

  const handleCustomPriceSubmit = () => {
      if (customPriceModal && customPriceValue) {
          const price = parseFloat(customPriceValue);
          if (!isNaN(price)) {
              addToCart(customPriceModal.product, customPriceModal.type, customPriceModal.variation, price);
              setCustomPriceModal(null);
          }
      }
  };

  const handleNumpadPress = (num: string) => {
      if (customPriceValue.includes('.') && num === '.') return;
      if (customPriceValue.length > 7) return; 
      setCustomPriceValue(prev => prev + num);
  };
  const handleNumpadBackspace = () => setCustomPriceValue(prev => prev.slice(0, -1));

  const removeFromCart = (cartId: string) => {
    setCart(cart.filter(item => item.cartId !== cartId));
  };

  const updateQuantity = (cartId: string, delta: number) => {
    setCart(cart.map(item => {
      if (item.cartId === cartId) {
        return { ...item, quantity: Math.max(1, item.quantity + delta) };
      }
      return item;
    }));
  };

  // Manual Item / Discount Addition
  const handleAddManualItem = () => {
      const dummyProduct: Product = {
          code: 'MANUAL',
          name: 'CONCEPTO MANUAL / DESCUENTO',
          description: 'Ajuste manual',
          salePrice: 0,
          rentalPrice: 0,
          category: 'SERVICIOS',
          stock: 999,
          variations: [],
          isRentalAvailable: false,
          isSaleAvailable: true,
      };
      // Use sale type for manual adjustments
      setCustomPriceModal({ product: dummyProduct, type: 'sale' });
      setCustomPriceValue('');
  };

  const handleQuickCategoryClick = (category: string) => {
      if (category === 'TODOS') {
          setActiveCategory('TODOS');
      } else {
          setActiveCategory(category);
      }
      setViewMode('catalog');
  };

  // --- Payment Calculations ---
  const cartTotal = cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
  const totalWithExtraDays = cartTotal + extraDaysTotal;
  const cardFeeAmount = settings.cardFeePercentage ? (totalWithExtraDays * (settings.cardFeePercentage / 100)) : 0;
  const finalPayableTotal = paymentMethod === 'card' ? totalWithExtraDays + cardFeeAmount : totalWithExtraDays;
  const tendered = parseFloat(amountTendered) || 0;
  const changeDue = paymentMethod === 'cash' ? Math.max(0, tendered - finalPayableTotal) : 0;

  const suggestedBills = useMemo(() => {
      if (paymentMethod !== 'cash') return [];
      const total = finalPayableTotal;
      const commonBills = [20, 50, 100, 200, 500, 1000];
      const suggestions = commonBills.filter(bill => bill >= total);
      return suggestions.slice(0, 3);
  }, [finalPayableTotal, paymentMethod]);

  const openPaymentModal = () => {
      if (!isCheckoutEnabled) return;
      setPaymentMethod('cash');
      setAmountTendered('');
      setShowPaymentModal(true);
  };

  const handlePrintReceipt = () => {
    window.print();
  };

  const confirmCheckout = async () => {
    if (paymentMethod === 'cash' && tendered < finalPayableTotal) {
        alert("El monto recibido es menor al total.");
        return;
    }

    const finalItems = [...cart];

    // Check if we are paying off a debt
    const debtItem = cart.find(i => i.code === 'DEUDA');

    if (extraDaysTotal > 0) {
        finalItems.push({
            code: 'EXT-DAY',
            name: `DÍAS EXTRA DE RENTA (${extraDaysCount})`,
            description: 'Cargo por extensión de periodo',
            salePrice: settings.pricePerExtraDay,
            rentalPrice: settings.pricePerExtraDay,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'extra-day-' + Date.now(),
            transactionType: 'sale',
            quantity: extraDaysCount,
            appliedPrice: settings.pricePerExtraDay
        });
    }

    if (paymentMethod === 'card' && cardFeeAmount > 0) {
         finalItems.push({
            code: 'CARD-FEE',
            name: `CARGO POR SERVICIO (${settings.cardFeePercentage}%)`,
            description: 'Cargo por servicio',
            salePrice: cardFeeAmount,
            rentalPrice: 0,
            category: 'SERVICIOS',
            stock: 999,
            variations: [],
            isRentalAvailable: false,
            isSaleAvailable: true,
            cartId: 'card-fee-' + Date.now(),
            transactionType: 'sale',
            quantity: 1,
            appliedPrice: cardFeeAmount
        });
    }

    const order: Omit<Order, 'id'> = {
      items: finalItems,
      total: finalPayableTotal,
      status: 'pending',
      createdAt: Date.now(),
      paymentMethod: paymentMethod,
      ...(selectedCustomer && { customer: selectedCustomer }),
      ...(rentalDate && { rentalStartDate: new Date(rentalDate).getTime() }),
      ...(returnDate && { rentalEndDate: new Date(returnDate).getTime() }),
    };

    try {
      const createdOrder = await createOrder(order);

      // If there was a debt item and the customer was selected, update their balance to 0 (Assuming full payment)
      if (debtItem && selectedCustomer && selectedCustomer.id) {
          // Update the balance in Firestore
          await updateCustomer(selectedCustomer.id, { balance: 0 });
          // Update local customer list state
          setCustomers(prev => prev.map(c => c.id === selectedCustomer.id ? { ...c, balance: 0 } : c));
      }

      // Set State for Receipt and Show Success Modal
      setLastOrder(createdOrder as Order);
      setLastChangeDue(changeDue);

      setCart([]);
      setSelectedCustomer(null);
      setRentalDate('');
      setReturnDate('');
      setShowPaymentModal(false);

      // Open Success Modal instead of Alert
      setShowSuccessModal(true);

    } catch (e) {
      console.error(e);
      alert("Error al registrar venta. Ver consola para más detalles.");
    }
  };

  const closeSuccessModal = () => {
    setShowSuccessModal(false);
    setViewMode('dashboard');
    setLastOrder(null);
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen overflow-hidden bg-[#f3f4f6]">
      {/* Hidden Receipt for Printing */}
      <ReceiptTemplate order={lastOrder} />

      {/* LEFT: Dashboard or Catalog */}
      <div className="flex-1 flex flex-col h-full overflow-hidden relative">

        {/* Top Navigation Bar */}
        <div className="p-4 md:p-6 pb-0 flex items-center gap-3">
            <div className="bg-white p-1 rounded-2xl border border-slate-200 shadow-sm flex items-center">
                <button 
                    onClick={() => setViewMode('dashboard')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'dashboard' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <LayoutGrid className="w-5 h-5" /> INICIO
                </button>
                <button 
                    onClick={() => setViewMode('catalog')}
                    className={`flex items-center gap-2 px-6 py-3 rounded-xl transition-all font-bold uppercase text-sm ${viewMode === 'catalog' ? 'bg-indigo-600 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                >
                    <ListFilter className="w-5 h-5" /> CATÁLOGO
                </button>
            </div>
            {viewMode === 'catalog' && (
                <div className="flex-1 relative animate-in fade-in slide-in-from-right-4">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR..." 
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    />
                </div>
            )}
        </div>

        <div className="flex-1 overflow-y-auto p-4 md:p-6 pb-32 lg:pb-6">

            {/* VIEW: DASHBOARD (Quick Access) */}
            {viewMode === 'dashboard' && (
                <div className="animate-in fade-in zoom-in-95 duration-300">
                    <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4 ml-1">ACCESOS RÁPIDOS</h3>
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {/* Special Actions */}
                        <div onClick={handleAddManualItem} className="bg-gradient-to-br from-amber-400 to-orange-500 rounded-3xl p-6 shadow-lg shadow-orange-500/20 text-white cursor-pointer active:scale-95 transition-transform flex flex-col justify-between h-40 group">
                            <Percent className="w-10 h-10 bg-white/20 p-2 rounded-full" />
                            <span className="font-bold text-lg uppercase leading-none">AGREGAR<br/>DESCUENTO / OTRO</span>
                        </div>

                        <div onClick={() => handleQuickCategoryClick('TODOS')} className="bg-white border border-slate-200 rounded-3xl p-6 shadow-sm hover:border-indigo-300 hover:shadow-md cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40">
                            <Box className="w-10 h-10 text-indigo-600 bg-indigo-50 p-2 rounded-full" />
                            <span className="font-bold text-lg text-slate-800 uppercase leading-none">VER TODO<br/>EL CATÁLOGO</span>
                        </div>

                        {/* Categories as Quick Tiles */}
                        {categories.filter(c => c !== 'TODOS').map((cat, idx) => (
                            <div 
                                key={cat} 
                                onClick={() => handleQuickCategoryClick(cat)}
                                className={`rounded-3xl p-6 shadow-sm cursor-pointer active:scale-95 transition-all flex flex-col justify-between h-40 border hover:shadow-md relative overflow-hidden group
                                    ${idx % 3 === 0 ? 'bg-emerald-50 border-emerald-100 hover:border-emerald-300 text-emerald-800' : ''}
                                    ${idx % 3 === 1 ? 'bg-purple-50 border-purple-100 hover:border-purple-300 text-purple-800' : ''}
                                    ${idx % 3 === 2 ? 'bg-blue-50 border-blue-100 hover:border-blue-300 text-blue-800' : ''}
                                `}
                            >
                                <div className="absolute -right-4 -bottom-4 opacity-10 transform rotate-12 scale-150">
                                    <Tag className="w-24 h-24" />
                                </div>
                                <Tag className="w-10 h-10 bg-white/50 p-2 rounded-full" />
                                <span className="font-bold text-lg uppercase leading-tight relative z-10">{cat}</span>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* VIEW: CATALOG */}
            {viewMode === 'catalog' && (
                <div className="flex flex-col h-full">
                    {/* Category Pills */}
                    <div className="flex gap-2 overflow-x-auto pb-4 hide-scrollbar flex-shrink-0">
                        {categories.map(cat => (
                            <button
                                key={cat}
                                onClick={() => setActiveCategory(cat)}
                                className={`px-5 py-2 rounded-full text-sm font-bold uppercase whitespace-nowrap transition-all flex-shrink-0 ${
                                    activeCategory === cat 
                                    ? 'bg-indigo-600 text-white shadow-md shadow-indigo-200' 
                                    : 'bg-white border border-slate-200 text-slate-500 hover:bg-slate-50'
                                }`}
                            >
                                {cat}
                            </button>
                        ))}
                    </div>

                    {/* Product Grid */}
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 pb-20">
                        {filteredProducts.map(product => (
                            <div key={product.id} className="bg-white rounded-3xl border border-slate-100 shadow-sm flex flex-col justify-between group active:scale-95 transition-transform overflow-hidden p-0">
                                {/* Image Area */}
                                <div className="w-full h-32 bg-slate-100 relative">
                                    {product.imageUrl ? (
                                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                                            <Box className="w-10 h-10" />
                                        </div>
                                    )}
                                    <div className="absolute top-2 right-2">
                                        <Badge color={product.category === 'Disfraces' ? 'indigo' : 'amber'}>{product.category}</Badge>
                                    </div>
                                    <div className="absolute bottom-2 left-2 bg-white/80 backdrop-blur-sm px-2 py-0.5 rounded text-[10px] font-mono font-bold text-slate-600">
                                        {product.code}
                                    </div>
                                </div>

                                <div className="p-4 pt-3 flex flex-col flex-1">
                                    <h3 className="font-bold text-slate-800 leading-tight mb-1 line-clamp-2">{product.name}</h3>
                                    <p className="text-xs text-slate-500 line-clamp-2 mb-3 flex-1">{product.description}</p>

                                    {product.variations && product.variations.length > 0 && (
                                        <div className="flex gap-1 mb-3 flex-wrap">
                                            <span className="text-[10px] bg-slate-50 px-2 py-0.5 rounded text-slate-500 border border-slate-100 font-medium">
                                                {product.variations.length} VAR
                                            </span>
                                        </div>
                                    )}

                                    <div className="space-y-2 mt-auto">
                                        {product.isRentalAvailable && (
                                        <button 
                                            onClick={() => handleProductClick(product, 'rent')}
                                            className="w-full flex items-center justify-between bg-indigo-50 text-indigo-700 px-3 py-2 rounded-xl text-xs font-bold hover:bg-indigo-100 active:scale-95 transition-transform uppercase"
                                        >
                                            <span>RENTAR</span>
                                            <span>{product.rentalPrice > 0 ? `$${product.rentalPrice}` : '$?'}</span>
                                        </button>
                                        )}
                                        {product.isSaleAvailable && (
                                        <button 
                                            onClick={() => handleProductClick(product, 'sale')}
                                            className="w-full flex items-center justify-between bg-emerald-50 text-emerald-700 px-3 py-2 rounded-xl text-xs font-bold hover:bg-emerald-100 active:scale-95 transition-transform uppercase"
                                        >
                                            <span>VENDER</span>
                                            <span>{product.salePrice > 0 ? `$${product.salePrice}` : '$?'}</span>
                                        </button>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))}
                        {filteredProducts.length === 0 && (
                            <div className="col-span-full py-20 text-center text-slate-400">
                                <Search className="w-12 h-12 mx-auto mb-2 opacity-20" />
                                <p>NO SE ENCONTRARON RESULTADOS EN "{activeCategory}"</p>
                            </div>
                        )}
                    </div>
                </div>
            )}
        </div>
      </div>

      {/* RIGHT: Cart & Checkout */}
      <div className="w-full lg:w-[360px] bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col h-[40vh] lg:h-full rounded-t-3xl lg:rounded-none">
        {/* Cart Header */}
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-white/80 backdrop-blur-md lg:rounded-none rounded-t-3xl">
          <h2 className="text-xl font-bold flex items-center gap-2 uppercase">
            <ShoppingBag className="w-6 h-6 text-indigo-600" />
            TICKET ACTUAL
          </h2>
          <button onClick={() => setCart([])} className="text-rose-500 text-sm font-medium hover:bg-rose-50 px-3 py-1 rounded-lg transition-colors uppercase">
            LIMPIAR
          </button>
        </div>

        {/* Cart Items */}
        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 && extraDaysCount === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 opacity-50">
                <ShoppingBag className="w-16 h-16 mb-4" />
                <p className="uppercase">EL CARRITO ESTÁ VACÍO</p>
            </div>
          ) : (
             <>
                {cart.map((item) => (
                <div key={item.cartId} className={`flex gap-4 p-3 rounded-2xl group ${item.code === 'DEUDA' ? 'bg-rose-50 border border-rose-100' : 'bg-slate-50'}`}>
                    <div className="flex-1">
                    <div className="flex justify-between">
                        <div>
                        <h4 className={`font-semibold leading-tight ${item.code === 'DEUDA' ? 'text-rose-800' : 'text-slate-800'}`}>{item.name}</h4>
                        {item.selectedVariation && (
                            <div className="text-xs text-indigo-600 font-bold bg-indigo-50 inline-block px-1 rounded mt-0.5">
                                {item.selectedVariation.name}
                            </div>
                        )}
                        </div>
                        <span className={`font-mono font-bold ${item.code === 'DEUDA' ? 'text-rose-700' : 'text-slate-700'}`}>
                            ${(item.appliedPrice * item.quantity).toFixed(2)}
                        </span>
                    </div>
                    <div className="flex items-center gap-2 mt-1">
                        <Badge color={item.code === 'DEUDA' ? 'rose' : (item.transactionType === 'rent' ? 'indigo' : 'green')}>
                            {item.code === 'DEUDA' ? 'ADEUDO' : (item.transactionType === 'rent' ? 'RENTA' : 'VENTA')}
                        </Badge>
                        <span className="text-xs text-slate-400">COD: {item.code}</span>
                        {item.appliedPrice === 0 || (item.transactionType === 'rent' && item.rentalPrice === 0) || (item.transactionType === 'sale' && item.salePrice === 0) ? (
                            <span className="text-[10px] text-amber-500 font-bold bg-amber-50 px-1 rounded uppercase">PRECIO MANUAL</span>
                        ) : null}
                    </div>
                    </div>

                    <div className="flex flex-col items-center gap-2">
                        {item.code !== 'DEUDA' && (
                            <div className="flex items-center bg-white rounded-lg shadow-sm border border-slate-200">
                                <button onClick={() => updateQuantity(item.cartId, -1)} className="p-2 hover:bg-slate-100 rounded-l-lg text-slate-500 active:bg-slate-200"><Minus className="w-4 h-4"/></button>
                                <span className="w-8 text-center text-sm font-medium">{item.quantity}</span>
                                <button onClick={() => updateQuantity(item.cartId, 1)} className="p-2 hover:bg-slate-100 rounded-r-lg text-slate-500 active:bg-slate-200"><Plus className="w-4 h-4"/></button>
                            </div>
                        )}
                        <button onClick={() => removeFromCart(item.cartId)} className="text-rose-400 hover:text-rose-600 p-2">
                            <Trash2 className="w-5 h-5" />
                        </button>
                    </div>
                </div>
                ))}

                {/* Phantom Item for Extra Days */}
                {extraDaysCount > 0 && (
                    <div className="flex gap-4 p-3 bg-indigo-50 rounded-2xl border border-indigo-100">
                         <div className="flex-1">
                            <div className="flex justify-between">
                                <div>
                                    <h4 className="font-semibold text-indigo-800 leading-tight">CARGO: DÍAS EXTRA</h4>
                                    <div className="text-xs text-indigo-600 font-bold mt-0.5">
                                        {extraDaysCount} Día(s) x ${settings.pricePerExtraDay}
                                    </div>
                                </div>
                                <span className="font-mono font-bold text-indigo-800">
                                    ${extraDaysTotal.toFixed(2)}
                                </span>
                            </div>
                            <div className="flex items-center gap-2 mt-1">
                                <span className="text-[10px] bg-indigo-200 text-indigo-800 font-bold px-1.5 py-0.5 rounded uppercase">SERVICIO</span>
                                <div className="text-xs text-indigo-400 flex items-center gap-1">
                                    <CalendarClock className="w-3 h-3" /> Automático
                                </div>
                            </div>
                         </div>
