      return {
          defaultLateFee: data.defaultLateFee || 50,
          pricePerExtraDay: data.pricePerExtraDay || 0,
          cardFeePercentage: data.cardFeePercentage || 0,
          businessName: data.businessName || 'CyC POS 26',
          receiptTemplate: data.receiptTemplate || 'v1'
