import { collection, addDoc, getDocs, query, orderBy, where, Timestamp, deleteDoc, doc, writeBatch, updateDoc, setDoc, getDoc } from 'firebase/firestore';
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";
import { Product, Order, Customer, User, SystemSettings } from '../types';

// Helper to generate a random code between 4 and 6 digits
export const generateProductCode = (): string => {
  const min = 1000;
  const max = 999999;
  const num = Math.floor(Math.random() * (max - min + 1)) + min;
  return num.toString();
};

// Helper to recursively strip undefined values from objects
const stripUndefined = (obj: any): any => {
  if (Array.isArray(obj)) {
    return obj.map(stripUndefined);
  } else if (obj !== null && typeof obj === 'object') {
    return Object.entries(obj).reduce((acc, [key, value]) => {
      if (value !== undefined) {
        acc[key] = stripUndefined(value);
      }
      return acc;
    }, {} as any);
  }
  return obj;
};

// --- Storage / Images (Compressed) ---

const compressImage = (file: File): Promise<Blob> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        // Max dimensions for optimization
        const MAX_WIDTH = 1024;
        const MAX_HEIGHT = 1024;
        let width = img.width;
        let height = img.height;

        // Calculate new dimensions keeping aspect ratio
        if (width > height) {
          if (width > MAX_WIDTH) {
            height *= MAX_WIDTH / width;
            width = MAX_WIDTH;
          }
        } else {
          if (height > MAX_HEIGHT) {
            width *= MAX_HEIGHT / height;
            height = MAX_HEIGHT;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(img, 0, 0, width, height);

        // Export as JPEG with 70% quality
        canvas.toBlob((blob) => {
          if (blob) resolve(blob);
          else reject(new Error('Image compression failed'));
        }, 'image/jpeg', 0.7);
      };
      img.onerror = (err) => reject(err);
    };
    reader.onerror = (err) => reject(err);
  });
};

export const uploadProductImage = async (file: File): Promise<string> => {
  try {
    // 1. Compress the image before uploading
    const compressedBlob = await compressImage(file);

    // 2. Create a unique path. We force .jpg extension since we converted it.
    const storageRef = ref(storage, `products/${Date.now()}_opt.jpg`);

    // 3. Upload the compressed blob
    const snapshot = await uploadBytes(storageRef, compressedBlob);

    // 4. Get URL
    const downloadURL = await getDownloadURL(snapshot.ref);
    return downloadURL;
  } catch (e) {
    console.error("Error uploading image: ", e);
    throw e;
  }
};

// --- Products ---

export const addProduct = async (product: Omit<Product, 'id'>) => {
  try {
    const docRef = await addDoc(collection(db, "products"), product);
    return { ...product, id: docRef.id };
  } catch (e) {
    console.error("Error adding product: ", e);
    throw e;
  }
};

export const updateProduct = async (id: string, product: Partial<Product>) => {
  try {
    const docRef = doc(db, "products", id);
    await updateDoc(docRef, product);
  } catch (e) {
    console.error("Error updating product: ", e);
    throw e;
  }
};

export const getProducts = async (): Promise<Product[]> => {
  try {
    const q = query(collection(db, "products"), orderBy("name"));
    const querySnapshot = await getDocs(q);
    return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Product));
  } catch (e) {
    console.error("Error fetching products: ", e);
    return [];
  }
};

export const deleteProduct = async (id: string) => {
    try {
        await deleteDoc(doc(db, "products", id));
    } catch (e) {
        console.error("Error deleting product", e);
        throw e;
    }
}

export const importProductsBatch = async (products: Omit<Product, 'id'>[]) => {
  try {
    const batch = writeBatch(db);
    const collectionRef = collection(db, "products");
    const chunk = products.slice(0, 500);

    chunk.forEach(prod => {
      const docRef = doc(collectionRef);
      batch.set(docRef, prod);
    });

    await batch.commit();
    return chunk.length;
  } catch (e) {
    console.error("Error batch importing: ", e);
    throw e;
  }
}

// --- Orders ---

export const createOrder = async (order: Omit<Order, 'id'>) => {
  try {
    const cleanOrder = stripUndefined(order);

    // Generate Custom ID: YY + 4 Random Digits
    const date = new Date();
    const year = date.getFullYear().toString().slice(-2);
    let isUnique = false;
    let customId = '';

    // Retry loop to ensure ID uniqueness
    let attempts = 0;
    while (!isUnique && attempts < 10) {
        // Generate random 4 digits (0000 - 9999)
        const randomPart = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
        customId = `${year}${randomPart}`;

        const docRef = doc(db, "orders", customId);
        const docSnap = await getDoc(docRef);
        if (!docSnap.exists()) {
            isUnique = true;
        }
        attempts++;
    }

    if (!isUnique) throw new Error("Could not generate unique Ticket ID");

    // Use setDoc with the specific customId
    await setDoc(doc(db, "orders", customId), {
      ...cleanOrder,
      createdAt: Timestamp.now().toMillis() 
    });

    return { ...order, id: customId };
  } catch (e) {
    console.error("Error creating order: ", e);
    throw e;
  }
