export const getSystemSettings = async (): Promise<SystemSettings> => {
  try {
    const docRef = doc(db, "settings", "global");
    const docSnap = await getDoc(docRef);
    if (docSnap.exists()) {
      const data = docSnap.data();
      return {
          defaultLateFee: data.defaultLateFee || 50,
          pricePerExtraDay: data.pricePerExtraDay || 0,
          cardFeePercentage: data.cardFeePercentage || 0,
          businessName: data.businessName || 'CyC POS 26',
          businessTagline: data.businessTagline || 'DISFRACES & ACCESORIOS',
          receiptTemplate: data.receiptTemplate || 'v1'
      } as SystemSettings;
    } else {
      // Return default
      return { 
          defaultLateFee: 50, 
          pricePerExtraDay: 50, 
          cardFeePercentage: 0,
          businessName: 'CyC POS 26',
          businessTagline: 'DISFRACES & ACCESORIOS',
          receiptTemplate: 'v1'
      };
    }
  } catch (e) {
    console.error("Error getting settings", e);
    return { defaultLateFee: 50, pricePerExtraDay: 50, cardFeePercentage: 0, businessName: 'CyC POS 26', businessTagline: 'DISFRACES & ACCESORIOS', receiptTemplate: 'v1' };
  }
}

export const updateSystemSettings = async (settings: SystemSettings) => {
  try {
    await setDoc(doc(db, "settings", "global"), settings);
  } catch (e) {
    console.error("Error saving settings", e);
    throw e;
  }
}

import React, { useState, useEffect } from 'react';
import { Settings as SettingsIcon, Shield, Trash2, UserPlus, Key, DollarSign, Save, CalendarClock, CreditCard, Printer, Store } from 'lucide-react';
import { Button, Input, Card, Select } from '../components/UI';
import { User } from '../types';
import { getUsers, addUser, deleteUser, getSystemSettings, updateSystemSettings } from '../services/dataService';

const Settings: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);

  // Settings
  const [lateFee, setLateFee] = useState<string>('50');
  const [extraDayPrice, setExtraDayPrice] = useState<string>('50');
  const [cardFee, setCardFee] = useState<string>('0');
  const [businessName, setBusinessName] = useState<string>('');
  const [businessTagline, setBusinessTagline] = useState<string>('');
  const [receiptTemplate, setReceiptTemplate] = useState<'v1'|'v2'>('v1');

  // New User Form
  const [newName, setNewName] = useState('');
  const [newCode, setNewCode] = useState('');

  const loadData = async () => {
    setLoading(true);
    const [u, s] = await Promise.all([getUsers(), getSystemSettings()]);
    setUsers(u);
    setLateFee(s.defaultLateFee.toString());
    setExtraDayPrice(s.pricePerExtraDay?.toString() || '0');
    setCardFee(s.cardFeePercentage?.toString() || '0');
    setBusinessName(s.businessName || 'CyC POS 26');
    setBusinessTagline(s.businessTagline || 'DISFRACES & ACCESORIOS');
    setReceiptTemplate(s.receiptTemplate || 'v1');
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSaveSettings = async () => {
      const fee = parseFloat(lateFee);
      const dayPrice = parseFloat(extraDayPrice);
      const card = parseFloat(cardFee);

      if (isNaN(fee) || isNaN(dayPrice) || isNaN(card)) { alert("Montos inválidos"); return; }
      if (!businessName.trim()) { alert("El nombre del negocio es requerido"); return; }

      try {
          await updateSystemSettings({ 
              defaultLateFee: fee,
              pricePerExtraDay: dayPrice,
              cardFeePercentage: card,
              businessName: businessName.toUpperCase(),
              businessTagline: businessTagline.toUpperCase(),
              receiptTemplate: receiptTemplate
          });
          alert("Ajustes guardados.");
      } catch (e) {
          alert("Error al guardar ajustes.");
      }
  };

  const handleAddUser = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName || newCode.length !== 4) {
      alert("NOMBRE REQUERIDO Y EL CÓDIGO DEBE SER DE 4 DÍGITOS.");
      return;
    }

    try {
      await addUser({ name: newName, code: newCode });
      setNewName('');
      setNewCode('');
      loadData();
      alert("USUARIO REGISTRADO.");
    } catch (e) {
      alert("ERROR AL GUARDAR.");
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("¿ELIMINAR ACCESO DE USUARIO?")) {
      await deleteUser(id);
      loadData();
    }
  };

  return (
    <div className="p-4 md:p-8 max-w-4xl mx-auto pb-24 h-full overflow-y-auto">
       <header className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
          <SettingsIcon className="w-8 h-8 text-indigo-600" />
          AJUSTES
        </h1>
        <p className="text-slate-500 mt-2 uppercase">CONFIGURACIÓN DEL SISTEMA Y USUARIOS</p>
      </header>

      <div className="space-y-8">

        {/* General Config */}
        <Card>
            <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800 uppercase">
              <DollarSign className="w-5 h-5 text-indigo-600" />
              CONFIGURACIÓN GENERAL
            </h3>

            <div className="space-y-6">
                {/* Branding & Design */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-6 border-b border-slate-100">
                    <div>
                        <Input 
                             label="NOMBRE DEL NEGOCIO"
                             value={businessName}
                             onChange={(e) => setBusinessName(e.target.value.toUpperCase())}
                             placeholder="EJ. CYC POS 26"
                        />
                    </div>
                    <div>
                        <Input 
                             label="SLOGAN / SUBTÍTULO"
                             value={businessTagline}
                             onChange={(e) => setBusinessTagline(e.target.value.toUpperCase())}
                             placeholder="EJ. DISFRACES & ACCESORIOS"
                        />
                        <p className="text-xs text-slate-400 mt-1 uppercase">* Aparece debajo del nombre en el ticket.</p>
                    </div>
                    <div className="md:col-span-2">
                        <Select 
                            label="DISEÑO DE RECIBO"
                            value={receiptTemplate}
                            onChange={(e) => setReceiptTemplate(e.target.value as 'v1' | 'v2')}
                        >
                            <option value="v1">DISEÑO V1 (CLÁSICO)</option>
                            <option value="v2">DISEÑO V2 (MINIMALISTA)</option>
                        </Select>
                        <p className="text-xs text-slate-400 mt-1 uppercase">* Formato de impresión (21.5 x 8.7cm).</p>
                    </div>
                </div>

                {/* Financials */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <div>
                        <Input 
                            label="RECARGO POR ATRASO (MULTA)"
                            type="number"
                            placeholder="50.00"
                            value={lateFee}
                            onChange={(e) => setLateFee(e.target.value)}
                        />
                    </div>
                    <div>
                        <Input 
                            label="PRECIO POR DÍA EXTRA DE RENTA"
                            type="number"
                            placeholder="50.00"
                            value={extraDayPrice}
                            onChange={(e) => setExtraDayPrice(e.target.value)}
                        />
                    </div>
                     <div>
                        <Input 
                            label="COMISIÓN POR TARJETA (%)"
                            type="number"
                            placeholder="0"
                            value={cardFee}
                            onChange={(e) => setCardFee(e.target.value)}
                        />
                    </div>
                </div>

                <div className="flex justify-end pt-2">
                    <Button onClick={handleSaveSettings} className="w-full md:w-auto">
                        <Save className="w-5 h-5" /> GUARDAR CAMBIOS
                    </Button>
                </div>
            </div>
        </Card>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            {/* Register Form */}
            <div>
            <Card className="h-full">
                <h3 className="text-lg font-bold mb-6 flex items-center gap-2 text-slate-800 uppercase">
                <UserPlus className="w-5 h-5 text-indigo-600" />
                NUEVO USUARIO
                </h3>
                <form onSubmit={handleAddUser} className="space-y-4">
                <Input 
                    label="NOMBRE DEL PERSONAL"
                    placeholder="EJ. MARIANA"
                    value={newName}
                    onChange={e => setNewName(e.target.value.toUpperCase())}
                />
                <Input 
                    label="CÓDIGO DE ACCESO (4 DÍGITOS)"
                    type="number"
                    placeholder="1234"
                    maxLength={4}
                    value={newCode}
                    onChange={e => setNewCode(e.target.value.slice(0, 4))}
                />
                <div className="pt-4">
                    <Button type="submit" className="w-full uppercase">
                    REGISTRAR ACCESO
                    </Button>
                </div>
                </form>
            </Card>
            </div>

            {/* User List */}
            <div className="space-y-4">
            <h3 className="text-lg font-bold text-slate-800 px-2 uppercase">USUARIOS REGISTRADOS</h3>

            {/* Super Admin Hardcoded Display (Read Only) */}
            <div className="bg-gradient-to-r from-indigo-600 to-purple-600 text-white p-4 rounded-2xl shadow-lg flex items-center justify-between">
                <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center">
                        <Shield className="w-5 h-5 text-white" />
                    </div>
                    <div>
                        <div className="font-bold uppercase">CRISTOBAL</div>
                        <div className="text-xs opacity-80 uppercase">SUPER ADMINISTRADOR</div>
                    </div>
                </div>
                <div className="bg-black/20 px-3 py-1 rounded-lg font-mono text-sm tracking-widest">
                    ******
                </div>
            </div>

            {/* Dynamic Users */}
            {loading ? (
                <div className="text-center py-4 text-slate-400 uppercase">CARGANDO...</div>
            ) : users.map(user => (
                <div key={user.id} className="bg-white border border-slate-200 p-4 rounded-2xl flex items-center justify-between shadow-sm">
                    <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 font-bold uppercase">
                        {user.name.charAt(0)}
                    </div>
                    <div>
                        <div className="font-bold text-slate-800 uppercase">{user.name}</div>
                        <div className="text-xs text-slate-400 flex items-center gap-1 uppercase">
                            <Key className="w-3 h-3" /> ACCESO NIVEL USUARIO
                        </div>
                    </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="bg-slate-50 border border-slate-100 px-3 py-1 rounded-lg font-mono text-sm text-slate-500 tracking-widest">
                            {user.code}
                        </div>
                        <button 
                        onClick={() => user.id && handleDelete(user.id)}
                        className="p-3 bg-slate-50 rounded-xl text-slate-400 hover:text-rose-500 hover:bg-rose-50 transition-all active:scale-95"
                        >
                        <Trash2 className="w-5 h-5" />
                        </button>
                    </div>
                </div>
            ))}

            {users.length === 0 && !loading && (
                <div className="text-center py-8 text-slate-400 text-sm uppercase">
                NO HAY OTROS USUARIOS REGISTRADOS.
                </div>
            )}
            </div>
        </div>
      </div>
    </div>
  );
};

