                    <input 
                        type="text" 
                        placeholder="BUSCAR..." 
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
