            </div>
          ) : (
             <>
                {cart.map((item) => (
                <div key={item.cartId} className={`flex gap-4 p-3 rounded-2xl group ${item.code === 'DEUDA' ? 'bg-rose-50 border border-rose-100' : 'bg-slate-50'}`}>
