export const ReceiptTemplate: React.FC<{ order: Order | null, settings?: SystemSettings }> = ({ order, settings }) => {
  // Retrieve user name from localStorage
  const currentUser = useMemo(() => {
    try {
        const u = localStorage.getItem('cyc_pos_user');
        return u ? JSON.parse(u) : { name: 'CAJERO' };
    } catch(e) { return { name: 'CAJERO' }; }
  }, []);

  if (!order) return null;

  const businessName = settings?.businessName || 'CyC POS 26';
  const businessTagline = settings?.businessTagline || 'DISFRACES & ACCESORIOS';
  const template = settings?.receiptTemplate || 'v1';

  return (
    <div className="hidden print:block fixed inset-0 bg-white z-[9999]">
      <style>
        {`
          @media print {
            @page {
              size: 21.5cm 8.7cm; /* Custom Receipt Size */
              margin: 0;
            }
            body {
              margin: 0;
              padding: 0;
            }
            .no-print {
              display: none !important;
            }
          }
        `}
      </style>

      {template === 'v1' ? (
          <ReceiptV1 order={order} businessName={businessName} businessTagline={businessTagline} currentUser={currentUser} />
      ) : (
          <ReceiptV2 order={order} businessName={businessName} businessTagline={businessTagline} currentUser={currentUser} />
      )}
    </div>
  );
};

export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
  imageUrl?: string; // New field for product image
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff';
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
  cardFeePercentage: number;
  businessName?: string; // New: Custom business name
  businessTagline?: string; // New: Custom slogan/subtitle
