                        <Button onClick={handlePrint} className="uppercase shadow-lg">
                            <Printer className="w-5 h-5" /> <span className="hidden md:inline">IMPRIMIR</span>
                        </Button>
                    </div>
                </div>

                {/* Receipt Container Preview (Scaled Visual) */}
                <div className="flex-1 overflow-y-auto p-4 md:p-10 flex items-center justify-center bg-slate-100/50">
                    <div className="scale-[0.8] md:scale-100 origin-top shadow-2xl transition-all duration-300">
