import React, { useState, useEffect, useMemo } from 'react';
import { BarChart3, Calendar, TrendingUp, DollarSign, ArrowUpRight, Activity } from 'lucide-react';
import { Card } from '../components/UI';
import { Order } from '../types';
import { getOrders } from '../services/dataService';

const Reports: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      const data = await getOrders();
      setOrders(data);
      setLoading(false);
    };
    loadData();
  }, []);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
    const now = new Date();

    // --- Helper for Date Ranges ---
    const formatDate = (date: Date) => date.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' }).toUpperCase();

    // 1. TODAY
    const todayStr = now.toLocaleDateString();
    const rangeToday = formatDate(now);

    // 2. THIS WEEK (Monday to Sunday)
    // JS getDay(): 0=Sun, 1=Mon... 
    // We want Monday to be the start. 
    // If today is Sunday (0), we go back 6 days. If Monday (1), go back 0 days.
    const currentDay = now.getDay(); 
    const daysToMonday = currentDay === 0 ? 6 : currentDay - 1;

    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - daysToMonday);
    startOfWeek.setHours(0,0,0,0);

    const endOfWeek = new Date(startOfWeek);
    endOfWeek.setDate(startOfWeek.getDate() + 6);
    endOfWeek.setHours(23,59,59,999);

    const rangeWeek = `${formatDate(startOfWeek)} - ${formatDate(endOfWeek)}`;

    // 3. THIS MONTH
    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0);
    const rangeMonth = `${formatDate(startOfMonth)} - ${formatDate(endOfMonth)}`;

    // 4. THIS YEAR
    const startOfYear = new Date(now.getFullYear(), 0, 1);
    const endOfYear = new Date(now.getFullYear(), 11, 31);
    const rangeYear = `${now.getFullYear()}`;

    let todayTotal = 0;
    let weekTotal = 0;
    let monthTotal = 0;
    let yearTotal = 0;

    // Daily Aggregation for Table
    const dailyMap: Record<string, { date: string, total: number, rentTotal: number, saleTotal: number, refundTotal: number, count: number }> = {};
    let maxDailyTotal = 0;

    orders.forEach(order => {
      const orderDate = new Date(order.createdAt);
      const isRefund = order.status === 'refunded';

      // Calculate effective amount (0 if refunded for Positive Totals, but we track refunds separately)
      // Actually, per requirement: "descontar de las ganancias"
      // So if refunded, the amount contributes negatively or 0 to total revenue, but we track the 'lost' amount.

      const amount = isRefund ? 0 : order.total; // Refunded orders don't count towards Positive Revenue directly here? 
      // Wait, if it was sold today and refunded today, total should be 0.
      // If sold yesterday and refunded today, we should probably record the refund on the refund date?
      // For simplicity in this POS context: We just ignore the amount in totals if status is 'refunded'.
      // If you want to track WHEN the refund happened, we'd need a 'refundedAt' timestamp. 
      // Assuming simple logic: If marked refunded, it's removed from revenue entirely retroactively or currently.
      // Based on prompt "descontar de las ganancias", removing it from totals seems correct.

      // However, to show "Reembolsos" in breakdown, we need to sum them up.

      // Totals by Period (Net Revenue)
      if (!isRefund) {
          if (orderDate.toLocaleDateString() === todayStr) todayTotal += amount;
          if (orderDate >= startOfWeek) weekTotal += amount;
          if (orderDate >= startOfMonth) monthTotal += amount;
          if (orderDate >= startOfYear) yearTotal += amount;
      }

      // Group by Day (Format YYYY-MM-DD for sorting logic)
      const sortKey = `${orderDate.getFullYear()}/${(orderDate.getMonth()+1).toString().padStart(2,'0')}/${orderDate.getDate().toString().padStart(2,'0')}`;

      if (!dailyMap[sortKey]) {
        dailyMap[sortKey] = {
            date: orderDate.toLocaleDateString('es-MX', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }).toUpperCase(),
            total: 0,
            rentTotal: 0,
            saleTotal: 0,
            refundTotal: 0,
            count: 0
        };
      }

      if (isRefund) {
          dailyMap[sortKey].refundTotal += order.total;
          dailyMap[sortKey].count += 1; // Still count the ticket? Yes, it existed.
      } else {
          dailyMap[sortKey].total += order.total;
          dailyMap[sortKey].count += 1;

          let orderRentSum = 0;
          let orderSaleSum = 0;
          order.items.forEach(item => {
              const itemTotal = item.appliedPrice * item.quantity;
              if (item.transactionType === 'rent') orderRentSum += itemTotal;
              else orderSaleSum += itemTotal;
          });

          dailyMap[sortKey].rentTotal += orderRentSum;
          dailyMap[sortKey].saleTotal += orderSaleSum;
      }

      if (dailyMap[sortKey].total > maxDailyTotal) maxDailyTotal = dailyMap[sortKey].total;
    });

    // Convert map to array and sort descending
    const dailyList = Object.keys(dailyMap).sort().reverse().map(key => dailyMap[key]);

    return {
      today: todayTotal,
      week: weekTotal,
      month: monthTotal,
      year: yearTotal,
      ranges: {
          today: rangeToday,
          week: rangeWeek,
          month: rangeMonth,
          year: rangeYear
      },
      dailyList,
      maxDailyTotal
    };
  }, [orders]);

