                                  >
                                      <Pencil className="w-4 h-4" />
                                  </button>
                                  <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-indigo-400" />
                              </div>
                          </div>
                      ))}
                      {filteredCustomers.length === 0 && customerSearchTerm && (
