  // Determine Rental Status for an Order
  const getRentalStatus = (order: Order) => {
      if (order.status === 'refunded') return { status: 'refunded', label: 'REEMBOLSADO', color: 'amber' as const, late: false };

      if (!order.items.some(i => i.transactionType === 'rent')) return null; // Not a rental

      // If manually marked as returned
      if (order.status === 'returned' || order.status === 'returned_late') {
          return { status: 'returned', label: 'DEVUELTO', color: 'green' as const, late: order.status === 'returned_late' };
      }

      const now = Date.now();
      const end = order.rentalEndDate || 0;

      // Add a small buffer (e.g., end of the day) if needed, but here we assume strict timestamp
      if (now > end) {
          return { status: 'late', label: 'ATRASO', color: 'rose' as const, late: true };
      }

      return { status: 'active', label: 'RENTADO', color: 'indigo' as const, late: false };
  };

  // Group orders by Date
  const groupedOrders = useMemo(() => {
    const groups: Record<string, Order[]> = {};

    // Filter first
    const filtered = orders.filter(o => 
       o.id?.toLowerCase().includes(searchQuery.toLowerCase()) ||
       o.customer?.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
       o.total.toString().includes(searchQuery)
    );

    filtered.forEach(order => {
      const dateKey = new Date(order.createdAt).toLocaleDateString('es-MX', {
        weekday: 'long',
        year: 'numeric',
        month: 'long',
        day: 'numeric'
      });
      // Capitalize first letter
      const formattedDate = dateKey.charAt(0).toUpperCase() + dateKey.slice(1);

      if (!groups[formattedDate]) {
        groups[formattedDate] = [];
      }
      groups[formattedDate].push(order);
    });

    return groups;
  }, [orders, searchQuery]);

  const handlePrint = () => {
    window.print();
  };

  const handleRefund = async () => {
      if (!selectedOrder) return;
      if (!confirm(`¿Estás seguro de REEMBOLSAR el ticket #${selectedOrder.id}? \n\nEsta acción no elimina el registro, pero lo marcará como reembolsado y se descontará de los reportes.`)) return;

      try {
          await updateOrder(selectedOrder.id!, { status: 'refunded' });
          alert("Ticket marcado como reembolsado.");
          setSelectedOrder(prev => prev ? { ...prev, status: 'refunded' } : null);
          loadData();
      } catch (e) {
          alert("Error al procesar reembolso.");
      }
  };

  // Dynamic Preview Component
  const TicketPreview = useMemo(() => {
      if (!selectedOrder) return null;
      const props = {
          order: selectedOrder,
          businessName: settings?.businessName || 'CyC POS 26',
          businessTagline: settings?.businessTagline || 'DISFRACES & ACCESORIOS',
          currentUser: user
      };

      return settings?.receiptTemplate === 'v2' 
        ? <ReceiptV2 {...props} /> 
        : <ReceiptV1 {...props} />;
  }, [selectedOrder, settings, user]);

  return (
    <div className="flex h-full flex-col lg:flex-row bg-white overflow-hidden">
      {/* Shared Receipt Component (Visible only when Printing) */}
      <ReceiptTemplate order={selectedOrder} settings={settings} />

      {/* LEFT PANEL: Ticket List - REDUCED WIDTH */}
      <div className={`w-full lg:w-[280px] xl:w-[320px] flex flex-col border-r border-slate-200 bg-white h-full transition-all duration-300 ${selectedOrder ? 'hidden lg:flex' : 'flex'}`}>

        {/* Header */}
        <div className="p-3 bg-indigo-600 text-white flex justify-between items-center flex-shrink-0">
             <div className="flex items-center gap-2">
                 <Receipt className="w-5 h-5" />
                 <h1 className="text-lg font-bold uppercase">Recibos</h1>
             </div>
             <div className="text-[10px] font-mono bg-indigo-500 px-1.5 py-0.5 rounded">
                 {orders.length}
             </div>
        </div>

        {/* Search */}
        <div className="p-3 border-b border-slate-100 bg-slate-50">
            <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                <input 
                    type="text" 
                    placeholder="BUSCAR..." 
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                    className="w-full pl-9 pr-3 py-2 rounded-xl border border-slate-200 text-xs focus:ring-2 focus:ring-indigo-500/20 outline-none uppercase"
                />
            </div>
        </div>

        {/* List */}
        <div className="flex-1 overflow-y-auto">
            {loading ? (
                <div className="p-8 text-center text-slate-400 text-xs uppercase">Cargando...</div>
            ) : Object.keys(groupedOrders).length === 0 ? (
                <div className="p-8 text-center text-slate-400 text-xs uppercase">Sin resultados</div>
            ) : (
                Object.entries(groupedOrders).map(([date, dateOrders]) => (
                    <div key={date}>
                        <div className="px-3 py-1.5 bg-slate-50 text-[10px] font-bold text-indigo-600 uppercase tracking-wider sticky top-0 border-b border-slate-100 z-10 backdrop-blur-sm bg-slate-50/90 truncate">
                            {date}
                        </div>
                        {(dateOrders as Order[]).map(order => {
                            const rStatus = getRentalStatus(order);
                            return (
                                <div 
                                    key={order.id}
                                    onClick={() => setSelectedOrder(order)}
                                    className={`px-3 py-3 border-b border-slate-50 cursor-pointer hover:bg-indigo-50 transition-colors flex justify-between items-center group relative ${selectedOrder?.id === order.id ? 'bg-indigo-50 border-l-4 border-l-indigo-600' : 'border-l-4 border-l-transparent'}`}
                                >
                                    <div className="flex items-center gap-3 overflow-hidden">
                                        <div className={`p-2 rounded-full flex-shrink-0 ${order.status === 'refunded' ? 'bg-amber-100 text-amber-600' : (order.status.includes('returned') ? 'bg-emerald-100 text-emerald-600' : (rStatus?.status === 'late' ? 'bg-rose-100 text-rose-600' : 'bg-slate-100 text-slate-500'))}`}>
                                            {order.items.length > 2 ? <ShoppingBag className="w-4 h-4"/> : <Receipt className="w-4 h-4" />}
                                        </div>
                                        <div className="min-w-0">
                                            <div className="font-bold text-slate-800 text-sm truncate">
                                                ${order.total.toFixed(2)}
                                            </div>
                                            <div className="text-[10px] text-slate-400 flex items-center flex-wrap gap-1 mt-0.5">
                                                <span>#{order.id?.slice(-4)}</span>
                                                {rStatus && (
                                                    <span className={`font-bold px-1 rounded-[4px] leading-none py-0.5 ${rStatus.color === 'rose' ? 'bg-rose-100 text-rose-600' : (rStatus.color === 'amber' ? 'bg-amber-100 text-amber-600' : 'bg-indigo-50 text-indigo-600')}`}>
                                                        {rStatus.label}
                                                    </span>
                                                )}
                                            </div>
                                        </div>
                                    </div>

                                    <div className="text-right pl-1">
                                        <ChevronRight className="w-4 h-4 text-slate-300 group-hover:text-indigo-400" />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ))
            )}
        </div>
      </div>

      {/* RIGHT PANEL: Details / Receipt Preview */}
      <div className={`flex-1 bg-slate-100 relative flex flex-col h-full ${!selectedOrder ? 'hidden lg:flex' : 'flex'}`}>
          {selectedOrder ? (
            <>
                {/* Mobile Header for Right Panel */}
                <div className="lg:hidden bg-white p-4 flex items-center gap-3 border-b border-slate-200">
                    <Button variant="ghost" onClick={() => setSelectedOrder(null)} className="p-2">
                        <ArrowLeft className="w-6 h-6" />
                    </Button>
                    <span className="font-bold text-slate-800">DETALLE DEL TICKET</span>
                </div>

                {/* Toolbar */}
                <div className="p-4 flex justify-between items-center bg-white border-b border-slate-200 shadow-sm z-20">
                    <div className="flex flex-col">
                        <h2 className="text-lg font-bold text-slate-800 uppercase">
                            VISTA PREVIA
                        </h2>
                        {selectedOrder.status === 'refunded' && (
                            <span className="text-xs font-bold text-amber-600 flex items-center gap-1 bg-amber-50 w-fit px-2 py-0.5 rounded border border-amber-200">
                                <AlertTriangle className="w-3 h-3" /> TICKET REEMBOLSADO
                            </span>
                        )}
                    </div>
                    <div className="flex gap-3">
                        {/* ONLY ADMIN CAN REFUND */}
                        {selectedOrder.status !== 'refunded' && isAdmin && (
                            <Button variant="danger" onClick={handleRefund} className="uppercase shadow-none bg-rose-50 text-rose-600 border border-rose-200 hover:bg-rose-100">
                                <RotateCcw className="w-4 h-4" /> <span className="hidden md:inline">REEMBOLSAR</span>
                            </Button>
                        )}
                        <Button onClick={handlePrint} className="uppercase shadow-lg">
                            <Printer className="w-5 h-5" /> <span className="hidden md:inline">IMPRIMIR</span>
                        </Button>
                    </div>
                </div>

                {/* Receipt Container Preview (Scaled Visual) */}
                <div className="flex-1 overflow-y-auto p-4 md:p-8 flex items-start justify-center bg-slate-100/50">
                    {/* Adjusted Scaling to ensure full visibility on smaller screens */}
                    <div className="scale-[0.55] sm:scale-[0.65] md:scale-[0.75] xl:scale-100 origin-top shadow-2xl transition-all duration-300 mt-4">
                         {TicketPreview}
                    </div>
                </div>
            </>
          ) : (
            <div className="h-full flex flex-col items-center justify-center text-slate-300 p-8">
                <div className="w-24 h-24 bg-slate-200 rounded-full flex items-center justify-center mb-6 animate-pulse">
                    <Receipt className="w-10 h-10 text-slate-400" />
                </div>
                <h2 className="text-2xl font-bold text-slate-400 uppercase mb-2">Ningún ticket seleccionado</h2>
                <p className="text-center max-w-xs text-sm uppercase">Selecciona una transacción de la lista para ver el recibo detallado</p>
            </div>
          )}
      </div>
    </div>
  );
};

export default Tickets;

import React, { useState, useEffect } from 'react';
import { Users, Search, Phone, MapPin, Plus, Trash2, Pencil, UserPlus, Map as MapIcon, History, Wallet, AlertCircle, CheckCircle, Clock, Receipt, ArrowUpRight, ArrowDownLeft, Filter } from 'lucide-react';
import { Button, Input, Card, Modal, Badge } from '../components/UI';
import { Customer, Order, User } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer, getOrders } from '../services/dataService';

const Customers: React.FC<{ user: User }> = ({ user }) => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState<'all' | 'attention'>('all');

  const isAdmin = user.role === 'admin';

  // Create/Edit Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newAddress, setNewAddress] = useState('');

  // History Modal State
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [customerOrders, setCustomerOrders] = useState<Order[]>([]);
  const [historyTab, setHistoryTab] = useState<'active' | 'all'>('active');

  const loadData = async () => {
    setLoading(true);
    const [cData, oData] = await Promise.all([getCustomers(), getOrders()]);
    setCustomers(cData);
    setOrders(oData);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  // --- Helpers ---
  const hasActiveRental = (customerId: string) => {
      return orders.some(o => 
        o.customer?.id === customerId && 
        o.items.some(i => i.transactionType === 'rent') &&
        !o.status.includes('returned')
      );
  };

  // --- CRUD Handlers ---

  const handleNewCustomerClick = () => {
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewAddress('');
      setIsModalOpen(true);
  };

  const handleEditClick = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewAddress(customer.address || '');
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            address: newAddress
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewAddress('');
        setIsModalOpen(false);
        setEditingId(null);
        loadData();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
      e.stopPropagation(); 
      if (!isAdmin) return;
      if(window.confirm('¿Eliminar cliente permanentemente?')) {
         await performDelete(id);
      }
  };

  const performDelete = async (id: string) => {
      try {
          await deleteCustomer(id);
          setCustomers(prev => prev.filter(c => c.id !== id));
      } catch (error) {
          alert("No se pudo eliminar el cliente.");
          loadData();
      }
  }

  // --- History & Balance Handlers ---

  const handleViewHistory = async (customer: Customer) => {
      setSelectedCustomer(customer);
      setIsHistoryOpen(true);
      const userOrders = orders.filter(o => o.customer?.id === customer.id);
      setCustomerOrders(userOrders);
      setHistoryTab('active');
  };

  const handleSettleDebt = async () => {
      if (!selectedCustomer || !selectedCustomer.id) return;
      if (!selectedCustomer.balance || selectedCustomer.balance >= 0) return;

      // Allow settle debt for everyone? Or just admin? Usually cashiers settle debt when getting paid. 
      // Let's assume cashiers can settle debt (accept payment).

      if (confirm(`¿Confirmar que ${selectedCustomer.name} ha liquidado su deuda de $${Math.abs(selectedCustomer.balance).toFixed(2)}?`)) {
          await updateCustomer(selectedCustomer.id, { balance: 0 });
          // Update local state
          const updated = { ...selectedCustomer, balance: 0 };
          setSelectedCustomer(updated);
          setCustomers(prev => prev.map(c => c.id === updated.id ? updated : c));
          alert("Deuda liquidada.");
      }
  };

  const filtered = customers.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(searchQuery.toLowerCase()) || c.phone.includes(searchQuery);

      if (filterMode === 'attention') {
          const isDebtor = (c.balance || 0) < 0;
          const isActive = c.id ? hasActiveRental(c.id) : false;
          return matchesSearch && (isDebtor || isActive);
      }

      return matchesSearch;
  });

  // Filter orders for the active tab inside modal
  const displayedOrders = customerOrders.filter(order => {
      if (historyTab === 'all') return true;
      // Active = Contains rentals that are NOT returned
      const hasRentals = order.items.some(i => i.transactionType === 'rent');
      const isClosed = order.status === 'returned' || order.status === 'returned_late';
      return hasRentals && !isClosed;
  });

  return (
    <div className="p-4 md:p-8 max-w-5xl mx-auto h-full flex flex-col">
      <header className="mb-8 flex justify-between items-end flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <Users className="w-8 h-8 text-indigo-600" />
            CLIENTES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">DIRECTORIO Y ALTA DE CLIENTES</p>
        </div>

        <div className="flex gap-4 items-center">
            <div className="text-right hidden sm:block">
                <div className="text-2xl font-bold text-slate-800">{customers.length}</div>
                <div className="text-xs text-slate-400 uppercase font-bold">TOTAL</div>
            </div>
            <Button onClick={handleNewCustomerClick} className="shadow-xl shadow-indigo-200 uppercase">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO CLIENTE</span>
                <span className="sm:hidden">NUEVO</span>
            </Button>
        </div>
      </header>

      {/* Main List Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
             <div className="flex gap-4 mb-6 flex-shrink-0">
                 <div className="relative flex-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR CLIENTE POR NOMBRE O TELÉFONO..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                    />
                </div>

                {/* Attention Filter Toggle */}
                <button 
                    onClick={() => setFilterMode(prev => prev === 'all' ? 'attention' : 'all')}
                    className={`px-4 rounded-2xl border flex items-center gap-2 font-bold uppercase transition-all ${filterMode === 'attention' ? 'bg-amber-100 border-amber-300 text-amber-800 shadow-sm' : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'}`}
                >
                    <AlertCircle className={`w-5 h-5 ${filterMode === 'attention' ? 'fill-current' : ''}`} />
                    <span className="hidden sm:inline">⚠️ ATENCIÓN REQUERIDA</span>
                    <span className="sm:hidden">FILTRAR</span>
                </button>
             </div>

            <div className="flex-1 overflow-y-auto space-y-3 pb-32">
                {filtered.map(customer => {
                    const isActiveRenter = customer.id && hasActiveRental(customer.id);
                    return (
                        <Card key={customer.id} className="flex items-center justify-between group hover:border-indigo-200 transition-colors cursor-pointer active:scale-[0.99]">
                            <div className="flex items-center gap-4 flex-1" onClick={() => handleViewHistory(customer)}>
                                <div className="w-14 h-14 rounded-2xl bg-indigo-50 text-indigo-600 flex flex-shrink-0 items-center justify-center font-bold text-xl uppercase relative">
                                    {customer.name.charAt(0)}
                                    {customer.balance && customer.balance < 0 ? (
                                        <div className="absolute -top-1 -right-1 w-4 h-4 bg-rose-500 rounded-full border-2 border-white"></div>
                                    ) : null}
                                </div>
                                <div>
                                    <h3 className="font-bold text-lg text-slate-800 uppercase flex items-center gap-2">
                                        {customer.name}
                                        {customer.balance && customer.balance < 0 && (
                                            <span className="text-[10px] bg-rose-100 text-rose-600 px-2 py-0.5 rounded-full border border-rose-200 animate-pulse font-bold flex items-center gap-1">
                                                <AlertCircle className="w-3 h-3" />
                                                DEUDA: ${Math.abs(customer.balance).toFixed(2)}
                                            </span>
                                        )}
                                        {isActiveRenter && (
                                            <span className="text-[10px] bg-indigo-100 text-indigo-600 px-2 py-0.5 rounded-full border border-indigo-200 font-bold flex items-center gap-1">
                                                <Clock className="w-3 h-3" /> RENTA ACTIVA
                                            </span>
                                        )}
                                        {customer.balance && customer.balance > 0 && (
                                            <span className="text-[10px] bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full border border-emerald-200 font-bold">
                                                FAVOR: ${customer.balance.toFixed(2)}
                                            </span>
                                        )}
                                    </h3>
                                    <div className="flex flex-col sm:flex-row sm:gap-4 text-sm text-slate-500 mt-1">
                                        {customer.phone && (
                                            <span className="flex items-center gap-1"><Phone className="w-3 h-3" /> {customer.phone}</span>
                                        )}
                                        {customer.address && (
                                            <span className="flex items-center gap-1 uppercase"><MapPin className="w-3 h-3" /> {customer.address}</span>
                                        )}
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-center gap-2 pl-3 border-l border-slate-100 ml-2">
                                {/* History Button */}
                                <button 
                                    onClick={() => handleViewHistory(customer)}
                                    className="p-3 bg-indigo-50 text-indigo-600 rounded-xl hover:bg-indigo-100 transition-all"
                                    title="Ver Historial"
                                >
                                    <History className="w-5 h-5" />
                                </button>

                                {/* Edit Button */}
                                <button 
                                    onClick={(e) => handleEditClick(e, customer)}
                                    className="p-3 bg-slate-50 text-slate-400 rounded-xl hover:bg-slate-100 hover:text-indigo-600 transition-all"
                                    title="Editar"
                                >
                                    <Pencil className="w-5 h-5" />
                                </button>

                                {/* Delete Button - ADMIN ONLY */}
                                {isAdmin && (
                                    <button 
                                        onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                        className="p-3 bg-rose-50 rounded-xl text-rose-400 hover:text-rose-600 hover:bg-rose-100 transition-all active:bg-rose-200"
                                        title="Eliminar Cliente"
                                    >
                                        <Trash2 className="w-5 h-5" />
                                    </button>
                                )}
                            </div>
                        </Card>
                    );
                })}
                {filtered.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                        <Users className="w-16 h-16 mb-4 opacity-20" />
                        <p className="uppercase">NO SE ENCONTRARON CLIENTES</p>
                    </div>
                )}
            </div>
      </div>

