                  <AlertTriangle className="w-6 h-6" />
                  <div>
                      ESTÁ A PUNTO DE ELIMINAR: <br/>
                      <span className="text-lg underline">{selectedDeleteCategory === 'TODOS' ? 'TODO EL INVENTARIO' : `CATEGORÍA ${selectedDeleteCategory}`}</span>
