import React, { useState, useEffect, useMemo } from 'react';
import { HashRouter, Routes, Route, Link, useLocation, Navigate } from 'react-router-dom';
import { LayoutGrid, ShoppingCart, History, Users, Settings as SettingsIcon, BarChart3, Receipt, RotateCcw, BoxSelect, Search, Clock, AlertTriangle, CheckCircle, X } from 'lucide-react';
import POS from './pages/POS';
import Inventory from './pages/Inventory';
import Customers from './pages/Customers';
import Settings from './pages/Settings';
import Reports from './pages/Reports';
import Tickets from './pages/Tickets';
import Returns from './pages/Returns';
import Login from './pages/Login';
import { User, Order, SystemSettings } from './types';
import { getOrders, updateOrder, updateCustomer, getSystemSettings } from './services/dataService';
import { Modal, Input, Button, Badge } from './components/UI';

// Icon Map for Nav
const NavItem = ({ to, icon: Icon, label }: { to: string, icon: any, label: string }) => {
  const location = useLocation();
  const isActive = location.pathname === to;

  return (
    <Link to={to} className={`flex flex-col items-center justify-center gap-1 p-2 rounded-2xl transition-all duration-300 ${isActive ? 'text-indigo-600 bg-indigo-50' : 'text-slate-400 hover:text-slate-600'}`}>
      <Icon className={`w-6 h-6 ${isActive ? 'fill-current' : ''}`} />
      <span className="text-[10px] font-medium uppercase">{label}</span>
    </Link>
  );
};

// Layout Component to handle Route-aware logic (FAB positioning)
const MainLayout: React.FC<{ 
  user: User, 
  setUser: (u: User | null) => void, 
  onOpenQuickReturn: () => void 
}> = ({ user, setUser, onOpenQuickReturn }) => {
  const location = useLocation();
  const isPos = location.pathname === '/';

  const canViewReports = user.role === 'admin' || user.permissions?.canViewReports;
  const canManageSettings = user.role === 'admin' || user.permissions?.canManageSettings;

  // Dynamic FAB Position
  // POS Desktop: Top-right of left panel (avoiding cart) -> top-6 right-[470px]
  // POS Mobile: Top-right (avoiding header buttons) -> top-24 right-4
  // Other Pages: Standard bottom-right -> bottom-24 lg:bottom-10 right-6 lg:right-10
  const fabPositionClass = isPos 
    ? "top-24 right-4 lg:top-6 lg:right-[390px]" 
    : "bottom-24 lg:bottom-10 right-6 lg:right-10";

  return (
    <div className="min-h-screen bg-[#f3f4f6] text-slate-900 font-sans pb-24 lg:pb-0 lg:pl-24 relative">
        {/* Desktop Sidebar / Mobile Bottom Bar */}
        <nav className="fixed bottom-0 left-0 w-full lg:w-24 lg:h-full bg-white border-t lg:border-t-0 lg:border-r border-slate-200 z-40 flex lg:flex-col items-center justify-around lg:justify-center gap-1 lg:gap-6 p-2 lg:p-6 shadow-2xl lg:shadow-none overflow-y-auto hide-scrollbar">
          <div className="hidden lg:flex items-center justify-center w-12 h-12 bg-indigo-600 rounded-xl mb-auto shadow-lg shadow-indigo-300 flex-shrink-0">
             <span className="text-white font-bold text-xl">CyC</span>
          </div>

          <div className="flex lg:flex-col justify-around w-full gap-1 lg:gap-4">
            <NavItem to="/" icon={ShoppingCart} label="Venta" />
            <NavItem to="/returns" icon={RotateCcw} label="Devoluciones" />
            <NavItem to="/tickets" icon={Receipt} label="Recibos" />
            <NavItem to="/inventory" icon={LayoutGrid} label="Stock" />
            <NavItem to="/customers" icon={Users} label="Clientes" />

            {/* PERMISSION BASED LINKS */}
            {canViewReports && <NavItem to="/reports" icon={BarChart3} label="Informes" />}
            {canManageSettings && <NavItem to="/settings" icon={SettingsIcon} label="Ajustes" />}
          </div>

          <div 
            className="hidden lg:flex mt-auto w-10 h-10 rounded-full bg-slate-100 items-center justify-center font-bold text-indigo-600 cursor-pointer hover:bg-rose-100 hover:text-rose-600 transition-colors flex-shrink-0" 
            title={`Cerrar sesión de ${user.name}`} 
            onClick={() => setUser(null)}
          >
            {user.name.charAt(0)}
          </div>
        </nav>

        {/* Main Content Area */}
        <main className="h-screen overflow-hidden">
          <Routes>
            <Route path="/" element={<POS />} />
            <Route path="/returns" element={<Returns />} />
            <Route path="/tickets" element={<Tickets user={user} />} />
            <Route path="/inventory" element={<Inventory user={user} />} />
            <Route path="/customers" element={<Customers user={user} />} />

            {/* Protected Routes */}
            <Route path="/reports" element={canViewReports ? <Reports /> : <Navigate to="/" />} />
            <Route path="/settings" element={canManageSettings ? <Settings /> : <Navigate to="/" />} />
          </Routes>
        </main>

        {/* --- FLOATING ACTION BUTTON (QUICK RETURN) --- */}
        <button 
            onClick={onOpenQuickReturn}
            className={`fixed ${fabPositionClass} z-50 bg-slate-900 text-white p-4 rounded-full shadow-2xl shadow-slate-900/40 hover:scale-110 active:scale-95 transition-all duration-300 border-4 border-[#f3f4f6] group`}
            title="Devolución Rápida"
        >
            <RotateCcw className="w-6 h-6 group-hover:-rotate-90 transition-transform" />
            {!isPos && (
              <span className="absolute right-full mr-4 top-1/2 -translate-y-1/2 bg-slate-800 text-white text-xs font-bold px-3 py-1 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
                  DEVOLUCIÓN RÁPIDA
              </span>
            )}
        </button>
    </div>
  );
};

const App: React.FC = () => {
  // Initialize state from localStorage if available
  const [user, setUser] = useState<User | null>(() => {
    try {
      const savedUser = localStorage.getItem('cyc_pos_user');
      return savedUser ? JSON.parse(savedUser) : null;
    } catch (error) {
      console.error("Error parsing user session", error);
      return null;
    }
  });

  // --- Quick Return Logic ---
  const [isQuickReturnOpen, setIsQuickReturnOpen] = useState(false);
  const [activeRentals, setActiveRentals] = useState<Order[]>([]);
  const [quickSearch, setQuickSearch] = useState('');
  const [loadingRentals, setLoadingRentals] = useState(false);
  const [selectedReturnOrder, setSelectedReturnOrder] = useState<Order | null>(null);
  const [lateFee, setLateFee] = useState('');
  const [step, setStep] = useState<'list' | 'confirm'>('list');

  // Sync state changes to localStorage
  useEffect(() => {
    if (user) {
      localStorage.setItem('cyc_pos_user', JSON.stringify(user));
    } else {
      localStorage.removeItem('cyc_pos_user');
    }
  }, [user]);

  // Load active rentals when modal opens
  useEffect(() => {
    if (isQuickReturnOpen) {
        loadActiveRentals();
    }
  }, [isQuickReturnOpen]);

  const loadActiveRentals = async () => {
      setLoadingRentals(true);
      const allOrders = await getOrders();
      // Filter: Has rental items AND status is NOT returned
      const active = allOrders.filter(o => 
          o.items.some(i => i.transactionType === 'rent') && 
          !o.status.includes('returned')
      );
      setActiveRentals(active);
      setLoadingRentals(false);
  };

  const filteredRentals = useMemo(() => {
      const q = quickSearch.toUpperCase();
      return activeRentals.filter(o => 
          o.id?.includes(q) || 
          o.customer?.name.includes(q)
      );
  }, [activeRentals, quickSearch]);

  const handleCardClick = async (order: Order) => {
      setSelectedReturnOrder(order);
      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;

      if (isLate) {
          const settings = await getSystemSettings();
          setLateFee(settings.defaultLateFee.toString());
      } else {
          setLateFee('0');
      }
      setStep('confirm');
  };

  const processQuickReturn = async (chargeToBalance: boolean) => {
      if (!selectedReturnOrder || !selectedReturnOrder.id) return;

      const fee = parseFloat(lateFee) || 0;
      const isLate = fee > 0; // Simplified logic: if fee > 0, assume late handling or just extra charge

      try {
          const updateData: any = {
              status: isLate ? 'returned_late' : 'returned',
              returnedAt: Date.now(),
          };
          if (isLate) updateData.lateFee = fee;

          await updateOrder(selectedReturnOrder.id, updateData);

          // Handle Debt
          if (isLate && chargeToBalance && selectedReturnOrder.customer?.id) {
               const currentBalance = selectedReturnOrder.customer.balance || 0;
               await updateCustomer(selectedReturnOrder.customer.id, {
                   balance: currentBalance - fee
               });
               alert(`Devolución registrada. Deuda de $${fee} cargada al cliente.`);
          } else {
               alert("Devolución registrada correctamente.");
          }

          // Reset and Reload
          setStep('list');
          setSelectedReturnOrder(null);
          loadActiveRentals();
          setQuickSearch('');

      } catch (e) {
          console.error(e);
          alert("Error al procesar la devolución.");
      }
  };

  if (!user) {
    return <Login onLogin={setUser} />;
  }

  return (
    <HashRouter>
      <MainLayout user={user} setUser={setUser} onOpenQuickReturn={() => setIsQuickReturnOpen(true)} />

      {/* --- QUICK RETURN MODAL --- */}
      <Modal 
          isOpen={isQuickReturnOpen} 
          onClose={() => { setIsQuickReturnOpen(false); setStep('list'); setQuickSearch(''); }} 
          title="DEVOLUCIÓN RÁPIDA"
      >
          <div className="h-[60vh] flex flex-col">
              {step === 'list' ? (
                  <>
                      <div className="mb-4 relative flex-shrink-0">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                          <input 
                              type="number" 
                              placeholder="ESCANEAR O TECLEAR ID TICKET..." 
                              value={quickSearch}
                              onChange={(e) => setQuickSearch(e.target.value)}
                              className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 border-2 border-indigo-100 focus:border-indigo-500 text-2xl font-bold text-center tracking-widest outline-none transition-colors"
                              autoFocus
                          />
                      </div>

                      <div className="flex-1 overflow-y-auto p-1">
                          {loadingRentals ? (
                              <div className="text-center py-10 text-slate-400">CARGANDO RENTAS...</div>
                          ) : filteredRentals.length === 0 ? (
                              <div className="text-center py-10 text-slate-400">
                                  <div className="inline-block p-4 bg-slate-100 rounded-full mb-2"><BoxSelect className="w-8 h-8 opacity-50"/></div>
                                  <p>NO SE ENCONTRARON RENTAS ACTIVAS</p>
                              </div>
                          ) : (
                              <div className="grid grid-cols-2 gap-3">
                                  {filteredRentals.map(order => {
                                      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;
                                      return (
                                          <div 
                                              key={order.id} 
                                              onClick={() => handleCardClick(order)}
                                              className={`p-3 rounded-2xl border-2 cursor-pointer transition-all active:scale-95 relative overflow-hidden flex flex-col justify-between min-h-[140px] ${
                                                  isLate 
                                                  ? 'bg-rose-50 border-rose-200 hover:border-rose-400' 
                                                  : 'bg-white border-slate-200 hover:border-indigo-400'
                                              }`}
                                          >
                                              <div className="flex justify-between items-start">
                                                  <span className={`font-mono font-black text-lg ${isLate ? 'text-rose-700' : 'text-slate-600'}`}>
                                                      #{order.id}
                                                  </span>
                                                  {isLate && <AlertTriangle className="w-5 h-5 text-rose-500 animate-pulse" />}
                                              </div>

                                              <div className="my-2">
                                                  <div className="text-[10px] uppercase text-slate-400 font-bold tracking-wider">CLIENTE</div>
                                                  <div className="font-bold text-slate-800 leading-tight uppercase line-clamp-2">
                                                      {order.customer?.name}
                                                  </div>
                                              </div>

                                              <div className="flex items-end justify-between">
                                                  <div className="text-xs text-slate-500">
                                                      {order.items.filter(i => i.transactionType === 'rent').length} Artículo(s)
                                                  </div>
                                                  <div className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${isLate ? 'bg-rose-200 text-rose-800' : 'bg-indigo-100 text-indigo-700'}`}>
                                                      {isLate ? 'ATRASADO' : 'A TIEMPO'}
                                                  </div>
                                              </div>
                                          </div>
                                      );
                                  })}
                              </div>
                          )}
                      </div>
                  </>
              ) : (
                  <div className="flex flex-col h-full animate-in slide-in-from-right duration-300">
                      {/* CONFIRMATION SCREEN */}
                      <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-4">
                          <div className="flex justify-between items-center mb-2">
                              <h3 className="font-bold text-slate-700 uppercase">CONFIRMAR DEVOLUCIÓN</h3>
                              <div className="font-mono text-slate-400">#{selectedReturnOrder?.id}</div>
                          </div>
                          <div className="text-2xl font-bold text-slate-900 uppercase mb-1">{selectedReturnOrder?.customer?.name}</div>
                          <div className="text-xs text-slate-500 uppercase flex flex-col gap-1">
                              {selectedReturnOrder?.items.filter(i => i.transactionType === 'rent').map((item, idx) => (
                                  <span key={idx}>• {item.name}</span>
                              ))}
                          </div>
                      </div>

                      {parseFloat(lateFee) > 0 && (
                          <div className="mb-4">
                              <div className="bg-rose-100 text-rose-800 p-3 rounded-t-xl flex items-center gap-2 font-bold text-sm">
                                  <AlertTriangle className="w-4 h-4" /> SE DETECTÓ ATRASO
                              </div>
                              <div className="bg-white border-x border-b border-rose-100 p-4 rounded-b-xl">
                                  <Input 
                                      label="MONTO A COBRAR (MULTA)" 
                                      type="number" 
                                      value={lateFee} 
                                      onChange={(e) => setLateFee(e.target.value)}
                                      className="text-xl font-bold text-rose-600"
                                      autoFocus
                                  />
                              </div>
                          </div>
                      )}

                      <div className="mt-auto grid grid-cols-1 gap-3">
                          {parseFloat(lateFee) > 0 ? (
                              <>
                                  <Button onClick={() => processQuickReturn(false)} className="py-4 uppercase shadow-lg">
                                      <div className="flex flex-col items-center leading-none">
                                          <span>COBRAR Y FINALIZAR</span>
                                          <span className="text-[10px] opacity-70 font-normal">EL CLIENTE PAGA AHORA</span>
                                      </div>
                                  </Button>
                                  <Button onClick={() => processQuickReturn(true)} variant="secondary" className="py-4 uppercase border-rose-200 text-rose-600 hover:bg-rose-50">
                                      CARGAR A CUENTA (DEUDA)
                                  </Button>
                              </>
                          ) : (
                              <Button onClick={() => processQuickReturn(false)} className="py-4 uppercase bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200">
                                  <CheckCircle className="w-5 h-5" /> CONFIRMAR RECEPCIÓN (SIN CARGO)
                              </Button>
                          )}
                          <Button variant="ghost" onClick={() => setStep('list')}>VOLVER A LISTA</Button>
                      </div>
                  </div>
              )}
          </div>
      </Modal>
    </HashRouter>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers, Search, Trash2, ArrowLeft, Upload, FileUp, LayoutGrid, List, Pencil, ImagePlus, X, Lock } from 'lucide-react';
import { Button, Input, Select, Card, Badge } from '../components/UI';
import { Product, Variation, User } from '../types';
import { generateProductCode, addProduct, getProducts, deleteProduct, importProductsBatch, updateProduct, uploadProductImage } from '../services/dataService';

const Inventory: React.FC<{ user: User }> = ({ user }) => {
  const [view, setView] = useState<'list' | 'form'>('list');
  const [displayMode, setDisplayMode] = useState<'grid' | 'table'>('grid'); // New: Toggle view
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('TODOS'); // New: Category Filter

  const canManageInventory = user.role === 'admin' || user.permissions?.canManageInventory;

  // File Import Ref
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Image Upload State
  const imageUploadRef = useRef<HTMLInputElement>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  // Form State
  const initialFormState: Partial<Product> = {
    code: '',
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'DISFRACES',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
    imageUrl: '',
  };
  const [formData, setFormData] = useState<Partial<Product>>(initialFormState);

  // New Variation Input State
  const [newVarName, setNewVarName] = useState('');
  const [newVarRent, setNewVarRent] = useState('');
  const [newVarSale, setNewVarSale] = useState('');

  // Load Data
  const loadProducts = async () => {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setLoading(false);
  };

  useEffect(() => {
    if (view === 'list') {
        loadProducts();
    }
  }, [view]);

  // Extract unique categories for filter
  const categories = useMemo(() => {
    const cats = new Set(products.map(p => p.category).filter(Boolean));
    return ['TODOS', ...Array.from(cats).sort()];
  }, [products]);

  // Actions
  const handleNewProduct = () => {
      setFormData({ ...initialFormState, code: generateProductCode() });
      setImageFile(null);
      setImagePreview(null);
      setView('form');
  };

  const handleEditProduct = (product: Product) => {
      if (!canManageInventory) return;

      setFormData({ ...product });
      setImageFile(null);
      setImagePreview(product.imageUrl || null);
      setView('form');
  };

  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  // --- Image Handling ---
  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      // Create local preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveImage = () => {
    setImageFile(null);
    setImagePreview(null);
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if(imageUploadRef.current) imageUploadRef.current.value = '';
  };

  // --- Variations ---

  const handleVariationAdd = () => {
    if (!newVarName.trim()) return;

    const newVariation: Variation = {
      name: newVarName.trim().toUpperCase(),
    };

    if (newVarRent) newVariation.rentalPrice = parseFloat(newVarRent);
    if (newVarSale) newVariation.salePrice = parseFloat(newVarSale);

    setFormData(prev => ({
      ...prev,
      variations: [...(prev.variations || []), newVariation]
    }));

    setNewVarName('');
    setNewVarRent('');
    setNewVarSale('');
  };

  const removeVariation = (index: number) => {
    setFormData(prev => ({
      ...prev,
      variations: prev.variations?.filter((_, i) => i !== index)
    }));
  };

  const handleDelete = async (id: string) => {
      if(confirm('¿Estás seguro de eliminar este artículo? Esta acción no se puede deshacer.')) {
          await deleteProduct(id);
          // Optimistic UI update
          setProducts(prev => prev.filter(p => p.id !== id));
      }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.code) return;

    setLoading(true);
    try {
      let finalImageUrl = formData.imageUrl;

      // Upload image if a new file exists
      if (imageFile) {
        finalImageUrl = await uploadProductImage(imageFile);
      }

      const productData = { ...formData, imageUrl: finalImageUrl };

      if (formData.id) {
          // Update
          await updateProduct(formData.id, productData);
          alert('Producto actualizado exitosamente');
      } else {
          // Create
          await addProduct(productData as Product);
          alert('Producto guardado exitosamente');
      }
      setView('list');
    } catch (error) {
      console.error(error);
      alert('Error al guardar');
    } finally {
      setLoading(false);
    }
  };

  // --- CSV Import Logic ---
  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const parseLoyverseCSV = (text: string) => {
    const splitCSVLine = (str: string) => {
        const matches = [];
        let inQuote = false;
        let buffer = '';
        for (let i = 0; i < str.length; i++) {
            const c = str[i];
            if (c === '"') {
                inQuote = !inQuote;
            } else if (c === ',' && !inQuote) {
                matches.push(buffer);
                buffer = '';
            } else {
                buffer += c;
            }
        }
        matches.push(buffer);
        return matches.map(m => m.trim().replace(/^"|"$/g, '').replace(/""/g, '"').toUpperCase());
    };

    const lines = text.split(/\r\n|\n/);
    if (lines.length < 2) return [];

    const headers = splitCSVLine(lines[0]).map(h => h.toLowerCase());

    const idxHandle = headers.findIndex(h => h === 'handle');
    const idxName = headers.findIndex(h => h === 'nombre');
    const idxCat = headers.findIndex(h => h === 'categoria');
    const idxRef = headers.findIndex(h => h === 'ref');
    const idxDesc = headers.findIndex(h => h.includes('descripción'));
    const idxPrice = headers.findIndex(h => h.includes('precio'));
    const idxStock = headers.findIndex(h => h.includes('en inventario') || h.includes('stock'));
    const idxOpt1Val = headers.findIndex(h => h === 'opción 1 valor' || h === 'option1 value');

    if (idxHandle === -1 || idxName === -1) {
        console.error("Columnas faltantes: Handle o Nombre son requeridas.");
        return [];
    }

    const grouped: Record<string, any[]> = {};

    for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const row = splitCSVLine(line);
        if (row.length <= idxHandle) continue;

        const handle = row[idxHandle];
        if (!handle) continue;

        if (!grouped[handle]) {
            grouped[handle] = [];
        }
        grouped[handle].push(row);
    }

    const products: Partial<Product>[] = [];

    Object.keys(grouped).forEach(handle => {
        const rows = grouped[handle];
        const mainRow = rows[0]; 
        const nameRow = rows.find(r => r[idxName]) || mainRow;

        const productName = nameRow[idxName] || 'SIN NOMBRE';
        const category = (idxCat > -1 ? nameRow[idxCat] : 'VENTA GENERAL') || 'VENTA GENERAL';
        const description = idxDesc > -1 ? nameRow[idxDesc] : '';
        const code = (idxRef > -1 && mainRow[idxRef]) ? mainRow[idxRef] : handle;

        const variations: Variation[] = [];
        let totalStock = 0;
        let basePrice = 0;

        rows.forEach(row => {
            const stockVal = idxStock > -1 ? parseFloat(row[idxStock]) : 0;
            const priceValString = idxPrice > -1 ? row[idxPrice] : '0';
            const priceVal = isNaN(parseFloat(priceValString)) ? 0 : parseFloat(priceValString);

            if (!isNaN(stockVal)) totalStock += stockVal;

            const optVal = idxOpt1Val > -1 ? row[idxOpt1Val] : '';

            if (optVal) {
                variations.push({
                    name: optVal.toUpperCase(),
                    salePrice: priceVal,
                    rentalPrice: 0 
                });
            } else {
                if (priceVal > 0) basePrice = priceVal;
            }
        });

        if (basePrice === 0 && variations.length > 0) {
            basePrice = variations[0].salePrice || 0;
        }

        products.push({
            name: productName.toUpperCase(),
            code: code,
            category: category.toUpperCase(),
            description: description.toUpperCase(),
            stock: totalStock,
            salePrice: basePrice,
            rentalPrice: 0,
            isSaleAvailable: true,
            isRentalAvailable: false,
            variations: variations
        });
    });

    return products;
  };

  const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    if (file.type !== 'text/csv' && !file.name.endsWith('.csv')) {
        alert('Por favor sube un archivo CSV válido.');
        return;
    }

    setLoading(true);
    const reader = new FileReader();

    reader.onload = async (e) => {
        try {
            const text = e.target?.result as string;
            const parsedProducts = parseLoyverseCSV(text);

            if (parsedProducts.length === 0) {
                alert('No se encontraron productos válidos.');
                setLoading(false);
                return;
            }

            const count = await importProductsBatch(parsedProducts as Omit<Product, 'id'>[]);
            alert(`¡Importación exitosa! Se guardaron ${count} productos.`);
            loadProducts();

        } catch (error) {
            console.error(error);
            alert('Hubo un error al procesar el archivo.');
        } finally {
            setLoading(false);
            if (fileInputRef.current) fileInputRef.current.value = '';
        }
    };

    reader.readAsText(file);
  };

  const filteredProducts = products.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.code.includes(searchQuery);
    const matchesCategory = categoryFilter === 'TODOS' || p.category === categoryFilter;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto h-full flex flex-col">
      <header className="mb-6 flex justify-between items-center flex-shrink-0">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3">
            <Box className="w-8 h-8 text-indigo-600" />
            INVENTARIO
            {!canManageInventory && <Lock className="w-5 h-5 text-slate-400" />}
            </h1>
            <p className="text-slate-500 mt-1 text-sm uppercase">{view === 'list' ? 'Gestión de existencias' : (formData.id ? 'Editar Producto' : 'Nuevo registro')}</p>
        </div>

        {/* Only Admin Actions */}
        {canManageInventory && (
            <div className="flex gap-2">
                {view === 'list' ? (
                    <>
                        <input 
                            type="file" 
                            ref={fileInputRef} 
                            onChange={handleFileChange} 
                            className="hidden" 
                            accept=".csv" 
                        />
                        <Button variant="secondary" onClick={handleImportClick} disabled={loading}>
                            <FileUp className="w-5 h-5" /> <span className="hidden sm:inline">IMPORTAR</span>
                        </Button>
                        <Button onClick={handleNewProduct} className="shadow-xl shadow-indigo-200">
                            <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO</span>
                        </Button>
                    </>
                ) : (
                    <Button variant="secondary" onClick={() => setView('list')}>
                        <ArrowLeft className="w-5 h-5" /> <span className="hidden sm:inline">VOLVER</span>
                    </Button>
                )}
            </div>
        )}
      </header>

      {view === 'list' ? (
          <div className="flex-1 overflow-hidden flex flex-col">
              {/* Filter Bar */}
              <div className="mb-6 flex flex-col md:flex-row gap-4 flex-shrink-0">
                  <div className="relative flex-1">
                      <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                      <input 
                          type="text" 
                          placeholder="BUSCAR POR CÓDIGO, NOMBRE..." 
                          value={searchQuery}
                          onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                          className="w-full pl-12 pr-4 py-3 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                      />
                  </div>
                  <div className="flex gap-2">
                     <div className="w-48">
                        <select 
                            value={categoryFilter}
                            onChange={(e) => setCategoryFilter(e.target.value)}
                            className="w-full h-full bg-white border border-slate-200 text-slate-700 rounded-2xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500/20 cursor-pointer uppercase"
                        >
                            {categories.map(cat => (
                                <option key={cat} value={cat}>{cat}</option>
                            ))}
                        </select>
                     </div>
                     <div className="flex bg-white rounded-2xl p-1 border border-slate-200">
                         <button 
                            onClick={() => setDisplayMode('grid')}
                            className={`p-3 rounded-xl transition-all ${displayMode === 'grid' ? 'bg-indigo-100 text-indigo-600' : 'text-slate-400 hover:bg-slate-50'}`}
                         >
                             <LayoutGrid className="w-5 h-5" />
                         </button>
                         <button 
                            onClick={() => setDisplayMode('table')}
                            className={`p-3 rounded-xl transition-all ${displayMode === 'table' ? 'bg-indigo-100 text-indigo-600' : 'text-slate-400 hover:bg-slate-50'}`}
                         >
                             <List className="w-5 h-5" />
                         </button>
                     </div>
                  </div>
              </div>

              {/* Data Display */}
              <div className="flex-1 overflow-y-auto pb-24">
                  {displayMode === 'grid' ? (
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                        {filteredProducts.map(product => (
                            <Card 
                                key={product.id} 
                                className={`group hover:border-indigo-200 transition-all duration-300 relative ${canManageInventory ? 'cursor-pointer active:scale-95' : ''} p-0 overflow-hidden`}
                            >
                                <div onClick={() => handleEditProduct(product)}>
                                    <div className="relative">
                                        {product.imageUrl ? (
                                            <img src={product.imageUrl} alt={product.name} className="w-full h-40 object-cover bg-slate-100" />
                                        ) : (
                                            <div className="w-full h-40 bg-slate-100 flex items-center justify-center text-slate-300">
                                                <Box className="w-12 h-12" />
                                            </div>
                                        )}
                                        <div className="absolute top-2 left-2">
                                            <Badge color={product.category === 'DISFRACES' ? 'indigo' : 'amber'}>{product.category}</Badge>
                                        </div>
                                    </div>

                                    <div className="p-4">
                                        <div className="flex justify-between items-start mb-1">
                                             <h3 className="font-bold text-lg text-slate-800 line-clamp-1">{product.name}</h3>
                                             <span className="font-mono text-xs bg-slate-100 px-2 py-1 rounded text-slate-500 font-bold">{product.code}</span>
                                        </div>

                                        <p className="text-sm text-slate-500 mb-4 line-clamp-1">{product.description || 'SIN DESCRIPCIÓN'}</p>

                                        <div className="flex items-end justify-between border-t border-slate-100 pt-3 mt-auto">
                                            <div>
                                                <div className="text-xs text-slate-400 font-semibold uppercase">Stock</div>
                                                <div className="text-lg font-bold text-slate-800">{product.stock}</div>
                                            </div>
                                            <div className="text-right">
                                                {product.isRentalAvailable && <div className="text-sm text-indigo-600 font-semibold">R: ${product.rentalPrice}</div>}
                                                {product.isSaleAvailable && <div className="text-sm text-emerald-600 font-semibold">V: ${product.salePrice}</div>}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                                {canManageInventory && (
                                    <button 
                                        onClick={(e) => { e.stopPropagation(); product.id && handleDelete(product.id); }}
                                        className="absolute top-2 right-2 p-2 bg-white rounded-full shadow-md text-slate-300 hover:text-rose-500 active:text-rose-600 active:scale-90 transition-all z-10"
                                        title="Eliminar"
                                    >
                                        <Trash2 className="w-5 h-5"/>
                                    </button>
                                )}
                            </Card>
                        ))}
                    </div>
                  ) : (
                    // TABLE VIEW
                    <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left">
                                <thead className="bg-slate-50 text-slate-500 font-bold uppercase text-xs">
                                    <tr>
                                        <th className="px-6 py-4">Imagen</th>
                                        <th className="px-6 py-4">Código</th>
                                        <th className="px-6 py-4">Nombre</th>
                                        <th className="px-6 py-4">Categoría</th>
                                        <th className="px-6 py-4">Stock</th>
                                        <th className="px-6 py-4 text-right">Renta</th>
                                        <th className="px-6 py-4 text-right">Venta</th>
                                        {canManageInventory && <th className="px-6 py-4">Acciones</th>}
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {filteredProducts.map(product => (
                                        <tr key={product.id} className="hover:bg-indigo-50/50 transition-colors">
                                            <td className="px-6 py-4">
                                                <div className="w-10 h-10 rounded-lg bg-slate-100 overflow-hidden">
                                                    {product.imageUrl ? (
                                                        <img src={product.imageUrl} className="w-full h-full object-cover" />
                                                    ) : (
                                                        <Box className="w-full h-full p-2 text-slate-300" />
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 font-mono text-slate-600">{product.code}</td>
                                            <td className="px-6 py-4 font-bold text-slate-800">
                                                {product.name}
                                                {product.variations && product.variations.length > 0 && (
                                                    <div className="text-xs text-slate-400 font-normal mt-1">
                                                        {product.variations.length} Variaciones
                                                    </div>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                <Badge color={product.category === 'DISFRACES' ? 'indigo' : 'amber'}>{product.category}</Badge>
                                            </td>
                                            <td className="px-6 py-4 font-bold text-slate-700">{product.stock}</td>
                                            <td className="px-6 py-4 text-right text-indigo-600 font-medium">
                                                {product.isRentalAvailable ? `$${product.rentalPrice}` : '-'}
                                            </td>
                                            <td className="px-6 py-4 text-right text-emerald-600 font-medium">
                                                {product.isSaleAvailable ? `$${product.salePrice}` : '-'}
                                            </td>
                                            {canManageInventory && (
                                                <td className="px-6 py-4">
                                                    <div className="flex items-center gap-2">
                                                        <button 
                                                            onClick={() => handleEditProduct(product)}
                                                            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                                                            title="Editar"
                                                        >
                                                            <Pencil className="w-4 h-4" />
                                                        </button>
                                                        <button 
                                                            onClick={() => product.id && handleDelete(product.id)}
                                                            className="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-lg transition-colors"
                                                            title="Eliminar"
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </button>
                                                    </div>
                                                </td>
                                            )}
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                  )}

                  {filteredProducts.length === 0 && (
                      <div className="py-12 text-center text-slate-400">
                          {loading ? 'PROCESANDO...' : 'NO SE ENCONTRARON ARTÍCULOS'}
                      </div>
                  )}
              </div>
          </div>
      ) : (
        /* Form View */
        <div className="flex-1 overflow-y-auto pb-24">
            <form onSubmit={handleSubmit} className="max-w-4xl mx-auto w-full animate-in slide-in-from-bottom-4 duration-500">
                <Card className="space-y-6">
                <div className="flex justify-between items-center pb-4 border-b border-slate-100">
                    <h3 className="text-xl font-bold text-slate-800 uppercase">
                        {formData.id ? 'Editar Producto' : 'Crear Nuevo Producto'}
                    </h3>
                    {formData.id && (
                        <span className="text-xs font-mono text-slate-400">ID: {formData.id}</span>
                    )}
                </div>

                {/* Main Info Grid */}
                <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    {/* Image Uploader */}
                    <div className="md:col-span-1">
                        <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider ml-1 mb-1.5">Imagen</label>
                        <div 
                            className="w-full aspect-square bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center cursor-pointer hover:bg-indigo-50 hover:border-indigo-300 transition-all relative overflow-hidden group"
                            onClick={() => imageUploadRef.current?.click()}
                        >
                            {imagePreview ? (
                                <>
                                    <img src={imagePreview} alt="Preview" className="w-full h-full object-cover" />
                                    <div className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity">
                                        <p className="text-white text-xs font-bold uppercase">CAMBIAR IMAGEN</p>
                                    </div>
                                    <button 
                                        type="button"
                                        onClick={(e) => { e.stopPropagation(); handleRemoveImage(); }}
                                        className="absolute top-2 right-2 p-1 bg-white rounded-full text-rose-500 shadow-sm z-20"
                                    >
                                        <X className="w-4 h-4" />
                                    </button>
                                </>
