import React, { useState, useEffect, useMemo } from 'react';
import { BarChart3, Calendar, TrendingUp, DollarSign, ArrowUpRight, Activity, TrendingDown, Wallet, PieChart } from 'lucide-react';
import { Card } from '../components/UI';
import { Order, Expense } from '../types';
import { getOrders, getExpenses } from '../services/dataService';

const Reports: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      const [oData, eData] = await Promise.all([getOrders(), getExpenses()]);
      setOrders(oData);
      setExpenses(eData);
      setLoading(false);
    };
    loadData();
  }, []);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
    const now = new Date();

    // Date Helpers
    const formatDate = (date: Date) => date.toLocaleDateString('es-MX', { day: '2-digit', month: 'short' }).toUpperCase();

    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());

    const currentDay = now.getDay(); 
    const daysToMonday = currentDay === 0 ? 6 : currentDay - 1;
    const startOfWeek = new Date(now);
    startOfWeek.setDate(now.getDate() - daysToMonday);
    startOfWeek.setHours(0,0,0,0);

    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
    const startOfYear = new Date(now.getFullYear(), 0, 1);

    // Initial Counters
    const totals = {
        today: { income: 0, expense: 0 },
        week: { income: 0, expense: 0 },
        month: { income: 0, expense: 0 },
        year: { income: 0, expense: 0 }
    };

    // 1. Process Orders (Income)
    orders.forEach(order => {
        const d = new Date(order.createdAt);
        const amount = order.status === 'refunded' ? 0 : order.total;

        // Note: For refunded orders, we technically exclude them from revenue here.
        // Refunds are tracked as lost revenue, but not expenses in this simplified model unless we want specific accounting.
        // Current model: Net Sales = Gross Sales - Refunds.

        if (order.status !== 'refunded') {
            if (d >= startOfToday) totals.today.income += amount;
            if (d >= startOfWeek) totals.week.income += amount;
            if (d >= startOfMonth) totals.month.income += amount;
            if (d >= startOfYear) totals.year.income += amount;
        }
    });

    // 2. Process Expenses
    expenses.forEach(exp => {
        const d = new Date(exp.createdAt);
        if (d >= startOfToday) totals.today.expense += exp.amount;
        if (d >= startOfWeek) totals.week.expense += exp.amount;
        if (d >= startOfMonth) totals.month.expense += exp.amount;
        if (d >= startOfYear) totals.year.expense += exp.amount;
    });

    // 3. Daily Breakdown (Last 30 days usually, but let's do All Time sorted)
    const dailyMap: Record<string, { date: string, income: number, expense: number }> = {};

    // Merge Orders
    orders.forEach(o => {
        if(o.status === 'refunded') return;
        const d = new Date(o.createdAt);
        const key = `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')}`;
        if(!dailyMap[key]) dailyMap[key] = { date: d.toLocaleDateString(), income: 0, expense: 0 };
        dailyMap[key].income += o.total;
    });

    // Merge Expenses
    expenses.forEach(e => {
        const d = new Date(e.createdAt);
        const key = `${d.getFullYear()}/${(d.getMonth()+1).toString().padStart(2,'0')}/${d.getDate().toString().padStart(2,'0')}`;
        if(!dailyMap[key]) dailyMap[key] = { date: d.toLocaleDateString(), income: 0, expense: 0 };
        dailyMap[key].expense += e.amount;
    });

    const dailyList = Object.keys(dailyMap).sort().reverse().map(k => dailyMap[k]);

    return { totals, dailyList };
  }, [orders, expenses]);

  // Visual Component
  const NetProfitCard = ({ title, income, expense }: { title: string, income: number, expense: number }) => {
      const net = income - expense;
      const isPositive = net >= 0;
      const margin = income > 0 ? ((net / income) * 100).toFixed(0) : 0;

      return (
        <div className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm flex flex-col justify-between">
            <div className="flex justify-between items-start mb-4">
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{title}</span>
                <span className={`text-[10px] font-bold px-2 py-1 rounded ${isPositive ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                    {margin}% MARGEN
                </span>
            </div>

            <div className="mb-4">
                <div className="text-3xl font-black text-slate-800 font-mono tracking-tight">
                    ${net.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                </div>
                <div className="text-xs font-bold text-slate-400 uppercase mt-1">GANANCIA NETA</div>
            </div>

            <div className="space-y-2 text-xs font-medium uppercase border-t border-slate-100 pt-3">
                <div className="flex justify-between text-emerald-600">
                    <span className="flex items-center gap-1"><ArrowUpRight className="w-3 h-3" /> INGRESOS</span>
                    <span>${income.toLocaleString(undefined, {minimumFractionDigits: 2})}</span>
                </div>
                <div className="flex justify-between text-rose-500">
                    <span className="flex items-center gap-1"><TrendingDown className="w-3 h-3" /> GASTOS</span>
                    <span>-${expense.toLocaleString(undefined, {minimumFractionDigits: 2})}</span>
                </div>
            </div>
        </div>
      );
  };

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto pb-24">
      <header className="mb-8">
        <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
          <PieChart className="w-8 h-8 text-indigo-600" />
          ESTADO FINANCIERO
        </h1>
        <p className="text-slate-500 mt-2 uppercase">ANÁLISIS DE INGRESOS MENOS GASTOS</p>
      </header>

      {/* KPI GRID */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-6 mb-8">
          <NetProfitCard title="HOY" income={stats.totals.today.income} expense={stats.totals.today.expense} />
          <NetProfitCard title="ESTA SEMANA" income={stats.totals.week.income} expense={stats.totals.week.expense} />
          <NetProfitCard title="ESTE MES" income={stats.totals.month.income} expense={stats.totals.month.expense} />
          <NetProfitCard title="ESTE AÑO" income={stats.totals.year.income} expense={stats.totals.year.expense} />
      </div>

      {/* DETAILED TABLE */}
      <Card className="overflow-hidden p-0">
          <div className="p-6 border-b border-slate-100 bg-white/50">
              <h3 className="text-lg font-bold text-slate-800 uppercase flex items-center gap-2">
                  <Activity className="w-5 h-5 text-indigo-600" />
                  BALANCE DIARIO
              </h3>
          </div>

          <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                  <thead>
                      <tr className="bg-slate-50/80 text-slate-500 text-xs uppercase font-bold tracking-wider">
                          <th className="px-6 py-4">FECHA</th>
                          <th className="px-6 py-4 text-right text-emerald-600">INGRESOS (+)</th>
                          <th className="px-6 py-4 text-right text-rose-500">GASTOS (-)</th>
                          <th className="px-6 py-4 text-right text-slate-800">UTILIDAD</th>
                          <th className="px-6 py-4 hidden md:table-cell">VISUAL</th>
                      </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                      {loading ? (
                          <tr><td colSpan={5} className="p-8 text-center text-slate-400 uppercase">CARGANDO DATOS...</td></tr>
                      ) : stats.dailyList.length === 0 ? (
                          <tr><td colSpan={5} className="p-8 text-center text-slate-400 uppercase">NO HAY REGISTROS AÚN</td></tr>
                      ) : (
                        stats.dailyList.map((day, idx) => {
                            const net = day.income - day.expense;
                            const maxVal = Math.max(day.income, day.expense);
                            const incomeWidth = maxVal > 0 ? (day.income / maxVal) * 100 : 0;
                            const expenseWidth = maxVal > 0 ? (day.expense / maxVal) * 100 : 0;

                            return (
                                <tr key={idx} className="hover:bg-slate-50 transition-colors">
                                    <td className="px-6 py-4">
                                        <div className="font-bold text-slate-700 uppercase text-sm">{day.date}</div>
                                    </td>
                                    <td className="px-6 py-4 text-right font-mono text-emerald-600 font-bold">
                                        ${day.income.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                    </td>
                                    <td className="px-6 py-4 text-right font-mono text-rose-500 font-bold">
                                        ${day.expense.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <div className={`font-black font-mono text-lg ${net >= 0 ? 'text-slate-800' : 'text-rose-600'}`}>
                                            ${net.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                        </div>
                                    </td>
                                    <td className="px-6 py-4 hidden md:table-cell w-48 align-middle">
                                        <div className="flex flex-col gap-1 w-full opacity-70">
                                            <div className="h-1.5 bg-emerald-200 rounded-full" style={{width: `${incomeWidth}%`}}></div>
                                            <div className="h-1.5 bg-rose-200 rounded-full" style={{width: `${expenseWidth}%`}}></div>
                                        </div>
                                    </td>
                                </tr>
                            );
                        })
                      )}
                  </tbody>
              </table>
          </div>
      </Card>
    </div>
  );
};

