                      {filteredExpenses.length === 0 ? (
                          <div className="p-10 text-center text-slate-400 uppercase">No hay gastos en este periodo</div>
                      ) : (
                          filteredExpenses.map(exp => (
                              <div key={exp.id} className="p-4 flex justify-between items-center hover:bg-slate-50 transition-colors">
                                  <div>
                                      <div className="font-bold text-slate-800 uppercase">{exp.concept}</div>
                                      <div className="text-xs text-slate-400 mt-1 flex items-center gap-2">
                                          <Calendar className="w-3 h-3" />
                                          {new Date(exp.createdAt).toLocaleDateString()}
                                          <span>•</span>
                                          {new Date(exp.createdAt).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                                          {exp.registeredBy && <span className="bg-slate-100 px-1 rounded text-[9px] uppercase font-bold text-slate-500">{exp.registeredBy}</span>}
                                      </div>
                                  </div>
                                  <div className="font-mono font-bold text-rose-600 text-lg">
                                      -${exp.amount.toLocaleString(undefined, {minimumFractionDigits: 2})}
                                  </div>
                              </div>
                          ))
                      )}
                  </div>
              </div>
          </div>
      )}

      {/* --- BALANCE VIEW --- */}
      {activeTab === 'balance' && (
          <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-300">
              <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                  <KPICard title="TOTAL INGRESOS" amount={stats.income.total} icon={ArrowUpRight} color="emerald" />
                  <KPICard title="TOTAL GASTOS" amount={stats.expense.total} icon={TrendingDown} color="rose" />

                  {/* NET PROFIT CARD */}
                  <div className={`p-6 rounded-3xl border-2 flex flex-col justify-between shadow-xl ${stats.net >= 0 ? 'bg-slate-900 border-slate-900 text-white' : 'bg-rose-50 border-rose-500 text-rose-900'}`}>
                      <div>
                          <p className="text-sm font-bold uppercase opacity-60 mb-2">UTILIDAD NETA (GANANCIA)</p>
                          <h3 className="text-4xl font-black font-mono tracking-tight">
                              ${stats.net.toLocaleString(undefined, {minimumFractionDigits: 2})}
                          </h3>
                      </div>
                      <div className="mt-4 pt-4 border-t border-white/20 flex justify-between items-center">
                          <span className="text-xs font-bold uppercase">MARGEN DE GANANCIA</span>
                          <span className={`px-2 py-1 rounded font-bold text-xs ${stats.net >= 0 ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                              {stats.income.total > 0 ? ((stats.net / stats.income.total) * 100).toFixed(1) : 0}%
                          </span>
                      </div>
                  </div>
              </div>

              <div className="p-8 bg-slate-50 rounded-3xl border border-dashed border-slate-300 text-center">
                  <p className="text-slate-400 uppercase text-sm font-bold">
                      EL BALANCE MUESTRA: (VENTAS + RENTAS COBRADAS) - (GASTOS REGISTRADOS)
                  </p>
                  <p className="text-slate-400 text-xs mt-1">
                      * No incluye tickets reembolsados.
                  </p>
              </div>
          </div>
      )}

    </div>
  );
};

