const Reports: React.FC = () => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState<'income' | 'expenses' | 'balance'>('income');
  const [timeFilter, setTimeFilter] = useState<'today' | 'week' | 'month' | 'year'>('today');

  useEffect(() => {
    const loadData = async () => {
      setLoading(true);
      const [oData, eData] = await Promise.all([getOrders(), getExpenses()]);
      setOrders(oData);
      setExpenses(eData);
      setLoading(false);
    };
    loadData();
  }, []);

  // --- Filter Logic ---
  const { filteredOrders, filteredExpenses } = useMemo(() => {
    const now = new Date();

    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime();

    const currentDay = now.getDay(); 
    const daysToMonday = currentDay === 0 ? 6 : currentDay - 1;
    const startOfWeekDate = new Date(now);
    startOfWeekDate.setDate(now.getDate() - daysToMonday);
    startOfWeekDate.setHours(0,0,0,0);
    const startOfWeek = startOfWeekDate.getTime();

    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
    const startOfYear = new Date(now.getFullYear(), 0, 1).getTime();

    const filterDate = (timestamp: number) => {
        if (timeFilter === 'today') return timestamp >= startOfToday;
        if (timeFilter === 'week') return timestamp >= startOfWeek;
        if (timeFilter === 'month') return timestamp >= startOfMonth;
        if (timeFilter === 'year') return timestamp >= startOfYear;
        return true;
    };

    return {
        filteredOrders: orders.filter(o => filterDate(o.createdAt) && o.status !== 'refunded'),
        filteredExpenses: expenses.filter(e => filterDate(e.createdAt))
    };
  }, [orders, expenses, timeFilter]);

  // --- Statistics Calculation ---
  const stats = useMemo(() => {
    // 1. Income Analysis
    let totalIncome = 0;
    let incomeCash = 0;
    let incomeCard = 0;
    let incomeTransfer = 0;

    // Category Breakdown
    const categoryMap: Record<string, number> = {};
    // Transaction Type Breakdown
    let totalRentals = 0;
    let totalSales = 0;

    filteredOrders.forEach(order => {
        totalIncome += order.total;

        // Payment Methods
        if (order.paymentMethod === 'cash') incomeCash += order.total;
        else if (order.paymentMethod === 'card') incomeCard += order.total;
        else if (order.paymentMethod === 'transfer') incomeTransfer += order.total;

        // Items Analysis
        order.items.forEach(item => {
            const itemTotal = item.appliedPrice * item.quantity;

            // By Category
            const cat = item.category || 'OTROS';
            categoryMap[cat] = (categoryMap[cat] || 0) + itemTotal;

            // By Type
            if (item.transactionType === 'rent') totalRentals += itemTotal;
            else totalSales += itemTotal;
        });
    });

    // 2. Expense Analysis
    let totalExpenses = 0;
    filteredExpenses.forEach(e => totalExpenses += e.amount);

    return {
        income: {
            total: totalIncome,
            cash: incomeCash,
            card: incomeCard,
            transfer: incomeTransfer,
            rentals: totalRentals,
            sales: totalSales,
            categories: Object.entries(categoryMap).sort((a,b) => b[1] - a[1]) // Sort highest first
        },
        expense: {
            total: totalExpenses
        },
        net: totalIncome - totalExpenses
    };
  }, [filteredOrders, filteredExpenses]);

  // --- Components ---

  const KPICard = ({ title, amount, icon: Icon, color, subtext }: any) => (
      <div className={`p-5 rounded-3xl border flex items-center justify-between ${color === 'indigo' ? 'bg-indigo-50 border-indigo-100 text-indigo-900' : (color === 'emerald' ? 'bg-emerald-50 border-emerald-100 text-emerald-900' : (color === 'rose' ? 'bg-rose-50 border-rose-100 text-rose-900' : 'bg-white border-slate-100 text-slate-800'))}`}>
          <div>
              <p className="text-xs font-bold uppercase opacity-60 mb-1">{title}</p>
              <h3 className="text-2xl font-black font-mono">${amount.toLocaleString(undefined, {minimumFractionDigits: 2})}</h3>
              {subtext && <p className="text-[10px] font-bold mt-1 opacity-70">{subtext}</p>}
          </div>
          <div className={`p-3 rounded-2xl ${color === 'indigo' ? 'bg-indigo-200 text-indigo-700' : (color === 'emerald' ? 'bg-emerald-200 text-emerald-700' : (color === 'rose' ? 'bg-rose-200 text-rose-700' : 'bg-slate-100 text-slate-500'))}`}>
              <Icon className="w-6 h-6" />
          </div>
      </div>
  );

  const handlePrint = () => {
    window.print();
  };

  return (
