                    </div>

                    <div className="flex gap-8">
                        {/* INCOME SIDE */}
                        <div className="flex-1">
                             <h3 className="font-bold border-b-2 border-slate-900 pb-2 mb-2 uppercase text-sm">INGRESOS DETALLADOS</h3>
