      </div>
  );

  const PaginationControls = ({ current, total, onPageChange }: any) => {
      if (total <= 1) return null;
      return (
          <div className="flex justify-center items-center gap-4 mt-4">
              <button 
                onClick={() => onPageChange(Math.max(1, current - 1))}
