                    <button 
                    key={f}
                    onClick={() => setTimeFilter(f as any)}
                    className={`px-4 py-2 rounded-xl text-xs font-bold uppercase transition-all ${timeFilter === f ? 'bg-slate-800 text-white shadow-md' : 'text-slate-500 hover:bg-slate-50'}`}
                    >
