  const handleSettleDebt = async () => {
      if (!selectedCustomer || !selectedCustomer.id) return;
      if (!selectedCustomer.balance || selectedCustomer.balance >= 0) return;

      // Allow settle debt for everyone? Or just admin? Usually cashiers settle debt when getting paid. 
      // Let's assume cashiers can settle debt (accept payment).

      if (confirm(`¿Confirmar que ${selectedCustomer.name} ha liquidado su deuda de $${Math.abs(selectedCustomer.balance).toFixed(2)}?`)) {
          await updateCustomer(selectedCustomer.id, { balance: 0 });
