            <div className="pt-2">
                <Button variant="ghost" onClick={() => setSelectionProduct(null)} className="w-full uppercase">CANCELAR</Button>
            </div>
        </div>
      </Modal>

      {/* Custom Price Modal */}
      {customPriceModal && (
         <div className="fixed inset-0 z-[80] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md animate-in fade-in">
             <div className="bg-white rounded-3xl shadow-2xl w-full max-w-sm overflow-hidden flex flex-col">
                 <div className="p-6 pb-2 text-center">
                    <h3 className="text-lg font-bold text-slate-500 uppercase tracking-wide">INGRESAR PRECIO</h3>
                    <p className="text-slate-400 text-sm mb-4">{customPriceModal.product.name} {customPriceModal.variation ? `(${typeof customPriceModal.variation === 'string' ? customPriceModal.variation : customPriceModal.variation.name})` : ''}</p>
                    <div className="text-5xl font-bold text-indigo-600 mb-2 font-mono h-14">
                        ${customPriceValue || '0'}
                    </div>
                 </div>

                 <div className="p-4 grid grid-cols-3 gap-3">
