                 </div>

                 <div className="p-4 pt-0 grid grid-cols-2 gap-3">
                     <Button variant="secondary" onClick={() => setCustomPriceModal(null)} className="h-14 text-lg uppercase">CANCELAR</Button>
                     <Button onClick={handleCustomPriceSubmit} className="h-14 text-lg uppercase">ACEPTAR</Button>
