  // --- User Management Handlers ---

  const openNewUserModal = () => {
      setEditingUser(null);
      setUserName('');
      setUserCode('');
      setUserPermissions(defaultPermissions);
      setShowUserModal(true);
  };

  const openEditUserModal = (user: User) => {
      setEditingUser(user);
      setUserName(user.name);
      setUserCode(user.code);
      setUserPermissions({ ...defaultPermissions, ...(user.permissions || {}) });
      setShowUserModal(true);
  };

  const handleUserSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userName || userCode.length !== 4) {
      alert("NOMBRE REQUERIDO Y EL CÓDIGO DEBE SER DE 4 DÍGITOS.");
      return;
    }

    try {
      const userData = { 
          name: userName, 
          code: userCode,
          permissions: userPermissions,
          role: 'staff' as const // Default to staff, logic relies on permissions now
      };

      if (editingUser && editingUser.id) {
          await updateUser(editingUser.id, userData);
          alert("USUARIO ACTUALIZADO.");
      } else {
          await addUser(userData);
          alert("USUARIO REGISTRADO.");
      }

      setShowUserModal(false);
      loadData();
    } catch (e) {
      alert("ERROR AL GUARDAR.");
    }
  };

  const handleDeleteUser = async (id: string) => {
    if (confirm("¿ELIMINAR ACCESO DE USUARIO?")) {
      await deleteUser(id);
