          setShowDeleteModal(false);
          setDeletePin('');
          loadData();
      } catch (e) {
          console.error(e);
          alert("ERROR AL ELIMINAR. REVISE LA CONSOLA.");
      } finally {
          setIsDeleting(false);
      }
  };

  // Helper for Permission Switch
  const PermissionSwitch = ({ label, pKey }: { label: string, pKey: keyof UserPermissions }) => (
      <div 
        onClick={() => togglePermission(pKey)}
