                </div>
                <div className="text-right">
                    <div className="text-xl font-bold uppercase">CyC POS 26</div>
                    <div className="text-xs text-slate-400 mt-1">Generado: {currentDate}</div>
                </div>
            </div>

            <table className="w-full text-left text-xs">
                <thead>
                    <tr className="border-b-2 border-slate-300 uppercase text-slate-500 font-bold">
                        <th className="py-2 w-1/4">CLIENTE / CONTACTO</th>
                        <th className="py-2 w-1/2">DETALLE DE SITUACIÓN</th>
                        <th className="py-2 w-1/4 text-right">SALDO PENDIENTE</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-200">
                    {reportData.length === 0 ? (
                        <tr><td colSpan={3} className="py-8 text-center text-slate-400 italic">NO HAY CLIENTES CON ADEUDOS O RENTAS ACTIVAS AL MOMENTO.</td></tr>
                    ) : (
                        reportData.map((data, idx) => (
                            <tr key={idx} className="break-inside-avoid">
                                <td className="py-3 align-top pr-2">
                                    <div className="font-bold text-sm uppercase">{data.name}</div>
                                    <div className="text-slate-500 mt-1 flex items-center gap-1"><Phone className="w-3 h-3"/> {data.phone}</div>
                                    {data.address && <div className="text-slate-400 mt-0.5 text-[10px] uppercase max-w-[200px]">{data.address}</div>}
                                </td>
                                <td className="py-3 align-top pr-2">
                                    {data.activeRentals.length > 0 ? (
                                        <div className="space-y-2">
                                            {data.activeRentals.map(order => {
                                                const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;
                                                return (
                                                    <div key={order.id} className="bg-slate-50 p-2 rounded border border-slate-100">
                                                        <div className="flex justify-between font-bold text-[10px] mb-1">
                                                            <span>TICKET #{order.id?.slice(-4)}</span>
                                                            <span className={isLate ? 'text-rose-600' : 'text-slate-600'}>
                                                                {isLate ? '¡VENCIDO!' : 'ENTREGA:'} {new Date(order.rentalEndDate || 0).toLocaleDateString()}
                                                            </span>
                                                        </div>
                                                        <ul className="list-disc list-inside text-[10px] text-slate-600 uppercase">
                                                            {order.items.filter(i => i.transactionType === 'rent').map((item, i) => (
                                                                <li key={i}>{item.quantity} {item.name}</li>
                                                            ))}
                                                        </ul>
                                                    </div>
                                                );
                                            })}
                                        </div>
                                    ) : (
                                        <span className="text-slate-400 italic text-[10px]">SIN RENTAS ACTIVAS</span>
                                    )}
                                </td>
                                <td className="py-3 align-top text-right">
                                    {data.balance && data.balance < 0 ? (
                                        <div className="font-mono font-bold text-lg text-rose-600">
                                            ${Math.abs(data.balance).toFixed(2)}
                                        </div>
                                    ) : (
                                        <div className="text-slate-300 font-bold">--</div>
                                    )}
                                    <div className="text-[9px] font-bold text-slate-400 uppercase mt-1">DEUDA TOTAL</div>
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>

            <div className="mt-8 pt-4 border-t border-slate-300 flex justify-between text-[10px] font-bold uppercase text-slate-400">
                <span>TOTAL CLIENTES EN LISTA: {reportData.length}</span>
                <span>SUMA TOTAL DEUDA: ${Math.abs(reportData.reduce((acc, curr) => acc + (curr.balance && curr.balance < 0 ? curr.balance : 0), 0)).toLocaleString()}</span>
            </div>
        </div>
    );
};

const Customers: React.FC<{ user: User }> = ({ user }) => {
  const navigate = useNavigate();
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterMode, setFilterMode] = useState<'all' | 'attention'>('all');

  const canDeleteCustomers = user.role === 'admin' || user.permissions?.canDeleteCustomers;

  // Create/Edit Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newAddress, setNewAddress] = useState('');

  // History Modal State
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [customerOrders, setCustomerOrders] = useState<Order[]>([]);
  const [historyTab, setHistoryTab] = useState<'active' | 'all'>('active');

  const loadData = async () => {
    setLoading(true);
    const [cData, oData] = await Promise.all([getCustomers(), getOrders()]);
    setCustomers(cData);
    setOrders(oData);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  // --- Helpers ---
  const hasActiveRental = (customerId: string) => {
      return orders.some(o => 
        o.customer?.id === customerId && 
        o.items.some(i => i.transactionType === 'rent') &&
        !o.status.includes('returned')
      );
  };

  const handlePrintReport = () => {
      window.print();
  };

  // --- CRUD Handlers ---

  const handleNewCustomerClick = () => {
      setEditingId(null);
      setNewName('');
      setNewPhone('');
      setNewAddress('');
      setIsModalOpen(true);
  };

  const handleEditClick = (e: React.MouseEvent, customer: Customer) => {
      e.stopPropagation();
      setEditingId(customer.id || null);
      setNewName(customer.name);
      setNewPhone(customer.phone);
      setNewAddress(customer.address || '');
      setIsModalOpen(true);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName) return;

    try {
        const customerData = {
            name: newName,
            phone: newPhone,
            address: newAddress
        };

        if (editingId) {
            await updateCustomer(editingId, customerData);
        } else {
            await addCustomer(customerData);
        }

        setNewName('');
        setNewPhone('');
        setNewAddress('');
        setIsModalOpen(false);
        setEditingId(null);
        loadData();
    } catch (error) {
        alert('Error al guardar cliente');
    }
  };

  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
      e.stopPropagation(); 
      if (!canDeleteCustomers) return;
      if(window.confirm('¿Eliminar cliente permanentemente?')) {
         await performDelete(id);
      }
  };

  const performDelete = async (id: string) => {
      try {
          await deleteCustomer(id);
          setCustomers(prev => prev.filter(c => c.id !== id));
      } catch (error) {
          alert("No se pudo eliminar el cliente.");
          loadData();
      }
  }

  // --- History & Balance Handlers ---

  const handleViewHistory = async (customer: Customer) => {
      setSelectedCustomer(customer);
      setIsHistoryOpen(true);
      const userOrders = orders.filter(o => o.customer?.id === customer.id);
      setCustomerOrders(userOrders);
      // Default to active rentals if any, otherwise all
      const hasActive = userOrders.some(o => o.items.some(i => i.transactionType === 'rent') && !o.status.includes('returned'));
      setHistoryTab(hasActive ? 'active' : 'all');
  };

  const handleSettleDebt = async () => {
      if (!selectedCustomer || !selectedCustomer.id) return;
      if (!selectedCustomer.balance || selectedCustomer.balance >= 0) return;

      // Send to POS to create a ticket for the debt
      navigate('/', { 
          state: { 
              action: 'settle_debt', 
              customer: selectedCustomer
          } 
      });
  };

  const filtered = customers.filter(c => {
      const matchesSearch = c.name.toLowerCase().includes(searchQuery.toLowerCase()) || c.phone.includes(searchQuery);

      if (filterMode === 'attention') {
          const isDebtor = (c.balance || 0) < 0;
          const isActive = c.id ? hasActiveRental(c.id) : false;
          return matchesSearch && (isDebtor || isActive);
      }

      return matchesSearch;
  });

  // Filter orders for the active tab inside modal
  const displayedOrders = customerOrders.filter(order => {
      if (historyTab === 'all') return true;
      // Active = Contains rentals that are NOT returned
      const hasRentals = order.items.some(i => i.transactionType === 'rent');
      const isClosed = order.status === 'returned' || order.status === 'returned_late';
      return hasRentals && !isClosed;
  });

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto h-full flex flex-col">
      {/* Hidden Component for Printing */}
      <PrintableDebtorsReport customers={customers} orders={orders} />

      <header className="mb-8 flex justify-between items-end flex-shrink-0">
        <div>
           <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
            <Users className="w-8 h-8 text-indigo-600" />
            CLIENTES
           </h1>
           <p className="text-slate-500 mt-2 uppercase">DIRECTORIO Y ALTA DE CLIENTES</p>
        </div>

        <div className="flex gap-2 items-center">
            <Button onClick={handlePrintReport} variant="secondary" className="shadow-sm border-slate-300 hidden sm:flex">
                <Printer className="w-5 h-5" /> <span className="hidden lg:inline">IMPRIMIR ADEUDOS</span>
            </Button>
            <Button onClick={handleNewCustomerClick} className="shadow-xl shadow-indigo-200 uppercase">
                <Plus className="w-5 h-5" /> <span className="hidden sm:inline">NUEVO CLIENTE</span>
                <span className="sm:hidden">NUEVO</span>
            </Button>
        </div>
      </header>

      {/* Main List Area */}
      <div className="flex-1 flex flex-col overflow-hidden">
             <div className="flex gap-4 mb-6 flex-shrink-0">
                 <div className="relative flex-1">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                    <input 
                        type="text" 
                        placeholder="BUSCAR CLIENTE POR NOMBRE O TELÉFONO..." 
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                        className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase placeholder:normal-case"
                    />
                </div>

                {/* Attention Filter Toggle */}
                <button 
                    onClick={() => setFilterMode(prev => prev === 'all' ? 'attention' : 'all')}
                    className={`px-4 rounded-2xl border flex items-center gap-2 font-bold uppercase transition-all ${filterMode === 'attention' ? 'bg-amber-100 border-amber-300 text-amber-800 shadow-sm' : 'bg-white border-slate-200 text-slate-500 hover:bg-slate-50'}`}
                >
                    <AlertCircle className={`w-5 h-5 ${filterMode === 'attention' ? 'fill-current' : ''}`} />
                    <span className="hidden sm:inline">⚠️ ATENCIÓN REQUERIDA</span>
                    <span className="sm:hidden">FILTRAR</span>
                </button>

                {/* Mobile Print Button */}
                <button 
                    onClick={handlePrintReport}
                    className="sm:hidden px-4 rounded-2xl border border-slate-200 bg-white text-slate-500 hover:bg-slate-50 flex items-center justify-center"
                >
                    <Printer className="w-5 h-5" />
                </button>
             </div>

            {/* TABLE VIEW */}
            <div className="flex-1 overflow-hidden bg-white rounded-3xl border border-slate-200 shadow-sm flex flex-col">
                <div className="overflow-x-auto flex-1">
                    <table className="w-full text-left border-collapse">
                        <thead className="bg-slate-50 text-slate-500 uppercase font-bold text-xs sticky top-0 z-10 shadow-sm">
                            <tr>
                                <th className="px-6 py-4">Estado</th>
                                <th className="px-6 py-4">Nombre</th>
                                <th className="px-6 py-4">Teléfono</th>
                                <th className="px-6 py-4">Dirección</th>
                                <th className="px-6 py-4 text-center">Rentas Activas</th>
                                <th className="px-6 py-4 text-right">Saldo</th>
                                <th className="px-6 py-4 text-center">Acciones</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-100 text-sm">
                            {loading ? (
                                <tr>
                                    <td colSpan={7} className="p-10 text-center text-slate-400">CARGANDO...</td>
                                </tr>
                            ) : filtered.length === 0 ? (
                                <tr>
                                    <td colSpan={7} className="p-20 text-center text-slate-400 flex flex-col items-center justify-center">
                                        <Users className="w-12 h-12 mb-2 opacity-20" />
                                        <span className="uppercase">NO SE ENCONTRARON CLIENTES</span>
                                    </td>
                                </tr>
                            ) : (
                                filtered.map(customer => {
                                    const isActiveRenter = customer.id && hasActiveRental(customer.id);
                                    const hasDebt = customer.balance && customer.balance < 0;
                                    const hasCredit = customer.balance && customer.balance > 0;

                                    return (
                                        <tr 
                                            key={customer.id} 
                                            onClick={() => handleViewHistory(customer)}
                                            className="hover:bg-indigo-50/50 transition-colors cursor-pointer group"
                                        >
                                            <td className="px-6 py-4">
                                                <div className="flex gap-1">
                                                    {hasDebt && (
                                                        <span className="bg-rose-100 text-rose-600 p-1.5 rounded-lg border border-rose-200" title="Tiene Deuda">
                                                            <AlertCircle className="w-4 h-4" />
                                                        </span>
                                                    )}
                                                    {isActiveRenter && (
                                                        <span className="bg-indigo-100 text-indigo-600 p-1.5 rounded-lg border border-indigo-200" title="Renta Activa">
                                                            <Clock className="w-4 h-4" />
                                                        </span>
                                                    )}
                                                    {!hasDebt && !isActiveRenter && (
                                                        <span className="bg-slate-100 text-slate-400 p-1.5 rounded-lg">
                                                            <CheckCircle className="w-4 h-4" />
                                                        </span>
                                                    )}
                                                </div>
                                            </td>
                                            <td className="px-6 py-4 font-bold text-slate-800 uppercase text-base">
                                                {customer.name}
                                            </td>
                                            <td className="px-6 py-4 font-medium text-slate-600">
                                                {customer.phone || '-'}
                                            </td>
                                            <td className="px-6 py-4 text-slate-500 uppercase text-xs max-w-xs truncate" title={customer.address}>
                                                {customer.address || '-'}
                                            </td>
                                            <td className="px-6 py-4 text-center">
                                                {isActiveRenter ? (
                                                    <span className="inline-block w-3 h-3 bg-indigo-500 rounded-full animate-pulse"></span>
                                                ) : (
                                                    <span className="text-slate-300">-</span>
                                                )}
                                            </td>
                                            <td className="px-6 py-4 text-right font-mono text-base">
                                                {hasDebt ? (
                                                    <span className="text-rose-600 font-bold bg-rose-50 px-2 py-1 rounded">
                                                        ${customer.balance?.toFixed(2)}
                                                    </span>
                                                ) : hasCredit ? (
                                                    <span className="text-emerald-600 font-bold bg-emerald-50 px-2 py-1 rounded">
                                                        +${customer.balance?.toFixed(2)}
                                                    </span>
                                                ) : (
                                                    <span className="text-slate-400">$0.00</span>
                                                )}
                                            </td>
                                            <td className="px-6 py-4">
                                                <div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button 
                                                        onClick={(e) => { e.stopPropagation(); handleViewHistory(customer); }}
                                                        className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-indigo-50 hover:text-indigo-600 hover:border-indigo-200 transition-all shadow-sm"
                                                        title="Ver Historial"
                                                    >
                                                        <History className="w-4 h-4" />
                                                    </button>
                                                    <button 
                                                        onClick={(e) => handleEditClick(e, customer)}
                                                        className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 hover:text-slate-800 transition-all shadow-sm"
                                                        title="Editar"
                                                    >
                                                        <Pencil className="w-4 h-4" />
                                                    </button>
                                                    {canDeleteCustomers && (
                                                        <button 
                                                            onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                                            className="p-2 bg-white border border-slate-200 rounded-lg hover:bg-rose-50 hover:text-rose-600 hover:border-rose-200 transition-all shadow-sm"
                                                            title="Eliminar"
                                                        >
                                                            <Trash2 className="w-4 h-4" />
                                                        </button>
                                                    )}
                                                </div>
                                            </td>
                                        </tr>
                                    );
                                })
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
      </div>

      {/* CREATE/EDIT MODAL */}
      <Modal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        title={editingId ? 'EDITAR CLIENTE' : 'REGISTRAR NUEVO CLIENTE'}
      >
        <form onSubmit={handleSubmit} className="space-y-6 pt-2">
            <div className="space-y-4">
                <Input 
                    label="NOMBRE COMPLETO" 
                    placeholder="EJ. JUAN PÉREZ" 
                    value={newName}
                    onChange={(e) => setNewName(e.target.value.toUpperCase())}
                    autoFocus
                />
                <Input 
                    label="TELÉFONO" 
                    placeholder="EJ. 55 1234 5678" 
                    value={newPhone}
                    onChange={(e) => {
                        const val = e.target.value.replace(/\D/g, '');
                        if (val.length <= 10) setNewPhone(val);
                    }}
                    type="tel"
                    maxLength={10}
                />
                 <Input 
                    label="DIRECCIÓN" 
                    placeholder="CALLE, NÚMERO, COLONIA..." 
                    value={newAddress}
                    onChange={(e) => setNewAddress(e.target.value.toUpperCase())}
                />
            </div>

            <div className="pt-6 flex gap-3">
                <Button type="button" variant="secondary" onClick={() => setIsModalOpen(false)} className="flex-1 uppercase">
                    CANCELAR
                </Button>
                <Button type="submit" className="flex-[2] uppercase">
                    {editingId ? 'GUARDAR CAMBIOS' : 'REGISTRAR CLIENTE'}
                </Button>
            </div>
        </form>
      </Modal>

      {/* HISTORY MODAL */}
      {selectedCustomer && (
        <Modal 
            isOpen={isHistoryOpen} 
            onClose={() => setIsHistoryOpen(false)} 
            title={`HISTORIAL: ${selectedCustomer.name}`}
        >
            <div className="space-y-6">

                {/* Balance Card */}
                <div className={`p-4 rounded-2xl border flex justify-between items-center ${selectedCustomer.balance && selectedCustomer.balance < 0 ? 'bg-rose-50 border-rose-100' : 'bg-slate-50 border-slate-100'}`}>
                    <div>
                        <div className="text-xs font-bold uppercase tracking-wider opacity-60 flex items-center gap-1">
                            <Wallet className="w-4 h-4" /> SALDO ACTUAL
                        </div>
                        <div className={`text-3xl font-bold font-mono ${selectedCustomer.balance && selectedCustomer.balance < 0 ? 'text-rose-600' : 'text-slate-800'}`}>
                            ${(selectedCustomer.balance || 0).toFixed(2)}
                        </div>
                    </div>
                    {selectedCustomer.balance && selectedCustomer.balance < 0 && (
                        <Button onClick={handleSettleDebt} className="uppercase text-xs px-4 shadow-lg shadow-rose-100 bg-rose-600 hover:bg-rose-700">
                            <ShoppingCart className="w-4 h-4" /> COBRAR DEUDA
                        </Button>
                    )}
                </div>

                {/* Tabs */}
                <div className="flex bg-slate-100 p-1 rounded-xl">
                    <button 
                        onClick={() => setHistoryTab('active')}
                        className={`flex-1 py-2 text-xs font-bold uppercase rounded-lg transition-all ${historyTab === 'active' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                    >
                        RENTAS ACTIVAS
                    </button>
                    <button 
                        onClick={() => setHistoryTab('all')}
                        className={`flex-1 py-2 text-xs font-bold uppercase rounded-lg transition-all ${historyTab === 'all' ? 'bg-white shadow-sm text-indigo-600' : 'text-slate-500'}`}
                    >
                        TODO EL HISTORIAL
                    </button>
                </div>

                {/* List */}
                <div className="max-h-[50vh] overflow-y-auto space-y-3">
                    {displayedOrders.length === 0 ? (
                        <div className="text-center py-10 text-slate-400 text-sm uppercase">
                            NO HAY MOVIMIENTOS {historyTab === 'active' ? 'ACTIVOS' : 'REGISTRADOS'}
                        </div>
                    ) : (
                        displayedOrders.map(order => {
                            // Check if late actively
                            const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate && !order.status.includes('returned');
                            // Check if has Late Fee charged history
                            const hasLateFee = order.lateFee && order.lateFee > 0;

                            return (
                                <div key={order.id} className={`p-4 rounded-xl border relative ${isLate || hasLateFee ? 'bg-rose-50/50 border-rose-200' : 'bg-white border-slate-100'}`}>
                                    <div className="flex justify-between items-start mb-2">
                                        <div className="flex items-center gap-2">
                                            <Badge color={order.items.some(i => i.transactionType === 'rent') ? 'indigo' : 'green'}>
                                                {order.items.some(i => i.transactionType === 'rent') ? 'RENTA' : 'VENTA'}
                                            </Badge>
                                            <span className="text-xs font-mono text-slate-400">#{order.id?.slice(-4)}</span>
                                        </div>
                                        <div className="font-bold text-slate-800">${order.total.toFixed(2)}</div>
                                    </div>

                                    <div className="text-xs text-slate-500 mb-2">
                                        {new Date(order.createdAt).toLocaleDateString()}
                                    </div>

                                    {/* Active Rental Warnings */}
                                    {order.rentalEndDate && !order.status.includes('returned') && (
                                        <div className={`text-xs font-bold uppercase flex items-center gap-1 mt-2 p-2 rounded-lg ${isLate ? 'text-rose-600 bg-rose-100' : 'text-indigo-600 bg-indigo-50'}`}>
                                            <Clock className="w-3 h-3" />
                                            {isLate ? 'ATRASADO - ' : 'ENTREGAR EL: '}
                                            {new Date(order.rentalEndDate).toLocaleDateString()}
                                        </div>
                                    )}

                                    {/* Late Fee Indicator (History of Debt Source) */}
                                    {hasLateFee && (
                                        <div className="text-xs font-bold uppercase flex items-center gap-1 mt-2 p-2 rounded-lg text-rose-700 bg-rose-100 border border-rose-200">
                                            <AlertCircle className="w-3 h-3" />
                                            MULTA APLICADA: ${order.lateFee?.toFixed(2)}
                                        </div>
                                    )}

                                    {/* Items Preview */}
                                    <div className="mt-2 space-y-1">
                                        {order.items.map((item, i) => (
                                            <div key={i} className="text-xs text-slate-600 flex justify-between">
                                                <span className="uppercase">{item.quantity} x {item.name}</span>
                                                {item.transactionType === 'rent' && <span className="font-bold text-indigo-400">R</span>}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            );
                        })
                    )}
                </div>

            </div>
        </Modal>
      )}

    </div>
  );
};

export default Customers;

import React, { useState, useEffect, useMemo } from 'react';
import { Users, Search, Phone, MapPin, Plus, Trash2, Pencil, UserPlus, Map as MapIcon, History, Wallet, AlertCircle, CheckCircle, Clock, Receipt, ArrowUpRight, ArrowDownLeft, Filter, ShoppingCart, Printer, FileText, ChevronRight } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Button, Input, Card, Modal, Badge } from '../components/UI';
import { Customer, Order, User } from '../types';
import { getCustomers, addCustomer, deleteCustomer, updateCustomer, getOrders } from '../services/dataService';

// --- PRINTABLE REPORT COMPONENT ---
const PrintableDebtorsReport: React.FC<{ customers: Customer[], orders: Order[] }> = ({ customers, orders }) => {
    const currentDate = new Date().toLocaleDateString('es-MX', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });

    // Filter Logic: Get only relevant customers
    const reportData = useMemo(() => {
        return customers.filter(c => {
            const hasDebt = (c.balance || 0) < 0;
            const hasRental = orders.some(o => 
                o.customer?.id === c.id && 
                o.items.some(i => i.transactionType === 'rent') &&
                !o.status.includes('returned')
            );
            return hasDebt || hasRental;
        }).map(c => {
            // Get Active Rentals Detail
            const activeRentals = orders.filter(o => 
                o.customer?.id === c.id && 
                o.items.some(i => i.transactionType === 'rent') &&
                !o.status.includes('returned')
            );
            return { ...c, activeRentals };
        });
    }, [customers, orders]);

    return (
        <div className="hidden print:block fixed inset-0 bg-white z-[9999] p-8 font-sans text-slate-900 overflow-y-auto">
            <style>
                {`@media print { @page { size: auto; margin: 10mm; } body { margin: 0; } }`}
