import React, { useState, useEffect, useMemo } from 'react';
import { Search, UserPlus, Phone, MapPin, History, Pencil, Trash2, Users, Receipt } from 'lucide-react';
import { Button, Input, Modal } from '../components/UI';
import { Customer, User, Order } from '../types';
import { getCustomers, addCustomer, updateCustomer, deleteCustomer, getOrders } from '../services/dataService';

const Customers: React.FC<{ user: User }> = ({ user }) => {
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  // Modal States
  const [showFormModal, setShowFormModal] = useState(false);
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);

  // Form State
  const [formData, setFormData] = useState<Partial<Customer>>({
    name: '',
    phone: '',
    address: ''
  });

  const canDeleteCustomers = user.role === 'admin' || user.permissions?.canDeleteCustomers;

  const loadData = async () => {
    setLoading(true);
    const [c, o] = await Promise.all([getCustomers(), getOrders()]);
    setCustomers(c);
    setOrders(o);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const filteredCustomers = useMemo(() => {
    return customers.filter(c => 
      c.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      c.phone.includes(searchQuery)
    );
  }, [customers, searchQuery]);

  // Handlers
  const handleEditClick = (e: React.MouseEvent, customer: Customer) => {
    e.stopPropagation();
    setSelectedCustomer(customer);
    setFormData({ ...customer });
    setShowFormModal(true);
  };

  const handleNewClick = () => {
    setSelectedCustomer(null);
    setFormData({ name: '', phone: '', address: '' });
    setShowFormModal(true);
  };

  const handleViewHistory = (customer: Customer) => {
    setSelectedCustomer(customer);
    setShowHistoryModal(true);
  };

  const handleDeleteFromList = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm('¿Estás seguro de eliminar este cliente?')) {
        await deleteCustomer(id);
        loadData();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;

    try {
        if (selectedCustomer && selectedCustomer.id) {
            await updateCustomer(selectedCustomer.id, formData);
        } else {
            await addCustomer(formData as Customer);
        }
        setShowFormModal(false);
        loadData();
    } catch (e) {
        console.error(e);
        alert('Error al guardar cliente');
    }
  };

  // Get history for selected customer
  const customerHistory = useMemo(() => {
      if (!selectedCustomer) return [];
      return orders.filter(o => o.customer?.id === selectedCustomer.id);
  }, [selectedCustomer, orders]);

  return (
    <div className="p-4 md:p-8 max-w-7xl mx-auto h-full flex flex-col">
      <header className="mb-6 flex justify-between items-center">
        <div>
            <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-3 uppercase">
                <Users className="w-8 h-8 text-indigo-600" />
                CLIENTES
            </h1>
            <p className="text-slate-500 mt-1 text-sm uppercase">DIRECTORIO Y CRÉDITO</p>
        </div>
        <Button onClick={handleNewClick} className="shadow-lg shadow-indigo-200 uppercase">
            <UserPlus className="w-5 h-5" /> NUEVO
        </Button>
      </header>

      {/* Search */}
      <div className="relative mb-6">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input 
              type="text" 
              placeholder="BUSCAR POR NOMBRE O TELÉFONO..." 
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
              className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white border border-slate-200 shadow-sm focus:ring-2 focus:ring-indigo-500/20 outline-none transition-all uppercase"
          />
      </div>

      {/* List */}
      <div className="flex-1 overflow-hidden bg-white rounded-3xl border border-slate-200 shadow-sm flex flex-col">
        <div className="overflow-x-auto">
            <table className="w-full text-left">
                <thead className="bg-slate-50 text-slate-500 uppercase font-bold text-xs">
                    <tr>
                        <th className="px-6 py-4">NOMBRE</th>
                        <th className="px-6 py-4">CONTACTO</th>
                        <th className="px-6 py-4">DIRECCIÓN</th>
                        <th className="px-6 py-4 text-center">BALANCE</th>
                        <th className="px-6 py-4 text-center">ACCIONES</th>
                    </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                    {loading ? (
                        <tr><td colSpan={5} className="p-8 text-center text-slate-400">CARGANDO...</td></tr>
                    ) : filteredCustomers.length === 0 ? (
                        <tr><td colSpan={5} className="p-8 text-center text-slate-400">NO SE ENCONTRARON CLIENTES</td></tr>
                    ) : (
                        filteredCustomers.map(customer => (
                            <tr key={customer.id} className="hover:bg-slate-50 transition-colors">
                                <td className="px-6 py-4 font-bold text-slate-800 uppercase">{customer.name}</td>
                                <td className="px-6 py-4 font-mono text-slate-500">{customer.phone}</td>
                                <td className="px-6 py-4 text-slate-500 uppercase max-w-xs truncate">{customer.address || '-'}</td>
                                <td className="px-6 py-4 text-center">
                                    {customer.balance && customer.balance !== 0 ? (
                                        <span className={`px-2 py-1 rounded text-xs font-bold ${customer.balance < 0 ? 'bg-rose-100 text-rose-700' : 'bg-emerald-100 text-emerald-700'}`}>
                                            {customer.balance < 0 ? `DEUDA: $${Math.abs(customer.balance).toFixed(2)}` : `CRÉDITO: $${customer.balance.toFixed(2)}`}
                                        </span>
                                    ) : (
                                        <span className="text-slate-300">-</span>
                                    )}
                                </td>
                                <td className="px-6 py-4">
                                    <div className="flex items-center justify-center gap-2">
                                        <button 
                                            onClick={(e) => { e.stopPropagation(); handleViewHistory(customer); }}
                                            className="p-2 bg-indigo-50 border border-indigo-200 text-indigo-600 rounded-lg hover:bg-indigo-100 transition-all shadow-sm"
                                            title="Ver Historial"
                                        >
                                            <History className="w-4 h-4" />
                                        </button>
                                        <button 
                                            onClick={(e) => handleEditClick(e, customer)}
                                            className="p-2 bg-white border border-slate-300 text-slate-600 rounded-lg hover:bg-slate-50 hover:text-slate-800 transition-all shadow-sm"
                                            title="Editar"
                                        >
                                            <Pencil className="w-4 h-4" />
                                        </button>
                                        {canDeleteCustomers && (
                                            <button 
                                                onClick={(e) => customer.id && handleDeleteFromList(e, customer.id)}
                                                className="p-2 bg-white border border-slate-200 text-rose-500 rounded-lg hover:bg-rose-50 hover:text-rose-600 hover:border-rose-200 transition-all shadow-sm"
                                                title="Eliminar"
                                            >
                                                <Trash2 className="w-4 h-4" />
                                            </button>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))
                    )}
                </tbody>
            </table>
        </div>
      </div>

      {/* Form Modal */}
      <Modal 
        isOpen={showFormModal} 
        onClose={() => setShowFormModal(false)} 
        title={selectedCustomer ? 'EDITAR CLIENTE' : 'NUEVO CLIENTE'}
      >
          <form onSubmit={handleSubmit} className="space-y-4 pt-2">
              <Input 
                  label="NOMBRE COMPLETO"
                  value={formData.name}
                  onChange={e => setFormData({...formData, name: e.target.value.toUpperCase()})}
                  placeholder="NOMBRE"
                  required
              />
              <Input 
                  label="TELÉFONO"
                  value={formData.phone}
                  onChange={e => {
                      const val = e.target.value.replace(/\D/g, '');
                      if(val.length <= 10) setFormData({...formData, phone: val});
                  }}
                  placeholder="10 DÍGITOS"
                  type="tel"
              />
              <Input 
                  label="DIRECCIÓN"
                  value={formData.address}
                  onChange={e => setFormData({...formData, address: e.target.value.toUpperCase()})}
                  placeholder="DIRECCIÓN COMPLETA"
              />
              <div className="pt-4 flex gap-3">
                  <Button type="button" variant="secondary" onClick={() => setShowFormModal(false)} className="flex-1 uppercase">CANCELAR</Button>
                  <Button type="submit" className="flex-[2] uppercase">GUARDAR</Button>
              </div>
          </form>
      </Modal>

      {/* History Modal */}
      <Modal
        isOpen={showHistoryModal}
        onClose={() => setShowHistoryModal(false)}
        title={`HISTORIAL: ${selectedCustomer?.name}`}
      >
          <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-1">
             {customerHistory.length === 0 ? (
                 <div className="text-center py-8 text-slate-400 uppercase">SIN MOVIMIENTOS REGISTRADOS</div>
             ) : (
                 customerHistory.map(order => (
                     <div key={order.id} className="p-3 bg-slate-50 rounded-xl border border-slate-200">
                         <div className="flex justify-between items-start mb-2">
                             <div>
                                 <div className="font-bold text-slate-800 flex items-center gap-2">
                                     <Receipt className="w-4 h-4 text-slate-400" />
                                     TICKET #{order.id?.slice(-6)}
                                 </div>
                                 <div className="text-xs text-slate-500">{new Date(order.createdAt).toLocaleDateString()}</div>
                             </div>
                             <div className="font-mono font-bold text-slate-700">${order.total.toFixed(2)}</div>
                         </div>
                         <div className="text-xs text-slate-500 bg-white p-2 rounded border border-slate-100">
                             {order.items.map((item, i) => (
                                 <div key={i} className="flex justify-between">
                                     <span className="uppercase">{item.name}</span>
                                     <span className="text-slate-400">x{item.quantity}</span>
                                 </div>
                             ))}
                         </div>
                         <div className="mt-2 text-right">
                             <span className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${order.status === 'refunded' ? 'bg-amber-100 text-amber-700' : (order.status.includes('returned') ? 'bg-emerald-100 text-emerald-700' : 'bg-indigo-100 text-indigo-700')}`}>
                                 {order.status === 'refunded' ? 'REEMBOLSADO' : (order.status.includes('returned') ? 'FINALIZADO' : 'ACTIVO')}
                             </span>
                         </div>
                     </div>
                 ))
             )}
          </div>
          <div className="pt-4">
               <Button variant="secondary" onClick={() => setShowHistoryModal(false)} className="w-full uppercase">CERRAR</Button>
          </div>
      </Modal>
    </div>
  );
};

export default Customers;

export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
  imageUrl?: string; // New field for product image
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface UserPermissions {
  canViewReports: boolean;
  canManageSettings: boolean; // Global settings
  canManageInventory: boolean; // Add/Edit/Delete products
  canManageUsers: boolean; // Add/Edit/Delete users
  canRefund: boolean; // Perform refunds
  canDeleteCustomers: boolean; // Delete customers
  canManageExpenses: boolean; // Access Expenses module
  canApplyDiscounts: boolean; // New: Apply coupons in POS
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff'; // Kept for legacy/fallback
  permissions?: UserPermissions; // Granular permissions
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
  cardFeePercentage: number;
  businessName?: string; // New: Custom business name
  businessTagline?: string; // New: Custom slogan/subtitle
  receiptTemplate?: 'v1' | 'v2'; // New: Template selector
  ticketPrefix?: string; // e.g. "26"
  nextTicketSequence?: number; // e.g. 1 (will result in 260001)
}

export interface Expense {
  id?: string;
  concept: string;
  amount: number;
  createdAt: number;
  registeredBy?: string;
}

export interface Coupon {
  id?: string;
  code: string;
  type: 'percentage' | 'amount'; // % or $
  value: number;
  isActive: boolean;
}

export type TransactionType = 'sale' | 'rent';

export interface CartItem extends Product {
  cartId: string; // Unique ID for the item in cart
  transactionType: TransactionType;
  quantity: number;
  selectedVariation?: Variation;
  appliedPrice: number; // The actual price used for this item (base or variation)
}

export interface Order {
  id?: string;
  items: CartItem[];
  customer?: Customer; // Required if there are rentals
  total: number;
  status: 'pending' | 'completed' | 'returned' | 'late' | 'returned_late' | 'refunded' | 'reservation';
  createdAt: number; // Timestamp
  rentalStartDate?: number;
  rentalEndDate?: number;
  returnedAt?: number; // When it was actually returned
  lateFee?: number; // Fee charged if returned late
  paymentMethod?: 'cash' | 'card' | 'transfer';

  // Reservation Fields
  downPayment?: number; // Amount paid upfront
  remainingBalance?: number; // Amount pending to pay
}

