// --- Quick Return Logic Extracted for Navigation Hook ---
const QuickReturnModal: React.FC<{ isOpen: boolean, onClose: () => void }> = ({ isOpen, onClose }) => {
  const navigate = useNavigate();
  const [activeRentals, setActiveRentals] = useState<Order[]>([]);
  const [quickSearch, setQuickSearch] = useState('');
  const [loadingRentals, setLoadingRentals] = useState(false);
  const [selectedReturnOrder, setSelectedReturnOrder] = useState<Order | null>(null);
  const [lateFee, setLateFee] = useState('');
  const [step, setStep] = useState<'list' | 'confirm'>('list');

  // Load active rentals when modal opens
  useEffect(() => {
    if (isOpen) {
        setStep('list');
        setQuickSearch('');
        loadActiveRentals();
    }
  }, [isOpen]);

  const loadActiveRentals = async () => {
      setLoadingRentals(true);
      const allOrders = await getOrders();
      // Filter: Has rental items AND status is NOT returned AND NOT RESERVATION
      const active = allOrders.filter(o => 
          o.items.some(i => i.transactionType === 'rent') && 
          !o.status.includes('returned') &&
          o.status !== 'reservation'
      );
      setActiveRentals(active);
      setLoadingRentals(false);
  };

  const filteredRentals = useMemo(() => {
      const q = quickSearch.toUpperCase();
      return activeRentals.filter(o => 
          o.id?.includes(q) || 
          o.customer?.name.includes(q)
      );
  }, [activeRentals, quickSearch]);

  const handleCardClick = async (order: Order) => {
      setSelectedReturnOrder(order);
      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;

      if (isLate) {
          const settings = await getSystemSettings();
          setLateFee(settings.defaultLateFee.toString());
      } else {
          setLateFee('0');
      }
      setStep('confirm');
  };

  const processQuickReturn = async (payNow: boolean) => {
      if (!selectedReturnOrder || !selectedReturnOrder.id) return;

      const fee = parseFloat(lateFee) || 0;
      const isLate = fee > 0;

      try {
          // 1. Update Order Status
          const updateData: any = {
              status: isLate ? 'returned_late' : 'returned',
              returnedAt: Date.now(),
          };
          if (isLate) updateData.lateFee = fee;

          await updateOrder(selectedReturnOrder.id, updateData);

          // 2. IMPORTANT: If Late Fee, ALWAYS add debt to customer first.
          // This ensures that even if they don't pay immediately (or cancel at POS), the debt is recorded.
          let updatedCustomer = selectedReturnOrder.customer;
          if (isLate && selectedReturnOrder.customer?.id) {
               const currentBalance = selectedReturnOrder.customer.balance || 0;
               const newBalance = currentBalance - fee;

               await updateCustomer(selectedReturnOrder.customer.id, {
                   balance: newBalance
               });

               // Update local object for passing
               updatedCustomer = { ...selectedReturnOrder.customer, balance: newBalance };
          }

          if (payNow && isLate) {
               // 3. Redirect to POS with pre-filled Debt Item
               navigate('/', { 
                  state: { 
                      action: 'pay_late_fee', 
                      customer: updatedCustomer, // Has the new negative balance
                      amount: fee,
                      refTicket: selectedReturnOrder.id
                  } 
               });
               onClose();
          } else {
               // 4. Just finish (Debt remains on account if late)
               if(isLate) {
                   alert(`Devolución registrada. Se cargó un adeudo de $${fee} a la cuenta del cliente.`);
               } else {
                   alert("Devolución registrada correctamente.");
               }
               onClose();
          }

      } catch (e) {
          console.error(e);
          alert("Error al procesar la devolución.");
      }
  };

  return (
      <Modal 
          isOpen={isOpen} 
          onClose={onClose} 
          title="DEVOLUCIÓN RÁPIDA"
      >
          <div className="h-[60vh] flex flex-col">
              {step === 'list' ? (
                  <>
                      <div className="mb-4 relative flex-shrink-0">
                          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                          <input 
                              type="number" 
                              placeholder="ESCANEAR O TECLEAR ID TICKET..." 
                              value={quickSearch}
                              onChange={(e) => setQuickSearch(e.target.value)}
                              className="w-full pl-12 pr-4 py-4 rounded-xl bg-slate-50 border-2 border-indigo-100 focus:border-indigo-500 text-2xl font-bold text-center tracking-widest outline-none transition-colors text-slate-900"
                              autoFocus
                          />
                      </div>

                      <div className="flex-1 overflow-y-auto p-1">
                          {loadingRentals ? (
                              <div className="text-center py-10 text-slate-400">CARGANDO RENTAS...</div>
                          ) : filteredRentals.length === 0 ? (
                              <div className="text-center py-10 text-slate-400">
                                  <div className="inline-block p-4 bg-slate-100 rounded-full mb-2"><BoxSelect className="w-8 h-8 opacity-50"/></div>
                                  <p>NO SE ENCONTRARON RENTAS ACTIVAS</p>
                              </div>
                          ) : (
                              <div className="grid grid-cols-2 gap-3">
                                  {filteredRentals.map(order => {
                                      const isLate = order.rentalEndDate && Date.now() > order.rentalEndDate;
                                      return (
                                          <div 
                                              key={order.id} 
                                              onClick={() => handleCardClick(order)}
                                              className={`p-3 rounded-2xl border-2 cursor-pointer transition-all active:scale-95 relative overflow-hidden flex flex-col justify-between min-h-[140px] ${
                                                  isLate 
                                                  ? 'bg-rose-50 border-rose-200 hover:border-rose-400' 
                                                  : 'bg-white border-slate-200 hover:border-indigo-400'
                                              }`}
                                          >
                                              <div className="flex justify-between items-start">
                                                  <span className={`font-mono font-black text-lg ${isLate ? 'text-rose-700' : 'text-slate-600'}`}>
                                                      #{order.id}
                                                  </span>
                                                  {isLate && <AlertTriangle className="w-5 h-5 text-rose-500 animate-pulse" />}
                                              </div>

                                              <div className="my-2">
                                                  <div className="text-[10px] uppercase text-slate-400 font-bold tracking-wider">CLIENTE</div>
                                                  <div className="font-bold text-slate-800 leading-tight uppercase line-clamp-2">
                                                      {order.customer?.name}
                                                  </div>
                                              </div>

                                              <div className="flex items-end justify-between">
                                                  <div className="text-xs text-slate-500">
                                                      {order.items.filter(i => i.transactionType === 'rent').length} Artículo(s)
                                                  </div>
                                                  <div className={`text-[10px] font-bold px-2 py-1 rounded uppercase ${isLate ? 'bg-rose-200 text-rose-800' : 'bg-indigo-100 text-indigo-700'}`}>
                                                      {isLate ? 'ATRASADO' : 'A TIEMPO'}
                                                  </div>
                                              </div>
                                          </div>
                                      );
                                  })}
                              </div>
                          )}
                      </div>
                  </>
              ) : (
                  <div className="flex flex-col h-full animate-in slide-in-from-right duration-300">
                      {/* CONFIRMATION SCREEN */}
                      <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 mb-4">
                          <div className="flex justify-between items-center mb-2">
                              <h3 className="font-bold text-slate-700 uppercase">CONFIRMAR DEVOLUCIÓN</h3>
                              <div className="font-mono text-slate-400">#{selectedReturnOrder?.id}</div>
                          </div>
                          <div className="text-2xl font-bold text-slate-900 uppercase mb-1">{selectedReturnOrder?.customer?.name}</div>
                          <div className="text-xs text-slate-500 uppercase flex flex-col gap-1">
                              {selectedReturnOrder?.items.filter(i => i.transactionType === 'rent').map((item, idx) => (
                                  <span key={idx}>• {item.name}</span>
                              ))}
                          </div>
                      </div>

                      {parseFloat(lateFee) > 0 && (
                          <div className="mb-4">
                              <div className="bg-rose-100 text-rose-800 p-3 rounded-t-xl flex items-center gap-2 font-bold text-sm">
                                  <AlertTriangle className="w-4 h-4" /> SE DETECTÓ ATRASO
                              </div>
                              <div className="bg-white border-x border-b border-rose-100 p-4 rounded-b-xl">
                                  <Input 
                                      label="MONTO A COBRAR (MULTA)" 
                                      type="number" 
                                      value={lateFee} 
                                      onChange={(e) => setLateFee(e.target.value)}
                                      className="text-xl font-bold text-rose-600"
                                      autoFocus
                                  />
                              </div>
                          </div>
                      )}

                      <div className="mt-auto grid grid-cols-1 gap-3">
                          {parseFloat(lateFee) > 0 ? (
                              <>
                                  <Button onClick={() => processQuickReturn(true)} className="py-4 uppercase shadow-lg">
                                      <div className="flex flex-col items-center leading-none">
                                          <span>COBRAR Y FINALIZAR</span>
                                          <span className="text-[10px] opacity-70 font-normal">EL CLIENTE PAGA AHORA</span>
                                      </div>
                                  </Button>
                                  <Button onClick={() => processQuickReturn(false)} variant="secondary" className="py-4 uppercase border-rose-200 text-rose-600 hover:bg-rose-50">
                                      CARGAR A CUENTA (DEUDA)
                                  </Button>
                              </>
                          ) : (
                              <Button onClick={() => processQuickReturn(false)} className="py-4 uppercase bg-emerald-600 hover:bg-emerald-700 shadow-emerald-200">
                                  <CheckCircle className="w-5 h-5" /> CONFIRMAR RECEPCIÓN (SIN CARGO)
                              </Button>
                          )}
                          <Button variant="ghost" onClick={() => setStep('list')}>VOLVER A LISTA</Button>
                      </div>
                  </div>
              )}
          </div>
      </Modal>
  );
};

