const getOrderType = (order: Order) => {
    const hasRent = order.items.some(i => i.transactionType === 'rent');
    const hasSale = order.items.some(i => i.transactionType === 'sale');
    if (hasRent && hasSale) return 'MIXTO';
    if (hasRent) return 'RENTA';
    return 'VENTA';
};

