              <div className="grid grid-cols-4 gap-2">
                  <Button variant="danger" onClick={clearCart} className="col-span-1 shadow-none bg-rose-50 text-rose-500 border border-rose-100 hover:bg-rose-100">
                      <Trash2 className="w-5 h-5" />
                  </Button>
                  <Button onClick={() => setPaymentModalOpen(true)} className="col-span-3 uppercase shadow-lg shadow-indigo-200" disabled={cart.length === 0 && !debtPaymentItem}>
