import React, { useState, useEffect, useRef, useMemo } from 'react';
import { Plus, RefreshCw, Box, Tag, DollarSign, Layers, Search, Trash2, ArrowLeft, Upload, FileUp, LayoutGrid, List, Pencil, ImagePlus, X, Lock } from 'lucide-react';
import { Button, Input, Select, Card, Badge } from '../components/UI';
import { Product, Variation, User } from '../types';
import { generateProductCode, addProduct, getProducts, deleteProduct, importProductsBatch, updateProduct, uploadProductImage } from '../services/dataService';

const Inventory: React.FC<{ user: User }> = ({ user }) => {
  const [view, setView] = useState<'list' | 'form'>('list');
  // Default to 'table' (List view) as requested
  const [displayMode, setDisplayMode] = useState<'grid' | 'table'>('table'); 
  const [loading, setLoading] = useState(false);
  const [products, setProducts] = useState<Product[]>([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('TODOS'); // New: Category Filter

  const canManageInventory = user.role === 'admin' || user.permissions?.canManageInventory;

  // File Import Ref
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Image Upload State
  const imageUploadRef = useRef<HTMLInputElement>(null);
  const [imageFile, setImageFile] = useState<File | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);

  // Form State
  const initialFormState: Partial<Product> = {
    code: '',
    name: '',
    description: '',
    salePrice: 0,
    rentalPrice: 0,
    category: 'DISFRACES',
    stock: 1,
    variations: [],
    isRentalAvailable: true,
    isSaleAvailable: false,
    imageUrl: '',
  };
  const [formData, setFormData] = useState<Partial<Product>>(initialFormState);

  // New Variation Input State
  const [newVarName, setNewVarName] = useState('');
  const [newVarRent, setNewVarRent] = useState('');
  const [newVarSale, setNewVarSale] = useState('');

  // Load Data
  const loadProducts = async () => {
      setLoading(true);
      const data = await getProducts();
      setProducts(data);
      setLoading(false);
  };

  useEffect(() => {
    if (view === 'list') {
        loadProducts();
    }
  }, [view]);

  // Extract unique categories for filter (includes TODOS)
  const categories = useMemo(() => {
    const cats = new Set(products.map(p => p.category).filter(Boolean));
    return ['TODOS', ...Array.from(cats).sort()];
  }, [products]);

  // Extract unique categories for FORM (does not include TODOS, includes Defaults + Imported)
  const formCategories = useMemo(() => {
      // Start with defaults to ensure they always exist
      const uniqueCats = new Set(['DISFRACES', 'ACCESORIOS', 'DECORACIÓN', 'VENTA GENERAL']);

      // Add existing categories from DB (Imported from CSV)
      products.forEach(p => {
          if (p.category) uniqueCats.add(p.category.toUpperCase().trim());
      });

      return Array.from(uniqueCats).sort();
  }, [products]);

  // Actions
  const handleNewProduct = () => {
      setFormData({ ...initialFormState, code: generateProductCode() });
      setImageFile(null);
      setImagePreview(null);
      setView('form');
  };

  const handleEditProduct = (product: Product) => {
      if (!canManageInventory) return;

      setFormData({ ...product });
      setImageFile(null);
      setImagePreview(product.imageUrl || null);
      setView('form');
  };

  const generateCode = () => {
    setFormData(prev => ({ ...prev, code: generateProductCode() }));
  };

  // --- Image Handling ---
  const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setImageFile(file);
      // Create local preview
      const reader = new FileReader();
      reader.onloadend = () => {
        setImagePreview(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleRemoveImage = () => {
    setImageFile(null);
    setImagePreview(null);
    setFormData(prev => ({ ...prev, imageUrl: '' }));
    if(imageUploadRef.current) imageUploadRef.current.value = '';
  };

  // --- Variations ---

  const handleVariationAdd = () => {
    if (!newVarName.trim()) return;

    const newVariation: Variation = {
      name: newVarName.trim().toUpperCase(),
    };

    if (newVarRent) newVariation.rentalPrice = parseFloat(newVarRent);
