      </Modal>

      {/* --- SUCCESS MODAL --- */}
      <Modal isOpen={showSuccessModal} onClose={handleCloseSuccess} title="VENTA COMPLETADA">
          <div className="text-center space-y-6 py-4">
              <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center mx-auto shadow-inner">
                  <CheckCircle className="w-12 h-12 text-emerald-600" />
              </div>
              <div>
                  <h2 className="text-2xl font-black text-slate-800 uppercase">¡Venta Exitosa!</h2>
                  <div className="bg-slate-100 rounded-lg py-2 px-4 inline-block mt-2">
                      <p className="text-slate-500 font-mono text-xl font-bold tracking-widest">TICKET #{lastOrder?.id.slice(-6)}</p>
                  </div>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2">
                  <Button variant="secondary" onClick={handleCloseSuccess} className="uppercase border-slate-200">
                      NUEVA VENTA
                  </Button>
                  <Button onClick={handlePrintReceipt} className="uppercase shadow-lg bg-indigo-600 hover:bg-indigo-700">
                      <Printer className="w-5 h-5" /> IMPRIMIR
                  </Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={showCustomerModal} onClose={() => setShowCustomerModal(false)} title="SELECCIONAR CLIENTE">
          {/* ... Existing Customer Modal Content ... */}
          {customerViewMode === 'search' ? (
              <div className="h-[50vh] flex flex-col">
                  <div className="flex gap-2 mb-4">
                      <div className="relative flex-1">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                          <input 
                              type="text" 
                              placeholder="BUSCAR CLIENTE..." 
                              value={customerSearch}
                              onChange={e => setCustomerSearch(e.target.value.toUpperCase())}
                              className="w-full pl-10 pr-3 py-3 rounded-xl bg-slate-50 border border-slate-200 outline-none uppercase"
                              autoFocus
                          />
                      </div>
                      <Button onClick={openNewCustomerForm} className="shadow-lg">
                          <Plus className="w-5 h-5" />
                      </Button>
                  </div>

                  <div className="flex-1 overflow-y-auto space-y-2">
                      {filteredCustomers.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => handleSetCustomer(c)}
                            className="p-3 rounded-xl border border-slate-100 hover:border-indigo-300 hover:bg-indigo-50 cursor-pointer transition-all flex justify-between items-center group"
                          >
                              <div>
                                  <div className="font-bold text-slate-800 uppercase group-hover:text-indigo-700">{c.name}</div>
                                  <div className="text-xs text-slate-500">{c.phone}</div>
                              </div>
                              {c.balance && c.balance < 0 && (
                                  <Badge color="rose">ADEUDO: ${Math.abs(c.balance)}</Badge>
                              )}
                          </div>
                      ))}
                      {filteredCustomers.length === 0 && (
                          <div className="text-center py-8 text-slate-400">NO SE ENCONTRARON CLIENTES</div>
                      )}
                  </div>
              </div>
          ) : (
              <form onSubmit={handleQuickCustomerAdd} className="space-y-4 pt-2">
                  <Input 
                      label="NOMBRE COMPLETO" 
                      value={newCustomerName}
                      onChange={e => setNewCustomerName(e.target.value.toUpperCase())}
                      placeholder="EJ. JUAN PÉREZ"
                      autoFocus
                  />
                  <Input 
                      label="TELÉFONO" 
                      value={newCustomerPhone}
                      onChange={e => setNewCustomerPhone(e.target.value)}
                      placeholder="EJ. 5512345678"
                      type="tel"
                  />
                  <Input 
                      label="DIRECCIÓN" 
                      value={newCustomerAddress}
                      onChange={e => setNewCustomerAddress(e.target.value.toUpperCase())}
                      placeholder="CALLE, NÚMERO, COLONIA"
                  />
                  <div className="pt-4 flex gap-3">
                      <Button type="button" variant="secondary" onClick={() => setCustomerViewMode('search')} className="flex-1 uppercase">VOLVER</Button>
                      <Button type="submit" className="flex-[2] uppercase">GUARDAR CLIENTE</Button>
                  </div>
              </form>
          )}
      </Modal>

      <DatePickerModal 
          isOpen={showDatePicker} 
          onClose={() => setShowDatePicker(false)} 
          title={datePickerMode === 'start' ? 'FECHA DE ENTREGA' : 'FECHA DE DEVOLUCIÓN'}
          onSelect={handleDateSelect}
      />

    </div>
  );
};

export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Search, ShoppingCart, Trash2, User, Plus, Minus, CreditCard, Calendar, X, Tag, Percent, Box, LayoutGrid, ArrowLeft, Layers, DollarSign, Archive, Shirt, Sparkles, Gift, Clock, ChevronRight, CheckCircle, Ticket, AlertCircle, Printer, TicketPercent } from 'lucide-react';
import { Product, CartItem, Customer, Order, Coupon, Variation, Category } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getCoupons, getSystemSettings, getCategories } from '../services/dataService';
import { Button, Input, Card, Modal, DatePickerModal, Select, Badge, ReceiptTemplate } from '../components/UI';

// Quick Access Item Interface
interface QuickAccessItem {
    id: string;
    label: string;
    type: 'category' | 'action' | 'product' | 'nav';
    value?: string; // Category Name or Product ID
    color: string;
    icon?: any;
    colSpan?: number;
}

const POS: React.FC = () => {
  const location = useLocation();

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [dbCategories, setDbCategories] = useState<Category[]>([]);
  const [systemSettings, setSystemSettings] = useState<any>({});

  // View State
  const [viewMode, setViewMode] = useState<'home' | 'catalog'>('home');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('TODOS');

  // Cart State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);

  // --- MODAL & FLOW STATES ---
  // Customer
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'new'>('search');
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null);

  // Payment
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountPaid, setAmountPaid] = useState('');
  const [isApartadoMode, setIsApartadoMode] = useState(false); // New: Explicit Reservation Mode

  // Success Modal State
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Dates
  const [rentalStartDate, setRentalStartDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [rentalEndDate, setRentalEndDate] = useState<string>('');
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

  // Coupon Logic
  const [appliedCoupon, setAppliedCoupon] = useState<Coupon | null>(null);
  const [showCouponListModal, setShowCouponListModal] = useState(false); // New: Coupon List Modal

  // --- NEW STATES FOR LOGIC ---
  // Variation Selection
  const [showVariationModal, setShowVariationModal] = useState(false);
  const [pendingProduct, setPendingProduct] = useState<{ product: Product, type: 'sale' | 'rent' } | null>(null);

  // Zero Price / Manual Price
  const [showPriceInputModal, setShowPriceInputModal] = useState(false);
  const [manualPrice, setManualPrice] = useState('');
  const [pendingCartItem, setPendingCartItem] = useState<CartItem | null>(null);

  // Manual Item / Discount (Fallback)
  const [showManualItemModal, setShowManualItemModal] = useState(false);
  const [manualItemDesc, setManualItemDesc] = useState('');
  const [manualItemPrice, setManualItemPrice] = useState('');

  // Settings
  const [debtPaymentItem, setDebtPaymentItem] = useState<{ amount: number, ref: string } | null>(null);

  useEffect(() => {
    loadData();
    if (location.state && location.state.action === 'pay_late_fee') {
        const { customer, amount, refTicket } = location.state;
        if (customer) setCurrentCustomer(customer);
        if (amount) {
            setDebtPaymentItem({ amount, ref: refTicket });
        }
    }
  }, [location]);

  // Set default rental end date on mount
  useEffect(() => {
      calculateDefaultEndDate(rentalStartDate);
  }, [rentalStartDate]);

  const loadData = async () => {
    const [p, c, co, s, cats] = await Promise.all([
        getProducts(), 
        getCustomers(), 
        getCoupons(),
        getSystemSettings(),
        getCategories()
    ]);
    setProducts(p);
    setCustomers(c);
    setCoupons(co);
    setSystemSettings(s);
    setDbCategories(cats);
  };

  // --- DATE LOGIC ---

  // Helper to format date strictly for display: "05 FEB 26"
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return '';
      // Appending T12:00:00 forces it to midday local time, preventing timezone rollback (the "day before" issue)
      const date = new Date(dateStr + 'T12:00:00'); 
      return date.toLocaleDateString('es-MX', {
          day: '2-digit',
          month: 'short',
          year: '2-digit'
      }).toUpperCase().replace('.', '');
  };

  const calculateDefaultEndDate = (startDateStr: string) => {
      // Logic: Rent is 1 day. If return falls on Sunday, move to Monday.
      // Append time to ensure calculation happens in local day frame
      const start = new Date(startDateStr + 'T12:00:00');
      const end = new Date(start);
      end.setDate(end.getDate() + 1); // +1 Day default

      if (end.getDay() === 0) { // 0 is Sunday
          end.setDate(end.getDate() + 1); // Skip to Monday
      }
      setRentalEndDate(end.toISOString().split('T')[0]);
  };

  // --- DERIVED STATE ---
  const categories = useMemo(() => {
    // Merge DB categories with any categories found in products that might not be in DB yet
    const cats = new Set(dbCategories.map(c => c.name));
    products.forEach(p => { if(p.category) cats.add(p.category); });

    // Ensure the currently selected category is in the list
    if (selectedCategory !== 'TODOS') {
        cats.add(selectedCategory);
    }
    return ['TODOS', ...Array.from(cats).sort()];
  }, [products, dbCategories, selectedCategory]);

  const filteredProducts = products.filter(p => {
    const term = searchQuery.toUpperCase();
    const matchesSearch = p.name.toUpperCase().includes(term) || p.code.includes(term);

    // Smart Filter: Match Category Field OR Name contents
    let matchesCategory = selectedCategory === 'TODOS';
    if (!matchesCategory) {
        const catFilter = selectedCategory.toUpperCase();
        matchesCategory = p.category === catFilter || p.name.toUpperCase().includes(catFilter);
    }

    return matchesSearch && matchesCategory;
  });

  const filteredCustomers = customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch)
  );

  // Detect Future Date for Reservation Suggestion
  const isFutureRental = useMemo(() => {
      const today = new Date();
      today.setHours(0,0,0,0);
      const start = new Date(rentalStartDate + 'T00:00:00'); // Force local time
      return start > today;
  }, [rentalStartDate]);

  // --- CART LOGIC ---

  const updateQuantity = (cartId: string, delta: number) => {
      setCart(prev => prev.map(item => {
          if (item.cartId === cartId) {
              const newQty = Math.max(1, item.quantity + delta);
              // Simple stock check (not robust for variants, but basic protection)
              if (delta > 0 && item.stock > 0 && newQty > item.stock) {
                  return item; // Don't increase
              }
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const initiateAddToCart = (product: Product, type: 'sale' | 'rent') => {
      if (product.variations && product.variations.length > 0) {
          setPendingProduct({ product, type });
          setShowVariationModal(true);
          return;
      }
      checkPriceAndAdd(product, type, undefined);
  };

  const handleVariationSelect = (variation: Variation) => {
      if (!pendingProduct) return;
      setShowVariationModal(false);
      checkPriceAndAdd(pendingProduct.product, pendingProduct.type, variation);
      setPendingProduct(null);
  };

  const checkPriceAndAdd = (product: Product, type: 'sale' | 'rent', variation?: Variation) => {
      let price = 0;
      if (variation) {
          price = type === 'rent' ? (variation.rentalPrice || product.rentalPrice) : (variation.salePrice || product.salePrice);
      } else {
          price = type === 'rent' ? product.rentalPrice : product.salePrice;
      }

      // Check if exact item already exists to just increment
      const existingItem = cart.find(i => 
          i.id === product.id && 
          i.transactionType === type && 
          i.selectedVariation?.name === variation?.name
      );

      if (existingItem) {
          updateQuantity(existingItem.cartId, 1);
          return;
      }

      const newItem: CartItem = {
          ...product,
          cartId: Math.random().toString(36).substr(2, 9),
          transactionType: type,
          quantity: 1,
          selectedVariation: variation,
          appliedPrice: price
      };

      if (price === 0) {
          setPendingCartItem(newItem);
          setManualPrice('');
          setShowPriceInputModal(true);
      } else {
          finalizeAddToCart(newItem);
      }
  };

  const confirmManualPrice = () => {
      if (!pendingCartItem) return;
      const price = parseFloat(manualPrice);
      if (isNaN(price)) return; 

      const updatedItem = { ...pendingCartItem, appliedPrice: price };
      finalizeAddToCart(updatedItem);
      setShowPriceInputModal(false);
      setPendingCartItem(null);
      setManualPrice('');
  };

  const finalizeAddToCart = (item: CartItem) => {
      const existingInCart = cart.filter(i => i.id === item.id);
      const totalInCart = existingInCart.reduce((sum, i) => sum + i.quantity, 0);

      if (totalInCart >= item.stock && item.stock > 0) {
          alert("Stock insuficiente.");
          return;
      }
      setCart(prev => [...prev, item]);
  };

  const removeFromCart = (cartId: string) => setCart(cart.filter(i => i.cartId !== cartId));

  const clearCart = () => {
      setCart([]);
      setDebtPaymentItem(null);
      setAppliedCoupon(null);
      calculateDefaultEndDate(rentalStartDate); // Reset date logic
  };

  const handleApplyCoupon = (coupon: Coupon) => {
      setAppliedCoupon(coupon);
      setShowCouponListModal(false);
  };

  const handleRemoveCoupon = () => {
      setAppliedCoupon(null);
  };

  const handleAddManualItem = (e: React.FormEvent) => {
      e.preventDefault();
      const price = parseFloat(manualItemPrice);
      if (!manualItemDesc || isNaN(price)) {
          alert("Ingrese descripción y monto.");
          return;
      }

      const manualItem: CartItem = {
          id: 'manual-' + Date.now(),
          code: 'MANUAL',
          name: manualItemDesc.toUpperCase(),
          description: 'Concepto Manual',
          salePrice: price,
          rentalPrice: 0,
          category: 'OTROS',
          stock: 9999,
          variations: [],
          isRentalAvailable: false,
          isSaleAvailable: true,
          cartId: Math.random().toString(36).substr(2, 9),
          transactionType: 'sale',
          quantity: 1,
          appliedPrice: price
      };

      setCart(prev => [...prev, manualItem]);
      setShowManualItemModal(false);
      setManualItemDesc('');
      setManualItemPrice('');
  };

  const handleQuickAccessClick = (item: QuickAccessItem) => {
      if (item.type === 'category') {
          setSelectedCategory(item.value || 'TODOS');
          setSearchQuery('');
          setViewMode('catalog');
      } else if (item.type === 'nav' && item.value === 'all_products') {
          setSelectedCategory('TODOS');
          setSearchQuery('');
          setViewMode('catalog');
      } else if (item.type === 'action' && item.value === 'manual_discount') {
          // Open the Coupon Selection Modal instead of manual directly
          setShowCouponListModal(true);
      }
  };

  // --- CALCULATIONS & CHECKOUT ---
  const hasRentals = cart.some(i => i.transactionType === 'rent');

  // Calculate Extra Days Fee
  const extraDaysInfo = useMemo(() => {
      if (!hasRentals || !rentalEndDate) return { days: 0, fee: 0 };

      const start = new Date(rentalStartDate + 'T12:00:00');

      // Calculate Standard Return (Next Business Day)
      let standardReturn = new Date(start);
      standardReturn.setDate(standardReturn.getDate() + 1);
      if (standardReturn.getDay() === 0) standardReturn.setDate(standardReturn.getDate() + 1);

      const selectedReturn = new Date(rentalEndDate + 'T12:00:00');

      if (selectedReturn <= standardReturn) return { days: 0, fee: 0 };

      // Count business days (exclude Sundays) between standard and selected
      let extraDays = 0;
      let current = new Date(standardReturn);
      while (current < selectedReturn) {
          current.setDate(current.getDate() + 1);
          if (current.getDay() !== 0) { // Skip Sunday
              extraDays++;
          }
      }

      if (extraDays <= 0) return { days: 0, fee: 0 };

      const rentalItemsCount = cart.filter(i => i.transactionType === 'rent').reduce((sum, i) => sum + i.quantity, 0);
      const feePerDay = systemSettings.pricePerExtraDay || 0;
      const totalFee = extraDays * feePerDay * rentalItemsCount;

      return { days: extraDays, fee: totalFee };

  }, [rentalStartDate, rentalEndDate, hasRentals, cart, systemSettings]);

  const subtotal = useMemo(() => {
      let sum = cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0);
      if (debtPaymentItem) sum += debtPaymentItem.amount;
      sum += extraDaysInfo.fee;
      return sum;
  }, [cart, debtPaymentItem, extraDaysInfo]);

  const discountAmount = useMemo(() => {
      if (!appliedCoupon) return 0;
      if (appliedCoupon.type === 'percentage') return subtotal * (appliedCoupon.value / 100);
      return appliedCoupon.value;
  }, [subtotal, appliedCoupon]);

  const totalBeforeFee = Math.max(0, subtotal - discountAmount);
  const cardFeeAmount = paymentMethod === 'card' ? totalBeforeFee * ((systemSettings.cardFeePercentage || 0) / 100) : 0;
  const total = totalBeforeFee + cardFeeAmount;

  // Initial Open of Payment Modal
  const handleOpenPayment = () => {
      if (cart.length === 0 && !debtPaymentItem) return;

      if (hasRentals && !currentCustomer) {
          alert("Es necesario seleccionar un cliente para rentas.");
          setShowCustomerModal(true);
          return;
      }
      if (hasRentals && !rentalEndDate) {
          alert("Selecciona fecha de devolución.");
          setDatePickerMode('end');
          setShowDatePicker(true);
          return;
      }

      // Logic to auto-suggest Reservation if date is future
      setIsApartadoMode(isFutureRental); 
      setAmountPaid('');
      setPaymentModalOpen(true);
  };

  const handleCheckout = async () => {
      const paid = parseFloat(amountPaid) || 0;

      // Validation Logic
      if (isApartadoMode) {
          if (paid <= 0) {
              alert("Para apartar se requiere un anticipo mayor a 0.");
              return;
          }
          if (paid >= total) {
              // If they pay full amount, warn them but allow. It effectively acts as a paid reservation.
              // alert("El monto cubre el total. Se registrará como pagado.");
          }
      } else {
          // Standard Sale Mode
          if (Math.abs(paid - total) > 0.5 && paid < total) { // Allow tiny diff for rounding
              alert("Monto incompleto. Si es un abono, active la opción 'ES UN APARTADO'.");
              return;
          }
          if (paid <= 0 && total > 0) {
              alert("Ingrese monto pagado.");
              return;
          }
      }

      try {
          // Clone cart items to modify if needed
          const finalItems = [...cart];

          // INJECT EXTRA DAYS FEE AS A CART ITEM
          if (extraDaysInfo.fee > 0) {
              finalItems.push({
                  id: 'extraday-' + Date.now(),
                  code: 'EXTRA',
                  name: `DÍAS EXTRA (${extraDaysInfo.days} DÍAS)`,
                  description: 'Costo por días adicionales de renta',
                  salePrice: extraDaysInfo.fee,
                  rentalPrice: 0,
                  category: 'SERVICIOS',
                  stock: 9999,
                  variations: [],
                  isRentalAvailable: false,
                  isSaleAvailable: true,
                  cartId: 'extraday-fee-item',
                  transactionType: 'sale', // It's a fee, treated as sale
                  quantity: 1,
                  appliedPrice: extraDaysInfo.fee
              });
          }

          const orderData: any = {
              items: finalItems,
              customer: currentCustomer || undefined,
              total: total,
              // Status determination
              status: isApartadoMode ? 'reservation' : 'completed', // Default completed, overridden if rent active
              paymentMethod: paymentMethod,
              createdAt: Date.now(),
          };

          if (hasRentals) {
              orderData.rentalStartDate = new Date(rentalStartDate + 'T12:00:00').getTime();
              orderData.rentalEndDate = new Date(rentalEndDate + 'T12:00:00').getTime();

              // If standard mode and has rentals, it's 'pending' (Active Rent) not completed
              if (!isApartadoMode) {
                  orderData.status = 'pending'; // Active Rental
              }
          }

          if (isApartadoMode) {
              orderData.downPayment = paid;
              orderData.remainingBalance = total - paid;
          } else {
              // Paid in full
              orderData.remainingBalance = 0;
          }

          if (debtPaymentItem && currentCustomer && currentCustomer.id) {
             const currentBal = currentCustomer.balance || 0;
             await updateCustomer(currentCustomer.id, {
                 balance: currentBal + debtPaymentItem.amount
             });
          }

          const newOrder = await createOrder(orderData);

          // SUCCESS HANDLER
          setLastOrder(newOrder as Order); // Cast needed as createOrder returns id
          setPaymentModalOpen(false);
          setShowSuccessModal(true); // Open Success Modal

          // Clear cart immediately so UI behind modal is clean
          clearCart();
          setAmountPaid('');
          setCurrentCustomer(null);
          setViewMode('home');

      } catch (e) {
          console.error(e);
          alert("Error al procesar venta");
      }
  };

  const handlePrintReceipt = () => {
      window.print();
  };

  const handleCloseSuccess = () => {
      setShowSuccessModal(false);
      setLastOrder(null);
  };

  // --- CUSTOMER LOGIC ---
  const handleSetCustomer = (customer: Customer) => {
      setCurrentCustomer(customer);
      setShowCustomerModal(false);
      setCustomerSearch('');
  };
  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
      if (e) e.preventDefault();
      if(!newCustomerName || !newCustomerPhone || !newCustomerAddress) {
          alert("Todos los datos son obligatorios.");
          return;
      }
      const customerData = { name: newCustomerName.toUpperCase(), phone: newCustomerPhone, address: newCustomerAddress.toUpperCase() };
      let resultCustomer: Customer;
      try {
        if (editingCustomerId) {
            await updateCustomer(editingCustomerId, customerData);
            resultCustomer = { ...customerData, id: editingCustomerId };
            setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
        } else {
            const saved = await addCustomer(customerData);
            resultCustomer = saved;
            setCustomers([...customers, saved]);
        }
        handleSetCustomer(resultCustomer);
        setShowCustomerModal(false);
        setNewCustomerName(''); setNewCustomerPhone(''); setNewCustomerAddress(''); setEditingCustomerId(null); setCustomerViewMode('search');
      } catch (e) { alert("Error al guardar cliente"); }
  };
  const openNewCustomerForm = () => {
      setCustomerViewMode('new');
      setNewCustomerName(customerSearch.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
  };
  // Dates
  const handleDateSelect = (date: string) => {
      if (datePickerMode === 'start') {
          setRentalStartDate(date);
          calculateDefaultEndDate(date);
      } else {
          setRentalEndDate(date);
      }
  };

  // --- DYNAMIC QUICK ACCESS ITEMS ---
  const quickAccessItems = useMemo(() => {
    // 1. Static Actions
    const items: QuickAccessItem[] = [
        { id: 'discount', label: 'AGREGAR DESCUENTO', type: 'action', value: 'manual_discount', color: 'bg-gradient-to-br from-orange-400 to-amber-500 text-white', icon: Tag, colSpan: 1 },
        { id: 'catalog', label: 'VER TODO EL CATÁLOGO', type: 'nav', value: 'all_products', color: 'bg-white border-2 border-slate-200 text-slate-700', icon: Box, colSpan: 1 },
    ];

    // 2. Map Registered Categories
    // We sort them so they appear in a consistent order (alphabetical usually)
    const sortedCats = [...dbCategories].sort((a,b) => a.name.localeCompare(b.name));

    const catItems = sortedCats.map((cat, index) => {
        // Cycle through a palette of 2026-ish colors
        const colors = [
            'bg-indigo-50 text-indigo-700 border border-indigo-100',
            'bg-emerald-50 text-emerald-700 border border-emerald-100',
            'bg-blue-50 text-blue-700 border border-blue-100',
            'bg-purple-50 text-purple-700 border border-purple-100',
            'bg-rose-50 text-rose-700 border border-rose-100',
            'bg-amber-50 text-amber-700 border border-amber-100',
            'bg-teal-50 text-teal-700 border border-teal-100',
            'bg-cyan-50 text-cyan-700 border border-cyan-100',
        ];

        const colorClass = colors[index % colors.length];

        return {
            id: cat.id || `cat-${index}`,
            label: cat.name, // Display Registered Name
            type: 'category',
            value: cat.name, // Value to filter by
            color: colorClass,
            icon: Shirt, // Generic Icon
            colSpan: 1
        } as QuickAccessItem;
    });

    return [...items, ...catItems];
  }, [dbCategories]);

  return (
    <div className="h-full flex flex-col lg:flex-row overflow-hidden bg-slate-100">

      {/* --- HIDDEN RECEIPT TEMPLATE FOR PRINTING --- */}
      <ReceiptTemplate order={lastOrder} settings={systemSettings} />

      {/* LEFT: Dynamic Content (Home or Catalog) */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200 relative">

        {/* VIEW: HOME (Quick Access) */}
        {viewMode === 'home' && (
            <div className="h-full overflow-y-auto p-4 md:p-8 animate-in fade-in zoom-in-95 duration-300">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-200">
                        <LayoutGrid className="w-6 h-6 text-white" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Inicio</h1>
                        <p className="text-slate-500 uppercase text-xs font-bold tracking-widest">Accesos Rápidos</p>
                    </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 auto-rows-[140px]">
                    {quickAccessItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => handleQuickAccessClick(item)}
                            className={`rounded-3xl p-6 relative group overflow-hidden transition-all hover:scale-[1.02] active:scale-95 shadow-sm hover:shadow-xl flex flex-col justify-between items-start text-left ${item.color} ${item.colSpan === 2 ? 'col-span-2' : 'col-span-1'}`}
                        >
                            <item.icon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:rotate-12 transition-transform" />
                            <div className="p-2 bg-white/20 backdrop-blur-md rounded-2xl">
                                <item.icon className="w-6 h-6" />
                            </div>
                            <span className="font-black uppercase text-sm md:text-base leading-tight max-w-[80%] z-10 line-clamp-2">
                                {item.label}
                            </span>
                        </button>
                    ))}
                </div>
            </div>
        )}

        {/* VIEW: CATALOG */}
        {viewMode === 'catalog' && (
            <div className="flex flex-col h-full animate-in slide-in-from-right duration-300">
                {/* Header */}
                <div className="p-4 bg-white border-b border-slate-200 flex gap-4 items-center">
                    <Button variant="secondary" onClick={() => setViewMode('home')} className="px-3 shadow-none border-slate-200">
                        <ArrowLeft className="w-5 h-5" />
                    </Button>
                    <div className="flex-1 relative">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                        <input 
                            type="text" 
                            placeholder="BUSCAR PRODUCTOS..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                            className="w-full pl-12 pr-4 py-3 rounded-xl bg-slate-100 border-transparent focus:bg-white focus:border-indigo-500 focus:ring-2 focus:ring-indigo-500/20 transition-all uppercase outline-none"
                            autoFocus
                        />
                    </div>
                    <div className="w-48 hidden md:block">
                        <select 
                            value={selectedCategory}
                            onChange={(e) => setSelectedCategory(e.target.value)}
                            className="w-full h-full bg-slate-100 rounded-xl px-4 font-bold text-slate-600 outline-none focus:ring-2 focus:ring-indigo-500/20 uppercase cursor-pointer"
                        >
                            {categories.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                {/* Grid */}
                <div className="flex-1 overflow-y-auto p-4 bg-slate-50/50">
                    <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
                        {filteredProducts.map(product => (
                            <Card key={product.id} className="p-0 overflow-hidden hover:shadow-lg hover:border-indigo-200 transition-all group border-0 shadow-sm bg-white cursor-pointer active:scale-[0.98]">
                                <div className="relative h-36 bg-slate-100 overflow-hidden">
                                    {product.imageUrl ? (
                                        <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                                    ) : (
                                        <div className="w-full h-full flex items-center justify-center text-slate-300">
                                            <Box className="w-12 h-12" />
                                        </div>
                                    )}
                                    <div className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                        <Badge color="indigo">{product.stock} DISP</Badge>
                                    </div>
                                    {product.variations && product.variations.length > 0 && (
                                        <div className="absolute bottom-2 left-2 bg-black/60 backdrop-blur-sm text-white text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center gap-1">
                                            <Layers className="w-3 h-3" /> OPCIONES
                                        </div>
                                    )}
                                </div>
                                <div className="p-3">
                                    <div className="text-xs font-mono text-slate-400 mb-1">{product.code}</div>
                                    <h3 className="font-bold text-slate-800 text-sm leading-tight mb-3 line-clamp-2 h-10 uppercase">{product.name}</h3>

                                    <div className="grid grid-cols-2 gap-2">
                                        {product.isRentalAvailable && (
                                            <Button 
                                                variant="primary" 
                                                className="py-2 text-[10px] shadow-none px-0"
                                                onClick={() => initiateAddToCart(product, 'rent')}
                                            >
                                                RENTA ${product.rentalPrice}
                                            </Button>
                                        )}
                                        {product.isSaleAvailable && (
                                            <Button 
                                                variant="secondary" 
                                                className="py-2 text-[10px] border-emerald-200 text-emerald-700 bg-emerald-50 hover:bg-emerald-100 px-0"
                                                onClick={() => initiateAddToCart(product, 'sale')}
                                            >
                                                VENTA ${product.salePrice}
                                            </Button>
                                        )}
                                    </div>
                                </div>
                            </Card>
                        ))}
                    </div>
                </div>
            </div>
        )}
      </div>

      {/* RIGHT: Cart & Checkout (REDESIGNED) */}
      <div className="w-full lg:w-[400px] xl:w-[450px] bg-slate-50 flex flex-col h-full shadow-2xl z-10 border-l border-slate-200">

          {/* 1. Customer Section */}
          <div className="p-6 pb-2 flex-shrink-0">
              {currentCustomer ? (
                  <div className="bg-slate-900 rounded-3xl p-5 text-white shadow-xl relative overflow-hidden group transition-all hover:scale-[1.02]">
                      {/* Decorative elements */}
                      <div className="absolute top-0 right-0 w-32 h-32 bg-white/5 rounded-full -mr-10 -mt-10 blur-2xl"></div>
                      <div className="absolute bottom-0 left-0 w-24 h-24 bg-indigo-500/20 rounded-full -ml-10 -mb-10 blur-xl"></div>

                      <div className="relative z-10 flex justify-between items-center">
                          <div className="flex items-center gap-4">
                              <div className="w-12 h-12 rounded-2xl bg-white/10 backdrop-blur-md flex items-center justify-center font-bold text-xl shadow-inner border border-white/10">
                                  {currentCustomer.name.charAt(0)}
                              </div>
                              <div>
                                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-0.5">CLIENTE VIP</p>
                                  <p className="font-bold text-base uppercase truncate max-w-[180px] leading-tight">{currentCustomer.name}</p>
                                  <p className="text-xs text-slate-400 font-mono mt-0.5">{currentCustomer.phone}</p>
                              </div>
                          </div>
                          <button onClick={() => setCurrentCustomer(null)} className="p-2 bg-white/5 hover:bg-white/20 rounded-xl transition-colors text-slate-300 hover:text-white">
                              <X className="w-5 h-5" />
                          </button>
                      </div>
                  </div>
              ) : (
                  <button 
                    onClick={() => setShowCustomerModal(true)}
                    className="w-full py-5 border-2 border-dashed border-slate-300 rounded-3xl flex flex-col items-center justify-center gap-2 text-slate-400 font-bold hover:border-indigo-400 hover:text-indigo-600 hover:bg-indigo-50/50 transition-all group bg-white"
                  >
                      <div className="p-3 bg-slate-100 rounded-full group-hover:bg-white group-hover:shadow-md transition-all">
                          <User className="w-6 h-6" />
                      </div>
                      <span className="uppercase text-xs tracking-widest">ASIGNAR CLIENTE</span>
                  </button>
              )}
          </div>

          {/* 2. Cart Items List */}
          <div className="flex-1 overflow-y-auto p-6 space-y-3 pt-2">
              {cart.length === 0 && !debtPaymentItem ? (
                  <div className="h-full flex flex-col items-center justify-center text-slate-300 opacity-60">
                      <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 shadow-inner">
                        <ShoppingCart className="w-12 h-12 text-slate-300" />
                      </div>
                      <p className="font-bold uppercase tracking-widest text-sm">CARRITO VACÍO</p>
                      {systemSettings.logoUrl && (
                          <img src={systemSettings.logoUrl} alt="Logo" className="w-24 h-auto object-contain mt-8 grayscale opacity-50 mix-blend-multiply" />
                      )}
                  </div>
              ) : (
                  <>
                    {cart.map(item => (
                        <div key={item.cartId} className={`relative p-3 bg-white rounded-2xl border transition-all duration-300 overflow-hidden group ${item.transactionType === 'rent' ? 'border-indigo-100 hover:border-indigo-300' : 'border-emerald-100 hover:border-emerald-300'}`}>

                            <div className="flex justify-between items-center gap-3">
                                {/* Details */}
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 mb-1">
                                       <span className={`text-[8px] font-black px-1.5 py-0.5 rounded flex items-center gap-1 uppercase tracking-wider ${item.transactionType === 'rent' ? 'bg-indigo-50 text-indigo-700' : 'bg-emerald-50 text-emerald-700'}`}>
                                          {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                                       </span>
                                       {item.selectedVariation && (
                                            <span className="text-[8px] font-bold text-slate-400 bg-slate-50 px-1.5 py-0.5 rounded uppercase truncate">
                                                {item.selectedVariation.name}
                                            </span>
                                        )}
                                    </div>
                                    <h4 className="font-bold text-slate-800 text-xs leading-tight uppercase truncate">{item.name}</h4>
                                    <div className="font-black text-slate-900 text-sm mt-1">${(item.appliedPrice * item.quantity).toFixed(2)}</div>
                                </div>

                                {/* Controls */}
                                <div className="flex items-center gap-2">
                                    {/* Qty Controls */}
                                    <div className="flex items-center bg-slate-50 rounded-xl p-1 border border-slate-100">
                                        <button 
                                            onClick={() => updateQuantity(item.cartId, -1)}
                                            disabled={item.quantity <= 1}
                                            className="w-7 h-7 flex items-center justify-center rounded-lg bg-white text-slate-500 hover:bg-indigo-50 hover:text-indigo-600 disabled:opacity-30 disabled:hover:bg-white shadow-sm transition-all"
                                        >
                                            <Minus className="w-3 h-3" />
                                        </button>
                                        <span className="w-6 text-center font-bold text-xs text-slate-700">{item.quantity}</span>
                                        <button 
                                            onClick={() => updateQuantity(item.cartId, 1)}
                                            className="w-7 h-7 flex items-center justify-center rounded-lg bg-white text-slate-500 hover:bg-indigo-50 hover:text-indigo-600 shadow-sm transition-all"
                                        >
                                            <Plus className="w-3 h-3" />
                                        </button>
                                    </div>

                                    {/* Delete */}
                                    <button 
                                        onClick={() => removeFromCart(item.cartId)}
                                        className="w-8 h-8 flex items-center justify-center text-slate-300 hover:text-rose-500 transition-colors rounded-xl hover:bg-rose-50"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    ))}

                    {/* Debt Item */}
                    {debtPaymentItem && (
                        <div className="p-4 bg-rose-50 rounded-3xl border border-rose-100 shadow-sm relative overflow-hidden">
                             <div className="absolute -right-6 -top-6 w-20 h-20 bg-rose-200 rounded-full opacity-20 blur-xl"></div>
                             <div className="flex justify-between items-center relative z-10">
                                 <div>
                                     <div className="flex items-center gap-2 mb-1">
                                         <span className="bg-rose-100 text-rose-700 text-[9px] font-black px-2 py-1 rounded-lg uppercase">ADEUDO</span>
                                     </div>
                                     <span className="font-black text-rose-900 text-sm uppercase block">COBRO DE MULTA</span>
                                     <span className="text-[10px] font-mono text-rose-600">TICKET REF: #{debtPaymentItem.ref}</span>
                                 </div>
                                 <div className="text-right">
                                    <span className="font-black text-rose-700 text-xl block">${debtPaymentItem.amount}</span>
                                    <button onClick={() => setDebtPaymentItem(null)} className="text-rose-400 hover:text-rose-600 text-xs font-bold mt-1 uppercase">
                                        REMOVER
                                    </button>
                                 </div>
                             </div>
                        </div>
                    )}
                  </>
              )}
          </div>

          {/* 3. Footer / Calculations (REDESIGNED) */}
          <div className="bg-white border-t border-slate-100 p-6 shadow-[0_-10px_40px_rgba(0,0,0,0.05)] z-20 rounded-t-[2.5rem] relative">

              {/* Expandable Grip */}
              <div className="absolute top-3 left-1/2 -translate-x-1/2 w-12 h-1.5 bg-slate-200 rounded-full"></div>

              {/* Rental Dates if needed */}
              {hasRentals && (
                  <div className="flex gap-3 mb-6 mt-2">
                      <div 
                        className={`flex-1 p-3 rounded-2xl border-2 cursor-pointer transition-all ${rentalStartDate ? 'border-indigo-100 bg-indigo-50/30' : 'border-slate-100 bg-slate-50'}`}
                        onClick={() => { setDatePickerMode('start'); setShowDatePicker(true); }}
                      >
                          <div className="text-[9px] font-black text-indigo-400 uppercase tracking-wider mb-1">ENTREGA</div>
                          <div className="text-sm font-bold text-slate-800 flex items-center gap-2">
                              <Calendar className="w-4 h-4 text-indigo-600" />
                              {formatDateDisplay(rentalStartDate)}
                          </div>
                      </div>
                      <div 
                        className={`flex-1 p-3 rounded-2xl border-2 cursor-pointer transition-all ${rentalEndDate ? 'border-indigo-100 bg-indigo-50/30' : 'border-dashed border-slate-300 hover:border-indigo-300'}`} 
                        onClick={() => { setDatePickerMode('end'); setShowDatePicker(true); }}
                      >
                          <div className="text-[9px] font-black text-indigo-400 uppercase tracking-wider mb-1">DEVOLUCIÓN</div>
                          <div className={`text-sm font-bold flex items-center gap-2 ${rentalEndDate ? 'text-slate-800' : 'text-slate-400'}`}>
                              <Calendar className="w-4 h-4 text-indigo-600" />
                              {rentalEndDate ? formatDateDisplay(rentalEndDate) : 'SELECCIONAR'}
                          </div>
                          {extraDaysInfo.days > 0 && (
                              <div className="text-[9px] text-rose-500 font-bold mt-1">
                                  +{extraDaysInfo.days} DÍAS EXTRA
                              </div>
                          )}
                      </div>
                  </div>
              )}

              {/* Totals Block */}
              <div className="space-y-2 mb-6">
                  <div className="flex justify-between text-xs font-bold text-slate-400 uppercase">
                      <span>Subtotal Productos</span>
                      <span>${cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0).toFixed(2)}</span>
                  </div>

                  {/* Applied Discount Display */}
                  {appliedCoupon && (
                      <div className="flex justify-between items-center text-xs font-bold text-emerald-600 uppercase bg-emerald-50 px-2 py-1 rounded-lg">
                          <span className="flex items-center gap-1">
                              <Tag className="w-3 h-3"/> DESCUENTO ({appliedCoupon.code})
                          </span>
                          <div className="flex items-center gap-2">
                              <span>-${discountAmount.toFixed(2)}</span>
                              <button onClick={handleRemoveCoupon} className="text-emerald-400 hover:text-emerald-700">
                                  <X className="w-3 h-3" />
                              </button>
                          </div>
                      </div>
                  )}

                  {/* Extra Days Fee Display */}
                  {extraDaysInfo.fee > 0 && (
                      <div className="flex justify-between text-xs font-bold text-rose-600 uppercase bg-rose-50 px-2 py-1 rounded-lg">
                          <span>Días Extra ({extraDaysInfo.days})</span>
                          <span>+${extraDaysInfo.fee.toFixed(2)}</span>
                      </div>
                  )}

                  {debtPaymentItem && (
                      <div className="flex justify-between text-xs font-bold text-rose-600 uppercase">
                          <span>Multa / Adeudo</span>
                          <span>+${debtPaymentItem.amount.toFixed(2)}</span>
                      </div>
                  )}

                  {paymentMethod === 'card' && cardFeeAmount > 0 && (
                      <div className="flex justify-between text-xs font-bold text-slate-500 uppercase">
                          <span>Comisión Tarjeta</span>
                          <span>${cardFeeAmount.toFixed(2)}</span>
                      </div>
                  )}
                  <div className="flex justify-between items-end pt-4 border-t border-slate-100">
                      <span className="text-sm font-black text-slate-800 uppercase tracking-widest">TOTAL A PAGAR</span>
                      <span className="text-4xl font-black text-slate-900 tracking-tighter">${total.toFixed(2)}</span>
                  </div>
              </div>

              <div className="grid grid-cols-5 gap-3">
                  <Button variant="danger" onClick={clearCart} className="col-span-1 shadow-none bg-rose-50 text-rose-500 border-2 border-rose-100 hover:bg-rose-100 hover:border-rose-200 rounded-2xl">
                      <Trash2 className="w-6 h-6" />
                  </Button>
                  <Button onClick={handleOpenPayment} className="col-span-4 uppercase shadow-xl shadow-indigo-200 text-lg font-black tracking-wide rounded-2xl h-14" disabled={cart.length === 0 && !debtPaymentItem}>
                      <div className="flex items-center gap-2">
                          COBRAR <ChevronRight className="w-6 h-6 opacity-50" />
                      </div>
                  </Button>
              </div>
          </div>
      </div>

      {/* --- COUPON LIST MODAL --- */}
      <Modal isOpen={showCouponListModal} onClose={() => setShowCouponListModal(false)} title="SELECCIONAR DESCUENTO">
          <div className="space-y-4 pt-2 max-h-[60vh] overflow-y-auto">
              {coupons.filter(c => c.isActive).length === 0 ? (
                  <div className="text-center py-8 text-slate-400 uppercase text-sm">No hay cupones activos registrados</div>
              ) : (
                  <div className="grid grid-cols-1 gap-3">
                      {coupons.filter(c => c.isActive).map(coupon => (
                          <button 
                              key={coupon.id}
                              onClick={() => handleApplyCoupon(coupon)}
                              className="flex items-center justify-between p-4 bg-white border-2 border-slate-100 rounded-2xl hover:border-indigo-500 hover:bg-indigo-50 transition-all group text-left shadow-sm"
                          >
                              <div className="flex items-center gap-4">
                                  <div className="w-12 h-12 bg-indigo-100 text-indigo-600 rounded-full flex items-center justify-center">
                                      <TicketPercent className="w-6 h-6" />
                                  </div>
                                  <div>
                                      <div className="font-bold text-slate-800 uppercase text-lg group-hover:text-indigo-700">{coupon.code}</div>
                                      <div className="text-xs text-slate-500 font-bold uppercase">
                                          {coupon.type === 'percentage' ? `${coupon.value}% DE DESCUENTO` : `$${coupon.value} DE DESCUENTO`}
                                      </div>
                                  </div>
                              </div>
                              <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-indigo-500" />
                          </button>
                      ))}
                  </div>
              )}

              <div className="border-t border-slate-100 pt-4 mt-4">
                  <p className="text-xs text-center text-slate-400 mb-3 uppercase">¿El descuento no está en la lista?</p>
                  <Button 
                      variant="secondary" 
                      onClick={() => { setShowCouponListModal(false); setShowManualItemModal(true); }}
                      className="w-full uppercase border-slate-300"
                  >
                      APLICAR DESCUENTO MANUAL
                  </Button>
              </div>
          </div>
      </Modal>

      {/* --- VARIATION SELECTION MODAL --- */}
      <Modal isOpen={showVariationModal} onClose={() => setShowVariationModal(false)} title="SELECCIONAR OPCIÓN">
         <div className="space-y-4">
             <div className="bg-slate-50 p-4 rounded-xl mb-4 text-center">
                 <h3 className="font-bold text-lg text-slate-800 uppercase">{pendingProduct?.product.name}</h3>
                 <p className="text-slate-500 text-sm uppercase">Seleccione una variante para continuar</p>
             </div>
             <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                 {pendingProduct?.product.variations?.map((v, i) => {
                     const price = pendingProduct.type === 'rent' 
                        ? (v.rentalPrice || pendingProduct.product.rentalPrice)
                        : (v.salePrice || pendingProduct.product.salePrice);
                     return (
                        <button
                            key={i}
                            onClick={() => handleVariationSelect(v)}
                            className="p-4 rounded-xl border-2 border-slate-100 hover:border-indigo-500 hover:bg-indigo-50 transition-all text-left group"
                        >
                            <div className="font-bold text-slate-800 uppercase group-hover:text-indigo-700">{v.name}</div>
                            <div className="text-sm font-mono text-slate-500 group-hover:text-indigo-600">${price}</div>
                        </button>
                     );
                 })}
             </div>
             <Button variant="secondary" onClick={() => setShowVariationModal(false)} className="w-full mt-4 uppercase">CANCELAR</Button>
         </div>
      </Modal>

      {/* --- ZERO PRICE INPUT MODAL --- */}
      <Modal isOpen={showPriceInputModal} onClose={() => {setShowPriceInputModal(false); setPendingCartItem(null);}} title="PRECIO REQUERIDO">
          <div className="space-y-6 text-center">
              <div className="bg-amber-50 text-amber-800 p-4 rounded-xl flex flex-col items-center">
                  <DollarSign className="w-8 h-8 mb-2" />
                  <p className="font-bold uppercase text-sm">Este artículo no tiene precio definido.</p>
                  <p className="text-xs opacity-70">Por favor ingrese el precio manualmente.</p>
              </div>

              <div>
                  <h3 className="font-bold text-slate-800 uppercase mb-4">{pendingCartItem?.name} {pendingCartItem?.selectedVariation && `(${pendingCartItem.selectedVariation.name})`}</h3>
                  <Input 
                      type="number" 
                      value={manualPrice} 
                      onChange={(e) => setManualPrice(e.target.value)}
                      placeholder="0.00"
                      className="text-4xl font-bold text-center tracking-widest h-20"
                      autoFocus
                  />
              </div>

              <div className="grid grid-cols-2 gap-4">
                  <Button variant="secondary" onClick={() => {setShowPriceInputModal(false); setPendingCartItem(null);}} className="uppercase">CANCELAR</Button>
                  <Button onClick={confirmManualPrice} className="uppercase shadow-lg">CONFIRMAR PRECIO</Button>
              </div>
          </div>
      </Modal>

      {/* --- MANUAL ITEM / DISCOUNT MODAL --- */}
      <Modal isOpen={showManualItemModal} onClose={() => setShowManualItemModal(false)} title="AGREGAR CONCEPTO MANUAL">
          <form onSubmit={handleAddManualItem} className="space-y-6 pt-2">
              <Input 
                  label="DESCRIPCIÓN DEL CONCEPTO"
                  value={manualItemDesc}
                  onChange={(e) => setManualItemDesc(e.target.value.toUpperCase())}
                  placeholder="EJ. DESCUENTO POR DAÑO, AJUSTE, ETC."
                  autoFocus
              />
              <div className="space-y-2">
                  <Input 
                    label="MONTO (USE MENOS (-) PARA DESCUENTOS)"
                    type="number"
                    value={manualItemPrice}
                    onChange={(e) => setManualItemPrice(e.target.value)}
                    placeholder="-50.00"
                    className="text-2xl font-bold"
                  />
                  <p className="text-xs text-slate-400">* Para descontar del total, ingrese un número negativo (ej. -100).</p>
              </div>
              <div className="pt-2">
                  <Button type="submit" className="w-full uppercase shadow-lg h-12">AGREGAR AL TICKET</Button>
              </div>
          </form>
      </Modal>

      {/* --- PAYMENT MODAL --- */}
      <Modal isOpen={paymentModalOpen} onClose={() => setPaymentModalOpen(false)} title={isApartadoMode ? "GENERAR APARTADO" : "PROCESAR PAGO"}>
           <div className="space-y-6 pt-2">
              <div className="text-center">
                  <div className="text-4xl font-black text-slate-800 font-mono">${total.toFixed(2)}</div>
                  <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mt-1">TOTAL DE LA ORDEN</div>
              </div>

              {/* Reservation Toggle (Show only if future rental) */}
              {isFutureRental && hasRentals && (
                  <div className="bg-amber-50 p-3 rounded-xl border border-amber-200 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                          <Clock className="w-5 h-5 text-amber-600" />
                          <div className="text-amber-800 font-bold text-sm uppercase">¿ES UN APARTADO?</div>
                      </div>
                      <label className="relative inline-flex items-center cursor-pointer">
                        <input 
                            type="checkbox" 
                            className="sr-only peer" 
                            checked={isApartadoMode}
                            onChange={(e) => setIsApartadoMode(e.target.checked)}
                        />
                        <div className="w-11 h-6 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-amber-500"></div>
                      </label>
                  </div>
              )}

              <div className="flex bg-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setPaymentMethod('cash')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'cash' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                        EFECTIVO
                    </button>
                    <button onClick={() => setPaymentMethod('card')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'card' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                        TARJETA
                    </button>
                    <button onClick={() => setPaymentMethod('transfer')} className={`flex-1 py-3 rounded-xl font-bold uppercase text-sm transition-all ${paymentMethod === 'transfer' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                        TRANSFER
                    </button>
              </div>

              <div className="space-y-2">
                  <label className="text-xs font-bold text-slate-500 uppercase ml-1">
                      {isApartadoMode ? 'ANTICIPO (MÍNIMO $1)' : 'DINERO RECIBIDO'}
                  </label>
                  <Input 
                      type="number" 
                      value={amountPaid} 
                      onChange={(e) => setAmountPaid(e.target.value)}
                      placeholder={isApartadoMode ? "0.00" : total.toFixed(2)}
                      className="text-2xl font-bold text-center"
                      autoFocus
                  />

                  {/* Reservation Math */}
                  {isApartadoMode && parseFloat(amountPaid) > 0 && parseFloat(amountPaid) < total && (
                      <div className="bg-amber-50 text-amber-700 p-3 rounded-xl text-center font-bold uppercase border border-amber-100 text-sm">
                          RESTA POR PAGAR: ${(total - parseFloat(amountPaid)).toFixed(2)}
                      </div>
                  )}

                  {/* Standard Change */}
                  {!isApartadoMode && parseFloat(amountPaid) > total && paymentMethod === 'cash' && (
                      <div className="bg-emerald-50 text-emerald-700 p-3 rounded-xl text-center font-bold uppercase border border-emerald-100">
                          CAMBIO: ${(parseFloat(amountPaid) - total).toFixed(2)}
                      </div>
                  )}
              </div>

              <div className="pt-2">
                  <Button onClick={handleCheckout} className="w-full uppercase py-4 shadow-xl">
                      {isApartadoMode ? 'REGISTRAR APARTADO' : 'CONFIRMAR VENTA'}
                  </Button>
              </div>
          </div>
      </Modal>

      {/* --- SUCCESS MODAL --- */}
      <Modal isOpen={showSuccessModal} onClose={handleCloseSuccess} title="VENTA COMPLETADA">
          <div className="text-center space-y-6 py-4">
              <div className="w-24 h-24 bg-emerald-100 rounded-full flex items-center justify-center mx-auto shadow-inner">
                  <CheckCircle className="w-12 h-12 text-emerald-600" />
              </div>
              <div>
                  <h2 className="text-2xl font-black text-slate-800 uppercase">¡Venta Exitosa!</h2>
                  <div className="bg-slate-100 rounded-lg py-2 px-4 inline-block mt-2">
                      <p className="text-slate-500 font-mono text-xl font-bold tracking-widest">TICKET #{lastOrder?.id.slice(-6)}</p>
                  </div>
              </div>
              <div className="grid grid-cols-2 gap-4 pt-2">
                  <Button variant="secondary" onClick={handleCloseSuccess} className="uppercase border-slate-200">
                      NUEVA VENTA
                  </Button>
                  <Button onClick={handlePrintReceipt} className="uppercase shadow-lg bg-indigo-600 hover:bg-indigo-700">
                      <Printer className="w-5 h-5" /> IMPRIMIR
                  </Button>
              </div>
          </div>
      </Modal>

      <Modal isOpen={showCustomerModal} onClose={() => setShowCustomerModal(false)} title="SELECCIONAR CLIENTE">
          {/* ... Existing Customer Modal Content ... */}
          {customerViewMode === 'search' ? (
              <div className="h-[50vh] flex flex-col">
                  <div className="flex gap-2 mb-4">
                      <div className="relative flex-1">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
                          <input 
                              type="text" 
                              placeholder="BUSCAR CLIENTE..." 
                              value={customerSearch}
                              onChange={e => setCustomerSearch(e.target.value.toUpperCase())}
                              className="w-full pl-10 pr-3 py-3 rounded-xl bg-slate-50 border border-slate-200 outline-none uppercase"
                              autoFocus
                          />
                      </div>
                      <Button onClick={openNewCustomerForm} className="shadow-lg">
                          <Plus className="w-5 h-5" />
                      </Button>
                  </div>

                  <div className="flex-1 overflow-y-auto space-y-2">
                      {filteredCustomers.map(c => (
                          <div 
                            key={c.id} 
                            onClick={() => handleSetCustomer(c)}
                            className="p-3 rounded-xl border border-slate-100 hover:border-indigo-300 hover:bg-indigo-50 cursor-pointer transition-all flex justify-between items-center group"
                          >
                              <div>
                                  <div className="font-bold text-slate-800 uppercase group-hover:text-indigo-700">{c.name}</div>
                                  <div className="text-xs text-slate-500">{c.phone}</div>
                              </div>
                              {c.balance && c.balance < 0 && (
                                  <Badge color="rose">ADEUDO: ${Math.abs(c.balance)}</Badge>
                              )}
                          </div>
                      ))}
                      {filteredCustomers.length === 0 && (
                          <div className="text-center py-8 text-slate-400">NO SE ENCONTRARON CLIENTES</div>
                      )}
                  </div>
              </div>
          ) : (
              <form onSubmit={handleQuickCustomerAdd} className="space-y-4 pt-2">
                  <Input 
                      label="NOMBRE COMPLETO" 
                      value={newCustomerName}
                      onChange={e => setNewCustomerName(e.target.value.toUpperCase())}
                      placeholder="EJ. JUAN PÉREZ"
                      autoFocus
                  />
                  <Input 
                      label="TELÉFONO" 
                      value={newCustomerPhone}
                      onChange={e => setNewCustomerPhone(e.target.value)}
                      placeholder="EJ. 5512345678"
                      type="tel"
                  />
                  <Input 
                      label="DIRECCIÓN" 
                      value={newCustomerAddress}
                      onChange={e => setNewCustomerAddress(e.target.value.toUpperCase())}
                      placeholder="CALLE, NÚMERO, COLONIA"
                  />
                  <div className="pt-4 flex gap-3">
                      <Button type="button" variant="secondary" onClick={() => setCustomerViewMode('search')} className="flex-1 uppercase">VOLVER</Button>
                      <Button type="submit" className="flex-[2] uppercase">GUARDAR CLIENTE</Button>
                  </div>
              </form>
          )}
      </Modal>

      <DatePickerModal 
          isOpen={showDatePicker} 
          onClose={() => setShowDatePicker(false)} 
          title={datePickerMode === 'start' ? 'FECHA DE ENTREGA' : 'FECHA DE DEVOLUCIÓN'}
          onSelect={handleDateSelect}
      />

    </div>
  );
};

export default POS;

export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
  imageUrl?: string; // New field for product image
}

export interface Category {
  id?: string;
  name: string;
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface UserPermissions {
  canViewReports: boolean;
  canManageSettings: boolean; // Global settings
  canManageInventory: boolean; // Add/Edit/Delete products
  canManageUsers: boolean; // Add/Edit/Delete users
  canRefund: boolean; // Perform refunds
  canDeleteCustomers: boolean; // Delete customers
  canManageExpenses: boolean; // Access Expenses module
  canApplyDiscounts: boolean; // New: Apply coupons in POS
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff'; // Kept for legacy/fallback
  permissions?: UserPermissions; // Granular permissions
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
  cardFeePercentage: number;
  businessName?: string; // New: Custom business name
  businessTagline?: string; // New: Custom slogan/subtitle
  receiptTemplate?: 'v1' | 'v2'; // New: Template selector
  ticketPrefix?: string; // e.g. "26"
  nextTicketSequence?: number; // e.g. 1 (will result in 260001)
  logoUrl?: string; // New: Logo URL for POS empty state
}

export interface Expense {
  id?: string;
  concept: string;
  amount: number;
  createdAt: number;
  registeredBy?: string;
}

export interface Coupon {
  id?: string;
  code: string;
  type: 'percentage' | 'amount'; // % or $
  value: number;
  isActive: boolean;
}

export type TransactionType = 'sale' | 'rent';

export interface CartItem extends Product {
  cartId: string; // Unique ID for the item in cart
  transactionType: TransactionType;
  quantity: number;
  selectedVariation?: Variation;
  appliedPrice: number; // The actual price used for this item (base or variation)
}

export interface Order {
  id?: string;
  items: CartItem[];
  customer?: Customer; // Required if there are rentals
  total: number;
  status: 'pending' | 'completed' | 'returned' | 'late' | 'returned_late' | 'refunded' | 'reservation';
  createdAt: number; // Timestamp
  rentalStartDate?: number;
  rentalEndDate?: number;
  returnedAt?: number; // When it was actually returned
  lateFee?: number; // Fee charged if returned late
  paymentMethod?: 'cash' | 'card' | 'transfer';

  // Discount Fields
  discount?: number;
  discountReason?: string;

  // Reservation Fields
  downPayment?: number; // Amount paid upfront
  remainingBalance?: number; // Amount pending to pay
  finalizedAt?: number; // When the reservation was paid in full/picked up
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Search, ShoppingCart, Trash2, User, Plus, Minus, CreditCard, Calendar, X, Tag, Percent, Box, LayoutGrid, ArrowLeft, Layers, DollarSign, Archive, Shirt, Sparkles, Gift, Clock, ChevronRight, CheckCircle, Ticket, AlertCircle, Printer, TicketPercent } from 'lucide-react';
import { Product, CartItem, Customer, Order, Coupon, Variation, Category } from '../types';
import { getProducts, getCustomers, createOrder, addCustomer, updateCustomer, getCoupons, getSystemSettings, getCategories } from '../services/dataService';
import { Button, Input, Card, Modal, DatePickerModal, Select, Badge, ReceiptTemplate } from '../components/UI';

// Quick Access Item Interface
interface QuickAccessItem {
    id: string;
    label: string;
    type: 'category' | 'action' | 'product' | 'nav';
    value?: string; // Category Name or Product ID
    color: string;
    icon?: any;
    colSpan?: number;
}

const POS: React.FC = () => {
  const location = useLocation();

  // Data State
  const [products, setProducts] = useState<Product[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [dbCategories, setDbCategories] = useState<Category[]>([]);
  const [systemSettings, setSystemSettings] = useState<any>({});

  // View State
  const [viewMode, setViewMode] = useState<'home' | 'catalog'>('home');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('TODOS');

  // Cart State
  const [cart, setCart] = useState<CartItem[]>([]);
  const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);

  // --- MODAL & FLOW STATES ---
  // Customer
  const [showCustomerModal, setShowCustomerModal] = useState(false);
  const [customerSearch, setCustomerSearch] = useState('');
  const [customerViewMode, setCustomerViewMode] = useState<'search' | 'new'>('search');
  const [newCustomerName, setNewCustomerName] = useState('');
  const [newCustomerPhone, setNewCustomerPhone] = useState('');
  const [newCustomerAddress, setNewCustomerAddress] = useState('');
  const [editingCustomerId, setEditingCustomerId] = useState<string | null>(null);

  // Payment
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');
  const [amountPaid, setAmountPaid] = useState('');
  const [isApartadoMode, setIsApartadoMode] = useState(false); // New: Explicit Reservation Mode

  // Success Modal State
  const [showSuccessModal, setShowSuccessModal] = useState(false);
  const [lastOrder, setLastOrder] = useState<Order | null>(null);

  // Dates
  const [rentalStartDate, setRentalStartDate] = useState<string>(new Date().toISOString().split('T')[0]);
  const [rentalEndDate, setRentalEndDate] = useState<string>('');
  const [showDatePicker, setShowDatePicker] = useState(false);
  const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

  // Coupon Logic
  const [appliedCoupon, setAppliedCoupon] = useState<Coupon | null>(null);
  const [showCouponListModal, setShowCouponListModal] = useState(false); // New: Coupon List Modal

  // --- NEW STATES FOR LOGIC ---
  // Variation Selection
  const [showVariationModal, setShowVariationModal] = useState(false);
  const [pendingProduct, setPendingProduct] = useState<{ product: Product, type: 'sale' | 'rent' } | null>(null);

  // Zero Price / Manual Price
  const [showPriceInputModal, setShowPriceInputModal] = useState(false);
  const [manualPrice, setManualPrice] = useState('');
  const [pendingCartItem, setPendingCartItem] = useState<CartItem | null>(null);

  // Manual Item / Discount (Fallback)
  const [showManualItemModal, setShowManualItemModal] = useState(false);
  const [manualItemDesc, setManualItemDesc] = useState('');
  const [manualItemPrice, setManualItemPrice] = useState('');

  // Settings
  const [debtPaymentItem, setDebtPaymentItem] = useState<{ amount: number, ref: string } | null>(null);

  useEffect(() => {
    loadData();
    if (location.state && location.state.action === 'pay_late_fee') {
        const { customer, amount, refTicket } = location.state;
        if (customer) setCurrentCustomer(customer);
        if (amount) {
            setDebtPaymentItem({ amount, ref: refTicket });
        }
    }
  }, [location]);

  // Set default rental end date on mount
  useEffect(() => {
      calculateDefaultEndDate(rentalStartDate);
  }, [rentalStartDate]);

  const loadData = async () => {
    const [p, c, co, s, cats] = await Promise.all([
        getProducts(), 
        getCustomers(), 
        getCoupons(),
        getSystemSettings(),
        getCategories()
    ]);
    setProducts(p);
    setCustomers(c);
    setCoupons(co);
    setSystemSettings(s);
    setDbCategories(cats);
  };

  // --- DATE LOGIC ---

  // Helper to format date strictly for display: "05 FEB 26"
  const formatDateDisplay = (dateStr: string) => {
      if (!dateStr) return '';
      // Appending T12:00:00 forces it to midday local time, preventing timezone rollback (the "day before" issue)
      const date = new Date(dateStr + 'T12:00:00'); 
      return date.toLocaleDateString('es-MX', {
          day: '2-digit',
          month: 'short',
          year: '2-digit'
      }).toUpperCase().replace('.', '');
  };

  const calculateDefaultEndDate = (startDateStr: string) => {
      // Logic: Rent is 1 day. If return falls on Sunday, move to Monday.
      // Append time to ensure calculation happens in local day frame
      const start = new Date(startDateStr + 'T12:00:00');
      const end = new Date(start);
      end.setDate(end.getDate() + 1); // +1 Day default

      if (end.getDay() === 0) { // 0 is Sunday
          end.setDate(end.getDate() + 1); // Skip to Monday
      }
      setRentalEndDate(end.toISOString().split('T')[0]);
  };

  // --- DERIVED STATE ---
  const categories = useMemo(() => {
    // Merge DB categories with any categories found in products that might not be in DB yet
    const cats = new Set(dbCategories.map(c => c.name));
    products.forEach(p => { if(p.category) cats.add(p.category); });

    // Ensure the currently selected category is in the list
    if (selectedCategory !== 'TODOS') {
        cats.add(selectedCategory);
    }
    return ['TODOS', ...Array.from(cats).sort()];
  }, [products, dbCategories, selectedCategory]);

  const filteredProducts = products.filter(p => {
    const term = searchQuery.toUpperCase();
    const matchesSearch = p.name.toUpperCase().includes(term) || p.code.includes(term);

    // Smart Filter: Match Category Field OR Name contents
    let matchesCategory = selectedCategory === 'TODOS';
    if (!matchesCategory) {
        const catFilter = selectedCategory.toUpperCase();
        matchesCategory = p.category === catFilter || p.name.toUpperCase().includes(catFilter);
    }

    return matchesSearch && matchesCategory;
  });

  const filteredCustomers = customers.filter(c => 
      c.name.toLowerCase().includes(customerSearch.toLowerCase()) || 
      c.phone.includes(customerSearch)
  );

  // Detect Future Date for Reservation Suggestion
  const isFutureRental = useMemo(() => {
      const today = new Date();
      today.setHours(0,0,0,0);
      const start = new Date(rentalStartDate + 'T00:00:00'); // Force local time
      return start > today;
  }, [rentalStartDate]);

  // --- CART LOGIC ---

  const updateQuantity = (cartId: string, delta: number) => {
      setCart(prev => prev.map(item => {
          if (item.cartId === cartId) {
              const newQty = Math.max(1, item.quantity + delta);
              // Simple stock check (not robust for variants, but basic protection)
              if (delta > 0 && item.stock > 0 && newQty > item.stock) {
                  return item; // Don't increase
              }
              return { ...item, quantity: newQty };
          }
          return item;
      }));
  };

  const initiateAddToCart = (product: Product, type: 'sale' | 'rent') => {
      if (product.variations && product.variations.length > 0) {
          setPendingProduct({ product, type });
          setShowVariationModal(true);
          return;
      }
      checkPriceAndAdd(product, type, undefined);
  };

  const handleVariationSelect = (variation: Variation) => {
      if (!pendingProduct) return;
      setShowVariationModal(false);
      checkPriceAndAdd(pendingProduct.product, pendingProduct.type, variation);
      setPendingProduct(null);
  };

  const checkPriceAndAdd = (product: Product, type: 'sale' | 'rent', variation?: Variation) => {
      let price = 0;
      if (variation) {
          price = type === 'rent' ? (variation.rentalPrice || product.rentalPrice) : (variation.salePrice || product.salePrice);
      } else {
          price = type === 'rent' ? product.rentalPrice : product.salePrice;
      }

      // Check if exact item already exists to just increment
      const existingItem = cart.find(i => 
          i.id === product.id && 
          i.transactionType === type && 
          i.selectedVariation?.name === variation?.name
      );

      if (existingItem) {
          updateQuantity(existingItem.cartId, 1);
          return;
      }

      const newItem: CartItem = {
          ...product,
          cartId: Math.random().toString(36).substr(2, 9),
          transactionType: type,
          quantity: 1,
          selectedVariation: variation,
          appliedPrice: price
      };

      if (price === 0) {
          setPendingCartItem(newItem);
          setManualPrice('');
          setShowPriceInputModal(true);
      } else {
          finalizeAddToCart(newItem);
      }
  };

  const confirmManualPrice = () => {
      if (!pendingCartItem) return;
      const price = parseFloat(manualPrice);
      if (isNaN(price)) return; 

      const updatedItem = { ...pendingCartItem, appliedPrice: price };
      finalizeAddToCart(updatedItem);
      setShowPriceInputModal(false);
      setPendingCartItem(null);
      setManualPrice('');
  };

  const finalizeAddToCart = (item: CartItem) => {
      const existingInCart = cart.filter(i => i.id === item.id);
      const totalInCart = existingInCart.reduce((sum, i) => sum + i.quantity, 0);

      if (totalInCart >= item.stock && item.stock > 0) {
          alert("Stock insuficiente.");
          return;
      }
      setCart(prev => [...prev, item]);
  };

  const removeFromCart = (cartId: string) => setCart(cart.filter(i => i.cartId !== cartId));

  const clearCart = () => {
      setCart([]);
      setDebtPaymentItem(null);
      setAppliedCoupon(null);
      calculateDefaultEndDate(rentalStartDate); // Reset date logic
  };

  const handleApplyCoupon = (coupon: Coupon) => {
      setAppliedCoupon(coupon);
      setShowCouponListModal(false);
  };

  const handleRemoveCoupon = () => {
      setAppliedCoupon(null);
  };

  const handleAddManualItem = (e: React.FormEvent) => {
      e.preventDefault();
      const price = parseFloat(manualItemPrice);
      if (!manualItemDesc || isNaN(price)) {
          alert("Ingrese descripción y monto.");
          return;
      }

      const manualItem: CartItem = {
          id: 'manual-' + Date.now(),
          code: 'MANUAL',
          name: manualItemDesc.toUpperCase(),
          description: 'Concepto Manual',
          salePrice: price,
          rentalPrice: 0,
          category: 'OTROS',
          stock: 9999,
          variations: [],
          isRentalAvailable: false,
          isSaleAvailable: true,
          cartId: Math.random().toString(36).substr(2, 9),
          transactionType: 'sale',
          quantity: 1,
          appliedPrice: price
      };

      setCart(prev => [...prev, manualItem]);
      setShowManualItemModal(false);
      setManualItemDesc('');
      setManualItemPrice('');
  };

  const handleQuickAccessClick = (item: QuickAccessItem) => {
      if (item.type === 'category') {
          setSelectedCategory(item.value || 'TODOS');
          setSearchQuery('');
          setViewMode('catalog');
      } else if (item.type === 'nav' && item.value === 'all_products') {
          setSelectedCategory('TODOS');
          setSearchQuery('');
          setViewMode('catalog');
      } else if (item.type === 'action' && item.value === 'manual_discount') {
          // Open the Coupon Selection Modal instead of manual directly
          setShowCouponListModal(true);
      }
  };

  // --- CALCULATIONS & CHECKOUT ---
  const hasRentals = cart.some(i => i.transactionType === 'rent');

  // Calculate Extra Days Fee
  const extraDaysInfo = useMemo(() => {
      if (!hasRentals || !rentalEndDate) return { days: 0, fee: 0 };

      const start = new Date(rentalStartDate + 'T12:00:00');

      // Calculate Standard Return (Next Business Day)
      let standardReturn = new Date(start);
      standardReturn.setDate(standardReturn.getDate() + 1);
      if (standardReturn.getDay() === 0) standardReturn.setDate(standardReturn.getDate() + 1);

      const selectedReturn = new Date(rentalEndDate + 'T12:00:00');

      if (selectedReturn <= standardReturn) return { days: 0, fee: 0 };

      // Count business days (exclude Sundays) between standard and selected
      let extraDays = 0;
      let current = new Date(standardReturn);
      while (current < selectedReturn) {
          current.setDate(current.getDate() + 1);
          if (current.getDay() !== 0) { // Skip Sunday
              extraDays++;
          }
      }

      if (extraDays <= 0) return { days: 0, fee: 0 };

      const rentalItemsCount = cart.filter(i => i.transactionType === 'rent').reduce((sum, i) => sum + i.quantity, 0);
      const feePerDay = systemSettings.pricePerExtraDay || 0;
      const totalFee = extraDays * feePerDay * rentalItemsCount;

      return { days: extraDays, fee: totalFee };

  }, [rentalStartDate, rentalEndDate, hasRentals, cart, systemSettings]);

  const subtotal = useMemo(() => {
      let sum = cart.reduce((acc, item) => acc + (item.appliedPrice * item.quantity), 0);
      if (debtPaymentItem) sum += debtPaymentItem.amount;
      sum += extraDaysInfo.fee;
      return sum;
  }, [cart, debtPaymentItem, extraDaysInfo]);

  const discountAmount = useMemo(() => {
      if (!appliedCoupon) return 0;
      if (appliedCoupon.type === 'percentage') return subtotal * (appliedCoupon.value / 100);
      return appliedCoupon.value;
  }, [subtotal, appliedCoupon]);

  const totalBeforeFee = Math.max(0, subtotal - discountAmount);
  const cardFeeAmount = paymentMethod === 'card' ? totalBeforeFee * ((systemSettings.cardFeePercentage || 0) / 100) : 0;
  const total = totalBeforeFee + cardFeeAmount;

  // Initial Open of Payment Modal
  const handleOpenPayment = () => {
      if (cart.length === 0 && !debtPaymentItem) return;

      if (hasRentals && !currentCustomer) {
          alert("Es necesario seleccionar un cliente para rentas.");
          setShowCustomerModal(true);
          return;
      }
      if (hasRentals && !rentalEndDate) {
          alert("Selecciona fecha de devolución.");
          setDatePickerMode('end');
          setShowDatePicker(true);
          return;
      }

      // Logic to auto-suggest Reservation if date is future
      setIsApartadoMode(isFutureRental); 
      setAmountPaid('');
      setPaymentModalOpen(true);
  };

  const handleCheckout = async () => {
      const paid = parseFloat(amountPaid) || 0;

      // Validation Logic
      if (isApartadoMode) {
          if (paid <= 0) {
              alert("Para apartar se requiere un anticipo mayor a 0.");
              return;
          }
          if (paid >= total) {
              // If they pay full amount, warn them but allow. It effectively acts as a paid reservation.
              // alert("El monto cubre el total. Se registrará como pagado.");
          }
      } else {
          // Standard Sale Mode
          if (Math.abs(paid - total) > 0.5 && paid < total) { // Allow tiny diff for rounding
              alert("Monto incompleto. Si es un abono, active la opción 'ES UN APARTADO'.");
              return;
          }
          if (paid <= 0 && total > 0) {
              alert("Ingrese monto pagado.");
              return;
          }
      }

      try {
          // Clone cart items to modify if needed
          const finalItems = [...cart];

          // INJECT EXTRA DAYS FEE AS A CART ITEM
          if (extraDaysInfo.fee > 0) {
              finalItems.push({
                  id: 'extraday-' + Date.now(),
                  code: 'EXTRA',
                  name: `DÍAS EXTRA (${extraDaysInfo.days} DÍAS)`,
                  description: 'Costo por días adicionales de renta',
                  salePrice: extraDaysInfo.fee,
                  rentalPrice: 0,
                  category: 'SERVICIOS',
                  stock: 9999,
                  variations: [],
                  isRentalAvailable: false,
                  isSaleAvailable: true,
                  cartId: 'extraday-fee-item',
                  transactionType: 'sale', // It's a fee, treated as sale
                  quantity: 1,
                  appliedPrice: extraDaysInfo.fee
              });
          }

          const orderData: any = {
              items: finalItems,
              customer: currentCustomer || undefined,
              total: total,
              // Status determination
              status: isApartadoMode ? 'reservation' : 'completed', // Default completed, overridden if rent active
              paymentMethod: paymentMethod,
              createdAt: Date.now(),
              // Save discount info for receipts
              discount: discountAmount,
              discountReason: appliedCoupon ? `CUPÓN: ${appliedCoupon.code}` : (discountAmount > 0 ? 'DESCUENTO' : undefined)
          };

          if (hasRentals) {
              orderData.rentalStartDate = new Date(rentalStartDate + 'T12:00:00').getTime();
              orderData.rentalEndDate = new Date(rentalEndDate + 'T12:00:00').getTime();

              // If standard mode and has rentals, it's 'pending' (Active Rent) not completed
              if (!isApartadoMode) {
                  orderData.status = 'pending'; // Active Rental
              }
          }

          if (isApartadoMode) {
              orderData.downPayment = paid;
              orderData.remainingBalance = total - paid;
          } else {
              // Paid in full
              orderData.remainingBalance = 0;
          }

          if (debtPaymentItem && currentCustomer && currentCustomer.id) {
             const currentBal = currentCustomer.balance || 0;
             await updateCustomer(currentCustomer.id, {
                 balance: currentBal + debtPaymentItem.amount
             });
          }

          const newOrder = await createOrder(orderData);

          // SUCCESS HANDLER
          setLastOrder(newOrder as Order); // Cast needed as createOrder returns id
          setPaymentModalOpen(false);
          setShowSuccessModal(true); // Open Success Modal

          // Clear cart immediately so UI behind modal is clean
          clearCart();
          setAmountPaid('');
          setCurrentCustomer(null);
          setViewMode('home');

      } catch (e) {
          console.error(e);
          alert("Error al procesar venta");
      }
  };

  const handlePrintReceipt = () => {
      window.print();
  };

  const handleCloseSuccess = () => {
      setShowSuccessModal(false);
      setLastOrder(null);
  };

  // --- CUSTOMER LOGIC ---
  const handleSetCustomer = (customer: Customer) => {
      setCurrentCustomer(customer);
      setShowCustomerModal(false);
      setCustomerSearch('');
  };
  const handleQuickCustomerAdd = async (e?: React.FormEvent) => {
      if (e) e.preventDefault();
      if(!newCustomerName || !newCustomerPhone || !newCustomerAddress) {
          alert("Todos los datos son obligatorios.");
          return;
      }
      const customerData = { name: newCustomerName.toUpperCase(), phone: newCustomerPhone, address: newCustomerAddress.toUpperCase() };
      let resultCustomer: Customer;
      try {
        if (editingCustomerId) {
            await updateCustomer(editingCustomerId, customerData);
            resultCustomer = { ...customerData, id: editingCustomerId };
            setCustomers(prev => prev.map(c => c.id === editingCustomerId ? resultCustomer : c));
        } else {
            const saved = await addCustomer(customerData);
            resultCustomer = saved;
            setCustomers([...customers, saved]);
        }
        handleSetCustomer(resultCustomer);
        setShowCustomerModal(false);
        setNewCustomerName(''); setNewCustomerPhone(''); setNewCustomerAddress(''); setEditingCustomerId(null); setCustomerViewMode('search');
      } catch (e) { alert("Error al guardar cliente"); }
  };
  const openNewCustomerForm = () => {
      setCustomerViewMode('new');
      setNewCustomerName(customerSearch.toUpperCase());
      setNewCustomerPhone('');
      setNewCustomerAddress('');
      setEditingCustomerId(null);
  };
  // Dates
  const handleDateSelect = (date: string) => {
      if (datePickerMode === 'start') {
          setRentalStartDate(date);
          calculateDefaultEndDate(date);
      } else {
          setRentalEndDate(date);
      }
  };

  // --- DYNAMIC QUICK ACCESS ITEMS ---
  const quickAccessItems = useMemo(() => {
    // 1. Static Actions
    const items: QuickAccessItem[] = [
        { id: 'discount', label: 'AGREGAR DESCUENTO', type: 'action', value: 'manual_discount', color: 'bg-gradient-to-br from-orange-400 to-amber-500 text-white', icon: Tag, colSpan: 1 },
        { id: 'catalog', label: 'VER TODO EL CATÁLOGO', type: 'nav', value: 'all_products', color: 'bg-white border-2 border-slate-200 text-slate-700', icon: Box, colSpan: 1 },
    ];

    // 2. Map Registered Categories
    // We sort them so they appear in a consistent order (alphabetical usually)
    const sortedCats = [...dbCategories].sort((a,b) => a.name.localeCompare(b.name));

    const catItems = sortedCats.map((cat, index) => {
        // Cycle through a palette of 2026-ish colors
        const colors = [
            'bg-indigo-50 text-indigo-700 border border-indigo-100',
            'bg-emerald-50 text-emerald-700 border border-emerald-100',
            'bg-blue-50 text-blue-700 border border-blue-100',
            'bg-purple-50 text-purple-700 border border-purple-100',
            'bg-rose-50 text-rose-700 border border-rose-100',
            'bg-amber-50 text-amber-700 border border-amber-100',
            'bg-teal-50 text-teal-700 border border-teal-100',
            'bg-cyan-50 text-cyan-700 border border-cyan-100',
        ];

        const colorClass = colors[index % colors.length];

        return {
            id: cat.id || `cat-${index}`,
            label: cat.name, // Display Registered Name
            type: 'category',
            value: cat.name, // Value to filter by
            color: colorClass,
            icon: Shirt, // Generic Icon
            colSpan: 1
        } as QuickAccessItem;
    });

    return [...items, ...catItems];
  }, [dbCategories]);

  return (
    <div className="h-full flex flex-col lg:flex-row overflow-hidden bg-slate-100">

      {/* --- HIDDEN RECEIPT TEMPLATE FOR PRINTING --- */}
      <ReceiptTemplate order={lastOrder} settings={systemSettings} />

      {/* LEFT: Dynamic Content (Home or Catalog) */}
      <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200 relative">

        {/* VIEW: HOME (Quick Access) */}
        {viewMode === 'home' && (
            <div className="h-full overflow-y-auto p-4 md:p-8 animate-in fade-in zoom-in-95 duration-300">
                <div className="flex items-center gap-3 mb-6">
                    <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-200">
                        <LayoutGrid className="w-6 h-6 text-white" />
                    </div>
                    <div>
                        <h1 className="text-2xl font-black text-slate-800 uppercase tracking-tight">Inicio</h1>
                        <p className="text-slate-500 uppercase text-xs font-bold tracking-widest">Accesos Rápidos</p>
                    </div>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4 auto-rows-[140px]">
                    {quickAccessItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => handleQuickAccessClick(item)}
                            className={`rounded-3xl p-6 relative group overflow-hidden transition-all hover:scale-[1.02] active:scale-95 shadow-sm hover:shadow-xl flex flex-col justify-between items-start text-left ${item.color} ${item.colSpan === 2 ? 'col-span-2' : 'col-span-1'}`}
                        >
                            <item.icon className="absolute -right-4 -bottom-4 w-32 h-32 opacity-10 group-hover:rotate-12 transition-transform" />
                            <div className="p-2 bg-white/20 backdrop-blur-md rounded-2xl">
                                <item.icon className="w-6 h-6" />
                            </div>
                            <span className="font-black uppercase text-sm md:text-base leading-tight max-w-[80%] z-10 line-clamp-2">
                                {item.label}
                            </span>
                        </button>
                    ))}
