                    {/* Discount Line for V2 */}
                    {discountValue > 0 && !isReservation && (
                        <div className="w-full text-[9px] font-bold opacity-80 flex justify-between border-b border-white/20 pb-1 mb-1">
                            <span>DESC:</span>
