  // --- DYNAMIC QUICK ACCESS ITEMS ---
  const quickAccessItems = useMemo(() => {
    // 1. Static Actions
    const items: QuickAccessItem[] = [
        { id: 'discount', label: 'AGREGAR DESCUENTO', type: 'action', value: 'manual_discount', color: 'bg-gradient-to-br from-orange-400 to-amber-500 text-white', icon: Tag, colSpan: 1 },
        { id: 'catalog', label: 'VER TODO EL CATÁLOGO', type: 'nav', value: 'all_products', color: 'bg-white border-2 border-slate-200 text-slate-700', icon: Box, colSpan: 1 },
    ];

    // 2. Map Registered Categories
    // We sort them so they appear in a consistent order (alphabetical usually)
    const sortedCats = [...dbCategories].sort((a,b) => a.name.localeCompare(b.name));

    const catItems = sortedCats.map((cat, index) => {
        // Cycle through a palette of 2026-ish colors
        const colors = [
            'bg-indigo-50 text-indigo-700 border border-indigo-100',
            'bg-emerald-50 text-emerald-700 border border-emerald-100',
            'bg-blue-50 text-blue-700 border border-blue-100',
            'bg-purple-50 text-purple-700 border border-purple-100',
            'bg-rose-50 text-rose-700 border border-rose-100',
            'bg-amber-50 text-amber-700 border border-amber-100',
            'bg-teal-50 text-teal-700 border border-teal-100',
            'bg-cyan-50 text-cyan-700 border border-cyan-100',
        ];

        const colorClass = colors[index % colors.length];

        return {
            id: cat.id || `cat-${index}`,
            label: cat.name, // Display Registered Name
            type: 'category',
            value: cat.name, // Value to filter by
            color: colorClass,
            icon: Shirt, // Generic Icon
            colSpan: 1
