          <form onSubmit={handleAddManualItem} className="space-y-6 pt-2">
              <Input 
                  label="DESCRIPCIÓN DEL CONCEPTO"
                  value={manualItemDesc}
                  onChange={(e) => setManualItemDesc(e.target.value.toUpperCase())}
                  placeholder="EJ. DESCUENTO POR DAÑO, AJUSTE, ETC."
                  autoFocus
              />
              <div className="space-y-2">
                  <Input 
                    label="MONTO (USE MENOS (-) PARA DESCUENTOS)"
                    type="number"
                    value={manualItemPrice}
                    onChange={(e) => setManualItemPrice(e.target.value)}
                    placeholder="-50.00"
                    className="text-2xl font-bold"
                  />
