import React, { useState, useEffect, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Search, ShoppingCart, User, Calendar, Trash2, Plus, Minus, X, CreditCard, Banknote, ArrowUpRight, Tag, RotateCcw } from 'lucide-react';
import { Button, Input, Card, Modal, DatePickerModal, Badge } from '../components/UI';
import { Product, Customer, CartItem, Variation, Coupon } from '../types';
import { getProducts, getCustomers, createOrder, updateCustomer, getCoupons } from '../services/dataService';

const POS: React.FC = () => {
    const location = useLocation();

    // Data State
    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [coupons, setCoupons] = useState<Coupon[]>([]);
    const [loading, setLoading] = useState(true);

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);
    const [isApartadoMode, setIsApartadoMode] = useState(false);

    // Dates for Rental
    const [rentalStartDate, setRentalStartDate] = useState<number | undefined>(undefined);
    const [rentalEndDate, setRentalEndDate] = useState<number | undefined>(undefined);

    // Debt / Late Fee State (from Returns page)
    const [debtPaymentItem, setDebtPaymentItem] = useState<{amount: number, refTicket: string} | null>(null);

    // Modals
    const [showPaymentModal, setPaymentModalOpen] = useState(false);
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDatePicker, setShowDatePicker] = useState(false);
    const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

    // Payment Form
    const [amountPaid, setAmountPaid] = useState('');
    const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');

    // Discount
    const [discountCode, setDiscountCode] = useState('');
    const [appliedDiscount, setAppliedDiscount] = useState<{amount: number, reason: string} | null>(null);

    // Load Data
    useEffect(() => {
        const init = async () => {
            setLoading(true);
            const [p, c, cp] = await Promise.all([getProducts(), getCustomers(), getCoupons()]);
            setProducts(p);
            setCustomers(c);
            setCoupons(cp);
            setLoading(false);
        };
        init();
    }, []);

    // Check for incoming state (Late Fee Payment)
    useEffect(() => {
        if (location.state && location.state.action === 'pay_late_fee') {
            const { customer, amount, refTicket } = location.state;
            if (customer) setCurrentCustomer(customer);
            setDebtPaymentItem({ amount, refTicket });
        }
    }, [location.state]);

    // Computed
    const cartTotal = useMemo(() => {
        return cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
    }, [cart]);

    const total = useMemo(() => {
        let base = cartTotal;
        if (debtPaymentItem) base += debtPaymentItem.amount;
        if (appliedDiscount) base -= appliedDiscount.amount;
        return Math.max(0, base);
    }, [cartTotal, debtPaymentItem, appliedDiscount]);

    const hasRentals = useMemo(() => cart.some(i => i.transactionType === 'rent'), [cart]);

    // Cart Actions
    const addToCart = (product: Product, variation?: Variation, type: 'sale' | 'rent' = 'sale') => {
        const price = variation 
            ? (type === 'sale' ? variation.salePrice : variation.rentalPrice) 
            : (type === 'sale' ? product.salePrice : product.rentalPrice);

        const finalPrice = price || 0;

        const newItem: CartItem = {
            ...product,
            cartId: Math.random().toString(36).substr(2, 9),
            transactionType: type,
            quantity: 1,
            selectedVariation: variation,
            appliedPrice: finalPrice
        };

        setCart(prev => [...prev, newItem]);
        setSearchQuery(''); // Clear search after adding
    };

    const removeFromCart = (cartId: string) => {
        setCart(prev => prev.filter(i => i.cartId !== cartId));
    };

    const updateQuantity = (cartId: string, delta: number) => {
        setCart(prev => prev.map(item => {
            if (item.cartId === cartId) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

