                            </Button>
                        </div>
                    </form>
                 )}
            </Modal>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setPaymentModalOpen(false)} title={isApartadoMode ? "CONFIRMAR APARTADO" : "COBRAR"}>
                 <div className="space-y-6">
                    <div className="text-center">
                        <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">TOTAL A PAGAR</div>
                        <div className="text-5xl font-black text-slate-900 font-mono">${total.toFixed(2)}</div>
                    </div>

                    <div className="flex bg-slate-100 p-1 rounded-2xl">
                        <button onClick={() => setPaymentMethod('cash')} className={`flex-1 py-4 rounded-xl font-bold uppercase text-sm transition-all flex flex-col items-center gap-1 ${paymentMethod === 'cash' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
