};

import React, { useState, useEffect, useMemo } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Search, ShoppingCart, User, Calendar, Trash2, Plus, Minus, X, CreditCard, Banknote, ArrowUpRight, Tag, RotateCcw, UserPlus, Save, ArrowLeft } from 'lucide-react';
import { Button, Input, Card, Modal, DatePickerModal, Badge } from '../components/UI';
import { Product, Customer, CartItem, Variation, Coupon } from '../types';
import { getProducts, getCustomers, createOrder, updateCustomer, getCoupons, addCustomer } from '../services/dataService';

const POS: React.FC = () => {
    const location = useLocation();

    // Data State
    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [coupons, setCoupons] = useState<Coupon[]>([]);
    const [loading, setLoading] = useState(true);

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);
    const [isApartadoMode, setIsApartadoMode] = useState(false);

    // Customer Modal State
    const [customerViewMode, setCustomerViewMode] = useState<'search' | 'new'>('search');
    const [newCustomerName, setNewCustomerName] = useState('');
    const [newCustomerPhone, setNewCustomerPhone] = useState('');
    const [newCustomerAddress, setNewCustomerAddress] = useState('');

    // Dates for Rental
    const [rentalStartDate, setRentalStartDate] = useState<number | undefined>(undefined);
    const [rentalEndDate, setRentalEndDate] = useState<number | undefined>(undefined);

    // Debt / Late Fee State (from Returns page)
    const [debtPaymentItem, setDebtPaymentItem] = useState<{amount: number, refTicket: string} | null>(null);

    // Modals
    const [showPaymentModal, setPaymentModalOpen] = useState(false);
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDatePicker, setShowDatePicker] = useState(false);
    const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

    // Payment Form
    const [amountPaid, setAmountPaid] = useState('');
    const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');

    // Discount
    const [discountCode, setDiscountCode] = useState('');
    const [appliedDiscount, setAppliedDiscount] = useState<{amount: number, reason: string} | null>(null);

    // Load Data
    useEffect(() => {
        const init = async () => {
            setLoading(true);
            const [p, c, cp] = await Promise.all([getProducts(), getCustomers(), getCoupons()]);
            setProducts(p);
            setCustomers(c);
            setCoupons(cp);
            setLoading(false);
        };
        init();
    }, []);

    // Check for incoming state (Late Fee Payment)
    useEffect(() => {
        if (location.state && location.state.action === 'pay_late_fee') {
            const { customer, amount, refTicket } = location.state;
            if (customer) setCurrentCustomer(customer);
            setDebtPaymentItem({ amount, refTicket });
        }
    }, [location.state]);

    // Reset customer modal state when closed/opened
    useEffect(() => {
        if (showCustomerModal) {
            setCustomerViewMode('search');
            setCustomerSearch('');
        }
    }, [showCustomerModal]);

    // Computed
    const cartTotal = useMemo(() => {
        return cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
    }, [cart]);

    const total = useMemo(() => {
        let base = cartTotal;
        if (debtPaymentItem) base += debtPaymentItem.amount;
        if (appliedDiscount) base -= appliedDiscount.amount;
        return Math.max(0, base);
    }, [cartTotal, debtPaymentItem, appliedDiscount]);

    const hasRentals = useMemo(() => cart.some(i => i.transactionType === 'rent'), [cart]);

    // Cart Actions
    const addToCart = (product: Product, variation?: Variation, type: 'sale' | 'rent' = 'sale') => {
        const price = variation 
            ? (type === 'sale' ? variation.salePrice : variation.rentalPrice) 
            : (type === 'sale' ? product.salePrice : product.rentalPrice);

        const finalPrice = price || 0;

        const newItem: CartItem = {
            ...product,
            cartId: Math.random().toString(36).substr(2, 9),
            transactionType: type,
            quantity: 1,
            selectedVariation: variation,
            appliedPrice: finalPrice
        };

        setCart(prev => [...prev, newItem]);
        setSearchQuery(''); // Clear search after adding
    };

    const removeFromCart = (cartId: string) => {
        setCart(prev => prev.filter(i => i.cartId !== cartId));
    };

    const updateQuantity = (cartId: string, delta: number) => {
        setCart(prev => prev.map(item => {
            if (item.cartId === cartId) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

    const handleApplyCoupon = () => {
        if (!discountCode.trim()) return;
        const coupon = coupons.find(c => c.code === discountCode.toUpperCase() && c.isActive);

        if (!coupon) {
            alert("Cupón no válido o expirado");
            setDiscountCode('');
            return;
        }

        let discountAmount = 0;
        if (coupon.type === 'percentage') {
            discountAmount = (cartTotal * coupon.value) / 100;
        } else {
            discountAmount = coupon.value;
        }

        // Cap discount at total
        discountAmount = Math.min(discountAmount, cartTotal);

        setAppliedDiscount({ amount: discountAmount, reason: coupon.code });
        setDiscountCode('');
    };

    const clearDiscount = () => {
        setAppliedDiscount(null);
    };

    // Dates
    const handleDateSelect = (dateStr: string) => {
        const timestamp = new Date(dateStr + 'T12:00:00').getTime(); // Noon to avoid timezone shifts
        if (datePickerMode === 'start') {
            setRentalStartDate(timestamp);
        } else {
            setRentalStartDate(prev => prev || Date.now()); // If no start date, set today
            setRentalEndDate(timestamp);
        }
    };

    // Payment Logic
    const handleOpenPayment = () => {
        if (cart.length === 0 && !debtPaymentItem) return;

        // Combined check: Rentals OR Apartado require customer
        if ((hasRentals || isApartadoMode) && !currentCustomer) {
            alert(isApartadoMode ? "Es necesario seleccionar un cliente para apartar." : "Es necesario seleccionar un cliente para rentas.");
            setShowCustomerModal(true);
            return;
        }

        if (hasRentals && !rentalEndDate) {
            alert("Selecciona fecha de devolución.");
            setDatePickerMode('end');
            setShowDatePicker(true);
            return;
        }

        setAmountPaid('');
        setPaymentModalOpen(true);
    };

    const handleCheckout = async () => {
        const paid = parseFloat(amountPaid) || 0;

        // Validation Logic
        if (isApartadoMode) {
            if (!currentCustomer) {
                alert("Para realizar un apartado es obligatorio asignar un cliente.");
                setPaymentModalOpen(false); 
                setShowCustomerModal(true); 
                return;
            }

            if (paid <= 0) {
                alert("Para apartar se requiere un anticipo mayor a 0.");
                return;
            }
        } else {
            // Standard Sale Mode
            if (Math.abs(paid - total) > 0.5 && paid < total) { 
                alert("Monto incompleto. Si es un abono, active la opción 'ES UN APARTADO'.");
                return;
            }
            if (paid <= 0 && total > 0) {
                alert("Ingrese monto pagado.");
                return;
            }
        }

        try {
            const finalItems = [...cart];

            // Debt Item Payment Logic
            if (debtPaymentItem) {
                 if (currentCustomer && currentCustomer.id) {
                     const newBalance = (currentCustomer.balance || 0) + debtPaymentItem.amount;
                     await updateCustomer(currentCustomer.id, { balance: newBalance });
                 }
            }

            const orderData: any = {
                items: finalItems,
                customer: currentCustomer || undefined,
                total: total,
                status: isApartadoMode ? 'reservation' : (hasRentals ? 'pending' : 'completed'), 
                createdAt: Date.now(),
                paymentMethod: paymentMethod,
                discount: appliedDiscount?.amount,
                discountReason: appliedDiscount?.reason
            };

            if (isApartadoMode) {
                orderData.status = 'reservation';
                orderData.downPayment = paid;
                orderData.remainingBalance = total - paid;
                orderData.rentalStartDate = rentalStartDate; 
                orderData.rentalEndDate = rentalEndDate;
            } else if (hasRentals) {
                orderData.status = 'pending'; // Active rental
                orderData.rentalStartDate = rentalStartDate || Date.now();
                orderData.rentalEndDate = rentalEndDate;
            } else {
                orderData.status = 'completed';
            }

            await createOrder(orderData);

            alert(isApartadoMode ? "Apartado registrado exitosamente." : "Venta registrada exitosamente.");

            // Reset
            setCart([]);
            setCurrentCustomer(null);
            setDebtPaymentItem(null);
            setAppliedDiscount(null);
            setPaymentModalOpen(false);
            setIsApartadoMode(false);
            setRentalEndDate(undefined);
            setRentalStartDate(undefined);

        } catch (e) {
            console.error(e);
            alert("Error al procesar la venta.");
        }
    };

    // UI Helpers
    const filteredProducts = useMemo(() => {
        if (!searchQuery) return [];
        const q = searchQuery.toUpperCase();
        return products.filter(p => p.name.includes(q) || p.code.includes(q));
    }, [products, searchQuery]);

    // Customer Selection inside Modal
    const [customerSearch, setCustomerSearch] = useState('');

    // Updated Logic: Only return customers if search string is not empty
    const modalCustomers = useMemo(() => {
        if (!customerSearch.trim()) return [];
        const q = customerSearch.toUpperCase();
        return customers.filter(c => c.name.includes(q) || c.phone.includes(q));
    }, [customers, customerSearch]);

    // NEW CUSTOMER LOGIC
    const handleSwitchToRegister = () => {
        setNewCustomerName(customerSearch);
        setNewCustomerPhone('');
        setNewCustomerAddress('');
        setCustomerViewMode('new');
    };

    const handleRegisterCustomer = async (e: React.FormEvent) => {
        e.preventDefault();

        // Strict Validation
        if(!newCustomerName.trim() || !newCustomerPhone.trim() || !newCustomerAddress.trim()) {
            alert("Faltan datos. El Nombre, Teléfono y Dirección son obligatorios.");
            return;
        }

        try {
            const newCustomerData = {
                name: newCustomerName.toUpperCase().trim(),
                phone: newCustomerPhone.trim(),
                address: newCustomerAddress.toUpperCase().trim(),
                balance: 0
            };
            const createdCustomer = await addCustomer(newCustomerData);

            // 1. Update local list
            setCustomers(prev => [...prev, createdCustomer]);
            // 2. Assign to ticket
            setCurrentCustomer(createdCustomer);
            // 3. Close modal
            setShowCustomerModal(false);

            // Reset form
            setCustomerViewMode('search');
            setCustomerSearch('');

        } catch(e) {
            console.error(e);
            alert("Error al registrar cliente.");
        }
    };

    return (
        <div className="flex h-full flex-col lg:flex-row bg-white overflow-hidden">
            {/* LEFT: Product Selection */}
            <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200">
                {/* Search Header */}
                <div className="p-4 bg-white border-b border-slate-100 flex gap-4">
                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                        <input 
                            type="text" 
                            placeholder="BUSCAR PRODUCTOS..." 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                            className="w-full pl-12 pr-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500/20 uppercase"
                            autoFocus
                        />
                    </div>
                </div>

                {/* Product Grid */}
                <div className="flex-1 overflow-y-auto p-4 bg-slate-50/50">
                    {searchQuery ? (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                            {filteredProducts.map(product => (
                                <div key={product.id} className="bg-white rounded-2xl p-3 shadow-sm border border-slate-200 hover:shadow-md transition-all flex flex-col justify-between group">
                                    <div>
                                        {/* Image placeholder or real image if available */}
                                        <div className="h-24 bg-slate-100 rounded-xl mb-2 flex items-center justify-center overflow-hidden relative">
                                            {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover" alt={product.name}/> : <Tag className="text-slate-300 w-8 h-8"/>}
                                            <div className="absolute top-1 right-1">
                                                 <Badge>{product.category}</Badge>
                                            </div>
                                        </div>
                                        <div className="font-bold text-slate-800 uppercase text-sm leading-tight mb-1">{product.name}</div>
                                        <div className="text-xs text-slate-500 font-mono mb-2">{product.code}</div>
                                    </div>

                                    <div className="mt-auto space-y-2">
                                        {/* Base Actions */}
                                        <div className="grid grid-cols-2 gap-2">
                                            {product.isSaleAvailable && (
                                                <button onClick={() => addToCart(product, undefined, 'sale')} className="bg-emerald-50 text-emerald-700 py-2 rounded-lg text-xs font-bold hover:bg-emerald-100 transition-colors uppercase">
                                                    Venta ${product.salePrice}
                                                </button>
                                            )}
                                            {product.isRentalAvailable && (
                                                <button onClick={() => addToCart(product, undefined, 'rent')} className="bg-indigo-50 text-indigo-700 py-2 rounded-lg text-xs font-bold hover:bg-indigo-100 transition-colors uppercase">
                                                    Renta ${product.rentalPrice}
                                                </button>
                                            )}
                                        </div>

                                        {/* Variations */}
                                        {product.variations && product.variations.length > 0 && (
                                            <div className="border-t border-slate-100 pt-2 flex flex-wrap gap-1">
                                                {product.variations.map((v, i) => (
                                                    <button 
                                                        key={i}
                                                        onClick={() => addToCart(product, v, product.isRentalAvailable ? 'rent' : 'sale')} 
                                                        className="px-2 py-1 bg-slate-100 hover:bg-slate-200 rounded text-[10px] uppercase text-slate-600 font-bold"
                                                    >
                                                        {v.name}
                                                    </button>
                                                ))}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                            {filteredProducts.length === 0 && (
                                <div className="col-span-full text-center py-10 text-slate-400 uppercase">No se encontraron productos</div>
                            )}
                        </div>
                    ) : (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300">
                            <Search className="w-16 h-16 mb-4 opacity-20" />
                            <p className="uppercase font-bold">Usa el buscador para agregar productos</p>
                        </div>
                    )}
                </div>
            </div>

            {/* RIGHT: Cart & Checkout */}
            <div className="w-full lg:w-[400px] xl:w-[450px] bg-white border-l border-slate-200 flex flex-col h-full shadow-2xl shadow-slate-200 z-10">
                {/* Customer Bar */}
                <div 
                    className={`p-4 border-b border-slate-100 flex justify-between items-center cursor-pointer hover:bg-slate-50 transition-colors ${!currentCustomer ? 'bg-slate-50' : 'bg-indigo-50/50'}`}
                    onClick={() => setShowCustomerModal(true)}
                >
                    <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentCustomer ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                            <User className="w-5 h-5" />
                        </div>
                        <div>
                            <div className="font-bold text-slate-800 uppercase text-sm">{currentCustomer ? currentCustomer.name : 'SELECCIONAR CLIENTE'}</div>
                            <div className="text-xs text-slate-500 font-mono">{currentCustomer?.phone || 'CLIENTE MOSTRADOR'}</div>
                        </div>
                    </div>
                    {currentCustomer && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); setCurrentCustomer(null); }}
                            className="p-1 text-slate-400 hover:text-rose-500"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>

                {/* Rental Dates (If Rentals present) */}
                {hasRentals && (
                    <div className="p-3 bg-indigo-50 border-b border-indigo-100 grid grid-cols-2 gap-2">
                        <div onClick={() => { setDatePickerMode('start'); setShowDatePicker(true); }} className="bg-white p-2 rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300">
                            <span className="text-[10px] font-bold text-indigo-400 uppercase block">ENTREGA</span>
                            <span className="text-sm font-bold text-indigo-900 block">
                                {rentalStartDate ? new Date(rentalStartDate).toLocaleDateString() : 'HOY'}
                            </span>
                        </div>
                        <div onClick={() => { setDatePickerMode('end'); setShowDatePicker(true); }} className="bg-white p-2 rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300">
                            <span className="text-[10px] font-bold text-indigo-400 uppercase block">DEVOLUCIÓN</span>
                            <span className={`text-sm font-bold block ${rentalEndDate ? 'text-indigo-900' : 'text-slate-300'}`}>
                                {rentalEndDate ? new Date(rentalEndDate).toLocaleDateString() : 'SELECCIONAR'}
                            </span>
                        </div>
                    </div>
                )}

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {/* Special Debt Item */}
                    {debtPaymentItem && (
                         <div className="flex justify-between items-center p-3 bg-rose-50 rounded-xl border border-rose-100 animate-in slide-in-from-right">
                             <div className="flex items-center gap-3">
                                 <div className="p-2 bg-white rounded-lg text-rose-500"><RotateCcw className="w-4 h-4"/></div>
                                 <div>
                                     <div className="font-bold text-rose-800 text-sm uppercase">PAGO DE RECARGO</div>
                                     <div className="text-xs text-rose-600 font-mono">TICKET REF: #{debtPaymentItem.refTicket}</div>
                                 </div>
                             </div>
                             <div className="flex items-center gap-3">
                                <div className="font-mono font-bold text-rose-700">${debtPaymentItem.amount.toFixed(2)}</div>
                                <button onClick={() => setDebtPaymentItem(null)} className="text-rose-300 hover:text-rose-600"><X className="w-4 h-4"/></button>
                             </div>
                         </div>
                    )}

                    {cart.map((item) => (
                        <div key={item.cartId} className="flex justify-between items-center p-2 group hover:bg-slate-50 rounded-xl transition-colors">
                            <div className="flex-1 min-w-0 pr-2">
                                <div className="font-bold text-slate-800 text-sm uppercase truncate">
                                    {item.name} {item.selectedVariation ? `(${item.selectedVariation.name})` : ''}
                                </div>
                                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                                    </Badge>
                                    <span className="font-mono">${item.appliedPrice} c/u</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <div className="flex items-center bg-slate-100 rounded-lg">
                                    <button onClick={() => updateQuantity(item.cartId, -1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-l-lg disabled:opacity-50" disabled={item.quantity <= 1}><Minus className="w-3 h-3" /></button>
                                    <span className="w-6 text-center text-xs font-bold">{item.quantity}</span>
                                    <button onClick={() => updateQuantity(item.cartId, 1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                </div>
                                <div className="font-mono font-bold text-slate-800 w-16 text-right">
                                    ${(item.appliedPrice * item.quantity).toFixed(2)}
                                </div>
                                <button onClick={() => removeFromCart(item.cartId)} className="text-slate-300 hover:text-rose-500 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Trash2 className="w-4 h-4" />
                                </button>
