const Inventory: React.FC<{ user: User }> = ({ user }) => {
  const [view, setView] = useState<'list' | 'form'>('list');
  // Default to 'table' (List view) as requested
  const [displayMode, setDisplayMode] = useState<'grid' | 'table'>('table'); 
