export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Search, ShoppingCart, User, Calendar, Trash2, Plus, Minus, X, CreditCard, Banknote, ArrowUpRight, Tag, RotateCcw, UserPlus, Save, ArrowLeft, LayoutGrid, ListFilter, Percent, ChevronLeft, Box, DollarSign } from 'lucide-react';
import { Button, Input, Modal, DatePickerModal, Badge } from '../components/UI';
import { Product, Customer, CartItem, Variation, Coupon, Category } from '../types';
import { getProducts, getCustomers, createOrder, updateCustomer, getCoupons, addCustomer, getCategories } from '../services/dataService';

const POS: React.FC = () => {
    const location = useLocation();

    // Data State
    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [coupons, setCoupons] = useState<Coupon[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [loading, setLoading] = useState(true);

    // View State
    const [viewMode, setViewMode] = useState<'categories' | 'all'>('categories');
    const [selectedCategory, setSelectedCategory] = useState<string | null>(null); // For Drill-down in 'categories' view
    const [filterCategory, setFilterCategory] = useState<string>('TODOS'); // For Filter in 'all' view

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);
    const [isApartadoMode, setIsApartadoMode] = useState(false);

    // Customer Modal State
    const [customerViewMode, setCustomerViewMode] = useState<'search' | 'new'>('search');
    const [newCustomerName, setNewCustomerName] = useState('');
    const [newCustomerPhone, setNewCustomerPhone] = useState('');
    const [newCustomerAddress, setNewCustomerAddress] = useState('');

    // Dates for Rental
    const [rentalStartDate, setRentalStartDate] = useState<number | undefined>(undefined);
    const [rentalEndDate, setRentalEndDate] = useState<number | undefined>(undefined);

    // Debt / Late Fee State (from Returns page)
    const [debtPaymentItem, setDebtPaymentItem] = useState<{amount: number, refTicket: string} | null>(null);

    // ZERO PRICE MODAL STATE
    const [showPriceModal, setShowPriceModal] = useState(false);
    const [pendingItem, setPendingItem] = useState<{product: Product, variation?: Variation, type: 'sale' | 'rent'} | null>(null);
    const [manualPriceInput, setManualPriceInput] = useState('');

    // Modals
    const [showPaymentModal, setPaymentModalOpen] = useState(false);
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDatePicker, setShowDatePicker] = useState(false);
    const [showCouponModal, setShowCouponModal] = useState(false);
    const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

    // Payment Form
    const [amountPaid, setAmountPaid] = useState('');
    const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');

    // Discount
    const [appliedDiscount, setAppliedDiscount] = useState<{amount: number, reason: string} | null>(null);

    // Load Data
    useEffect(() => {
        const init = async () => {
            setLoading(true);
            const [p, c, cp, cats] = await Promise.all([getProducts(), getCustomers(), getCoupons(), getCategories()]);
            setProducts(p);
            setCustomers(c);
            setCoupons(cp);
            setCategories(cats);
            setLoading(false);
        };
        init();
    }, []);

    // Check for incoming state (Late Fee Payment)
    useEffect(() => {
        if (location.state && location.state.action === 'pay_late_fee') {
            const { customer, amount, refTicket } = location.state;
            if (customer) setCurrentCustomer(customer);
            setDebtPaymentItem({ amount, refTicket });
        }
    }, [location.state]);

    // Reset customer modal state when closed/opened
    useEffect(() => {
        if (showCustomerModal) {
            setCustomerViewMode('search');
            setCustomerSearch('');
        }
    }, [showCustomerModal]);

    // Computed
    const cartTotal = useMemo(() => {
        return cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
    }, [cart]);

    const total = useMemo(() => {
        let base = cartTotal;
        if (debtPaymentItem) base += debtPaymentItem.amount;
        if (appliedDiscount) base -= appliedDiscount.amount;
        return Math.max(0, base);
    }, [cartTotal, debtPaymentItem, appliedDiscount]);

    const hasRentals = useMemo(() => cart.some(i => i.transactionType === 'rent'), [cart]);

    // Cart Actions
    const addToCart = (product: Product, variation?: Variation, type: 'sale' | 'rent' = 'sale', manualPriceOverride?: number) => {
        // 1. Determine Price
        let price = manualPriceOverride;

        if (price === undefined) {
            price = variation 
                ? (type === 'sale' ? variation.salePrice : variation.rentalPrice) 
                : (type === 'sale' ? product.salePrice : product.rentalPrice);
        }

        const finalPrice = price || 0;

        // 2. Check for Zero Price (Trigger Modal)
        if (finalPrice === 0 && manualPriceOverride === undefined) {
            setPendingItem({ product, variation, type });
            setManualPriceInput('');
            setShowPriceModal(true);
            return;
        }

        // 3. Add to Cart
        const newItem: CartItem = {
            ...product,
            cartId: Math.random().toString(36).substr(2, 9),
            transactionType: type,
            quantity: 1,
            selectedVariation: variation,
            appliedPrice: finalPrice
        };

        setCart(prev => [...prev, newItem]);
        // Note: We don't clear search query here to allow fast adding of multiple items
    };

    const handleConfirmManualPrice = (e: React.FormEvent) => {
        e.preventDefault();
        if (!pendingItem) return;

        const price = parseFloat(manualPriceInput);
        if (isNaN(price) || price < 0) {
            alert("Ingrese un precio válido.");
            return;
        }

        addToCart(pendingItem.product, pendingItem.variation, pendingItem.type, price);

        // Cleanup
        setShowPriceModal(false);
        setPendingItem(null);
        setManualPriceInput('');
    };

    const removeFromCart = (cartId: string) => {
        setCart(prev => prev.filter(i => i.cartId !== cartId));
    };

    const updateQuantity = (cartId: string, delta: number) => {
        setCart(prev => prev.map(item => {
            if (item.cartId === cartId) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

    const selectCoupon = (coupon: Coupon) => {
        let discountAmount = 0;
        if (coupon.type === 'percentage') {
            discountAmount = (cartTotal * coupon.value) / 100;
        } else {
            discountAmount = coupon.value;
        }

        // Cap discount at total
        discountAmount = Math.min(discountAmount, cartTotal);

        setAppliedDiscount({ amount: discountAmount, reason: coupon.code });
        setShowCouponModal(false);
    };

    const clearDiscount = () => {
        setAppliedDiscount(null);
    };

    // Dates
    const handleDateSelect = (dateStr: string) => {
        const timestamp = new Date(dateStr + 'T12:00:00').getTime(); // Noon to avoid timezone shifts
        if (datePickerMode === 'start') {
            setRentalStartDate(timestamp);
        } else {
            setRentalStartDate(prev => prev || Date.now()); // If no start date, set today
            setRentalEndDate(timestamp);
        }
    };

    // Payment Logic
    const handleOpenPayment = () => {
        if (cart.length === 0 && !debtPaymentItem) return;

        // Combined check: Rentals OR Apartado require customer
        if ((hasRentals || isApartadoMode) && !currentCustomer) {
            alert(isApartadoMode ? "Es necesario seleccionar un cliente para apartar." : "Es necesario seleccionar un cliente para rentas.");
            setShowCustomerModal(true);
            return;
        }

        if (hasRentals && !rentalEndDate) {
            alert("Selecciona fecha de devolución.");
            setDatePickerMode('end');
            setShowDatePicker(true);
            return;
        }

        setAmountPaid('');
        setPaymentModalOpen(true);
    };

    const handleCheckout = async () => {
        const paid = parseFloat(amountPaid) || 0;

        // Validation Logic
        if (isApartadoMode) {
            if (!currentCustomer) {
                alert("Para realizar un apartado es obligatorio asignar un cliente.");
                setPaymentModalOpen(false); 
                setShowCustomerModal(true); 
                return;
            }

            if (paid <= 0) {
                alert("Para apartar se requiere un anticipo mayor a 0.");
                return;
            }
        } else {
            // Standard Sale Mode
            if (Math.abs(paid - total) > 0.5 && paid < total) { 
                alert("Monto incompleto. Si es un abono, active la opción 'ES UN APARTADO'.");
                return;
            }
            if (paid <= 0 && total > 0) {
                alert("Ingrese monto pagado.");
                return;
            }
        }

        try {
            const finalItems = [...cart];

            // Debt Item Payment Logic
            if (debtPaymentItem) {
                 if (currentCustomer && currentCustomer.id) {
                     const newBalance = (currentCustomer.balance || 0) + debtPaymentItem.amount;
                     await updateCustomer(currentCustomer.id, { balance: newBalance });
                 }
            }

            const orderData: any = {
                items: finalItems,
                customer: currentCustomer || undefined,
                total: total,
                status: isApartadoMode ? 'reservation' : (hasRentals ? 'pending' : 'completed'), 
                createdAt: Date.now(),
                paymentMethod: paymentMethod,
                discount: appliedDiscount?.amount,
                discountReason: appliedDiscount?.reason
            };

            if (isApartadoMode) {
                orderData.status = 'reservation';
                orderData.downPayment = paid;
                orderData.remainingBalance = total - paid;
                orderData.rentalStartDate = rentalStartDate; 
                orderData.rentalEndDate = rentalEndDate;
            } else if (hasRentals) {
                orderData.status = 'pending'; // Active rental
                orderData.rentalStartDate = rentalStartDate || Date.now();
                orderData.rentalEndDate = rentalEndDate;
            } else {
                orderData.status = 'completed';
            }

            await createOrder(orderData);

            alert(isApartadoMode ? "Apartado registrado exitosamente." : "Venta registrada exitosamente.");

            // Reset
            setCart([]);
            setCurrentCustomer(null);
            setDebtPaymentItem(null);
            setAppliedDiscount(null);
            setPaymentModalOpen(false);
            setIsApartadoMode(false);
            setRentalEndDate(undefined);
            setRentalStartDate(undefined);

        } catch (e) {
            console.error(e);
            alert("Error al procesar la venta.");
        }
    };

    // UI Helpers & Product Filtering
    const filteredProducts = useMemo(() => {
        let result = products;

        // 1. Filter by Search Query (Global Priority)
        if (searchQuery) {
            const q = searchQuery.toUpperCase();
            return products.filter(p => p.name.includes(q) || p.code.includes(q));
        }

        // 2. Logic based on View Mode
        if (viewMode === 'categories') {
            if (selectedCategory) {
                 result = result.filter(p => p.category === selectedCategory);
            } else {
                // In main category view (grid), we don't show products, we show categories
                return []; 
            }
        } else {
            // View Mode 'all'
            if (filterCategory !== 'TODOS') {
                result = result.filter(p => p.category === filterCategory);
            }
        }

        return result;
    }, [products, searchQuery, viewMode, selectedCategory, filterCategory]);

    // Consolidate all categories (DB + Products) and attach images if available
    const availableCategories = useMemo(() => {
        const catMap = new Map<string, { name: string, imageUrl?: string }>();

        // 1. Load from DB first (they have images)
        categories.forEach(c => {
            catMap.set(c.name, { name: c.name, imageUrl: c.imageUrl });
        });

        // 2. Load from products (in case some products have categories not in DB yet)
        products.forEach(p => { 
            if(p.category && !catMap.has(p.category)) {
                catMap.set(p.category, { name: p.category });
            }
        });

        return Array.from(catMap.values()).sort((a,b) => a.name.localeCompare(b.name));
    }, [categories, products]);

    // Customer Selection inside Modal
    const [customerSearch, setCustomerSearch] = useState('');

    // Updated Logic: Only return customers if search string is not empty
    const modalCustomers = useMemo(() => {
        if (!customerSearch.trim()) return [];
        const q = customerSearch.toUpperCase();
        return customers.filter(c => c.name.includes(q) || c.phone.includes(q));
    }, [customers, customerSearch]);

    // NEW CUSTOMER LOGIC
    const handleSwitchToRegister = () => {
        setNewCustomerName(customerSearch);
        setNewCustomerPhone('');
        setNewCustomerAddress('');
        setCustomerViewMode('new');
    };

    const handleRegisterCustomer = async (e: React.FormEvent) => {
        e.preventDefault();

        // Strict Validation
        if(!newCustomerName.trim() || !newCustomerPhone.trim() || !newCustomerAddress.trim()) {
            alert("Faltan datos. El Nombre, Teléfono y Dirección son obligatorios.");
            return;
        }

        if(newCustomerPhone.length !== 10) {
            alert("El teléfono debe tener exactamente 10 dígitos numéricos.");
            return;
        }

        try {
            const newCustomerData = {
                name: newCustomerName.toUpperCase().trim(),
                phone: newCustomerPhone.trim(),
                address: newCustomerAddress.toUpperCase().trim(),
                balance: 0
            };
            const createdCustomer = await addCustomer(newCustomerData);

            setCustomers(prev => [...prev, createdCustomer]);
            setCurrentCustomer(createdCustomer);
            setShowCustomerModal(false);

            setCustomerViewMode('search');
            setCustomerSearch('');

        } catch(e) {
            console.error(e);
            alert("Error al registrar cliente.");
        }
    };

    return (
        <div className="flex h-full flex-col lg:flex-row bg-white overflow-hidden">
            {/* LEFT: Product Selection */}
            <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200 relative bg-slate-50/30">

                {/* Header: Search & View Toggle */}
                <div className="p-4 bg-white border-b border-slate-100 flex gap-4 items-center shadow-sm z-10">
                     {/* View Toggle */}
                    <div className="flex bg-slate-100 p-1 rounded-xl flex-shrink-0">
                        <button 
                            onClick={() => { setViewMode('categories'); setSelectedCategory(null); }}
                            className={`p-2 rounded-lg transition-all ${viewMode === 'categories' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                            title="Por Categorías"
                        >
                            <LayoutGrid className="w-5 h-5" />
                        </button>
                        <button 
                             onClick={() => setViewMode('all')}
                             className={`p-2 rounded-lg transition-all ${viewMode === 'all' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                             title="Catálogo Completo"
                        >
                             <ListFilter className="w-5 h-5" />
                        </button>
                    </div>

                    <div className="relative flex-1">
                        <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                        <input 
                            type="text" 
                            placeholder={viewMode === 'categories' && !selectedCategory ? "BUSCAR PRODUCTO (SALTA CATEGORÍAS)..." : "BUSCAR PRODUCTO..."} 
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                            className="w-full pl-12 pr-4 py-3 rounded-2xl bg-slate-50 border border-slate-200 outline-none focus:ring-2 focus:ring-indigo-500/20 uppercase transition-all focus:bg-white"
                        />
                    </div>
                </div>

                {/* --- CONTENT AREA --- */}
                <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">

                    {/* SCENARIO 1: SEARCH ACTIVE (Overrides all views) */}
                    {searchQuery ? (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in fade-in zoom-in-95 duration-300">
                             {filteredProducts.map(product => (
                                <ProductCard key={product.id} product={product} onAdd={addToCart} />
                             ))}
                             {filteredProducts.length === 0 && (
                                 <div className="col-span-full py-12 text-center text-slate-400 uppercase font-bold">
                                     No se encontraron productos
                                 </div>
                             )}
                        </div>
                    ) : (
                        <>
                            {/* SCENARIO 2: VIEW MODE = CATEGORIES (Main Grid) */}
                            {viewMode === 'categories' && !selectedCategory && (
                                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 animate-in slide-in-from-bottom-4 duration-500">

                                    {/* DISCOUNT BUTTON (First Item) */}
                                    <button 
                                        onClick={() => setShowCouponModal(true)}
                                        className="aspect-[4/3] rounded-3xl bg-gradient-to-br from-rose-500 to-pink-600 text-white flex flex-col items-center justify-center gap-2 shadow-lg shadow-rose-200 hover:scale-[1.02] active:scale-95 transition-all group"
                                    >
                                        <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center backdrop-blur-sm group-hover:rotate-12 transition-transform">
                                            <Percent className="w-6 h-6 text-white" />
                                        </div>
                                        <span className="font-bold uppercase text-sm tracking-wider">OFERTAS / CUPONES</span>
                                    </button>

                                    {/* CATEGORY CARDS */}
                                    {availableCategories.map((cat, idx) => (
                                        <button 
                                            key={cat.name}
                                            onClick={() => setSelectedCategory(cat.name)}
                                            className="aspect-[4/3] rounded-3xl bg-white border border-slate-100 hover:border-indigo-300 hover:shadow-xl hover:shadow-indigo-100 flex flex-col items-center justify-center gap-3 transition-all active:scale-95 group relative overflow-hidden"
                                        >
                                            {cat.imageUrl ? (
                                                <>
                                                    <img src={cat.imageUrl} className="absolute inset-0 w-full h-full object-cover z-0 transition-transform duration-500 group-hover:scale-110" />
                                                    <div className="absolute inset-0 bg-black/40 group-hover:bg-black/20 transition-colors z-10" />
                                                    <span className="font-black text-white uppercase text-center px-4 z-20 text-lg leading-tight tracking-wide drop-shadow-md">
                                                        {cat.name}
                                                    </span>
                                                </>
                                            ) : (
                                                <>
                                                    <div className="absolute inset-0 bg-gradient-to-br from-slate-50 to-white z-0" />
                                                    <div className="w-14 h-14 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center z-10 group-hover:bg-indigo-600 group-hover:text-white transition-colors duration-300 shadow-sm">
                                                        <Box className="w-7 h-7" />
                                                    </div>
                                                    <span className="font-bold text-slate-700 uppercase text-center px-4 z-10 text-sm leading-tight group-hover:text-indigo-700 transition-colors">
                                                        {cat.name}
                                                    </span>
                                                </>
                                            )}
                                        </button>
                                    ))}
                                </div>
                            )}

                            {/* SCENARIO 3: VIEW MODE = CATEGORIES (Drill Down) */}
                            {viewMode === 'categories' && selectedCategory && (
                                <div className="animate-in slide-in-from-right-8 duration-300">
                                    <div className="flex items-center gap-3 mb-6">
                                        <button 
                                            onClick={() => setSelectedCategory(null)}
                                            className="p-2 bg-white border border-slate-200 rounded-xl hover:bg-slate-50 transition-colors"
                                        >
                                            <ChevronLeft className="w-6 h-6 text-slate-500" />
                                        </button>
                                        <h2 className="text-2xl font-bold text-slate-800 uppercase">{selectedCategory}</h2>
                                    </div>
                                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                                        {filteredProducts.map(product => (
                                            <ProductCard key={product.id} product={product} onAdd={addToCart} />
                                        ))}
                                        {filteredProducts.length === 0 && (
                                            <div className="col-span-full py-12 text-center text-slate-400">
                                                CATEGORÍA VACÍA
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}

                            {/* SCENARIO 4: VIEW MODE = ALL (With Filter) */}
                            {viewMode === 'all' && (
                                <div className="h-full flex flex-col">
                                    {/* Horizontal Category Filter */}
                                    <div className="flex gap-2 overflow-x-auto pb-4 mb-2 flex-shrink-0 hide-scrollbar">
                                        <button 
                                            onClick={() => setFilterCategory('TODOS')}
                                            className={`px-4 py-2 rounded-xl text-xs font-bold uppercase whitespace-nowrap transition-all border ${filterCategory === 'TODOS' ? 'bg-indigo-600 text-white border-indigo-600 shadow-md shadow-indigo-200' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
                                        >
                                            TODOS
                                        </button>
                                        {availableCategories.map(cat => (
                                            <button 
                                                key={cat.name}
                                                onClick={() => setFilterCategory(cat.name)}
                                                className={`px-4 py-2 rounded-xl text-xs font-bold uppercase whitespace-nowrap transition-all border ${filterCategory === cat.name ? 'bg-indigo-600 text-white border-indigo-600 shadow-md shadow-indigo-200' : 'bg-white text-slate-500 border-slate-200 hover:bg-slate-50'}`}
                                            >
                                                {cat.name}
                                            </button>
                                        ))}
                                    </div>

                                    {/* Products Grid */}
                                    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 pb-20">
                                         {filteredProducts.map(product => (
                                            <ProductCard key={product.id} product={product} onAdd={addToCart} />
                                         ))}
                                    </div>
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>

            {/* RIGHT: Cart & Checkout */}
            <div className="w-full lg:w-[400px] xl:w-[450px] bg-white border-l border-slate-200 flex flex-col h-full shadow-2xl shadow-slate-200 z-10">
                {/* Customer Bar */}
                <div 
                    className={`p-4 border-b border-slate-100 flex justify-between items-center cursor-pointer hover:bg-slate-50 transition-colors ${!currentCustomer ? 'bg-slate-50' : 'bg-indigo-50/50'}`}
                    onClick={() => setShowCustomerModal(true)}
                >
                    <div className="flex items-center gap-3">
                        <div className={`w-10 h-10 rounded-full flex items-center justify-center ${currentCustomer ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                            <User className="w-5 h-5" />
                        </div>
                        <div>
                            <div className="font-bold text-slate-800 uppercase text-sm">{currentCustomer ? currentCustomer.name : 'SELECCIONAR CLIENTE'}</div>
                            <div className="text-xs text-slate-500 font-mono">{currentCustomer?.phone || 'CLIENTE MOSTRADOR'}</div>
                        </div>
                    </div>
                    {currentCustomer && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); setCurrentCustomer(null); }}
                            className="p-1 text-slate-400 hover:text-rose-500"
                        >
                            <X className="w-4 h-4" />
                        </button>
                    )}
                </div>

                {/* Rental Dates (If Rentals present) */}
                {hasRentals && (
                    <div className="p-3 bg-indigo-50 border-b border-indigo-100 grid grid-cols-2 gap-2">
                        <div onClick={() => { setDatePickerMode('start'); setShowDatePicker(true); }} className="bg-white p-2 rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300">
                            <span className="text-[10px] font-bold text-indigo-400 uppercase block">ENTREGA</span>
                            <span className="text-sm font-bold text-indigo-900 block">
                                {rentalStartDate ? new Date(rentalStartDate).toLocaleDateString() : 'HOY'}
                            </span>
                        </div>
                        <div onClick={() => { setDatePickerMode('end'); setShowDatePicker(true); }} className="bg-white p-2 rounded-xl border border-indigo-100 cursor-pointer hover:border-indigo-300">
                            <span className="text-[10px] font-bold text-indigo-400 uppercase block">DEVOLUCIÓN</span>
                            <span className={`text-sm font-bold block ${rentalEndDate ? 'text-indigo-900' : 'text-slate-300'}`}>
                                {rentalEndDate ? new Date(rentalEndDate).toLocaleDateString() : 'SELECCIONAR'}
                            </span>
                        </div>
                    </div>
                )}

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {/* Special Debt Item */}
                    {debtPaymentItem && (
                         <div className="flex justify-between items-center p-3 bg-rose-50 rounded-xl border border-rose-100 animate-in slide-in-from-right">
                             <div className="flex items-center gap-3">
                                 <div className="p-2 bg-white rounded-lg text-rose-500"><RotateCcw className="w-4 h-4"/></div>
                                 <div>
                                     <div className="font-bold text-rose-800 text-sm uppercase">PAGO DE RECARGO</div>
                                     <div className="text-xs text-rose-600 font-mono">TICKET REF: #{debtPaymentItem.refTicket}</div>
                                 </div>
                             </div>
                             <div className="flex items-center gap-3">
                                <div className="font-mono font-bold text-rose-700">${debtPaymentItem.amount.toFixed(2)}</div>
                                <button onClick={() => setDebtPaymentItem(null)} className="text-rose-300 hover:text-rose-600"><X className="w-4 h-4"/></button>
                             </div>
                         </div>
                    )}

                    {cart.map((item) => (
                        <div key={item.cartId} className="flex justify-between items-center p-2 group hover:bg-slate-50 rounded-xl transition-colors">
                            <div className="flex-1 min-w-0 pr-2">
                                <div className="font-bold text-slate-800 text-sm uppercase truncate">
                                    {item.name} {item.selectedVariation ? `(${item.selectedVariation.name})` : ''}
                                </div>
                                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                                    </Badge>
                                    <span className="font-mono">${item.appliedPrice} c/u</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <div className="flex items-center bg-slate-100 rounded-lg">
                                    <button onClick={() => updateQuantity(item.cartId, -1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-l-lg disabled:opacity-50" disabled={item.quantity <= 1}><Minus className="w-3 h-3" /></button>
                                    <span className="w-6 text-center text-xs font-bold">{item.quantity}</span>
                                    <button onClick={() => updateQuantity(item.cartId, 1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                </div>
                                <div className="font-mono font-bold text-slate-800 w-16 text-right">
                                    ${(item.appliedPrice * item.quantity).toFixed(2)}
                                </div>
                                <button onClick={() => removeFromCart(item.cartId)} className="text-slate-300 hover:text-rose-500 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    ))}

                    {cart.length === 0 && !debtPaymentItem && (
                        <div className="h-40 flex flex-col items-center justify-center text-slate-300 opacity-60">
                            <ShoppingCart className="w-12 h-12 mb-2" />
                            <span className="text-sm font-bold uppercase">CARRITO VACÍO</span>
                        </div>
                    )}
                </div>

                {/* Footer Totals */}
                <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-3">

                    {/* Discount Input */}
                    <div className="flex gap-2">
                        {appliedDiscount ? (
                            <div className="flex-1 bg-emerald-100 text-emerald-800 px-3 py-2 rounded-xl flex justify-between items-center text-xs font-bold uppercase">
                                <span>CUPÓN: {appliedDiscount.reason} (-${appliedDiscount.amount.toFixed(2)})</span>
                                <button onClick={clearDiscount}><X className="w-4 h-4"/></button>
                            </div>
                        ) : (
                            <Button 
                                variant="secondary" 
                                onClick={() => setShowCouponModal(true)} 
                                className="w-full text-xs py-2 border-dashed border-slate-300 text-slate-400 hover:border-indigo-300 hover:text-indigo-600"
                            >
                                <Tag className="w-4 h-4 mr-1" /> AGREGAR DESCUENTO / CUPÓN
                            </Button>
                        )}
                    </div>

                    <div className="flex justify-between items-end">
                        <div className="flex items-center gap-2">
                            <span className="text-slate-500 font-bold uppercase text-xs">TOTAL A PAGAR</span>
                        </div>
                        <div className="text-3xl font-black text-slate-800 font-mono tracking-tight">
                            ${total.toFixed(2)}
                        </div>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                         {/* Toggle Apartado */}
                         <button 
                            onClick={() => setIsApartadoMode(!isApartadoMode)}
                            className={`py-3 rounded-xl text-xs font-bold uppercase border-2 transition-all flex flex-col items-center justify-center gap-1 ${isApartadoMode ? 'border-amber-400 bg-amber-50 text-amber-700' : 'border-slate-200 text-slate-400 hover:bg-white'}`}
                        >
                            <Calendar className="w-4 h-4" />
                            ES APARTADO
                        </button>

                         <Button 
                            onClick={handleOpenPayment} 
                            disabled={total === 0 && !debtPaymentItem} 
                            className="bg-slate-900 text-white shadow-xl shadow-slate-300 hover:bg-slate-800"
                        >
                            COBRAR <ArrowUpRight className="w-5 h-5 ml-1" />
                        </Button>
                    </div>
                </div>
            </div>

            {/* CUSTOMER MODAL */}
            <Modal isOpen={showCustomerModal} onClose={() => setShowCustomerModal(false)} title={customerViewMode === 'new' ? "REGISTRAR NUEVO CLIENTE" : "SELECCIONAR CLIENTE"}>
                 {customerViewMode === 'search' ? (
                     <div className="space-y-4">
                        <Input 
                            placeholder="BUSCAR CLIENTE..." 
                            value={customerSearch}
                            onChange={(e) => setCustomerSearch(e.target.value.toUpperCase())}
                            autoFocus
                            onKeyDown={(e) => {
                                if (e.key === 'Enter' && modalCustomers.length === 0 && customerSearch.trim()) {
                                    handleSwitchToRegister();
                                }
                            }}
                        />
                        <div className="max-h-60 overflow-y-auto space-y-2">
                            {modalCustomers.map(c => (
                                <div 
                                    key={c.id} 
                                    onClick={() => { setCurrentCustomer(c); setShowCustomerModal(false); setCustomerSearch(''); }}
                                    className="p-3 bg-slate-50 hover:bg-indigo-50 rounded-xl border border-slate-100 cursor-pointer flex justify-between items-center"
                                >
                                    <div>
                                        <div className="font-bold text-slate-800 uppercase">{c.name}</div>
                                        <div className="text-xs text-slate-500">{c.phone}</div>
                                    </div>
                                    {(c.balance || 0) < 0 && (
                                        <span className="text-xs font-bold text-rose-500 bg-rose-50 px-2 py-1 rounded">DEUDA: ${Math.abs(c.balance || 0)}</span>
                                    )}
                                </div>
                            ))}

                            {customerSearch.trim() !== '' && modalCustomers.length === 0 && (
                                <div className="text-center py-6">
                                    <div className="text-slate-400 text-xs mb-3">NO SE ENCONTRARON CLIENTES</div>
                                    <Button onClick={handleSwitchToRegister} className="w-full uppercase shadow-lg">
                                        <UserPlus className="w-5 h-5" /> REGISTRAR "{customerSearch}"
                                    </Button>
                                    <div className="text-[10px] text-slate-400 mt-2">TIP: Presiona ENTER para registrar rápido</div>
                                </div>
                            )}

                            {customerSearch.trim() === '' && (
                                <div className="text-center text-slate-300 text-xs py-8 opacity-60">
                                    ESCRIBE PARA BUSCAR...
                                </div>
                            )}
                        </div>
                     </div>
                 ) : (
                     <form onSubmit={handleRegisterCustomer} className="space-y-4 pt-2">
                        <Input 
                            label="NOMBRE COMPLETO" 
                            value={newCustomerName}
                            onChange={e => setNewCustomerName(e.target.value.toUpperCase())}
                            placeholder="EJ. JUAN PÉREZ"
                            autoFocus
                        />
                        <Input 
                            label="TELÉFONO" 
                            value={newCustomerPhone}
                            onChange={e => {
                                const val = e.target.value.replace(/\D/g, '');
                                if(val.length <= 10) setNewCustomerPhone(val);
                            }}
                            placeholder="10 DÍGITOS"
                            type="tel"
                            maxLength={10}
                        />
                        <Input 
                            label="DIRECCIÓN" 
                            value={newCustomerAddress}
                            onChange={e => setNewCustomerAddress(e.target.value.toUpperCase())}
                            placeholder="CALLE, NÚMERO, COLONIA"
                        />

                        <div className="pt-4 flex gap-3">
                            <Button type="button" variant="secondary" onClick={() => setCustomerViewMode('search')} className="flex-1 uppercase">
                                <ArrowLeft className="w-4 h-4 mr-1" /> VOLVER
                            </Button>
                            <Button type="submit" className="flex-[2] uppercase shadow-xl">
                                <Save className="w-4 h-4" /> GUARDAR Y ASIGNAR
                            </Button>
                        </div>
                    </form>
                 )}
            </Modal>

            {/* MANUAL PRICE MODAL (Zero Price Items) */}
            <Modal isOpen={showPriceModal} onClose={() => setShowPriceModal(false)} title="INGRESAR PRECIO">
                <form onSubmit={handleConfirmManualPrice} className="space-y-4">
                    <div className="text-center mb-4">
                        <span className="block text-xs font-bold text-slate-400 uppercase mb-1">PRODUCTO</span>
                        <h3 className="text-lg font-bold text-slate-800 uppercase">{pendingItem?.product.name}</h3>
                        <span className="text-xs bg-slate-100 px-2 py-1 rounded text-slate-500 font-bold uppercase">{pendingItem?.type === 'rent' ? 'RENTA' : 'VENTA'}</span>
                    </div>

                    <div>
                        <label className="text-xs font-bold text-slate-500 uppercase ml-1">PRECIO MANUAL ($)</label>
                        <Input 
                            type="number"
                            value={manualPriceInput}
                            onChange={(e) => setManualPriceInput(e.target.value)}
                            placeholder="0.00"
                            className="text-center text-2xl font-bold"
                            autoFocus
                            step="0.01"
                        />
                    </div>

                    <div className="flex gap-2 pt-2">
                        <Button type="button" variant="secondary" onClick={() => setShowPriceModal(false)} className="flex-1 uppercase">CANCELAR</Button>
                        <Button type="submit" className="flex-[2] uppercase shadow-xl">CONFIRMAR PRECIO</Button>
                    </div>
                </form>
            </Modal>

            {/* PAYMENT MODAL */}
            <Modal isOpen={showPaymentModal} onClose={() => setPaymentModalOpen(false)} title={isApartadoMode ? "CONFIRMAR APARTADO" : "COBRAR"}>
                 <div className="space-y-6">
                    <div className="text-center">
                        <div className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">TOTAL A PAGAR</div>
                        <div className="text-5xl font-black text-slate-900 font-mono">${total.toFixed(2)}</div>
                    </div>

                    <div className="flex bg-slate-100 p-1 rounded-2xl">
                        <button onClick={() => setPaymentMethod('cash')} className={`flex-1 py-4 rounded-xl font-bold uppercase text-sm transition-all flex flex-col items-center gap-1 ${paymentMethod === 'cash' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                            <Banknote className="w-5 h-5"/> EFECTIVO
                        </button>
                        <button onClick={() => setPaymentMethod('card')} className={`flex-1 py-4 rounded-xl font-bold uppercase text-sm transition-all flex flex-col items-center gap-1 ${paymentMethod === 'card' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                            <CreditCard className="w-5 h-5"/> TARJETA
                        </button>
                        <button onClick={() => setPaymentMethod('transfer')} className={`flex-1 py-4 rounded-xl font-bold uppercase text-sm transition-all flex flex-col items-center gap-1 ${paymentMethod === 'transfer' ? 'bg-white shadow-md text-indigo-600' : 'text-slate-500'}`}>
                            <ArrowUpRight className="w-5 h-5"/> TRANSFER
                        </button>
                    </div>

                    <div className="space-y-4">
                        <div>
                            <label className="text-xs font-bold text-slate-500 uppercase ml-1 block mb-1">
                                {isApartadoMode ? 'ANTICIPO RECIBIDO ($)' : 'DINERO RECIBIDO ($)'}
                            </label>
                            <Input 
                                type="number" 
                                value={amountPaid}
                                onChange={(e) => setAmountPaid(e.target.value)}
                                placeholder="0.00"
                                className="text-center text-xl font-bold"
                                autoFocus
                            />
                        </div>

                        {/* Change Calculator */}
                        {!isApartadoMode && amountPaid && parseFloat(amountPaid) >= total && (
                            <div className="bg-emerald-50 text-emerald-800 p-4 rounded-xl text-center">
                                <span className="text-xs font-bold uppercase block opacity-60">CAMBIO A ENTREGAR</span>
                                <span className="text-3xl font-black font-mono">${(parseFloat(amountPaid) - total).toFixed(2)}</span>
                            </div>
                        )}

                        {isApartadoMode && amountPaid && parseFloat(amountPaid) < total && (
                             <div className="bg-amber-50 text-amber-800 p-4 rounded-xl text-center">
                                 <span className="text-xs font-bold uppercase block opacity-60">RESTARÁ POR PAGAR</span>
                                <span className="text-3xl font-black font-mono">${(total - parseFloat(amountPaid)).toFixed(2)}</span>
                            </div>
                        )}
                    </div>

                    <Button onClick={handleCheckout} className="w-full py-4 text-lg shadow-xl uppercase">
                        CONFIRMAR {isApartadoMode ? 'APARTADO' : 'COBRO'}
                    </Button>
                 </div>
            </Modal>

            {/* COUPON MODAL */}
            <Modal isOpen={showCouponModal} onClose={() => setShowCouponModal(false)} title="SELECCIONAR DESCUENTO">
                <div className="space-y-2 max-h-[60vh] overflow-y-auto">
                    {coupons.filter(c => c.isActive).length === 0 ? (
                        <div className="text-center py-8 text-slate-400 uppercase">NO HAY CUPONES DISPONIBLES</div>
                    ) : (
                        coupons.filter(c => c.isActive).map(coupon => (
                            <button
                                key={coupon.id}
                                onClick={() => selectCoupon(coupon)}
                                className="w-full flex justify-between items-center p-4 bg-slate-50 hover:bg-indigo-50 border border-slate-100 hover:border-indigo-200 rounded-xl transition-all group"
                            >
                                <div className="text-left">
                                    <div className="font-bold text-slate-800 text-lg">{coupon.code}</div>
                                    <div className="text-xs text-slate-500 font-bold uppercase">
                                        DESCUENTO: {coupon.type === 'percentage' ? `${coupon.value}%` : `$${coupon.value}`}
                                    </div>
                                </div>
                                <div className="bg-white p-2 rounded-full text-slate-300 group-hover:text-indigo-600 transition-colors">
                                    <ArrowUpRight className="w-5 h-5 rotate-45" />
                                </div>
                            </button>
                        ))
                    )}
                </div>
            </Modal>

            {/* DATE PICKER MODAL */}
            <DatePickerModal 
                isOpen={showDatePicker}
                onClose={() => setShowDatePicker(false)}
                onSelect={handleDateSelect}
                title={datePickerMode === 'start' ? 'FECHA DE ENTREGA' : 'FECHA DE DEVOLUCIÓN'}
            />

        </div>
    );
};

// --- Sub-component for Product Card ---
const ProductCard: React.FC<{ product: Product, onAdd: (p: Product, v?: Variation, t?: 'sale'|'rent') => void }> = ({ product, onAdd }) => {

    // Determine default action on card click
    const handleCardClick = () => {
        // If has variations, user MUST select one, so do nothing (buttons are available)
        // If not, use logic:
        if (product.variations && product.variations.length > 0) return;

        if (product.isRentalAvailable) {
            onAdd(product, undefined, 'rent');
        } else if (product.isSaleAvailable) {
            onAdd(product, undefined, 'sale');
        }
    };

    const isMainlyCostume = product.category === 'DISFRACES';

    return (
        <div 
            onClick={handleCardClick}
            className={`
                bg-white rounded-3xl p-3 shadow-sm transition-all flex flex-col justify-between group overflow-hidden relative cursor-pointer active:scale-95
                border-2 ${isMainlyCostume ? 'border-indigo-100 hover:border-indigo-400' : 'border-amber-100 hover:border-amber-400'}
            `}
        >
            <div className="relative">
                {/* Image placeholder or real image */}
                <div className="h-32 bg-slate-100 rounded-2xl mb-2 flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover" alt={product.name}/> : <Tag className="text-slate-300 w-8 h-8"/>}
                </div>
                <div className="font-bold text-slate-800 uppercase text-xs leading-tight mb-1 line-clamp-2 min-h-[2.5em]">{product.name}</div>
                <div className="text-[10px] text-slate-500 font-mono mb-2">{product.code}</div>

                {/* Hover Actions Overlay */}
                <div className="absolute inset-0 bg-white/90 backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity flex flex-col justify-center gap-2 p-2">
                     <div className="grid grid-cols-1 gap-2">
                        {product.isSaleAvailable && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); onAdd(product, undefined, 'sale'); }}
                                className="bg-emerald-100 text-emerald-700 py-3 rounded-xl text-xs font-bold hover:bg-emerald-200 transition-colors uppercase shadow-sm"
                            >
                                Venta ${product.salePrice}
                            </button>
                        )}
                        {product.isRentalAvailable && (
                            <button 
                                onClick={(e) => { e.stopPropagation(); onAdd(product, undefined, 'rent'); }}
                                className="bg-indigo-100 text-indigo-700 py-3 rounded-xl text-xs font-bold hover:bg-indigo-200 transition-colors uppercase shadow-sm"
                            >
                                Renta ${product.rentalPrice}
                            </button>
                        )}
                        {/* Variations if any */}
                        {product.variations && product.variations.length > 0 && (
                            <div className="flex flex-wrap gap-1 justify-center mt-1">
                                {product.variations.map((v, i) => (
                                    <button 
                                        key={i}
                                        onClick={(e) => { 
                                            e.stopPropagation(); 
                                            onAdd(product, v, product.isRentalAvailable ? 'rent' : 'sale');
                                        }}
                                        className="px-2 py-1 bg-slate-200 hover:bg-slate-300 rounded text-[9px] font-bold uppercase"
                                    >
                                        {v.name}
                                    </button>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Footer info when not hovering */}
            <div className="mt-auto flex justify-between items-end opacity-100 group-hover:opacity-0 transition-opacity">
                <Badge color={isMainlyCostume ? 'indigo' : 'amber'}>{product.category}</Badge>
                <div className="text-[10px] font-bold text-slate-400">STOCK: {product.stock}</div>
            </div>
        </div>
    );
};

export default POS;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { Search, ShoppingCart, User, Calendar, Trash2, Plus, Minus, X, CreditCard, Banknote, ArrowUpRight, Tag, RotateCcw, UserPlus, Save, ArrowLeft, LayoutGrid, ListFilter, Percent, ChevronLeft, Box, DollarSign, Layers } from 'lucide-react';
import { Button, Input, Modal, DatePickerModal, Badge } from '../components/UI';
import { Product, Customer, CartItem, Variation, Coupon, Category } from '../types';
import { getProducts, getCustomers, createOrder, updateCustomer, getCoupons, addCustomer, getCategories } from '../services/dataService';

const POS: React.FC = () => {
    const location = useLocation();

    // Data State
    const [products, setProducts] = useState<Product[]>([]);
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [coupons, setCoupons] = useState<Coupon[]>([]);
    const [categories, setCategories] = useState<Category[]>([]);
    const [loading, setLoading] = useState(true);

    // View State
    const [viewMode, setViewMode] = useState<'categories' | 'all'>('categories');
    const [selectedCategory, setSelectedCategory] = useState<string | null>(null); // For Drill-down in 'categories' view
    const [filterCategory, setFilterCategory] = useState<string>('TODOS'); // For Filter in 'all' view

    // Cart State
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [currentCustomer, setCurrentCustomer] = useState<Customer | null>(null);
    const [isApartadoMode, setIsApartadoMode] = useState(false);

    // Customer Modal State
    const [customerViewMode, setCustomerViewMode] = useState<'search' | 'new'>('search');
    const [newCustomerName, setNewCustomerName] = useState('');
    const [newCustomerPhone, setNewCustomerPhone] = useState('');
    const [newCustomerAddress, setNewCustomerAddress] = useState('');

    // Dates for Rental
    const [rentalStartDate, setRentalStartDate] = useState<number | undefined>(undefined);
    const [rentalEndDate, setRentalEndDate] = useState<number | undefined>(undefined);

    // Debt / Late Fee State (from Returns page)
    const [debtPaymentItem, setDebtPaymentItem] = useState<{amount: number, refTicket: string} | null>(null);

    // ZERO PRICE MODAL STATE
    const [showPriceModal, setShowPriceModal] = useState(false);
    const [pendingItem, setPendingItem] = useState<{product: Product, variation?: Variation, type: 'sale' | 'rent'} | null>(null);
    const [manualPriceInput, setManualPriceInput] = useState('');

    // VARIATION SELECTION MODAL STATE
    const [showVariationModal, setShowVariationModal] = useState(false);
    const [selectedProductForVariations, setSelectedProductForVariations] = useState<Product | null>(null);

    // Modals
    const [showPaymentModal, setPaymentModalOpen] = useState(false);
    const [showCustomerModal, setShowCustomerModal] = useState(false);
    const [showDatePicker, setShowDatePicker] = useState(false);
    const [showCouponModal, setShowCouponModal] = useState(false);
    const [datePickerMode, setDatePickerMode] = useState<'start' | 'end'>('start');

    // Payment Form
    const [amountPaid, setAmountPaid] = useState('');
    const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer'>('cash');

    // Discount
    const [appliedDiscount, setAppliedDiscount] = useState<{amount: number, reason: string} | null>(null);

    // Load Data
    useEffect(() => {
        const init = async () => {
            setLoading(true);
            const [p, c, cp, cats] = await Promise.all([getProducts(), getCustomers(), getCoupons(), getCategories()]);
            setProducts(p);
            setCustomers(c);
            setCoupons(cp);
            setCategories(cats);
            setLoading(false);
        };
        init();
    }, []);

    // Check for incoming state (Late Fee Payment)
    useEffect(() => {
        if (location.state && location.state.action === 'pay_late_fee') {
            const { customer, amount, refTicket } = location.state;
            if (customer) setCurrentCustomer(customer);
            setDebtPaymentItem({ amount, refTicket });
        }
    }, [location.state]);

    // Reset customer modal state when closed/opened
    useEffect(() => {
        if (showCustomerModal) {
            setCustomerViewMode('search');
            setCustomerSearch('');
        }
    }, [showCustomerModal]);

    // Computed
    const cartTotal = useMemo(() => {
        return cart.reduce((sum, item) => sum + (item.appliedPrice * item.quantity), 0);
    }, [cart]);

    const total = useMemo(() => {
        let base = cartTotal;
        if (debtPaymentItem) base += debtPaymentItem.amount;
        if (appliedDiscount) base -= appliedDiscount.amount;
        return Math.max(0, base);
    }, [cartTotal, debtPaymentItem, appliedDiscount]);

    const hasRentals = useMemo(() => cart.some(i => i.transactionType === 'rent'), [cart]);

    // Cart Actions
    const addToCart = (product: Product, variation?: Variation, type: 'sale' | 'rent' = 'sale', manualPriceOverride?: number) => {
        // 1. Determine Price
        let price = manualPriceOverride;

        if (price === undefined) {
            price = variation 
                ? (type === 'sale' ? variation.salePrice : variation.rentalPrice) 
                : (type === 'sale' ? product.salePrice : product.rentalPrice);
        }

        const finalPrice = price || 0;

        // 2. Check for Zero Price (Trigger Modal)
        if (finalPrice === 0 && manualPriceOverride === undefined) {
            setPendingItem({ product, variation, type });
            setManualPriceInput('');
            setShowPriceModal(true);
            return;
        }

        // 3. Add to Cart
        const newItem: CartItem = {
            ...product,
            cartId: Math.random().toString(36).substr(2, 9),
            transactionType: type,
            quantity: 1,
            selectedVariation: variation,
            appliedPrice: finalPrice
        };

        setCart(prev => [...prev, newItem]);
        // Note: We don't clear search query here to allow fast adding of multiple items
    };

    const handleOpenVariations = (product: Product) => {
        setSelectedProductForVariations(product);
        setShowVariationModal(true);
    };

    const handleConfirmManualPrice = (e: React.FormEvent) => {
        e.preventDefault();
        if (!pendingItem) return;

        const price = parseFloat(manualPriceInput);
        if (isNaN(price) || price < 0) {
            alert("Ingrese un precio válido.");
            return;
        }

        addToCart(pendingItem.product, pendingItem.variation, pendingItem.type, price);

        // Cleanup
        setShowPriceModal(false);
        setPendingItem(null);
        setManualPriceInput('');
    };

    const removeFromCart = (cartId: string) => {
        setCart(prev => prev.filter(i => i.cartId !== cartId));
    };

    const updateQuantity = (cartId: string, delta: number) => {
        setCart(prev => prev.map(item => {
            if (item.cartId === cartId) {
                const newQty = Math.max(1, item.quantity + delta);
                return { ...item, quantity: newQty };
            }
            return item;
        }));
    };

    const selectCoupon = (coupon: Coupon) => {
        let discountAmount = 0;
        if (coupon.type === 'percentage') {
            discountAmount = (cartTotal * coupon.value) / 100;
        } else {
            discountAmount = coupon.value;
        }

        // Cap discount at total
        discountAmount = Math.min(discountAmount, cartTotal);

        setAppliedDiscount({ amount: discountAmount, reason: coupon.code });
        setShowCouponModal(false);
    };

    const clearDiscount = () => {
        setAppliedDiscount(null);
    };

    // Dates
    const handleDateSelect = (dateStr: string) => {
        const timestamp = new Date(dateStr + 'T12:00:00').getTime(); // Noon to avoid timezone shifts
        if (datePickerMode === 'start') {
            setRentalStartDate(timestamp);
        } else {
            setRentalStartDate(prev => prev || Date.now()); // If no start date, set today
            setRentalEndDate(timestamp);
        }
    };

    // Payment Logic
    const handleOpenPayment = () => {
        if (cart.length === 0 && !debtPaymentItem) return;

        // Combined check: Rentals OR Apartado require customer
        if ((hasRentals || isApartadoMode) && !currentCustomer) {
            alert(isApartadoMode ? "Es necesario seleccionar un cliente para apartar." : "Es necesario seleccionar un cliente para rentas.");
            setShowCustomerModal(true);
            return;
        }

        if (hasRentals && !rentalEndDate) {
            alert("Selecciona fecha de devolución.");
            setDatePickerMode('end');
            setShowDatePicker(true);
            return;
        }

        setAmountPaid('');
        setPaymentModalOpen(true);
    };

    const handleCheckout = async () => {
        const paid = parseFloat(amountPaid) || 0;

        // Validation Logic
        if (isApartadoMode) {
            if (!currentCustomer) {
                alert("Para realizar un apartado es obligatorio asignar un cliente.");
                setPaymentModalOpen(false); 
                setShowCustomerModal(true); 
                return;
            }

            if (paid <= 0) {
                alert("Para apartar se requiere un anticipo mayor a 0.");
                return;
            }
        } else {
            // Standard Sale Mode
            if (Math.abs(paid - total) > 0.5 && paid < total) { 
                alert("Monto incompleto. Si es un abono, active la opción 'ES UN APARTADO'.");
                return;
            }
            if (paid <= 0 && total > 0) {
                alert("Ingrese monto pagado.");
                return;
            }
        }

        try {
            const finalItems = [...cart];

            // Debt Item Payment Logic
            if (debtPaymentItem) {
                 if (currentCustomer && currentCustomer.id) {
                     const newBalance = (currentCustomer.balance || 0) + debtPaymentItem.amount;
                     await updateCustomer(currentCustomer.id, { balance: newBalance });
                 }
            }

            const orderData: any = {
                items: finalItems,
                customer: currentCustomer || undefined,
                total: total,
                status: isApartadoMode ? 'reservation' : (hasRentals ? 'pending' : 'completed'), 
                createdAt: Date.now(),
                paymentMethod: paymentMethod,
                discount: appliedDiscount?.amount,
                discountReason: appliedDiscount?.reason
            };

            if (isApartadoMode) {
                orderData.status = 'reservation';
                orderData.downPayment = paid;
                orderData.remainingBalance = total - paid;
                orderData.rentalStartDate = rentalStartDate; 
                orderData.rentalEndDate = rentalEndDate;
            } else if (hasRentals) {
                orderData.status = 'pending'; // Active rental
                orderData.rentalStartDate = rentalStartDate || Date.now();
                orderData.rentalEndDate = rentalEndDate;
            } else {
                orderData.status = 'completed';
            }

            await createOrder(orderData);

            alert(isApartadoMode ? "Apartado registrado exitosamente." : "Venta registrada exitosamente.");

            // Reset
            setCart([]);
            setCurrentCustomer(null);
            setDebtPaymentItem(null);
            setAppliedDiscount(null);
            setPaymentModalOpen(false);
            setIsApartadoMode(false);
            setRentalEndDate(undefined);
            setRentalStartDate(undefined);

        } catch (e) {
            console.error(e);
            alert("Error al procesar la venta.");
        }
    };

    // UI Helpers & Product Filtering
    const filteredProducts = useMemo(() => {
        let result = products;

        // 1. Filter by Search Query (Global Priority)
        if (searchQuery) {
            const q = searchQuery.toUpperCase();
            return products.filter(p => p.name.includes(q) || p.code.includes(q));
        }

        // 2. Logic based on View Mode
        if (viewMode === 'categories') {
            if (selectedCategory) {
                 result = result.filter(p => p.category === selectedCategory);
            } else {
                // In main category view (grid), we don't show products, we show categories
                return []; 
            }
        } else {
            // View Mode 'all'
            if (filterCategory !== 'TODOS') {
                result = result.filter(p => p.category === filterCategory);
            }
        }

        return result;
    }, [products, searchQuery, viewMode, selectedCategory, filterCategory]);

    // Consolidate all categories (DB + Products) and attach images if available
    const availableCategories = useMemo(() => {
        const catMap = new Map<string, { name: string, imageUrl?: string }>();

        // 1. Load from DB first (they have images)
        categories.forEach(c => {
            catMap.set(c.name, { name: c.name, imageUrl: c.imageUrl });
        });

        // 2. Load from products (in case some products have categories not in DB yet)
        products.forEach(p => { 
            if(p.category && !catMap.has(p.category)) {
                catMap.set(p.category, { name: p.category });
            }
        });

        return Array.from(catMap.values()).sort((a,b) => a.name.localeCompare(b.name));
    }, [categories, products]);

    // Customer Selection inside Modal
    const [customerSearch, setCustomerSearch] = useState('');

    // Updated Logic: Only return customers if search string is not empty
    const modalCustomers = useMemo(() => {
        if (!customerSearch.trim()) return [];
        const q = customerSearch.toUpperCase();
        return customers.filter(c => c.name.includes(q) || c.phone.includes(q));
    }, [customers, customerSearch]);

    // NEW CUSTOMER LOGIC
    const handleSwitchToRegister = () => {
        setNewCustomerName(customerSearch);
        setNewCustomerPhone('');
        setNewCustomerAddress('');
        setCustomerViewMode('new');
    };

    const handleRegisterCustomer = async (e: React.FormEvent) => {
        e.preventDefault();

        // Strict Validation
        if(!newCustomerName.trim() || !newCustomerPhone.trim() || !newCustomerAddress.trim()) {
            alert("Faltan datos. El Nombre, Teléfono y Dirección son obligatorios.");
            return;
        }

        if(newCustomerPhone.length !== 10) {
            alert("El teléfono debe tener exactamente 10 dígitos numéricos.");
            return;
        }

        try {
            const newCustomerData = {
                name: newCustomerName.toUpperCase().trim(),
                phone: newCustomerPhone.trim(),
                address: newCustomerAddress.toUpperCase().trim(),
                balance: 0
            };
            const createdCustomer = await addCustomer(newCustomerData);

            setCustomers(prev => [...prev, createdCustomer]);
            setCurrentCustomer(createdCustomer);
            setShowCustomerModal(false);

            setCustomerViewMode('search');
            setCustomerSearch('');

        } catch(e) {
            console.error(e);
            alert("Error al registrar cliente.");
        }
    };

    return (
        <div className="flex h-full flex-col lg:flex-row bg-white overflow-hidden">
            {/* LEFT: Product Selection */}
            <div className="flex-1 flex flex-col h-full overflow-hidden border-r border-slate-200 relative bg-slate-50/30">

                {/* Header: Search & View Toggle */}
                <div className="p-4 bg-white border-b border-slate-100 flex gap-4 items-center shadow-sm z-10">
                     {/* View Toggle */}
                    <div className="flex bg-slate-100 p-1 rounded-xl flex-shrink-0">
                        <button 
                            onClick={() => { setViewMode('categories'); setSelectedCategory(null); }}
                            className={`p-2 rounded-lg transition-all ${viewMode === 'categories' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                            title="Por Categorías"
                        >
                            <LayoutGrid className="w-5 h-5" />
                        </button>
                        <button 
                             onClick={() => setViewMode('all')}
