                        </div>
                    </div>
                )}

                {/* Cart Items */}
                <div className="flex-1 overflow-y-auto p-4 space-y-3">
                    {/* Special Debt Item */}
                    {debtPaymentItem && (
                         <div className="flex justify-between items-center p-3 bg-rose-50 rounded-xl border border-rose-100 animate-in slide-in-from-right">
                             <div className="flex items-center gap-3">
                                 <div className="p-2 bg-white rounded-lg text-rose-500"><RotateCcw className="w-4 h-4"/></div>
                                 <div>
                                     <div className="font-bold text-rose-800 text-sm uppercase">PAGO DE RECARGO</div>
                                     <div className="text-xs text-rose-600 font-mono">TICKET REF: #{debtPaymentItem.refTicket}</div>
                                 </div>
                             </div>
                             <div className="flex items-center gap-3">
                                <div className="font-mono font-bold text-rose-700">${debtPaymentItem.amount.toFixed(2)}</div>
                                <button onClick={() => setDebtPaymentItem(null)} className="text-rose-300 hover:text-rose-600"><X className="w-4 h-4"/></button>
                             </div>
                         </div>
                    )}

                    {cart.map((item) => (
                        <div key={item.cartId} className="flex justify-between items-center p-2 group hover:bg-slate-50 rounded-xl transition-colors">
                            <div className="flex-1 min-w-0 pr-2">
                                <div className="font-bold text-slate-800 text-sm uppercase truncate">
                                    {item.name} {item.selectedVariation ? `(${item.selectedVariation.name})` : ''}
                                </div>
                                <div className="text-[10px] text-slate-500 flex items-center gap-1">
                                    <Badge color={item.transactionType === 'rent' ? 'indigo' : 'green'}>
                                        {item.transactionType === 'rent' ? 'RENTA' : 'VENTA'}
                                    </Badge>
                                    <span className="font-mono">${item.appliedPrice} c/u</span>
                                </div>
                            </div>

                            <div className="flex items-center gap-3">
                                <div className="flex items-center bg-slate-100 rounded-lg">
                                    <button onClick={() => updateQuantity(item.cartId, -1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-l-lg disabled:opacity-50" disabled={item.quantity <= 1}><Minus className="w-3 h-3" /></button>
                                    <span className="w-6 text-center text-xs font-bold">{item.quantity}</span>
                                    <button onClick={() => updateQuantity(item.cartId, 1)} className="p-1 text-slate-500 hover:bg-slate-200 rounded-r-lg"><Plus className="w-3 h-3" /></button>
                                </div>
                                <div className="font-mono font-bold text-slate-800 w-16 text-right">
                                    ${(item.appliedPrice * item.quantity).toFixed(2)}
                                </div>
                                <button onClick={() => removeFromCart(item.cartId)} className="text-slate-300 hover:text-rose-500 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <Trash2 className="w-4 h-4" />
                                </button>
                            </div>
                        </div>
                    ))}

                    {cart.length === 0 && !debtPaymentItem && (
                        <div className="h-40 flex flex-col items-center justify-center text-slate-300 opacity-60">
                            <ShoppingCart className="w-12 h-12 mb-2" />
                            <span className="text-sm font-bold uppercase">CARRITO VACÍO</span>
                        </div>
                    )}
                </div>

                {/* Footer Totals */}
                <div className="p-4 bg-slate-50 border-t border-slate-200 space-y-3">

                    {/* Discount Input */}
                    <div className="flex gap-2">
                        {appliedDiscount ? (
                            <div className="flex-1 bg-emerald-100 text-emerald-800 px-3 py-2 rounded-xl flex justify-between items-center text-xs font-bold uppercase">
                                <span>CUPÓN: {appliedDiscount.reason} (-${appliedDiscount.amount.toFixed(2)})</span>
                                <button onClick={clearDiscount}><X className="w-4 h-4"/></button>
                            </div>
                        ) : (
                            <Button 
                                variant="secondary" 
                                onClick={() => setShowCouponModal(true)} 
                                className="w-full text-xs py-2 border-dashed border-slate-300 text-slate-400 hover:border-indigo-300 hover:text-indigo-600"
