                        <div className="max-h-60 overflow-y-auto space-y-2">
                            {modalCustomers.map(c => (
                                <div 
                                    key={c.id} 
                                    onClick={() => { setCurrentCustomer(c); setShowCustomerModal(false); setCustomerSearch(''); }}
