                           <input type="file" ref={catImageUploadRef} className="hidden" accept="image/*" onChange={handleCatImageSelect}/>
                      </div>

                      <div className="flex-1">
                          <Input 
                              label={editingCategory ? "RENOMBRAR / EDITAR" : "NUEVA CATEGORÍA"}
