                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value.toUpperCase())}
                            onKeyDown={(e) => {
                                // If Enter is pressed, user typed something, AND no results -> Open Quick Register
                                if (e.key === 'Enter' && searchQuery.trim() && filteredProducts.length === 0 && onOpenQuickAdd) {
