                            <div className="text-xs text-slate-500 font-mono">{currentCustomer?.phone || 'CLIENTE MOSTRADOR'}</div>
                        </div>
                    </div>
                    {currentCustomer && (
                        <button 
                            onClick={(e) => { e.stopPropagation(); setCurrentCustomer(null); }}
                            className="p-1 text-slate-400 hover:text-rose-500"
