                    {cart.map((item) => (
                        <div key={item.cartId} className={`flex justify-between items-center p-2 group hover:bg-slate-50 rounded-xl transition-colors ${item.cartId === 'EXTRA_DAYS_AUTO_FEE' ? 'bg-indigo-50/50 border border-dashed border-indigo-200' : ''}`}>
