        </div>
    );
};

// --- Sub-component for Product Card ---
const ProductCard: React.FC<{ 
    product: Product, 
    onAdd: (p: Product, v?: Variation, t?: 'sale'|'rent') => void,
    onOpenVariations: (p: Product) => void
}> = ({ product, onAdd, onOpenVariations }) => {

    // Determine default action on card click
    const handleCardClick = () => {
        // If has variations, OPEN MODAL
        if (product.variations && product.variations.length > 0) {
            onOpenVariations(product);
            return;
        }

        // If simple product, Add directly
        if (product.isRentalAvailable) {
            onAdd(product, undefined, 'rent');
        } else if (product.isSaleAvailable) {
            onAdd(product, undefined, 'sale');
        }
    };

    const isMainlyCostume = product.category === 'DISFRACES';

    return (
        <div 
            onClick={handleCardClick}
            className={`
                bg-white rounded-3xl p-3 shadow-sm transition-all flex flex-col justify-between overflow-hidden relative cursor-pointer active:scale-95
                border-2 ${isMainlyCostume ? 'border-indigo-100 hover:border-indigo-400' : 'border-amber-100 hover:border-amber-400'}
            `}
        >
            <div className="relative">
                {/* Image placeholder or real image */}
                <div className="h-32 bg-slate-100 rounded-2xl mb-2 flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover" alt={product.name}/> : <Tag className="text-slate-300 w-8 h-8"/>}
                </div>
                <div className="font-bold text-slate-800 uppercase text-xs leading-tight mb-1 line-clamp-2 min-h-[2.5em]">{product.name}</div>
                <div className="text-[10px] text-slate-500 font-mono mb-2 flex flex-wrap items-center gap-1">
                    <span>{product.code}</span>
                    {product.isRentalAvailable && (
                        <span className="text-[9px] font-bold text-indigo-600 bg-indigo-50 px-1 rounded border border-indigo-100">RENTA</span>
                    )}
                    {product.isSaleAvailable && (
                        <span className="text-[9px] font-bold text-emerald-600 bg-emerald-50 px-1 rounded border border-emerald-100">VENTA</span>
                    )}
                </div>
            </div>

            {/* Footer info - Cleaned up (No Stock, No Hover Actions) */}
            <div className="mt-auto flex justify-start items-center">
                <Badge color={isMainlyCostume ? 'indigo' : 'amber'}>{product.category}</Badge>
            </div>
        </div>
    );
};

export default POS;

export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
  imageUrl?: string; // New field for product image
}

export interface Category {
  id?: string;
  name: string;
  imageUrl?: string; // New field for category image
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface UserPermissions {
  canViewReports: boolean;
  canManageSettings: boolean; // Global settings
  canManageInventory: boolean; // Add/Edit/Delete products
  canManageUsers: boolean; // Add/Edit/Delete users
  canRefund: boolean; // Perform refunds
  canDeleteCustomers: boolean; // Delete customers
  canManageExpenses: boolean; // Access Expenses module
  canApplyDiscounts: boolean; // New: Apply coupons in POS
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff'; // Kept for legacy/fallback
  permissions?: UserPermissions; // Granular permissions
  sessionToken?: string; // New: Used to validate active session
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
  cardFeePercentage: number;
  businessName?: string; // New: Custom business name
  businessTagline?: string; // New: Custom slogan/subtitle
  receiptTemplate?: 'v1' | 'v2'; // New: Template selector
  ticketPrefix?: string; // e.g. "26"
  nextTicketSequence?: number; // e.g. 1 (will result in 260001)
  logoUrl?: string; // New: Logo URL for POS empty state
}

export interface Expense {
  id?: string;
  concept: string;
  amount: number;
  createdAt: number;
  registeredBy?: string;
}

export interface Coupon {
  id?: string;
  code: string;
  type: 'percentage' | 'amount'; // % or $
  value: number;
  isActive: boolean;
}

export type TransactionType = 'sale' | 'rent';

export interface CartItem extends Product {
  cartId: string; // Unique ID for the item in cart
  transactionType: TransactionType;
  quantity: number;
  selectedVariation?: Variation;
  appliedPrice: number; // The actual price used for this item (base or variation)
}

export interface Order {
  id?: string;
  items: CartItem[];
  customer?: Customer; // Required if there are rentals
  total: number;
  status: 'pending' | 'completed' | 'returned' | 'late' | 'returned_late' | 'refunded' | 'reservation';
  createdAt: number; // Timestamp
  rentalStartDate?: number;
  rentalEndDate?: number;
  returnedAt?: number; // When it was actually returned
  lateFee?: number; // Fee charged if returned late
  paymentMethod?: 'cash' | 'card' | 'transfer';

  // Discount Fields
  discount?: number;
  discountReason?: string;

  // Reservation Fields
  downPayment?: number; // Amount paid upfront
  remainingBalance?: number; // Amount pending to pay
  finalizedAt?: number; // When the reservation was paid in full/picked up
}

