        </nav>

        {/* Main Content Area */}
        <main className="h-screen overflow-hidden">
          <Routes>
            <Route path="/" element={canAccessPOS ? <POS onOpenQuickAdd={(name) => onOpenQuickRegister()} /> : <Navigate to="/tickets" />} /> 
            <Route path="/returns" element={<Returns />} />
