                            onClick={handleOpenPayment} 
                            disabled={total === 0 && !debtPaymentItem} 
                            className="bg-slate-900 text-white shadow-xl shadow-slate-300 hover:bg-slate-800"
                        >
                            COBRAR <ArrowUpRight className="w-5 h-5 ml-1" />
                        </Button>
                    </div>
                </div>
