export interface Variation {
  name: string;
  rentalPrice?: number;
  salePrice?: number;
}

export interface Product {
  id?: string;
  code: string; // 4 to 6 digits
  name: string;
  description: string;
  salePrice: number;
  rentalPrice: number;
  category: string;
  stock: number;
  variations: Variation[]; 
  isRentalAvailable: boolean;
  isSaleAvailable: boolean;
  imageUrl?: string; // New field for product image
}

export interface Category {
  id?: string;
  name: string;
  imageUrl?: string; // New field for category image
}

export interface Customer {
  id?: string;
  name: string;
  phone: string;
  address?: string; 
  balance?: number; // Positive = Credit (rare), Negative = Debt
}

export interface UserPermissions {
  canAccessPOS: boolean; // New: Access to the Point of Sale screen
  canViewReports: boolean;
  canManageSettings: boolean; // Global settings
  canManageInventory: boolean; // Add/Edit/Delete products
  canManageUsers: boolean; // Add/Edit/Delete users
  canRefund: boolean; // Perform refunds
  canDeleteCustomers: boolean; // Delete customers
  canManageExpenses: boolean; // Access Expenses module
  canApplyDiscounts: boolean; // New: Apply coupons in POS
  canSettleDebt: boolean; // New: Manually clear customer debt
}

export interface User {
  id?: string;
  name: string;
  code: string; // 4 digits typically
  role?: 'admin' | 'staff'; // Kept for legacy/fallback
  permissions?: UserPermissions; // Granular permissions
  sessionToken?: string; // New: Used to validate active session
  menuOrder?: string[]; // New: Custom order of menu paths
}

export interface SystemSettings {
  id?: string;
  defaultLateFee: number;
  pricePerExtraDay: number;
  cardFeePercentage: number;
  businessName?: string; // New: Custom business name
  businessTagline?: string; // New: Custom slogan/subtitle
  receiptTemplate?: 'v1' | 'v2'; // New: Template selector
  ticketPrefix?: string; // e.g. "26"
  nextTicketSequence?: number; // e.g. 1 (will result in 260001)
  logoUrl?: string; // New: Logo URL for POS empty state
  pwaIconUrl?: string; // New: Logo URL for PWA Manifest and Favicon
}

export interface Expense {
  id?: string;
  concept: string;
  amount: number;
  createdAt: number;
  registeredBy?: string;
}

export interface Coupon {
  id?: string;
  code: string;
  type: 'percentage' | 'amount'; // % or $
  value: number;
  isActive: boolean;
}

export type TransactionType = 'sale' | 'rent';

export interface CartItem extends Product {
  cartId: string; // Unique ID for the item in cart
  transactionType: TransactionType;
  quantity: number;
  selectedVariation?: Variation;
  appliedPrice: number; // The actual price used for this item (base or variation)
}

export interface Order {
  id?: string;
  items: CartItem[];
  customer?: Customer; // Required if there are rentals
  total: number;
  status: 'pending' | 'completed' | 'returned' | 'late' | 'returned_late' | 'refunded' | 'reservation';
  createdAt: number; // Timestamp
  rentalStartDate?: number;
  rentalEndDate?: number;
  returnedAt?: number; // When it was actually returned
  lateFee?: number; // Fee charged if returned late
  paymentMethod?: 'cash' | 'card' | 'transfer';

  // Discount Fields
  discount?: number;
  discountReason?: string;

  // Reservation Fields
  downPayment?: number; // Amount paid upfront
  remainingBalance?: number; // Amount pending to pay
  finalizedAt?: number; // When the reservation was paid in full/picked up
}

import React, { useState, useEffect, useMemo } from 'react';
import { Settings as SettingsIcon, Shield, Trash2, UserPlus, Key, DollarSign, Save, AlertTriangle, Check, Pencil, X, Hash, TicketPercent, Plus, Percent, ToggleRight, ToggleLeft, LogOut, ArrowUp, ArrowDown, GripVertical, Menu, Smartphone } from 'lucide-react';
import { Button, Input, Card, Select, Modal } from '../components/UI';
import { User, Product, UserPermissions, Coupon } from '../types';
import { getUsers, addUser, updateUser, deleteUser, getSystemSettings, updateSystemSettings, getProducts, bulkDeleteProducts, getCoupons, addCoupon, deleteCoupon, updateCoupon, resetUserSession, resetAllUserSessions } from '../services/dataService';
import { MENU_ITEMS } from '../App'; // Import MENU_ITEMS to know available routes

const defaultPermissions: UserPermissions = {
    canAccessPOS: true, // Default to true for most staff
    canViewReports: false,
    canManageSettings: false,
    canManageInventory: false,
    canManageUsers: false,
    canRefund: false,
    canDeleteCustomers: false,
    canManageExpenses: false,
    canApplyDiscounts: false, // Default false
    canSettleDebt: false // Default false
};

const Settings: React.FC<{ user: User }> = ({ user }) => {
  // Check Super Admin via prop
  const isSuperAdmin = user.code === '012004';

  const [users, setUsers] = useState<User[]>([]);
  const [loading, setLoading] = useState(false);

  // Settings
  const [lateFee, setLateFee] = useState<string>('50');
  const [extraDayPrice, setExtraDayPrice] = useState<string>('50');
  const [cardFee, setCardFee] = useState<string>('0');
  const [businessName, setBusinessName] = useState<string>('');
  const [businessTagline, setBusinessTagline] = useState<string>('');
  const [receiptTemplate, setReceiptTemplate] = useState<'v1'|'v2'>('v1');
  const [logoUrl, setLogoUrl] = useState<string>('');
  const [pwaIconUrl, setPwaIconUrl] = useState<string>('');

  // Ticket Sequence Settings
  const [ticketPrefix, setTicketPrefix] = useState<string>('26');
  const [nextSequence, setNextSequence] = useState<string>('1');

  // Coupon State
  const [coupons, setCoupons] = useState<Coupon[]>([]);
  const [showCouponModal, setShowCouponModal] = useState(false);
  const [newCouponCode, setNewCouponCode] = useState('');
  const [newCouponType, setNewCouponType] = useState<'percentage' | 'amount'>('percentage');
  const [newCouponValue, setNewCouponValue] = useState('');

  // User Management State
  const [showUserModal, setShowUserModal] = useState(false);
  const [editingUser, setEditingUser] = useState<User | null>(null);
  const [userName, setUserName] = useState('');
  const [userCode, setUserCode] = useState('');
  const [userPermissions, setUserPermissions] = useState<UserPermissions>(defaultPermissions);

  // Custom Menu Order State
  const [customMenuEnabled, setCustomMenuEnabled] = useState(false);
  const [currentMenuOrder, setCurrentMenuOrder] = useState<string[]>([]);

  // Bulk Delete State
  const [allProducts, setAllProducts] = useState<Product[]>([]);
  const [selectedDeleteCategory, setSelectedDeleteCategory] = useState('TODOS');
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [deletePin, setDeletePin] = useState('');
  const [isDeleting, setIsDeleting] = useState(false);

  const loadData = async () => {
    setLoading(true);
    const [u, s, p, c] = await Promise.all([getUsers(), getSystemSettings(), getProducts(), getCoupons()]);
    setUsers(u);
    setLateFee(s.defaultLateFee.toString());
    setExtraDayPrice(s.pricePerExtraDay?.toString() || '0');
    setCardFee(s.cardFeePercentage?.toString() || '0');
    setBusinessName(s.businessName || ''); // Allow empty
    setBusinessTagline(s.businessTagline || ''); // Allow empty
    setReceiptTemplate(s.receiptTemplate || 'v1');
    setTicketPrefix(s.ticketPrefix || '26');
    setNextSequence(s.nextTicketSequence?.toString() || '1');
    setLogoUrl(s.logoUrl || '');
    setPwaIconUrl(s.pwaIconUrl || '');
    setAllProducts(p);
    setCoupons(c);
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const categories = useMemo(() => {
     const cats = new Set(allProducts.map(p => p.category).filter(Boolean));
     return ['TODOS', ...Array.from(cats).sort()];
  }, [allProducts]);

  const handleSaveSettings = async () => {
      const fee = parseFloat(lateFee);
      const dayPrice = parseFloat(extraDayPrice);
      const card = parseFloat(cardFee);
      const nextSeq = parseInt(nextSequence);

      if (isNaN(fee) || isNaN(dayPrice) || isNaN(card)) { alert("Montos inválidos"); return; }
      if (isNaN(nextSeq) || nextSeq < 1) { alert("El número de folio debe ser mayor a 0"); return; }

      // Validation for businessName removed to allow empty values
      if (!ticketPrefix.trim()) { alert("El prefijo del ticket es requerido"); return; }

      try {
          await updateSystemSettings({ 
              defaultLateFee: fee,
              pricePerExtraDay: dayPrice,
              cardFeePercentage: card,
              businessName: businessName.toUpperCase(),
              businessTagline: businessTagline.toUpperCase(),
              receiptTemplate: receiptTemplate,
              ticketPrefix: ticketPrefix,
              nextTicketSequence: nextSeq,
              logoUrl: logoUrl,
              pwaIconUrl: pwaIconUrl
          });
          alert("Ajustes guardados. Si cambió el icono PWA, recargue la página.");
          loadData(); // Reload to ensure sync
      } catch (e) {
          alert("Error al guardar ajustes.");
      }
  };

  // --- Coupon Handlers ---
  const handleCreateCoupon = async (e: React.FormEvent) => {
      e.preventDefault();
      const val = parseFloat(newCouponValue);
      if(!newCouponCode || isNaN(val) || val <= 0) {
          alert("Datos inválidos");
          return;
      }

      try {
          await addCoupon({
              code: newCouponCode.toUpperCase(),
              type: newCouponType,
              value: val,
              isActive: true
          });
          setNewCouponCode('');
          setNewCouponValue('');
          setShowCouponModal(false);
          loadData();
      } catch (e: any) {
          alert(e.message || "Error al crear cupón");
      }
  };

  const handleDeleteCoupon = async (id: string) => {
      if(confirm("¿Eliminar cupón?")) {
          await deleteCoupon(id);
          loadData();
      }
  };

  const handleToggleCoupon = async (coupon: Coupon) => {
      if (coupon.id) {
          await updateCoupon(coupon.id, { isActive: !coupon.isActive });
          setCoupons(prev => prev.map(c => c.id === coupon.id ? { ...c, isActive: !c.isActive } : c));
      }
  };


  // --- User Management Handlers ---

  const openNewUserModal = () => {
      setEditingUser(null);
      setUserName('');
      setUserCode('');
      setUserPermissions(defaultPermissions);
      setCustomMenuEnabled(false);
      // Default order based on MENU_ITEMS
      setCurrentMenuOrder(MENU_ITEMS.map(i => i.path));
      setShowUserModal(true);
  };

  const openEditUserModal = (user: User) => {
      setEditingUser(user);
      setUserName(user.name);
      setUserCode(user.code);
      setUserPermissions({ ...defaultPermissions, ...(user.permissions || {}) });

      if (user.menuOrder && user.menuOrder.length > 0) {
          setCustomMenuEnabled(true);
          // Merge user order with any potentially new default items
          const savedOrder = user.menuOrder;
          const defaultItems = MENU_ITEMS.map(i => i.path);
          // Keep saved order, append any missing new items at the end
          const merged = [...savedOrder, ...defaultItems.filter(p => !savedOrder.includes(p))];
          setCurrentMenuOrder(merged);
      } else {
          setCustomMenuEnabled(false);
          setCurrentMenuOrder(MENU_ITEMS.map(i => i.path));
      }

      setShowUserModal(true);
  };

