                                                >
                                                    <span className="text-[10px] opacity-70">VENTA</span>
                                                    <span className="text-sm font-black">${v.salePrice || selectedProductForVariations.salePrice}</span>
                                                </button>
                                            )}
                                        </div>
                                    </div>
                                ))}
                            </div>
