                                    </div>
                                    <div className="text-[10px] text-slate-500 flex items-center gap-1">
                                        <Badge color={isDebt ? 'rose' : (item.transactionType === 'rent' ? 'indigo' : 'green')}>
                                            {isDebt ? 'ADEUDO' : (isAutoFee ? 'CARGO' : (item.transactionType === 'rent' ? 'RENTA' : 'VENTA'))}
