                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        );
                    })}
                    {/* ... (Discount and Empty State remain same) ... */}
                    {appliedDiscount && (
                        <div className="flex justify-between items-center p-2 bg-emerald-50 rounded-xl border border-emerald-100 animate-in slide-in-from-right">
